class Stage61MgbaError(RuntimeError):
    """exact-ROM、fixture、mGBA出力の契約違反。"""


def _fail(message: str) -> NoReturn:
    raise Stage61MgbaError(message)


def _sha256(raw: bytes) -> str:
    return hashlib.sha256(raw).hexdigest()


def build_orchestrator_identity() -> dict[str, Any]:
    path = ROOT / ORCHESTRATOR_SOURCE
    if not path.is_file():
        _fail(f"Stage61 mGBA orchestrator source欠落: {path}")
    return {
        "source": str(ORCHESTRATOR_SOURCE),
        "source_sha256": _sha256(path.read_bytes()),
        "status": "PASS",
    }


def build_map_field_return_callback_contracts(
    final_rom: bytes,
) -> dict[str, Any]:
    """final ROMへ静的に固定したMAP tag 5/7 field-return契約を返す。

    STARTで通常メニューを開くと、0x0806EA18 が callback slot へ
    0x0806EA75 を格納する。通常taskは0x0806EA30の間接dispatchを経て
    callbackへ入り、Bでfieldへ戻る。この関数はその3区間のexact byteを
    先に検証するため、mGBA観測値を期待値へ昇格することはない。
    """
    if type(final_rom) is not bytes:  # bytearray/memoryviewもmutableなので拒否
        _fail("MAP field-return callback final_romはimmutable bytes必須です")
    if len(final_rom) != 32 * 1024 * 1024:
        _fail(
            "MAP field-return callback final ROM size不一致: "
            f"{len(final_rom)}"
        )
    rom_sha256 = _sha256(final_rom)
    bindings: list[dict[str, Any]] = []
    for expected in _MAP_FIELD_RETURN_CALLBACK_PREIMAGES:
        address = expected["address"]
        raw = bytes.fromhex(expected["raw_hex"])
        offset = address - 0x08000000
        actual = final_rom[offset:offset + len(raw)]
        actual_sha256 = _sha256(actual)
        if actual != raw or actual_sha256 != expected["sha256"]:
            _fail(
                "MAP field-return callback static preimage不一致: "
                f"{expected['role']}@0x{address:08X} "
                f"expected={expected['sha256']} actual={actual_sha256}"
            )
        bindings.append({
            "role": expected["role"],
            "address": f"0x{address:08X}",
            "byte_length": len(raw),
            "raw_hex": raw.hex().upper(),
            "sha256": expected["sha256"],
        })
    provenance = {
        "kind": "FINAL_ROM_STATIC_START_MENU_FIELD_RETURN_CALLBACK",
        "rom_sha256": rom_sha256,
        "derivation": "STATIC_FINAL_ROM_PREIMAGE_NOT_RUNTIME_LEARNED",
        "callback_slot_address": f"0x{_MAP_FIELD_RETURN_CALLBACK_SLOT:08X}",
        "callback_pointer_literal_address": "0x0806EA28",
        "callback_pointer_literal_value": (
            f"0x{_MAP_FIELD_RETURN_CALLBACK_ADDRESS:08X}"
        ),
        "mGBA_instruction_pc_basis": "THUMB_RAW_PC_MINUS_4",
        "normal_field_lifecycle": [
            "FIELD", "START", "START_MENU_OPEN", "B", "FIELD_RETURN",
        ],
        "bindings": bindings,
    }
    row = {
        "callback_address": _MAP_FIELD_RETURN_CALLBACK_ADDRESS,
        "callback_install_instruction_pc": (
            _MAP_FIELD_RETURN_CALLBACK_INSTALL_PC
        ),
        "callback_dispatch_instruction_pc": (
            _MAP_FIELD_RETURN_CALLBACK_DISPATCH_PC
        ),
        "normal_trigger_tokens": ["START", "B"],
        "source_provenance": provenance,
    }
    return {
        "schema_version": 1,
        "kind": "STAGE61_MAP_FIELD_RETURN_CALLBACK_CONTRACTS",
        "rom_sha256": rom_sha256,
        "by_tag": {"5": deepcopy(row), "7": deepcopy(row)},
    }


def _fnv1a64(raw: bytes) -> str:
    value = 14695981039346656037
    for byte in raw:
        value ^= byte
        value = value * 1099511628211 & 0xFFFFFFFFFFFFFFFF
    return f"{value:016X}"


def _stable(value: Any) -> str:
    return json.dumps(value, ensure_ascii=False, sort_keys=True, indent=2) + "\n"


def _effect_stable(value: Any) -> bytes:
    return (
        json.dumps(
            value, ensure_ascii=False, sort_keys=True,
            separators=(",", ":"),
        ) + "\n"
    ).encode("utf-8")


def _effect_binding_sha256(value: Any) -> str:
    return _sha256(_effect_stable(value))


def _read_identity(
    rom_path: Path, metadata_path: Path,
) -> tuple[bytes, dict[str, Any], str]:
    if not rom_path.is_file() or not metadata_path.is_file():
        _fail(f"Stage61 ROM/metadataがありません: {rom_path}, {metadata_path}")
    raw = rom_path.read_bytes()
    try:
        metadata = json.loads(metadata_path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as error:
        _fail(f"Stage61 metadataを読めません: {error}")
    digest = _sha256(raw)
    if len(raw) != 32 * 1024 * 1024:
        _fail(f"Stage61 ROM size不一致: {len(raw)}")
    if (metadata.get("task"), metadata.get("stage")) != (TASK, STAGE):
        _fail("Stage61 metadata task/stage不一致")
    output = metadata.get("output")
    declared_hashes = []
    if isinstance(output, Mapping) and output.get("sha256") is not None:
        declared_hashes.append(output["sha256"])
    if metadata.get("rom_sha256") is not None:
        declared_hashes.append(metadata["rom_sha256"])
    if not declared_hashes \
            or any(not isinstance(value, str)
                   or _RAW_SHA256.fullmatch(value) is None
                   or value != digest for value in declared_hashes):
        _fail("Stage61 ROM/metadata SHA-256不一致")
    return raw, metadata, digest


def _int(value: Any, label: str, maximum: int) -> int:
    if isinstance(value, bool) or not isinstance(value, int):
        _fail(f"fixture {label} は整数ではありません")
    if value < 0 or value > maximum:
        _fail(f"fixture {label} は0..{maximum}外です: {value}")
    return value


def _pair(value: Any, label: str) -> list[int]:
    if not isinstance(value, list) or len(value) != 2:
        _fail(f"fixture {label} は[x,y]ではありません")
    return [_int(value[0], f"{label}[0]", 65535),
            _int(value[1], f"{label}[1]", 65535)]


def _interaction(value: Any, label: str) -> dict[str, Any]:
    if not isinstance(value, Mapping):
        _fail(f"fixture interactions.{label} はobjectではありません")
    required = {
        "group", "map", "object", "start", "action",
        "approach_steps", "local_id",
    }
    if set(value) != required:
        _fail(f"fixture interactions.{label} keys不一致: {sorted(value)}")
    action = value["action"]
    if not isinstance(action, str) or action.upper() not in {
        "UP", "DOWN", "LEFT", "RIGHT",
    }:
        _fail(f"fixture interactions.{label}.action不正: {action!r}")
    result = {
        "group": _int(value["group"], f"{label}.group", 255),
        "map": _int(value["map"], f"{label}.map", 255),
        "object": _pair(value["object"], f"{label}.object"),
        "start": _pair(value["start"], f"{label}.start"),
        "action": action.upper(),
        "approach_steps": _int(
            value["approach_steps"], f"{label}.approach_steps", 32,
        ),
        "local_id": _int(value["local_id"], f"{label}.local_id", 255),
    }
    if result["approach_steps"] == 0:
        _fail(f"fixture interactions.{label} は実歩行を最低1歩必要とします")
    delta = {
        "UP": (0, -1), "DOWN": (0, 1),
        "LEFT": (-1, 0), "RIGHT": (1, 0),
    }[result["action"]]
    adjacent = [
        result["start"][0] + delta[0] * result["approach_steps"],
        result["start"][1] + delta[1] * result["approach_steps"],
    ]
    target = [adjacent[0] + delta[0], adjacent[1] + delta[1]]
    if target != result["object"]:
        _fail(
            f"fixture interactions.{label} のstart/歩数/方向が"
            f"object隣接へ到達しません: target={target} object={result['object']}"
        )
    return result


def _catalog_interaction_execution(
    entry: Mapping[str, Any], label: str,
) -> dict[str, Any]:
    """Normalize the physical OBJECT trigger independently of static entry.

    The final placement allocator deliberately keeps the player on the legal
    stance and performs a closed real-walk cycle before facing the object.
    Counter interactions therefore have distance two and must never be
    coerced into the old one-step-adjacent geometry.  Older strict catalogs
    remain readable by projecting their straight approach into the same
    execution representation; no row is skipped on account of either form.
    """
    base_keys = {"group", "map", "object", "local_id"}
    if not base_keys <= set(entry):
        _fail(f"NPC catalog {label} interaction identity欠落")
    group = _int(entry["group"], f"{label}.group", 255)
    map_number = _int(entry["map"], f"{label}.map", 255)
    object_position = _pair(entry["object"], f"{label}.object")
    local_id = _int(entry["local_id"], f"{label}.local_id", 255)
    shadow = entry.get("non_product_shadow_alias")
    if shadow is not None and (
        not isinstance(shadow, Mapping)
        or set(shadow) != {
            "classification", "role", "source_owner_id",
            "canonical_owner_id",
        }
        or shadow.get("classification")
            != "CANONICAL_SHADOW_NON_PRODUCT_SOURCE"
        or shadow.get("role") not in {
            "NON_PRODUCT_SOURCE", "CANONICAL_PHYSICAL_OWNER",
        }
        or not isinstance(shadow.get("source_owner_id"), str)
        or not isinstance(shadow.get("canonical_owner_id"), str)
    ):
        _fail(f"NPC catalog {label}.non_product_shadow_alias不正")
    expected_template_raw_hex = entry.get("expected_template_raw_hex")
    if expected_template_raw_hex is not None and (
        not isinstance(expected_template_raw_hex, str)
        or re.fullmatch(r"[0-9A-F]{48}", expected_template_raw_hex) is None
    ):
        _fail(f"NPC catalog {label}.expected_template_raw_hex不正")
    execution = entry.get("interaction_execution")
    if execution is None:
        legacy = _interaction({
            "group": group, "map": map_number,
            "object": object_position, "start": entry.get("start"),
            "action": entry.get("action"),
            "approach_steps": entry.get("approach_steps"),
            "local_id": local_id,
        }, label)
        delta = {
            "UP": (0, -1), "DOWN": (0, 1),
            "LEFT": (-1, 0), "RIGHT": (1, 0),
        }[legacy["action"]]
        stance = [
            legacy["start"][0] + delta[0] * legacy["approach_steps"],
            legacy["start"][1] + delta[1] * legacy["approach_steps"],
        ]
        return {
            **legacy,
            "trigger": "LEGACY_STRAIGHT_APPROACH_FACE_AND_A",
            "walk_sequence": [legacy["action"]] * legacy["approach_steps"],
            "stance": stance, "interaction_distance": 1,
            "counter_tile": None, "actual_walk_required": True,
            "actual_walk_exception": None,
            "walk_path_basis": "LEGACY_STRAIGHT_APPROACH",
            "direct_script_call_forbidden": True,
            "map_level_real_walk_probe_required": False,
            "non_product_shadow_alias": None,
            "expected_template_raw_hex": expected_template_raw_hex,
        }

    required = {
        "trigger", "start", "walk_sequence", "stance", "action",
        "interaction_distance", "counter_tile", "actual_walk_required",
        "actual_walk_exception", "walk_path_basis",
        "direct_script_call_forbidden",
    }
    if not isinstance(execution, Mapping) or set(execution) != required:
        _fail(f"NPC catalog {label}.interaction_execution keys不一致")
    if execution.get("trigger") \
            != "TELEPORT_TO_WALK_START_REAL_WALK_TO_STANCE_FACE_AND_A" \
            or execution.get("direct_script_call_forbidden") is not True:
        _fail(f"NPC catalog {label}.interaction_execution trigger契約不一致")
    walk_path_basis = execution.get("walk_path_basis")
    if not isinstance(walk_path_basis, str) or not walk_path_basis.strip():
        _fail(f"NPC catalog {label}.interaction_execution walk根拠欠落")
    start = _pair(execution["start"], f"{label}.interaction_execution.start")
    stance = _pair(
        execution["stance"], f"{label}.interaction_execution.stance",
    )
    action = execution["action"]
    if not isinstance(action, str) or action not in {
        "UP", "DOWN", "LEFT", "RIGHT",
    }:
        _fail(f"NPC catalog {label}.interaction_execution.action不正")
    distance = _int(
        execution["interaction_distance"],
        f"{label}.interaction_execution.interaction_distance", 2,
    )
    if distance not in {1, 2}:
        _fail(f"NPC catalog {label}.interaction_execution distance不正")
    walk_sequence = execution["walk_sequence"]
    if not isinstance(walk_sequence, list) or len(walk_sequence) > 64 \
            or any(token not in {"UP", "DOWN", "LEFT", "RIGHT"}
                   for token in walk_sequence):
        _fail(f"NPC catalog {label}.interaction_execution walk不正")
    cursor = list(start)
    deltas = {
        "UP": (0, -1), "DOWN": (0, 1),
        "LEFT": (-1, 0), "RIGHT": (1, 0),
    }
    for token in walk_sequence:
        dx, dy = deltas[token]
        cursor[0] += dx
        cursor[1] += dy
    if cursor != stance:
        _fail(f"NPC catalog {label}.interaction_execution walk終点不一致")
    dx, dy = deltas[action]
    expected_object = [stance[0] + dx * distance, stance[1] + dy * distance]
    if expected_object != object_position:
        _fail(f"NPC catalog {label}.interaction_execution object距離不一致")
    counter_tile = execution["counter_tile"]
    if distance == 1:
        if counter_tile is not None:
            _fail(f"NPC catalog {label}.interaction_execution counter過剰")
        normalized_counter = None
    else:
        normalized_counter = _pair(
            counter_tile, f"{label}.interaction_execution.counter_tile",
        )
        if normalized_counter != [stance[0] + dx, stance[1] + dy]:
            _fail(f"NPC catalog {label}.interaction_execution counter位置不一致")
    required_walk = execution["actual_walk_required"]
    exception = execution["actual_walk_exception"]
    if not isinstance(required_walk, bool):
        _fail(f"NPC catalog {label}.interaction_execution walk要否不正")
    map_level_required = False
    is_shadow_source = isinstance(shadow, Mapping) \
        and shadow.get("role") == "NON_PRODUCT_SOURCE"
    is_shadow_canonical = isinstance(shadow, Mapping) \
        and shadow.get("role") == "CANONICAL_PHYSICAL_OWNER"
    if is_shadow_source and shadow["source_owner_id"] != entry.get("owner_key") \
            or is_shadow_canonical \
            and shadow["canonical_owner_id"] != entry.get("owner_key"):
        _fail(f"NPC catalog {label} shadow owner identity不一致")
    if is_shadow_source:
        expected_exception = {
            "classification": "CANONICAL_SHADOW_NON_PRODUCT_SOURCE",
            "canonical_owner_id": shadow["canonical_owner_id"],
            "canonical_walk_required": True,
            "source_teleport_face_a_required": True,
            "direct_script_call_forbidden": True,
        }
        if required_walk is not False or walk_sequence \
                or exception != expected_exception or start != stance \
                or walk_path_basis != (
                    "CANONICAL_SHADOW_NON_PRODUCT_SOURCE_DIAGNOSTIC_STANCE"
                ):
            _fail(f"NPC catalog {label} shadow source walk契約不一致")
    elif required_walk is not True or not walk_sequence or exception is not None:
        _fail(
            f"NPC catalog {label}.interaction_execution "
            "owner-specific実歩行根拠不一致"
        )
    if is_shadow_canonical and walk_path_basis != (
        "CANONICAL_SHADOW_EXACT_STOCK_INCOMING_ARRIVAL_TO_STANCE"
    ):
        _fail(f"NPC catalog {label} shadow canonical walk根拠不一致")
    return {
        "group": group, "map": map_number, "object": object_position,
        "start": start, "action": action,
        "approach_steps": len(walk_sequence), "local_id": local_id,
        "trigger": execution["trigger"],
        "walk_sequence": list(walk_sequence), "stance": stance,
        "interaction_distance": distance,
        "counter_tile": normalized_counter,
        "actual_walk_required": required_walk,
        "actual_walk_exception": deepcopy(exception),
        "walk_path_basis": walk_path_basis,
        "direct_script_call_forbidden": True,
        "map_level_real_walk_probe_required": map_level_required,
        "non_product_shadow_alias": (
            None if shadow is None else deepcopy(dict(shadow))
        ),
        "expected_template_raw_hex": expected_template_raw_hex,
    }


def _bill_sevii_scope_guard(value: Any) -> dict[str, Any]:
    """Billのscope外Sevii抑止adapterを独立fixtureへexact bindingする。"""
    extra = {
        "owner_id", "expected_text_utf8", "required_postcondition",
        "scope_contract",
    }
    if not isinstance(value, Mapping) or not extra <= set(value):
        _fail("fixture interactions.bill_sevii_scope_guard schema不一致")
    base_source = {key: value[key] for key in set(value) - extra}
    if set(base_source) != {
        "group", "map", "object", "start", "action",
        "approach_steps", "local_id",
    }:
        _fail("fixture Bill interaction base keys不一致")
    normalized = _interaction(base_source, "bill_sevii_scope_guard")
    if (
        normalized["group"], normalized["map"], normalized["local_id"],
        normalized["object"], normalized["start"], normalized["action"],
        normalized["approach_steps"], value["owner_id"],
        value["required_postcondition"],
    ) != (
        98, 77, 7, [11, 5], [11, 3], "DOWN", 1,
        "OBJECT:098/077:006",
        "FIELD_INPUT_RECOVERED_WITHOUT_FLAG_VAR_BGM_MOVEMENT_OBJECT_OR_WARP_MUTATION",
    ):
        _fail("fixture Bill physical interaction/postcondition不一致")
    if not isinstance(value["expected_text_utf8"], str) \
            or not value["expected_text_utf8"]:
        _fail("fixture Bill expected visible text不正")
    scope = value["scope_contract"]
    if not isinstance(scope, Mapping) or set(scope) != {
        "schema_version", "kind", "status", "owner_id",
        "product_contract", "source_contract", "assertions",
    } or (
        scope.get("schema_version"), scope.get("kind"),
        scope.get("status"), scope.get("owner_id"),
    ) != (
        1, "STAGE61_OUT_OF_SCOPE_STORY_ATOMIC_ADAPTER", "PASS",
        "OBJECT:098/077:006",
    ):
        _fail("fixture Bill scope contract root不一致")
    product = scope["product_contract"]
    product_keys = {
        "adapter_address", "adapter_offset", "adapter_raw_hex",
        "adapter_sha256", "adapter_size", "allowed_semantics",
        "canonical_destination", "forbidden_product_effects", "interaction",
        "normalized_opcode_template_hex", "policy",
        "preserved_source_effect_classes", "suppressed_source_effect_classes",
        "text_pointer", "visible_text_sha256",
    }
    if not isinstance(product, Mapping) or set(product) != product_keys \
            or product.get("adapter_size") != 12 \
            or product.get("canonical_destination") is not None \
            or product.get("interaction") \
            != "REAL_WALK_FACE_A_THEN_FIELD_INPUT_RECOVERY" \
            or product.get("policy") \
            != "ATOMIC_PRODUCER_SUPPRESSION_FOR_OUT_OF_SCOPE_DESTINATION" \
            or product.get("allowed_semantics") \
            != ["LOCK", "FACEPLAYER", "VISIBLE_MSGBOX", "RELEASE", "END"] \
            or product.get("forbidden_product_effects") != [
                "AUDIO", "FLAG_WRITE", "VAR_WRITE", "MOVEMENT",
                "OBJECT_MUTATION", "WARP", "WAITSTATE",
            ]:
        _fail("fixture Bill atomic adapter semantics不一致")
    try:
        adapter_raw = bytes.fromhex(product["adapter_raw_hex"])
        normalized_raw = bytes.fromhex(product["normalized_opcode_template_hex"])
    except (TypeError, ValueError) as error:
        _fail(f"fixture Bill adapter raw hex不正: {error}")
    for key in ("adapter_sha256", "visible_text_sha256"):
        if not isinstance(product.get(key), str) \
                or _RAW_SHA256.fullmatch(product[key]) is None:
            _fail(f"fixture Bill {key}不正")
    if len(adapter_raw) != 12 or len(normalized_raw) != 12 \
            or _sha256(adapter_raw) != product["adapter_sha256"]:
        _fail("fixture Bill adapter bytes/SHA不一致")
    normalized.update({
        "owner_id": value["owner_id"],
        "expected_text_utf8": value["expected_text_utf8"],
        "required_postcondition": value["required_postcondition"],
        "scope_contract": deepcopy(dict(scope)),
        "adapter_address": _fixture_rom_address(
            product["adapter_address"], "Bill.adapter_address",
        ),
        "adapter_raw_hex": adapter_raw.hex(),
        "adapter_sha256": product["adapter_sha256"],
        "text_pointer": _fixture_rom_address(
            product["text_pointer"], "Bill.text_pointer",
        ),
        "visible_text_sha256": product["visible_text_sha256"],
    })
    return normalized


_DIAGNOSTIC_ASSERTIONS = {
    "all_direct_script_calls_forbidden",
    "all_exception_bg_records_classified",
    "all_exception_maps_have_diagnostic_cases",
    "all_exception_script_objects_covered",
    "all_hidden_non_script_bg_roles_have_visibility_proof",
    "all_positive_interactions_use_direction_plus_a",
    "every_map_has_real_walk_cycle",
}
_DIAGNOSTIC_DIRECTIONS = {"UP", "DOWN", "LEFT", "RIGHT"}

_PRODUCT_MAP_SCRIPT_ASSERTIONS = {
    "exact_two_physical_maps",
    "baseline_preimage_is_independent_negative_evidence",
    "stage61_empty_project_table_is_independent_oracle",
    "stock_warp_and_real_walk_only",
    "trainer_pre_and_post_both_required",
    "invalid_control_flow_zero_after_repair",
    "coord_bg_08000000_normalized_to_null",
    "consumer_pointer_read_pc_preimage_bound",
    "all_eight_gym_bg_type3_prepost_visible_text",
}


def _diagnostic_address(value: Any, label: str) -> int:
    if not isinstance(value, str) \
            or re.fullmatch(r"0x0[89][0-9A-F]{6}", value) is None:
        _fail(f"fixture diagnostic {label} ROM address不正")
    return int(value, 16)


def _diagnostic_hash(value: Any, label: str) -> str:
    if not isinstance(value, str) \
            or re.fullmatch(r"[0-9a-f]{64}", value) is None:
        _fail(f"fixture diagnostic {label} SHA-256不正")
    return value


def _normalize_diagnostic_input(value: Any, label: str) -> list[dict[str, Any]]:
    if not isinstance(value, list) or not value or len(value) > 8:
        _fail(f"fixture diagnostic {label} input sequence不正")
    result = []
    purposes = []
    for index, row in enumerate(value):
        row_label = f"{label}.input_sequence[{index}]"
        if not isinstance(row, Mapping) or set(row) != {
            "key", "pressed", "released", "purpose",
        }:
            _fail(f"fixture diagnostic {row_label} keys不一致")
        key = row["key"]
        purpose = row["purpose"]
        if key not in KEYS or purpose not in {
            "REAL_OVERWORLD_WALK_CYCLE", "FACE_EVENT",
            "NORMAL_DIRECTION_A_INTERACTION",
        }:
            _fail(f"fixture diagnostic {row_label} key/purpose不正")
        pressed = _int(row["pressed"], f"diagnostic.{row_label}.pressed", 60)
        released = _int(
            row["released"], f"diagnostic.{row_label}.released", 3600,
        )
        if pressed == 0:
            _fail(f"fixture diagnostic {row_label} pressed=0")
        result.append({
            "key": key, "pressed": pressed, "released": released,
            "purpose": purpose,
        })
        purposes.append(purpose)
    if purposes[-2:] != [
        "FACE_EVENT", "NORMAL_DIRECTION_A_INTERACTION",
    ] or result[-2]["key"] not in _DIAGNOSTIC_DIRECTIONS \
            or result[-1]["key"] != "A":
        _fail(f"fixture diagnostic {label} direction+A終端不正")
    if any(row["purpose"] == "REAL_OVERWORLD_WALK_CYCLE"
           and row["key"] not in _DIAGNOSTIC_DIRECTIONS for row in result):
        _fail(f"fixture diagnostic {label} walk key不正")
    return result


def _normalize_local_static_incoming_absent_map_diagnostics(
    value: Any,
) -> dict[str, Any]:
    root_keys = {
        "schema_version", "status", "map_count", "object_probe_count",
        "object_visibility_negative_probe_count", "bg_script_probe_count",
        "bg_non_script_visibility_proof_count", "maps", "assertions",
    }
    if not isinstance(value, Mapping) or set(value) != root_keys \
            or value.get("schema_version") != 1 \
            or value.get("status") != "PASS":
        _fail("fixture local-incoming-absent diagnostic root契約不一致")
    assertions = value["assertions"]
    if not isinstance(assertions, Mapping) \
            or set(assertions) != _DIAGNOSTIC_ASSERTIONS \
            or any(item is not True for item in assertions.values()):
        _fail("fixture local-incoming-absent diagnostic assertions不一致")
    maps = value["maps"]
    if not isinstance(maps, list) or len(maps) != 40:
        _fail("fixture local-incoming-absent diagnostic map count不一致")
    normalized_maps = []
    map_ids: set[tuple[int, int]] = set()
    probe_ids: set[str] = set()
    object_count = 0
    negative_count = 0
    bg_count = 0
    hidden_count = 0
    for map_index, map_row in enumerate(maps):
        label = f"local_incoming_absent.maps[{map_index}]"
        map_keys = {
            "group", "map", "classification",
            "local_static_incoming_available",
            "diagnostic_teleport_required", "direct_script_call_forbidden",
            "minimum_real_walk_cycle_probe_id", "object_probes",
            "bg_script_probes", "bg_non_script_visibility_proofs",
        }
        if not isinstance(map_row, Mapping) or set(map_row) != map_keys:
            _fail(f"fixture diagnostic {label} keys不一致")
        group = _int(map_row["group"], f"diagnostic.{label}.group", 255)
        map_number = _int(map_row["map"], f"diagnostic.{label}.map", 255)
        identity = (group, map_number)
        if identity in map_ids:
            _fail(f"fixture diagnostic map重複: {identity}")
        map_ids.add(identity)
        if map_row["classification"] not in {
            "ENGINE_DORMANT_LOCAL_INCOMING_ABSENT",
            "CANONICAL_CLONE_SHADOWED_LOCAL_INCOMING_ABSENT",
            "PROJECT_STATE_DEPENDENT_TOPOLOGY_ENTRY",
        } or (
            map_row["local_static_incoming_available"],
            map_row["diagnostic_teleport_required"],
            map_row["direct_script_call_forbidden"],
        ) != (False, True, True):
            _fail(f"fixture diagnostic {label} classification契約不一致")
        objects = map_row["object_probes"]
        bgs = map_row["bg_script_probes"]
        hidden = map_row["bg_non_script_visibility_proofs"]
        if not all(isinstance(rows, list) for rows in (objects, bgs, hidden)):
            _fail(f"fixture diagnostic {label} probe list不正")
        normalized_objects = []
        normalized_bgs = []
        normalized_hidden = []
        walk_probe_ids = set()
        for index, row in enumerate(objects):
            row_label = f"{label}.object_probes[{index}]"
            keys = {
                "probe_id", "owner_id", "object_index", "local_id",
                "script_pointer", "script_prefix_sha256", "teleport",
                "target_object", "input_sequence", "real_walk_cycle",
                "direction_a_required", "direct_script_call_forbidden",
                "visibility", "local_static_incoming_available",
                "diagnostic_interaction_expected",
            }
            if not isinstance(row, Mapping) or set(row) != keys:
                _fail(f"fixture diagnostic {row_label} keys不一致")
            probe_id = row["probe_id"]
            owner_id = row["owner_id"]
            if not isinstance(probe_id, str) \
                    or re.fullmatch(r"DIAG::OBJECT:[0-9]{3}/[0-9]{3}:[0-9]{3}", probe_id) is None \
                    or not isinstance(owner_id, str) \
                    or probe_id != f"DIAG::{owner_id}" \
                    or probe_id in probe_ids:
                _fail(f"fixture diagnostic {row_label} probe/owner ID不正")
            probe_ids.add(probe_id)
            teleport = row["teleport"]
            if not isinstance(teleport, Mapping) or set(teleport) != {
                "group", "map", "x", "y", "kind",
            } or teleport.get("kind") != "OVERWORLD_PLAYER_POSITION_ONLY" \
                    or (teleport.get("group"), teleport.get("map")) != identity:
                _fail(f"fixture diagnostic {row_label} teleport不正")
            position = _pair(row["target_object"], f"diagnostic.{row_label}.target")
            sequence = _normalize_diagnostic_input(row["input_sequence"], row_label)
            cycle = row["real_walk_cycle"]
            if not isinstance(cycle, list) \
                    or any(key not in _DIAGNOSTIC_DIRECTIONS for key in cycle) \
                    or cycle != [step["key"] for step in sequence
                                 if step["purpose"] == "REAL_OVERWORLD_WALK_CYCLE"]:
                _fail(f"fixture diagnostic {row_label} walk cycle不一致")
            if cycle:
                walk_probe_ids.add(probe_id)
            visibility = row["visibility"]
            visibility_keys = {
                "flag", "positive_setup", "positive_expected_template_visible",
                "negative_setup", "negative_expected_template_visible", "basis",
            }
            if not isinstance(visibility, Mapping) \
                    or set(visibility) != visibility_keys:
                _fail(f"fixture diagnostic {row_label} visibility不正")
            flag = _int(
                visibility["flag"], f"diagnostic.{row_label}.visibility.flag",
                0x18FF,
            )
            expected_visibility = (
                ("ALWAYS_VISIBLE_TEMPLATE", True, None, None,
                 "ZERO_VISIBILITY_FLAG_HAS_NO_FLAG_HIDE_STATE")
                if flag == 0 else
                ("CLEAR", True, "SET", False,
                 "OBJECT_EVENT_TEMPLATE_FLAG_CLEAR_SHOWS_SET_HIDES")
            )
            if tuple(visibility[key] for key in (
                "positive_setup", "positive_expected_template_visible",
                "negative_setup", "negative_expected_template_visible", "basis",
            )) != expected_visibility \
                    or any(row[key] is not expected for key, expected in {
                        "direction_a_required": True,
                        "direct_script_call_forbidden": True,
                        "local_static_incoming_available": False,
                        "diagnostic_interaction_expected": True,
                    }.items()):
                _fail(f"fixture diagnostic {row_label} semantic契約不一致")
            negative_count += int(flag != 0)
            normalized_objects.append({
                **deepcopy(dict(row)),
                "object_index": _int(row["object_index"], row_label, 255),
                "local_id": _int(row["local_id"], row_label, 255),
                "script_pointer": _diagnostic_address(
                    row["script_pointer"], f"{row_label}.script_pointer",
                ),
                "script_prefix_sha256": _diagnostic_hash(
                    row["script_prefix_sha256"], f"{row_label}.script_prefix",
                ),
                "teleport": {
                    "group": group, "map": map_number,
                    "x": _int(teleport["x"], row_label, 65535),
                    "y": _int(teleport["y"], row_label, 65535),
                    "kind": teleport["kind"],
                },
                "target_object": position, "input_sequence": sequence,
                "visibility": {**deepcopy(dict(visibility)), "flag": flag},
            })
        object_count += len(normalized_objects)
        for index, row in enumerate(bgs):
            row_label = f"{label}.bg_script_probes[{index}]"
            keys = {
                "bg_index", "position", "kind", "record_address",
                "record_raw_hex", "record_sha256", "probe_id",
                "script_pointer", "script_prefix_sha256", "teleport",
                "target_bg_position", "input_sequence", "real_walk_cycle",
                "direction_a_required", "direct_script_call_forbidden",
            }
            if not isinstance(row, Mapping) or set(row) != keys:
                _fail(f"fixture diagnostic {row_label} keys不一致")
            probe_id = row["probe_id"]
            if not isinstance(probe_id, str) \
                    or re.fullmatch(r"DIAG::BG:[0-9]{3}/[0-9]{3}:[0-9]{3}", probe_id) is None \
                    or probe_id in probe_ids:
                _fail(f"fixture diagnostic {row_label} probe ID不正")
            probe_ids.add(probe_id)
            teleport = row["teleport"]
            if not isinstance(teleport, Mapping) or set(teleport) != {
                "group", "map", "x", "y", "kind",
            } or teleport.get("kind") != "OVERWORLD_PLAYER_POSITION_ONLY" \
                    or (teleport.get("group"), teleport.get("map")) != identity:
                _fail(f"fixture diagnostic {row_label} teleport不正")
            sequence = _normalize_diagnostic_input(row["input_sequence"], row_label)
            cycle = row["real_walk_cycle"]
            if cycle != [step["key"] for step in sequence
                         if step["purpose"] == "REAL_OVERWORLD_WALK_CYCLE"]:
                _fail(f"fixture diagnostic {row_label} walk cycle不一致")
            if cycle:
                walk_probe_ids.add(probe_id)
            raw_hex = row["record_raw_hex"]
            if not isinstance(raw_hex, str) or re.fullmatch(
                r"[0-9a-f]{24}", raw_hex,
            ) is None:
                _fail(f"fixture diagnostic {row_label} record raw不正")
            raw = bytes.fromhex(raw_hex)
            if hashlib.sha256(raw).hexdigest() != row["record_sha256"]:
                _fail(f"fixture diagnostic {row_label} record hash不一致")
            normalized_bgs.append({
                **deepcopy(dict(row)),
                "bg_index": _int(row["bg_index"], row_label, 255),
                "position": _pair(row["position"], row_label),
                "kind": _int(row["kind"], row_label, 255),
                "record_address": _diagnostic_address(
                    row["record_address"], f"{row_label}.record_address",
                ),
                "script_pointer": _diagnostic_address(
                    row["script_pointer"], f"{row_label}.script_pointer",
                ),
                "script_prefix_sha256": _diagnostic_hash(
                    row["script_prefix_sha256"], f"{row_label}.script_prefix",
                ),
                "teleport": {
                    "group": group, "map": map_number,
                    "x": _int(teleport["x"], row_label, 65535),
                    "y": _int(teleport["y"], row_label, 65535),
                    "kind": teleport["kind"],
                },
                "target_bg_position": _pair(row["target_bg_position"], row_label),
                "input_sequence": sequence,
            })
        bg_count += len(normalized_bgs)
        for index, row in enumerate(hidden):
            row_label = f"{label}.bg_non_script[{index}]"
            keys = {
                "bg_index", "position", "kind", "record_address",
                "record_raw_hex", "record_sha256", "role",
                "script_pointer_interpretation_forbidden",
                "visible_template_expected", "normal_visibility_assertion",
                "operand", "meaning_source",
            }
            if not isinstance(row, Mapping) or set(row) != keys \
                    or row.get("kind") != 7 \
                    or row.get("role") != "ENGINE_HIDDEN_ITEM" \
                    or row.get("script_pointer_interpretation_forbidden") is not True \
                    or row.get("visible_template_expected") is not False \
                    or row.get("normal_visibility_assertion") \
                        != "NO_OBJECT_EVENT_TEMPLATE_IS_MATERIALIZED":
                _fail(f"fixture diagnostic {row_label} hidden BG契約不一致")
            raw_hex = row["record_raw_hex"]
            if not isinstance(raw_hex, str) \
                    or re.fullmatch(r"[0-9a-f]{24}", raw_hex) is None:
                _fail(f"fixture diagnostic {row_label} hidden raw不正")
            raw = bytes.fromhex(raw_hex)
            operand = _int(row["operand"], row_label, 0xFFFFFFFF)
            if hashlib.sha256(raw).hexdigest() != row["record_sha256"] \
                    or int.from_bytes(raw[8:12], "little") != operand:
                _fail(f"fixture diagnostic {row_label} hidden hash/operand不一致")
            source = row["meaning_source"]
            if not isinstance(source, Mapping) or set(source) != {
                "constants_path", "constants_sha256", "consumer_path",
                "consumer_sha256",
            } or any(not isinstance(source[key], str) or not source[key]
                     for key in ("constants_path", "consumer_path")):
                _fail(f"fixture diagnostic {row_label} meaning source不正")
            for hash_key in ("constants_sha256", "consumer_sha256"):
                _diagnostic_hash(source[hash_key], f"{row_label}.{hash_key}")
            normalized_hidden.append({
                **deepcopy(dict(row)),
                "bg_index": _int(row["bg_index"], row_label, 255),
                "position": _pair(row["position"], row_label),
                "record_address": _diagnostic_address(
                    row["record_address"], f"{row_label}.record_address",
                ),
                "operand": operand,
                "visibility_flag": operand >> 16,
                "probe_id": (
                    f"DIAG::BG_VIS:{group:03d}/{map_number:03d}:"
                    f"{int(row['bg_index']):03d}"
                ),
            })
        hidden_count += len(normalized_hidden)
        minimum = map_row["minimum_real_walk_cycle_probe_id"]
        if minimum not in walk_probe_ids:
            _fail(f"fixture diagnostic {label} minimum walk probe不一致")
        normalized_maps.append({
            **deepcopy(dict(map_row)), "group": group, "map": map_number,
            "object_probes": normalized_objects,
            "bg_script_probes": normalized_bgs,
            "bg_non_script_visibility_proofs": normalized_hidden,
        })
    actual_counts = (
        len(normalized_maps), object_count, negative_count, bg_count, hidden_count,
    )
    declared_counts = tuple(value[key] for key in (
        "map_count", "object_probe_count",
        "object_visibility_negative_probe_count", "bg_script_probe_count",
        "bg_non_script_visibility_proof_count",
    ))
    if actual_counts != declared_counts or actual_counts != (40, 99, 14, 7, 5):
        _fail(
            "fixture non-product diagnostic coverage不一致: "
            f"declared={declared_counts} actual={actual_counts}"
        )
    return {**deepcopy(dict(value)), "maps": normalized_maps}


def _validate_diagnostic_rom_bindings(
    rom: bytes, diagnostics: Mapping[str, Any] | None,
) -> None:
    """Builderが固定したrecord/script bytesを実行対象ROMへ再結合する。"""
    if diagnostics is None:
        return

    def read_rom(address: int, size: int, label: str) -> bytes:
        offset = address - 0x08000000
        if offset < 0 or offset + size > len(rom):
            _fail(f"fixture diagnostic {label} ROM range不正")
        return rom[offset:offset + size]

    for map_row in diagnostics["maps"]:
        for row in map_row["object_probes"]:
            actual = hashlib.sha256(read_rom(
                row["script_pointer"], 32, row["probe_id"],
            )).hexdigest()
            if actual != row["script_prefix_sha256"]:
                _fail(
                    f"fixture diagnostic {row['probe_id']} script ROM binding不一致"
                )
        for row in map_row["bg_script_probes"]:
            record = read_rom(row["record_address"], 12, row["probe_id"])
            if record.hex() != row["record_raw_hex"] \
                    or hashlib.sha256(record).hexdigest() != row["record_sha256"]:
                _fail(
                    f"fixture diagnostic {row['probe_id']} BG record ROM binding不一致"
                )
            actual = hashlib.sha256(read_rom(
                row["script_pointer"], 32, row["probe_id"],
            )).hexdigest()
            if actual != row["script_prefix_sha256"]:
                _fail(
                    f"fixture diagnostic {row['probe_id']} BG script ROM binding不一致"
                )
        for row in map_row["bg_non_script_visibility_proofs"]:
            record = read_rom(row["record_address"], 12, row["probe_id"])
            if record.hex() != row["record_raw_hex"] \
                    or hashlib.sha256(record).hexdigest() != row["record_sha256"]:
                _fail(
                    f"fixture diagnostic {row['probe_id']} hidden BG ROM binding不一致"
                )


def _normalize_final_map_script_regressions(value: Any) -> dict[str, Any]:
    root_keys = {
        "schema_version", "status", "baseline_rom", "maps",
        "null_script_owners", "gym_bg_trainer_regressions", "assertions",
    }
    if not isinstance(value, Mapping) or set(value) != root_keys \
            or value.get("schema_version") != 1 \
            or value.get("status") != "PASS":
        _fail("fixture final map-script regression root契約不一致")
    baseline = value["baseline_rom"]
    if not isinstance(baseline, Mapping) or set(baseline) != {
        "path_hint", "sha256",
    } or baseline.get("path_hint") != str(DEFAULT_STAGE60_ROM) \
            or not isinstance(baseline.get("sha256"), str) \
            or _RAW_SHA256.fullmatch(baseline["sha256"]) is None:
        _fail("fixture final map-script Stage60 baseline契約不一致")
    assertions = value["assertions"]
    if not isinstance(assertions, Mapping) \
            or set(assertions) != _PRODUCT_MAP_SCRIPT_ASSERTIONS \
            or any(item is not True for item in assertions.values()):
        _fail("fixture final map-script assertions不一致")
    maps = value["maps"]
    if not isinstance(maps, list) or len(maps) != 2:
        _fail("fixture final map-script map count不一致")
    normalized = []
    identities: set[tuple[int, int]] = set()
    baseline_tags: set[int] = set()
    for index, row in enumerate(maps):
        label = f"final_map_script_regressions.maps[{index}]"
        keys = {
            "case_id", "group", "map", "start", "walk_cycle", "action",
            "expected_map_scripts_contract", "map_scripts_pointer",
            "stage60_map_scripts_pointer", "stage60_preimage_hex",
            "stage61_preimage_hex", "trainer",
        }
        if not isinstance(row, Mapping) or set(row) != keys:
            _fail(f"fixture {label} keys不一致")
        group = _int(row["group"], f"{label}.group", 255)
        map_number = _int(row["map"], f"{label}.map", 255)
        identity = (group, map_number)
        if identity not in {(1, 85), (1, 86)} or identity in identities:
            _fail(f"fixture {label} physical map不一致")
        identities.add(identity)
        case_id = row["case_id"]
        if not isinstance(case_id, str) \
                or _CASE_ID.fullmatch(case_id) is None:
            _fail(f"fixture {label}.case_id不正")
        start = _pair(row["start"], f"{label}.start")
        action = row["action"]
        cycle = row["walk_cycle"]
        if action not in _DIAGNOSTIC_DIRECTIONS \
                or not isinstance(cycle, list) or not cycle \
                or len(cycle) > 8 \
                or any(key not in _DIAGNOSTIC_DIRECTIONS for key in cycle):
            _fail(f"fixture {label} walk/action不正")
        deltas = {
            "UP": (0, -1), "DOWN": (0, 1),
            "LEFT": (-1, 0), "RIGHT": (1, 0),
        }
        if tuple(map(sum, zip(*(deltas[key] for key in cycle)))) != (0, 0):
            _fail(f"fixture {label} walk_cycleが閉路ではありません")
        pointers = {}
        for key in ("map_scripts_pointer", "stage60_map_scripts_pointer"):
            pointer = row[key]
            if not isinstance(pointer, str) \
                    or re.fullmatch(r"0x0[89][0-9A-F]{6}", pointer) is None:
                _fail(f"fixture {label}.{key}不正")
            pointers[key] = int(pointer, 16)
        preimages = {}
        for key in ("stage60_preimage_hex", "stage61_preimage_hex"):
            raw_hex = row[key]
            if not isinstance(raw_hex, str) \
                    or re.fullmatch(r"[0-9a-f]{32}", raw_hex) is None:
                _fail(f"fixture {label}.{key}不正")
            preimages[key] = raw_hex
        baseline_tags.add(bytes.fromhex(preimages["stage60_preimage_hex"])[0])
        if row["expected_map_scripts_contract"] != "EMPTY_PROJECT_TABLE" \
                or bytes.fromhex(preimages["stage61_preimage_hex"])[0] != 0:
            _fail(f"fixture {label} empty map-script oracle不一致")
        trainer = row["trainer"]
        if not isinstance(trainer, Mapping) or set(trainer) != {
            "local_id", "object", "trainer_id", "script_pointer", "prepost",
        } or trainer.get("prepost") != ["PRE", "POST"]:
            _fail(f"fixture {label}.trainer schema不一致")
        local_id = _int(trainer["local_id"], f"{label}.local_id", 255)
        object_position = _pair(trainer["object"], f"{label}.object")
        trainer_id = _int(
            trainer["trainer_id"], f"{label}.trainer_id", 0x2FF,
        )
        script_pointer = trainer["script_pointer"]
        if not isinstance(script_pointer, str) \
                or re.fullmatch(r"0x0[89][0-9A-F]{6}", script_pointer) is None:
            _fail(f"fixture {label}.trainer.script_pointer不正")
        dx, dy = deltas[action]
        if [start[0] + dx, start[1] + dy] != object_position:
            _fail(f"fixture {label} trainer/start/actionが非隣接")
        normalized.append({
            **deepcopy(dict(row)), "group": group, "map": map_number,
            "start": start, "walk_cycle": list(cycle),
            **pointers, **preimages,
            "trainer": {
                **deepcopy(dict(trainer)), "local_id": local_id,
                "object": object_position, "trainer_id": trainer_id,
                "script_pointer": int(script_pointer, 16),
            },
        })
    if identities != {(1, 85), (1, 86)} or baseline_tags != {0xF6, 0x6A}:
        _fail("fixture final map-script physical/tag coverage不一致")
    null_rows = value["null_script_owners"]
    if not isinstance(null_rows, list) or len(null_rows) != 2:
        _fail("fixture final null-script owner count不一致")
    normalized_null = []
    null_kinds: set[str] = set()
    null_ids: set[str] = set()
    for index, row in enumerate(null_rows):
        label = f"final_map_script_regressions.null_script_owners[{index}]"
        keys = {
            "case_id", "owner_kind", "consumer_kind", "group", "map",
            "index", "position", "record_address", "stage60_record_hex",
            "stage61_record_hex", "entry", "required_state",
            "trigger_var", "trigger_value",
            "expected_stage60_failure", "expected_stage61_terminal",
            "consumer_pointer_read_pc", "consumer_pointer_read_preimage_hex",
            "consumer_thumb_mode",
        }
        if not isinstance(row, Mapping) or set(row) != keys:
            _fail(f"fixture {label} keys不一致")
        case_id = row["case_id"]
        owner_kind = row["owner_kind"]
        consumer_kind = row["consumer_kind"]
        if not isinstance(case_id, str) or _CASE_ID.fullmatch(case_id) is None \
                or case_id in null_ids \
                or owner_kind not in {"COORD", "BG"} \
                or owner_kind in null_kinds \
                or not isinstance(consumer_kind, str) \
                or re.fullmatch(rf"{owner_kind}_[A-Z0-9_]+", consumer_kind) is None:
            _fail(f"fixture {label} ID/kind不正")
        null_ids.add(case_id)
        null_kinds.add(owner_kind)
        group = _int(row["group"], f"{label}.group", 255)
        map_number = _int(row["map"], f"{label}.map", 255)
        owner_index = _int(row["index"], f"{label}.index", 255)
        position = _pair(row["position"], f"{label}.position")
        record_address = _diagnostic_address(
            row["record_address"], f"{label}.record_address",
        )
        expected_size = 16 if owner_kind == "COORD" else 12
        records: dict[str, str] = {}
        for key in ("stage60_record_hex", "stage61_record_hex"):
            raw_hex = row[key]
            if not isinstance(raw_hex, str) \
                    or re.fullmatch(
                        rf"[0-9a-f]{{{expected_size * 2}}}", raw_hex,
                    ) is None:
                _fail(f"fixture {label}.{key}不正")
            records[key] = raw_hex
        pointer_offset = 12 if owner_kind == "COORD" else 8
        if int.from_bytes(
            bytes.fromhex(records["stage60_record_hex"])[
                pointer_offset:pointer_offset + 4
            ], "little",
        ) != 0x08000000 or int.from_bytes(
            bytes.fromhex(records["stage61_record_hex"])[
                pointer_offset:pointer_offset + 4
            ], "little",
        ) != 0:
            _fail(f"fixture {label} 0x08000000->NULL record契約不一致")
        entry = row["entry"]
        if not isinstance(entry, Mapping) or set(entry) != {
            "start", "walk_cycle", "action", "entry_seed",
        }:
            _fail(f"fixture {label}.entry schema不一致")
        start = _pair(entry["start"], f"{label}.entry.start")
        cycle = entry["walk_cycle"]
        action = entry["action"]
        entry_seed = entry["entry_seed"]
        if not isinstance(cycle, list) or not cycle or len(cycle) > 8 \
                or any(key not in _DIAGNOSTIC_DIRECTIONS for key in cycle) \
                or action not in _DIAGNOSTIC_DIRECTIONS \
                or not isinstance(entry_seed, str) or not entry_seed.strip():
            _fail(f"fixture {label}.entry walk/action/seed不正")
        deltas = {
            "UP": (0, -1), "DOWN": (0, 1),
            "LEFT": (-1, 0), "RIGHT": (1, 0),
        }
        if tuple(map(sum, zip(*(deltas[key] for key in cycle)))) != (0, 0):
            _fail(f"fixture {label}.entry walk_cycleが閉路ではありません")
        dx, dy = deltas[action]
        if [start[0] + dx, start[1] + dy] != position:
            _fail(f"fixture {label}.entry triggerがowner座標に隣接しません")
        required_state = row["required_state"]
        if not isinstance(required_state, Mapping) or set(required_state) != {
            "flags", "vars",
        }:
            _fail(f"fixture {label}.required_state keys不一致")
        state = {"flags": [], "vars": []}
        for kind, value_key, minimum, maximum in (
            ("flags", "value", 0, 0x18FF),
            ("vars", "value", 0x4000, 0x51FF),
        ):
            source = required_state[kind]
            if not isinstance(source, list) or len(source) > 16:
                _fail(f"fixture {label}.required_state.{kind}不正")
            seen_state = set()
            for state_index, item in enumerate(source):
                if not isinstance(item, Mapping) or set(item) != {
                    "id", value_key,
                }:
                    _fail(f"fixture {label}.{kind}[{state_index}]不正")
                identifier = _int(
                    item["id"], f"{label}.{kind}.id", maximum,
                )
                if identifier < minimum or identifier in seen_state:
                    _fail(f"fixture {label}.{kind} namespace/重複不正")
                seen_state.add(identifier)
                raw_value = item[value_key]
                if kind == "flags":
                    if not isinstance(raw_value, bool):
                        _fail(f"fixture {label}.flags.valueはboolです")
                    normalized_value: int | bool = raw_value
                else:
                    normalized_value = _int(
                        raw_value, f"{label}.vars.value", 0xFFFF,
                    )
                state[kind].append({"id": identifier, "value": normalized_value})
        trigger_var = _int(row["trigger_var"], f"{label}.trigger_var", 0x51FF)
        trigger_value = _int(
            row["trigger_value"], f"{label}.trigger_value", 0xFFFF,
        )
        if owner_kind == "COORD":
            coord_records = [
                bytes.fromhex(records[key])
                for key in ("stage60_record_hex", "stage61_record_hex")
            ]
            if any(
                int.from_bytes(record[6:8], "little") != trigger_var
                or int.from_bytes(record[8:10], "little") != trigger_value
                for record in coord_records
            ):
                _fail(f"fixture {label} COORD trigger record不一致")
            expected_vars = [
                item for item in state["vars"] if item["id"] == trigger_var
            ] if trigger_var != 0 else []
            if trigger_var != 0 and expected_vars != [{
                "id": trigger_var, "value": trigger_value,
            }]:
                _fail(f"fixture {label} COORD trigger state欠落/不一致")
        elif (trigger_var, trigger_value) != (0, 0):
            _fail(f"fixture {label} BGにCOORD triggerがあります")
        if row["expected_stage60_failure"] \
                != "INVALID_POINTER_0x08000000" \
                or row["expected_stage61_terminal"] \
                != "FIELD_INPUT_RECOVERED_NO_SCRIPT" \
                or row["consumer_thumb_mode"] is not True:
            _fail(f"fixture {label} expected terminal/Thumb契約不一致")
        read_pc = row["consumer_pointer_read_pc"]
        if not isinstance(read_pc, str) \
                or re.fullmatch(r"0x0[89][0-9A-F]{6}", read_pc) is None:
            _fail(f"fixture {label}.consumer_pointer_read_pc不正")
        read_preimage = row["consumer_pointer_read_preimage_hex"]
        if not isinstance(read_preimage, str) \
                or re.fullmatch(r"[0-9a-f]{32}", read_preimage) is None:
            _fail(f"fixture {label}.consumer pointer preimage不正")
        normalized_null.append({
            **deepcopy(dict(row)), "group": group, "map": map_number,
            "index": owner_index, "position": position,
            "record_address": record_address, **records,
            "entry": {
                "start": start, "walk_cycle": list(cycle),
                "action": action, "entry_seed": entry_seed,
            },
            "required_state": state,
            "trigger_var": trigger_var, "trigger_value": trigger_value,
            "consumer_pointer_read_pc": int(read_pc, 16) & ~1,
        })
    if null_kinds != {"COORD", "BG"}:
        _fail("fixture final null-script COORD/BG coverage不一致")
    gym_rows = value["gym_bg_trainer_regressions"]
    if not isinstance(gym_rows, list) or len(gym_rows) != 8:
        _fail("fixture product gym BG trainer count不一致")
    normalized_gym = []
    gym_case_ids: set[str] = set()
    gym_owner_ids: set[str] = set()
    gym_sites: set[int] = set()
    for index, row in enumerate(gym_rows):
        label = (
            "final_map_script_regressions."
            f"gym_bg_trainer_regressions[{index}]"
        )
        keys = {
            "case_id", "owner_id", "group", "map", "bg_index",
            "position", "record_address", "stage60_record_hex",
            "stage61_record_hex", "script_root", "trainerbattle_site",
            "trainerbattle_type_offset", "stage60_trainerbattle_prefix_hex",
            "stage61_trainerbattle_prefix_hex", "stage60_eos_text_pointer",
            "prebattle_text_pointer", "repaired_defeat_text_pointer",
            "trainer_id", "entry", "required_state", "pre_text_oracle",
            "post_text_oracle", "expected_stage60_semantic",
            "expected_stage61_pre_terminal",
            "expected_stage61_post_terminal", "prepost",
        }
        if not isinstance(row, Mapping) or set(row) != keys:
            _fail(f"fixture {label} keys不一致")
        case_id = row["case_id"]
        owner_id = row["owner_id"]
        if not isinstance(case_id, str) \
                or _CASE_ID.fullmatch(case_id) is None \
                or case_id in gym_case_ids \
                or not isinstance(owner_id, str) \
                or _OWNER_ID.fullmatch(owner_id) is None \
                or owner_id in gym_owner_ids:
            _fail(f"fixture {label} case/owner ID不正")
        gym_case_ids.add(case_id)
        gym_owner_ids.add(owner_id)
        group = _int(row["group"], f"{label}.group", 255)
        map_number = _int(row["map"], f"{label}.map", 255)
        bg_index = _int(row["bg_index"], f"{label}.bg_index", 255)
        position = _pair(row["position"], f"{label}.position")
        record_address = _diagnostic_address(
            row["record_address"], f"{label}.record_address",
        )
        records: dict[str, str] = {}
        for key in ("stage60_record_hex", "stage61_record_hex"):
            raw_hex = row[key]
            if not isinstance(raw_hex, str) \
                    or re.fullmatch(r"[0-9a-f]{24}", raw_hex) is None:
                _fail(f"fixture {label}.{key}不正")
            records[key] = raw_hex
        addresses = {}
        for key in (
            "script_root", "trainerbattle_site", "stage60_eos_text_pointer",
            "prebattle_text_pointer", "repaired_defeat_text_pointer",
        ):
            addresses[key] = _diagnostic_address(row[key], f"{label}.{key}")
        if addresses["trainerbattle_site"] in gym_sites:
            _fail(f"fixture {label} trainerbattle site重複")
        gym_sites.add(addresses["trainerbattle_site"])
        for key in ("stage60_record_hex", "stage61_record_hex"):
            if int.from_bytes(bytes.fromhex(records[key])[8:12], "little") \
                    != addresses["script_root"]:
                _fail(f"fixture {label} BG record/script root不一致")
        prefixes: dict[str, str] = {}
        for key in (
            "stage60_trainerbattle_prefix_hex",
            "stage61_trainerbattle_prefix_hex",
        ):
            raw_hex = row[key]
            if not isinstance(raw_hex, str) \
                    or re.fullmatch(r"[0-9a-f]{64}", raw_hex) is None:
                _fail(f"fixture {label}.{key}不正")
            prefixes[key] = raw_hex
        type_offset = _int(
            row["trainerbattle_type_offset"], f"{label}.type_offset", 31,
        )
        stage60_prefix = bytes.fromhex(
            prefixes["stage60_trainerbattle_prefix_hex"]
        )
        stage61_prefix = bytes.fromhex(
            prefixes["stage61_trainerbattle_prefix_hex"]
        )
        eos_pointer = addresses["stage60_eos_text_pointer"]
        defeat_pointer = addresses["repaired_defeat_text_pointer"]
        if eos_pointer != 0x0938A585 \
                or stage60_prefix[type_offset] != 0 \
                or stage61_prefix[type_offset] != 3 \
                or eos_pointer.to_bytes(4, "little") not in stage60_prefix \
                or defeat_pointer.to_bytes(4, "little") not in stage61_prefix \
                or eos_pointer.to_bytes(4, "little") in stage61_prefix:
            _fail(f"fixture {label} type0/EOS -> type3/defeat契約不一致")
        entry = row["entry"]
        if not isinstance(entry, Mapping) or set(entry) != {
            "start", "walk_cycle", "action", "entry_seed",
        }:
            _fail(f"fixture {label}.entry schema不一致")
        start = _pair(entry["start"], f"{label}.entry.start")
        cycle = entry["walk_cycle"]
        action = entry["action"]
        entry_seed = entry["entry_seed"]
        if not isinstance(cycle, list) or not cycle or len(cycle) > 8 \
                or any(key not in _DIAGNOSTIC_DIRECTIONS for key in cycle) \
                or action not in _DIAGNOSTIC_DIRECTIONS \
                or not isinstance(entry_seed, str) or not entry_seed.strip():
            _fail(f"fixture {label}.entry walk/action/seed不正")
        deltas = {
            "UP": (0, -1), "DOWN": (0, 1),
            "LEFT": (-1, 0), "RIGHT": (1, 0),
        }
        if tuple(map(sum, zip(*(deltas[key] for key in cycle)))) != (0, 0):
            _fail(f"fixture {label}.entry walk_cycleが閉路ではありません")
        dx, dy = deltas[action]
        if [start[0] + dx, start[1] + dy] != position:
            _fail(f"fixture {label}.entry BG隣接不一致")
        required_state = row["required_state"]
        if not isinstance(required_state, Mapping) or set(required_state) != {
            "flags", "vars",
        }:
            _fail(f"fixture {label}.required_state keys不一致")
        state = {"flags": [], "vars": []}
        for kind, minimum, maximum in (
            ("flags", 0, 0x18FF), ("vars", 0x4000, 0x51FF),
        ):
            source = required_state[kind]
            if not isinstance(source, list) or len(source) > 16:
                _fail(f"fixture {label}.required_state.{kind}不正")
            seen_state = set()
            for state_index, item in enumerate(source):
                if not isinstance(item, Mapping) or set(item) != {"id", "value"}:
                    _fail(f"fixture {label}.{kind}[{state_index}]不正")
                identifier = _int(item["id"], f"{label}.{kind}.id", maximum)
                if identifier < minimum or identifier in seen_state:
                    _fail(f"fixture {label}.{kind} namespace/重複不正")
                seen_state.add(identifier)
                raw_value = item["value"]
                if kind == "flags":
                    if not isinstance(raw_value, bool):
                        _fail(f"fixture {label}.flags.valueはboolです")
                    normalized_value: int | bool = raw_value
                else:
                    normalized_value = _int(
                        raw_value, f"{label}.vars.value", 0xFFFF,
                    )
                state[kind].append({"id": identifier, "value": normalized_value})
        pre_oracle = _normalize_text_oracle(
            row["pre_text_oracle"], label, require_ordered_printers=False,
        )
        post_oracle = _normalize_text_oracle(
            row["post_text_oracle"], label, require_ordered_printers=False,
        )
        if addresses["prebattle_text_pointer"] not in \
                pre_oracle["provenance"]["source_text_addresses"] \
                or addresses["repaired_defeat_text_pointer"] not in \
                post_oracle["provenance"]["source_text_addresses"]:
            _fail(f"fixture {label} independent text provenance pointer欠落")
        for oracle_name, oracle in (("PRE", pre_oracle), ("POST", post_oracle)):
            provenance_hashes = set(oracle["provenance"]["raw_sha256s"])
            if not set(oracle["ordered_raw_sha256s"]) <= provenance_hashes \
                    or any(not set(sequence) <= provenance_hashes for sequence in
                           oracle["allowed_ordered_raw_sha256_sequences"]):
                _fail(f"fixture {label} {oracle_name} ordered/provenance hash不一致")
        trainer_id = _int(row["trainer_id"], f"{label}.trainer_id", 0x2FF)
        if (
            row["expected_stage60_semantic"],
            row["expected_stage61_pre_terminal"],
            row["expected_stage61_post_terminal"],
            row["prepost"],
        ) != (
            "TYPE0_TRAINERBATTLE_EOS_ONLY_TEXT", "BATTLE_START",
            "FIELD_INPUT_RECOVERED", ["PRE", "POST"],
        ):
            _fail(f"fixture {label} PRE/POST semantic契約不一致")
        normalized_gym.append({
            **deepcopy(dict(row)), "group": group, "map": map_number,
            "bg_index": bg_index, "position": position,
            "record_address": record_address, **records, **addresses,
            **prefixes, "trainerbattle_type_offset": type_offset,
            "trainer_id": trainer_id,
            "entry": {
                "start": start, "walk_cycle": list(cycle),
                "action": action, "entry_seed": entry_seed,
            },
            "required_state": state,
            "pre_text_oracle": pre_oracle,
            "post_text_oracle": post_oracle,
        })
    return {
        **deepcopy(dict(value)), "baseline_rom": deepcopy(dict(baseline)),
        "maps": sorted(normalized, key=lambda row: (row["group"], row["map"])),
        "null_script_owners": sorted(
            normalized_null, key=lambda row: row["owner_kind"],
        ),
        "gym_bg_trainer_regressions": sorted(
            normalized_gym, key=lambda row: row["case_id"],
        ),
    }


def _map_scripts_pointer(rom: bytes, group: int, map_number: int) -> int:
    def pointer(offset: int, label: str) -> int:
        if offset < 0 or offset + 4 > len(rom):
            _fail(f"product map-script {label} ROM range不正")
        value = int.from_bytes(rom[offset:offset + 4], "little")
        if value < 0x08000000 or value >= 0x0A000000:
            _fail(f"product map-script {label} pointer不正")
        return value

    root = pointer(0x54B0C, "gMapGroups") - 0x08000000
    group_table = pointer(root + group * 4, "group") - 0x08000000
    header = pointer(group_table + map_number * 4, "header") - 0x08000000
    return pointer(header + 8, "mapScripts")


def _validate_product_map_script_rom_bindings(
    stage61_rom: bytes, baseline_rom: bytes,
    fixture: Mapping[str, Any] | None,
) -> None:
    if fixture is None:
        return
    for row in fixture["maps"]:
        for rom, pointer_key, preimage_key, label in (
            (stage61_rom, "map_scripts_pointer", "stage61_preimage_hex", "Stage61"),
            (baseline_rom, "stage60_map_scripts_pointer", "stage60_preimage_hex", "Stage60"),
        ):
            pointer = _map_scripts_pointer(rom, row["group"], row["map"])
            expected_pointer = row[pointer_key]
            offset = pointer - 0x08000000
            actual = rom[offset:offset + 16]
            if pointer != expected_pointer or actual.hex() != row[preimage_key]:
                _fail(
                    f"product map-script {row['case_id']} {label} ROM binding不一致"
                )
    for row in fixture["null_script_owners"]:
        size = 16 if row["owner_kind"] == "COORD" else 12
        offset = row["record_address"] - 0x08000000
        if offset < 0 or offset + size > len(stage61_rom) \
                or stage61_rom[offset:offset + size].hex() \
                != row["stage61_record_hex"] \
                or baseline_rom[offset:offset + size].hex() \
                != row["stage60_record_hex"]:
            _fail(f"product null-script {row['case_id']} record ROM binding不一致")
        pc_offset = row["consumer_pointer_read_pc"] - 0x08000000
        if pc_offset < 0 or pc_offset + 16 > len(stage61_rom) \
                or stage61_rom[pc_offset:pc_offset + 16].hex() \
                != row["consumer_pointer_read_preimage_hex"]:
            _fail(f"product null-script {row['case_id']} consumer PC preimage不一致")
    for row in fixture["gym_bg_trainer_regressions"]:
        record_offset = row["record_address"] - 0x08000000
        site_offset = row["trainerbattle_site"] - 0x08000000
        if record_offset < 0 or record_offset + 12 > len(stage61_rom) \
                or stage61_rom[record_offset:record_offset + 12].hex() \
                != row["stage61_record_hex"] \
                or baseline_rom[record_offset:record_offset + 12].hex() \
                != row["stage60_record_hex"] \
                or site_offset < 0 or site_offset + 32 > len(stage61_rom) \
                or stage61_rom[site_offset:site_offset + 32].hex() \
                != row["stage61_trainerbattle_prefix_hex"] \
                or baseline_rom[site_offset:site_offset + 32].hex() \
                != row["stage60_trainerbattle_prefix_hex"]:
            _fail(f"product gym BG {row['case_id']} record/script ROM binding不一致")
        for phase in ("pre", "post"):
            oracle = row[f"{phase}_text_oracle"]
            source_hashes = set(oracle["provenance"]["raw_sha256s"])
            for address in oracle["provenance"]["source_text_addresses"]:
                offset = address - 0x08000000
                if offset < 0 or offset >= len(stage61_rom):
                    _fail(
                        f"product gym BG {row['case_id']} {phase} text ROM range不正"
                    )
                end = stage61_rom.find(b"\xFF", offset, min(offset + 512, len(stage61_rom)))
                if end < 0:
                    _fail(
                        f"product gym BG {row['case_id']} {phase} text EOS欠落"
                    )
                digest = hashlib.sha256(stage61_rom[offset:end + 1]).hexdigest()
                if digest not in source_hashes:
                    _fail(
                        f"product gym BG {row['case_id']} {phase} independent "
                        "text ROM binding不一致"
                    )


def _validate_connection_transition_rom_binding(rom: bytes) -> None:
    """Pin one real, independently parsed west connection in the final ROM."""
    def raw(address: int, size: int, label: str) -> bytes:
        offset = address - 0x08000000
        if offset < 0 or offset + size > len(rom):
            _fail(f"connection lifecycle {label} ROM range不正")
        return rom[offset:offset + size]

    def word(address: int, label: str) -> int:
        return int.from_bytes(raw(address, 4, label), "little")

    expected = {
        0x08316A8C: bytes.fromhex("030000000000000003000000"),
        0x08866AF0: bytes.fromhex(
            "0300167F0802A002800801106B860800"
        ),
    }
    for address, expected_raw in expected.items():
        actual = raw(address, len(expected_raw), f"0x{address:08X}")
        if actual != expected_raw:
            _fail(
                f"connection lifecycle ROM preimage不一致: 0x{address:08X}"
            )
    if _sha256(raw(0x08316A8C, 12, "connection row")) \
            != "40272649e0393212abbc8ff2488eaf24e664d0b272a8f83539aedbd567e4bdbe" \
            or _sha256(raw(0x087F1600, 64, "transition root")) \
            != "9d67c4c16e695842cb71b15da3ce68866803e64df3c18073f652bbbeb202b1a7":
        _fail("connection lifecycle row/root SHA-256不一致")
    if (
        word(0x08054B0C, "gMapGroups literal"),
        word(0x092C5194 + 3 * 4, "group 3 table"),
        word(0x083163A4 + 19 * 4, "source header pointer"),
        word(0x083163A4 + 0 * 4, "destination header pointer"),
        word(0x083148DC, "source layout pointer"),
        word(0x083146C8, "destination layout pointer"),
        word(0x083148DC + 12, "source connections pointer"),
        word(0x083146C8 + 8, "destination map scripts pointer"),
        word(0x086F21E8, "source width"),
        word(0x086F21E8 + 4, "source height"),
        word(0x086F044C, "destination width"),
        word(0x086F044C + 4, "destination height"),
    ) != (
        0x092C5194, 0x083163A4, 0x083148DC, 0x083146C8,
        0x086F21E8, 0x086F044C, 0x08316AA4, 0x08866AF0,
        60, 24, 35, 30,
    ):
        _fail("connection lifecycle map/header/layout binding不一致")


def _fixture_rom_address(value: Any, label: str) -> int:
    if not isinstance(value, str) or re.fullmatch(
        r"0x0[89][0-9A-F]{6}", value,
    ) is None:
        _fail(f"fixture {label} ROM address不正")
    return int(value, 16)


def _normalize_popup_stock_warp(value: Any, label: str) -> dict[str, Any]:
    keys = {
        "source", "source_map_key", "source_warp_record_address",
        "source_warp_record_hex", "predecessor_tile", "trigger_tile",
        "trigger_key", "destination_warp_id", "arrival_tile", "seed_basis",
    }
    if not isinstance(value, Mapping) or set(value) != keys:
        _fail(f"fixture {label} stock_warp schema不一致")
    source = value["source"]
    if not isinstance(source, list) or len(source) != 3:
        _fail(f"fixture {label}.sourceは[group,map,warp]ではありません")
    normalized_source = [
        _int(source[0], f"{label}.source.group", 255),
        _int(source[1], f"{label}.source.map", 255),
        _int(source[2], f"{label}.source.warp", 255),
    ]
    if not isinstance(value["source_map_key"], str) \
            or not value["source_map_key"]:
        _fail(f"fixture {label}.source_map_key不正")
    record_address = _fixture_rom_address(
        value["source_warp_record_address"],
        f"{label}.source_warp_record_address",
    )
    try:
        record = bytes.fromhex(value["source_warp_record_hex"])
    except (TypeError, ValueError) as error:
        _fail(f"fixture {label}.source_warp_record_hex不正: {error}")
    if len(record) != 8:
        _fail(f"fixture {label}.source_warp_recordは8 bytesではありません")
    predecessor = _pair(value["predecessor_tile"], f"{label}.predecessor")
    trigger = _pair(value["trigger_tile"], f"{label}.trigger")
    key = value["trigger_key"]
    if key not in {"UP", "DOWN", "LEFT", "RIGHT"}:
        _fail(f"fixture {label}.trigger_key不正")
    delta = {
        "UP": (0, -1), "DOWN": (0, 1),
        "LEFT": (-1, 0), "RIGHT": (1, 0),
    }[key]
    if [predecessor[0] + delta[0], predecessor[1] + delta[1]] != trigger:
        _fail(f"fixture {label} predecessor/trigger/key不一致")
    if value["seed_basis"] != "EXACT_INCOMING_WARP_DESTINATION_ROW":
        _fail(f"fixture {label}.seed_basis不一致")
    return {
        "source": normalized_source,
        "source_map_key": value["source_map_key"],
        "source_warp_record_address": record_address,
        "source_warp_record_hex": record.hex(),
        "predecessor_tile": predecessor,
        "trigger_tile": trigger,
        "trigger_key": key,
        "destination_warp_id": _int(
            value["destination_warp_id"], f"{label}.destination_warp_id", 255,
        ),
        "arrival_tile": _pair(value["arrival_tile"], f"{label}.arrival"),
        "seed_basis": value["seed_basis"],
    }


def _normalize_map_popup_regressions(value: Any) -> dict[str, Any]:
    if not isinstance(value, Mapping) or set(value) != {
        "schema_version", "status", "cases", "assertions",
    } or (value.get("schema_version"), value.get("status")) != (1, "PASS"):
        _fail("fixture map_popup_regressions root不一致")
    assertions = value["assertions"]
    required_assertions = {
        "exact_seven_section_collision_popup_maps",
        "kanto_three_use_project_section_41",
        "tohoku_four_preserve_stock_section_131",
        "all_popup_names_have_independent_raw_hash",
        "all_popups_use_exact_usable_incoming_warp",
    }
    if not isinstance(assertions, Mapping) \
            or set(assertions) != required_assertions \
            or any(item is not True for item in assertions.values()):
        _fail("fixture map_popup_regressions assertions不一致")
    cases = value["cases"]
    row_keys = {
        "case_id", "group", "map", "physical_provenance",
        "header_address", "header_sha256", "runtime_map_section",
        "resolver_source_map_section", "namespace", "show_map_name",
        "expected_name_utf8", "expected_name_pointer",
        "expected_name_raw_size", "expected_name_raw_sha256",
        "name_provenance", "stock_warp", "entry_report_sha256",
        "expected_terminal",
    }
    if not isinstance(cases, list) or len(cases) != 7:
        _fail("fixture map_popup_regressionsはexact 7 casesが必要です")
    normalized = []
    seen: set[tuple[int, int]] = set()
    for index, row in enumerate(cases):
        label = f"map_popup_regressions.cases[{index}]"
        if not isinstance(row, Mapping) or set(row) != row_keys:
            _fail(f"fixture {label} keys不一致")
        group = _int(row["group"], f"{label}.group", 255)
        map_number = _int(row["map"], f"{label}.map", 255)
        identity = (group, map_number)
        if identity in seen:
            _fail(f"fixture {label} physical map重複")
        seen.add(identity)
        expected_identity = (
            group == 97 and map_number in {36, 37, 38}
        ) or (group == 1 and map_number in {36, 37, 38, 73})
        provenance = row["physical_provenance"]
        namespace = row["namespace"]
        section = _int(
            row["runtime_map_section"], f"{label}.runtime_section", 255,
        )
        if not expected_identity or (
            group == 97 and (
                provenance != "IMPORTED_KANTO_CANONICAL"
                or namespace != "PROJECT_KANTO_NAMESPACE" or section != 41
            )
        ) or (
            group == 1 and (
                provenance != "VEGA_STOCK_PHYSICAL"
                or namespace != "VEGA_STOCK_NAMESPACE" or section != 131
            )
        ):
            _fail(f"fixture {label} physical provenance/section不一致")
        if row["show_map_name"] is not True \
                or row["expected_terminal"] \
                != "MAP_POPUP_RENDERED_THEN_FIELD_INPUT" \
                or not isinstance(row["expected_name_utf8"], str) \
                or not row["expected_name_utf8"]:
            _fail(f"fixture {label} name/terminal不一致")
        for hash_key in (
            "header_sha256", "expected_name_raw_sha256",
            "entry_report_sha256",
        ):
            if not isinstance(row[hash_key], str) \
                    or _RAW_SHA256.fullmatch(row[hash_key]) is None:
                _fail(f"fixture {label}.{hash_key}不正")
        name_provenance = row["name_provenance"]
        if not isinstance(name_provenance, Mapping) \
                or not isinstance(name_provenance.get("kind"), str) \
                or not isinstance(name_provenance.get("source_pointer"), str):
            _fail(f"fixture {label}.name_provenance不正")
        normalized.append({
            "case_id": row["case_id"], "group": group, "map": map_number,
            "physical_provenance": provenance,
            "header_address": _fixture_rom_address(
                row["header_address"], f"{label}.header_address",
            ),
            "header_sha256": row["header_sha256"],
            "runtime_map_section": section,
            "resolver_source_map_section": _int(
                row["resolver_source_map_section"],
                f"{label}.resolver_source_section", 255,
            ),
            "namespace": namespace, "show_map_name": True,
            "expected_name_utf8": row["expected_name_utf8"],
            "expected_name_pointer": _fixture_rom_address(
                row["expected_name_pointer"], f"{label}.name_pointer",
            ),
            "expected_name_raw_size": _int(
                row["expected_name_raw_size"], f"{label}.name_size", 512,
            ),
            "expected_name_raw_sha256": row["expected_name_raw_sha256"],
            "name_provenance": deepcopy(dict(name_provenance)),
            "stock_warp": _normalize_popup_stock_warp(
                row["stock_warp"], label,
            ),
            "entry_report_sha256": row["entry_report_sha256"],
            "expected_terminal": row["expected_terminal"],
        })
    if seen != {
        (97, 36), (97, 37), (97, 38),
        (1, 36), (1, 37), (1, 38), (1, 73),
    }:
        _fail("fixture map_popup_regressions physical coverage不一致")
    return {
        "schema_version": 1, "status": "PASS",
        "cases": normalized, "assertions": deepcopy(dict(assertions)),
    }


def _normalize_diglett_natural_interaction(value: Any) -> dict[str, Any]:
    keys = {
        "case_id", "owner_id", "group", "map", "local_id",
        "object_index", "object", "stance", "stock_warp",
        "walk_key_sequence", "walk_tiles", "walk_step_count", "action",
        "press_a", "path_provenance", "interaction_oracle_binding",
        "required_prepost", "expected_terminal",
    }
    if not isinstance(value, Mapping) or set(value) != keys:
        _fail("fixture diglett_b1f_natural_interaction keys不一致")
    if (value.get("group"), value.get("map"), value.get("local_id")) \
            != (97, 37, 1) or value.get("press_a") is not True \
            or value.get("required_prepost") != ["PRE", "POST"] \
            or value.get("expected_terminal") \
            != "VISIBLE_INTERACTION_NO_SOFTLOCK":
        _fail("fixture Diglett B1F target/prepost契約不一致")
    object_position = _pair(value["object"], "diglett.object")
    stance = _pair(value["stance"], "diglett.stance")
    action = value["action"]
    if action not in {"UP", "DOWN", "LEFT", "RIGHT"}:
        _fail("fixture Diglett action不正")
    delta = {
        "UP": (0, -1), "DOWN": (0, 1),
        "LEFT": (-1, 0), "RIGHT": (1, 0),
    }[action]
    if [stance[0] + delta[0], stance[1] + delta[1]] != object_position:
        _fail("fixture Diglett stance/action/object不一致")
    keys_sequence = value["walk_key_sequence"]
    tiles = value["walk_tiles"]
    steps = _int(value["walk_step_count"], "diglett.walk_step_count", 4096)
    if not isinstance(keys_sequence, list) or len(keys_sequence) != steps \
            or any(key not in {"UP", "DOWN", "LEFT", "RIGHT"}
                   for key in keys_sequence) \
            or not isinstance(tiles, list) or len(tiles) != steps + 1:
        _fail("fixture Diglett natural path shape不一致")
    normalized_tiles = [
        _pair(tile, f"diglett.walk_tiles[{index}]")
        for index, tile in enumerate(tiles)
    ]
    if normalized_tiles[-1] != stance:
        _fail("fixture Diglett pathがstanceへ到達しません")
    provenance = value["path_provenance"]
    if not isinstance(provenance, Mapping) or set(provenance) == {"sha256"} \
            or not isinstance(provenance.get("sha256"), str):
        _fail("fixture Diglett path provenance不正")
    provenance_basis = {
        key: deepcopy(item) for key, item in provenance.items()
        if key != "sha256"
    }
    if _sha256(_stable(provenance_basis).encode("utf-8")) \
            != provenance["sha256"]:
        _fail("fixture Diglett path provenance SHA不一致")
    binding = value["interaction_oracle_binding"]
    if not isinstance(binding, Mapping) or set(binding) != {
        "catalog", "owner_key", "calibration_derived_oracle_forbidden",
    } or binding.get("catalog") \
            != "reports/generated/stage61_interaction_oracles.json" \
            or binding.get("calibration_derived_oracle_forbidden") is not True:
        _fail("fixture Diglett independent oracle binding不一致")
    stock_warp = _normalize_popup_stock_warp(
        value["stock_warp"], "diglett.stock_warp",
    )
    if normalized_tiles[0] != stock_warp["arrival_tile"]:
        _fail("fixture Diglett path start/stock warp arrival不一致")
    return {
        "case_id": value["case_id"], "owner_id": value["owner_id"],
        "group": 97, "map": 37, "local_id": 1,
        "object_index": _int(value["object_index"], "diglett.object_index", 255),
        "object": object_position, "stance": stance,
        "stock_warp": stock_warp,
        "walk_key_sequence": list(keys_sequence),
        "walk_tiles": normalized_tiles, "walk_step_count": steps,
        "action": action, "press_a": True,
        "path_provenance": deepcopy(dict(provenance)),
        "interaction_oracle_binding": deepcopy(dict(binding)),
        "required_prepost": ["PRE", "POST"],
        "expected_terminal": value["expected_terminal"],
    }


def _normalize_engine_special_flag_lifecycle(value: Any) -> dict[str, Any]:
    keys = {
        "schema_version", "status", "kind", "flag_id", "runtime_storage",
        "producer", "transition", "consumer", "expected_trace",
        "required_final", "source_contract", "assertions",
    }
    if not isinstance(value, Mapping) or set(value) != keys or (
        value.get("schema_version"), value.get("status"), value.get("kind"),
        value.get("flag_id"),
    ) != (1, "PASS", "ENGINE_SPECIAL_FLAG_CROSS_MAP_LIFECYCLE", "0x4001"):
        _fail("fixture engine_special_flag_lifecycle root不一致")
    storage = value["runtime_storage"]
    if not isinstance(storage, Mapping) or storage != {
        "owner_address": "0x02037014", "size": 16, "byte_offset": 0,
        "bit_mask": 2, "encoding": "PLAIN_BITSET_ID_0x4000_IS_BIT_0",
        "persistence": "EWRAM_VOLATILE_NOT_SAVEBLOCK",
    }:
        _fail("fixture engine special flag owner ABI不一致")
    producer = value["producer"]
    if not isinstance(producer, Mapping) or set(producer) != {
        "map", "trigger_var", "trigger_value", "set_site", "record_owners",
        "variants",
    } or _pair(producer["map"], "engine producer.map") != [3, 0] \
            or producer["trigger_var"] != "0x4050" \
            or producer["trigger_value"] != 0:
        _fail("fixture engine special producer schema不一致")
    owners = producer["record_owners"]
    if not isinstance(owners, list) or len(owners) != 2:
        _fail("fixture engine special producer owner数不一致")
    normalized_owners = []
    for index, owner in enumerate(owners):
        label = f"engine producer.record_owners[{index}]"
        if not isinstance(owner, Mapping) or set(owner) != {
            "owner_id", "owner_kind", "record_address", "record_hex",
            "record_sha256", "runtime_root",
        } or owner.get("owner_kind") != "COORD":
            _fail(f"fixture {label} schema不一致")
        record = bytes.fromhex(owner["record_hex"])
        if len(record) != 16 or _sha256(record) != owner["record_sha256"]:
            _fail(f"fixture {label} record SHA不一致")
        normalized_owners.append({
            **deepcopy(dict(owner)),
            "record_address": _fixture_rom_address(
                owner["record_address"], f"{label}.record_address",
            ),
            "runtime_root": _fixture_rom_address(
                owner["runtime_root"], f"{label}.runtime_root",
            ),
        })
    variants = producer["variants"]
    if not isinstance(variants, list) or len(variants) != 2:
        _fail("fixture engine special variants数不一致")
    normalized_variants = []
    owner_ids = {owner["owner_id"] for owner in normalized_owners}
    for index, variant in enumerate(variants):
        label = f"engine producer.variants[{index}]"
        if not isinstance(variant, Mapping) or set(variant) != {
            "variant", "coord_owner_id", "start", "trigger_tile",
            "walk_tokens", "temporary_side",
        } or variant.get("coord_owner_id") not in owner_ids \
                or variant.get("temporary_side") not in {0, 1} \
                or not isinstance(variant.get("walk_tokens"), list) \
                or len(variant["walk_tokens"]) != 1 \
                or variant["walk_tokens"][0] not in {
                    "UP", "DOWN", "LEFT", "RIGHT",
                }:
            _fail(f"fixture {label} schema不一致")
        start = _pair(variant["start"], f"{label}.start")
        trigger = _pair(variant["trigger_tile"], f"{label}.trigger_tile")
        delta = {
            "UP": (0, -1), "DOWN": (0, 1),
            "LEFT": (-1, 0), "RIGHT": (1, 0),
        }[variant["walk_tokens"][0]]
        if [start[0] + delta[0], start[1] + delta[1]] != trigger:
            _fail(f"fixture {label} actual step geometry不一致")
        normalized_variants.append({
            **deepcopy(dict(variant)), "start": start,
            "trigger_tile": trigger,
        })
    transition = value["transition"]
    if not isinstance(transition, Mapping) or set(transition) != {
        "relation", "destination_map", "destination_position",
        "scene_var", "scene_value",
    } or transition.get("relation") \
            != "REAL_COORD_STEP_CUTSCENE_THEN_STOCK_WARP" \
            or transition.get("scene_var") != "0x4055" \
            or transition.get("scene_value") != 1:
        _fail("fixture engine special transition schema不一致")
    destination_map = _pair(
        transition["destination_map"], "engine transition.destination_map",
    )
    destination_position = _pair(
        transition["destination_position"],
        "engine transition.destination_position",
    )
    consumer = value["consumer"]
    if not isinstance(consumer, Mapping) or set(consumer) != {
        "trigger", "clear_site", "owner",
    } or consumer.get("trigger") \
            != "DESTINATION_MAP_LOAD_CONDITION_0x4055_EQ_1":
        _fail("fixture engine special consumer schema不一致")
    consumer_owner = consumer["owner"]
    if not isinstance(consumer_owner, Mapping) or set(consumer_owner) != {
        "owner_id", "owner_kind", "record_address", "record_hex",
        "record_sha256", "runtime_root",
    } or consumer_owner.get("owner_kind") != "MAP":
        _fail("fixture engine special MAP owner schema不一致")
    consumer_record = bytes.fromhex(consumer_owner["record_hex"])
    if len(consumer_record) != 8 \
            or _sha256(consumer_record) != consumer_owner["record_sha256"]:
        _fail("fixture engine special MAP record SHA不一致")
    expected_trace = [
        "COORD_TRIGGER_HIT", "SET_0x4001_BIT_OBSERVED",
        "STOCK_WARP_TO_004_003_006_012", "MAP_CONDITION_OWNER_HIT",
        "CLEAR_0x4001_BIT_OBSERVED", "BGM_TRANSITION_COMPLETES",
        "FIELD_INPUT_RECOVERED",
    ]
    required_final = value["required_final"]
    assertions = value["assertions"]
    if value["expected_trace"] != expected_trace \
            or required_final != {
                "engine_special_flag_0x4001": False,
                "map": [4, 3], "invalid_script_pc_count": 0,
                "softlock_count": 0,
            } or not isinstance(assertions, Mapping) or not assertions \
            or any(item is not True for item in assertions.values()) \
            or not isinstance(value["source_contract"], Mapping) \
            or not value["source_contract"]:
        _fail("fixture engine special final/source/assertion不一致")
    return {
        "schema_version": 1, "status": "PASS",
        "kind": value["kind"], "flag_id": 0x4001,
        "runtime_storage": deepcopy(dict(storage)),
        "producer": {
            "map": [3, 0], "trigger_var": 0x4050,
            "trigger_value": 0,
            "set_site": _fixture_rom_address(
                producer["set_site"], "engine producer.set_site",
            ),
            "record_owners": normalized_owners,
            "variants": normalized_variants,
        },
        "transition": {
            **deepcopy(dict(transition)), "destination_map": destination_map,
            "destination_position": destination_position,
            "scene_var": 0x4055,
        },
        "consumer": {
            "trigger": consumer["trigger"],
            "clear_site": _fixture_rom_address(
                consumer["clear_site"], "engine consumer.clear_site",
            ),
            "owner": {
                **deepcopy(dict(consumer_owner)),
                "record_address": _fixture_rom_address(
                    consumer_owner["record_address"],
                    "engine consumer.record_address",
                ),
                "runtime_root": _fixture_rom_address(
                    consumer_owner["runtime_root"],
                    "engine consumer.runtime_root",
                ),
            },
        },
        "expected_trace": expected_trace,
        "required_final": deepcopy(dict(required_final)),
        "source_contract": deepcopy(dict(value["source_contract"])),
        "assertions": deepcopy(dict(assertions)),
    }


def validate_fixture_document(value: Any) -> dict[str, Any]:
    """外部fixtureを厳格に検証し、環境へ渡せる正規形にする。"""
    if not isinstance(value, Mapping):
        _fail("fixture rootはobjectではありません")
    required = {"schema_version", "task", "stage", "interactions",
                "story", "popup", "fly"}
    optional = {
        "local_static_incoming_absent_map_diagnostics",
        "final_map_script_regressions",
        "map_popup_regressions", "diglett_b1f_natural_interaction",
        "engine_special_flag_lifecycle",
    }
    if not required <= set(value) or set(value) - required - optional:
        _fail(f"fixture root keys不一致: {sorted(value)}")
    if (value.get("schema_version"), value.get("task"), value.get("stage")) \
            != (1, TASK, STAGE):
        _fail("fixture schema/task/stage不一致")
    interactions = value["interactions"]
    if not isinstance(interactions, Mapping) \
            or set(interactions) != {
                "giver", "snorlax", "fuji", "bill_sevii_scope_guard",
            }:
        _fail("fixture interactions keys不一致")
    normalized_interactions = {
        name: _interaction(interactions[name], name)
        for name in ("giver", "snorlax", "fuji")
    }
    normalized_interactions["bill_sevii_scope_guard"] = (
        _bill_sevii_scope_guard(interactions["bill_sevii_scope_guard"])
    )

    story = value["story"]
    story_keys = {
        "flute_flag", "flute_item", "snorlax_hidden_flag",
        "snorlax_species", "snorlax_hides_after_flee",
    }
    if not isinstance(story, Mapping) or set(story) != story_keys:
        _fail("fixture story keys不一致")
    if not isinstance(story["snorlax_hides_after_flee"], bool):
        _fail("fixture story.snorlax_hides_after_fleeはboolではありません")
    normalized_story = {
        "flute_flag": _int(story["flute_flag"], "story.flute_flag", 65535),
        "flute_item": _int(story["flute_item"], "story.flute_item", 65535),
        "snorlax_hidden_flag": _int(
            story["snorlax_hidden_flag"], "story.snorlax_hidden_flag", 65535,
        ),
        "snorlax_species": _int(
            story["snorlax_species"], "story.snorlax_species", 65535,
        ),
        "snorlax_hides_after_flee": story["snorlax_hides_after_flee"],
    }
    if normalized_story["flute_flag"] == normalized_story["snorlax_hidden_flag"]:
        _fail("笛取得flagとカビゴン消去flagが同一です")

    popup = value["popup"]
    popup_keys = {"group", "map", "start", "runtime_section", "expected_name"}
    if not isinstance(popup, Mapping) or set(popup) != popup_keys:
        _fail("fixture popup keys不一致")
    if not isinstance(popup["expected_name"], str) or not popup["expected_name"]:
        _fail("fixture popup.expected_nameは非空文字列ではありません")
    normalized_popup = {
        "group": _int(popup["group"], "popup.group", 255),
        "map": _int(popup["map"], "popup.map", 255),
        "start": _pair(popup["start"], "popup.start"),
        "runtime_section": _int(
            popup["runtime_section"], "popup.runtime_section", 255,
        ),
        "expected_name": popup["expected_name"],
    }

    fly = value["fly"]
    if not isinstance(fly, Mapping) or set(fly) != {
        "origin", "party_context_down", "visited_flag", "destination",
        "map_sequence",
    }:
        _fail("fixture fly keys不一致")
    origin = fly["origin"]
    if not isinstance(origin, Mapping) or set(origin) != {"group", "map", "start"}:
        _fail("fixture fly.origin keys不一致")
    normalized_origin = {
        "group": _int(origin["group"], "fly.origin.group", 255),
        "map": _int(origin["map"], "fly.origin.map", 255),
        "start": _pair(origin["start"], "fly.origin.start"),
    }
    destination = fly["destination"]
    normalized_destination: dict[str, Any] | None
    if destination is None:
        normalized_destination = None
    elif isinstance(destination, Mapping) \
            and set(destination) == {"group", "map", "start"}:
        normalized_destination = {
            "group": _int(destination["group"], "fly.destination.group", 255),
            "map": _int(destination["map"], "fly.destination.map", 255),
            "start": _pair(destination["start"], "fly.destination.start"),
        }
        if (normalized_destination["group"], normalized_destination["map"]) \
                == (normalized_origin["group"], normalized_origin["map"]):
            _fail("fixture Fly destinationがoriginと同一です")
    else:
        _fail("fixture fly.destinationはnullまたは{group,map,start}です")
    sequence = fly["map_sequence"]
    if not isinstance(sequence, list) or not sequence or len(sequence) > 64:
        _fail("fixture fly.map_sequenceは1..64 stepが必要です")
    normalized_sequence = []
    for index, step in enumerate(sequence):
        if not isinstance(step, Mapping) \
                or set(step) != {"key", "pressed", "released"}:
            _fail(f"fixture fly.map_sequence[{index}] keys不一致")
        key = step["key"]
        if not isinstance(key, str) or key.upper() not in KEYS:
            _fail(f"fixture fly.map_sequence[{index}].key不正")
        normalized_sequence.append({
            "key": key.upper(),
            "pressed": _int(step["pressed"], f"fly.sequence[{index}].pressed", 60),
            "released": _int(
                step["released"], f"fly.sequence[{index}].released", 3600,
            ),
        })
        if normalized_sequence[-1]["pressed"] == 0:
            _fail("fixture Fly sequence pressed=0は禁止です")
    if not any(step["key"] == "A" for step in normalized_sequence):
        _fail("fixture Fly sequenceは通常選択用A入力を必要とします")

    diagnostics = (
        _normalize_local_static_incoming_absent_map_diagnostics(
            value["local_static_incoming_absent_map_diagnostics"]
        )
        if "local_static_incoming_absent_map_diagnostics" in value else None
    )
    product_regressions = (
        _normalize_final_map_script_regressions(
            value["final_map_script_regressions"]
        )
        if "final_map_script_regressions" in value else None
    )
    popup_regressions = (
        _normalize_map_popup_regressions(value["map_popup_regressions"])
        if "map_popup_regressions" in value else None
    )
    diglett_natural = (
        _normalize_diglett_natural_interaction(
            value["diglett_b1f_natural_interaction"]
        ) if "diglett_b1f_natural_interaction" in value else None
    )
    if (popup_regressions is None) != (diglett_natural is None):
        _fail("fixture popup regressions/Diglett naturalは同時提供が必要です")
    engine_special_lifecycle = (
        _normalize_engine_special_flag_lifecycle(
            value["engine_special_flag_lifecycle"]
        ) if "engine_special_flag_lifecycle" in value else None
    )
    result = {
        "schema_version": 1,
        "task": TASK,
        "stage": STAGE,
        "interactions": normalized_interactions,
        "story": normalized_story,
        "popup": normalized_popup,
        "fly": {
            "origin": normalized_origin,
            "party_context_down": _int(
                fly["party_context_down"], "fly.party_context_down", 8,
            ),
            "visited_flag": _int(
                fly["visited_flag"], "fly.visited_flag", 65535,
            ),
            "destination": normalized_destination,
            "map_sequence": normalized_sequence,
        },
    }
    if diagnostics is not None:
        result["local_static_incoming_absent_map_diagnostics"] = diagnostics
    if product_regressions is not None:
        result["final_map_script_regressions"] = product_regressions
    if popup_regressions is not None:
        result["map_popup_regressions"] = popup_regressions
        result["diglett_b1f_natural_interaction"] = diglett_natural
    if engine_special_lifecycle is not None:
        result["engine_special_flag_lifecycle"] = engine_special_lifecycle
    return result


def load_fixtures(path: Path | None) -> tuple[dict[str, Any], str]:
    if path is not None and path.is_file():
        try:
            source = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError) as error:
            _fail(f"fixture JSONを読めません: {error}")
        origin = str(path)
    else:
        source = deepcopy(DEFAULT_FIXTURE_DOCUMENT)
        origin = "embedded-default"
    normalized = validate_fixture_document(source)
    return normalized, origin


def fixture_environment(fixtures: Mapping[str, Any]) -> dict[str, str]:
    env: dict[str, str] = {}
    for name in ("giver", "snorlax", "fuji", "bill_sevii_scope_guard"):
        row = fixtures["interactions"][name]
        prefix = "S61_BILL" if name == "bill_sevii_scope_guard" \
            else f"S61_{name.upper()}"
        env[f"{prefix}_GROUP"] = str(row["group"])
        env[f"{prefix}_MAP"] = str(row["map"])
        env[f"{prefix}_START_X"] = str(row["start"][0])
        env[f"{prefix}_START_Y"] = str(row["start"][1])
        env[f"{prefix}_ACTION_KEY"] = str(KEYS[row["action"]])
        env[f"{prefix}_APPROACH_STEPS"] = str(row["approach_steps"])
        env[f"{prefix}_LOCAL_ID"] = str(row["local_id"])
        if name == "bill_sevii_scope_guard":
            env[f"{prefix}_ADAPTER_ADDRESS"] = str(row["adapter_address"])
            env[f"{prefix}_TEXT_POINTER"] = str(row["text_pointer"])
    story = fixtures["story"]
    env.update({
        "S61_FLUTE_FLAG": str(story["flute_flag"]),
        "S61_FLUTE_ITEM": str(story["flute_item"]),
        "S61_SNORLAX_HIDDEN_FLAG": str(story["snorlax_hidden_flag"]),
        "S61_SNORLAX_SPECIES": str(story["snorlax_species"]),
        "S61_SNORLAX_HIDES_AFTER_FLEE": (
            "true" if story["snorlax_hides_after_flee"] else "false"
        ),
    })
    popup = fixtures["popup"]
    env.update({
        "S61_POPUP_GROUP": str(popup["group"]),
        "S61_POPUP_MAP": str(popup["map"]),
        "S61_POPUP_X": str(popup["start"][0]),
        "S61_POPUP_Y": str(popup["start"][1]),
        "S61_POPUP_SECTION": str(popup["runtime_section"]),
    })
    fly = fixtures["fly"]
    origin = fly["origin"]
    env.update({
        "S61_FLY_ORIGIN_GROUP": str(origin["group"]),
        "S61_FLY_ORIGIN_MAP": str(origin["map"]),
        "S61_FLY_ORIGIN_X": str(origin["start"][0]),
        "S61_FLY_ORIGIN_Y": str(origin["start"][1]),
        "S61_FLY_CONTEXT_DOWN": str(fly["party_context_down"]),
        "S61_FLY_VISITED_FLAG": str(fly["visited_flag"]),
        "S61_FLY_MAP_SEQUENCE": ",".join(
            f"{step['key']}:{step['pressed']}:{step['released']}"
            for step in fly["map_sequence"]
        ),
    })
    if fly["destination"] is not None:
        env["S61_FLY_DESTINATION_GROUP"] = str(fly["destination"]["group"])
        env["S61_FLY_DESTINATION_MAP"] = str(fly["destination"]["map"])
        env["S61_FLY_DESTINATION_X"] = str(fly["destination"]["start"][0])
        env["S61_FLY_DESTINATION_Y"] = str(fly["destination"]["start"][1])
    lifecycle = fixtures.get("engine_special_flag_lifecycle")
    if isinstance(lifecycle, Mapping):
        producer = lifecycle["producer"]
        transition = lifecycle["transition"]
        consumer = lifecycle["consumer"]
        env.update({
            "S61_ENGINE_FLAG_ID": str(lifecycle["flag_id"]),
            "S61_ENGINE_FLAG_OWNER": str(int(
                lifecycle["runtime_storage"]["owner_address"], 16,
            )),
            "S61_ENGINE_FLAG_MASK": str(
                lifecycle["runtime_storage"]["bit_mask"]
            ),
            "S61_ENGINE_PRODUCER_GROUP": str(producer["map"][0]),
            "S61_ENGINE_PRODUCER_MAP": str(producer["map"][1]),
            "S61_ENGINE_TRIGGER_VAR": str(producer["trigger_var"]),
            "S61_ENGINE_TRIGGER_VALUE": str(producer["trigger_value"]),
            "S61_ENGINE_SET_SITE": str(producer["set_site"]),
            "S61_ENGINE_DESTINATION_GROUP": str(
                transition["destination_map"][0]
            ),
            "S61_ENGINE_DESTINATION_MAP": str(
                transition["destination_map"][1]
            ),
            "S61_ENGINE_DESTINATION_X": str(
                transition["destination_position"][0]
            ),
            "S61_ENGINE_DESTINATION_Y": str(
                transition["destination_position"][1]
            ),
            "S61_ENGINE_SCENE_VAR": str(transition["scene_var"]),
            "S61_ENGINE_SCENE_VALUE": str(transition["scene_value"]),
            "S61_ENGINE_MAP_ROOT": str(consumer["owner"]["runtime_root"]),
            "S61_ENGINE_CLEAR_SITE": str(consumer["clear_site"]),
        })
        for index, variant in enumerate(producer["variants"]):
            owner = next(
                row for row in producer["record_owners"]
                if row["owner_id"] == variant["coord_owner_id"]
            )
            prefix = f"S61_ENGINE_VARIANT_{index}"
            env.update({
                f"{prefix}_NAME": variant["variant"],
                f"{prefix}_START_X": str(variant["start"][0]),
                f"{prefix}_START_Y": str(variant["start"][1]),
                f"{prefix}_TRIGGER_X": str(variant["trigger_tile"][0]),
                f"{prefix}_TRIGGER_Y": str(variant["trigger_tile"][1]),
                f"{prefix}_KEY": str(KEYS[variant["walk_tokens"][0]]),
                f"{prefix}_TEMPORARY_SIDE": str(
                    variant["temporary_side"]
                ),
                f"{prefix}_COORD_ROOT": str(owner["runtime_root"]),
            })
    return env


_CASE_ID = re.compile(r"[A-Za-z0-9_.-]+\Z")
_OWNER_ID = re.compile(r"[A-Za-z0-9_./:-]+\Z")
_RAW_SHA256 = re.compile(r"[0-9a-f]{64}\Z")
_IDENTITY_ONLY_BRANCH_CONTRACT = (
    "STATE_MATRIX_ALL_CASE_INDEPENDENT_ORACLE"
)
_ALL_CASE_ORACLE_KIND = (
    "STAGE61_ALL_CASE_INDEPENDENT_INTERACTION_ORACLES"
)
_TEXT_PRINTER_ENTRY = "0x08002C44"
_TEXT_PRINTER_PREIMAGE_HEX = "F0B5474680B484B00A9C0B9D0C9F0906"
_TEXT_PRINTER_PREIMAGE_SHA256 = hashlib.sha256(
    bytes.fromhex(_TEXT_PRINTER_PREIMAGE_HEX)
).hexdigest()
_TEMPLATE_TEXT_PRINTER_ENTRY = "0x08002CF0"
_TEMPLATE_TEXT_PRINTER_PREIMAGE_HEX = "F0B5061C944609060D0E034800680028"
_TEMPLATE_TEXT_PRINTER_PREIMAGE_SHA256 = hashlib.sha256(
    bytes.fromhex(_TEMPLATE_TEXT_PRINTER_PREIMAGE_HEX)
).hexdigest()


def validate_catalog_document(
    value: Any, *, expected_rom_sha256: str | None = None,
) -> tuple[dict[str, Any], dict[str, dict[str, Any]]]:
    """builder生成の全NPC×branch catalogを展開し、重複を拒否する。"""
    if not isinstance(value, Mapping) or set(value) != {
        "schema_version", "task", "stage", "rom_sha256", "entries",
    }:
        _fail("NPC catalog root keys不一致")
    if (value.get("schema_version"), value.get("task"), value.get("stage")) \
            != (1, TASK, STAGE):
        _fail("NPC catalog schema/task/stage不一致")
    catalog_rom = value["rom_sha256"]
    if catalog_rom is not None \
            and (not isinstance(catalog_rom, str)
                 or _RAW_SHA256.fullmatch(catalog_rom) is None):
        _fail("NPC catalog rom_sha256はnullまたは小文字SHA-256です")
    if expected_rom_sha256 is not None \
            and catalog_rom != expected_rom_sha256:
        _fail("NPC catalog/Stage61 ROM SHA-256不一致")
    entries = value["entries"]
    if not isinstance(entries, list) or not entries:
        _fail("NPC catalog entriesは非空listが必要です")

    normalized_entries: list[dict[str, Any]] = []
    expanded: dict[str, dict[str, Any]] = {}
    base_ids: set[str] = set()
    bound_matrix_case_ids: set[str] = set()
    for entry_index, entry in enumerate(entries):
        label = f"entries[{entry_index}]"
        legacy_keys = {
            "case_id", "owner_key", "group", "map", "local_id", "object",
            "start", "action", "approach_steps", "branches",
        }
        final_keys = legacy_keys | {"interaction_execution"}
        compact_final_keys = {
            "case_id", "owner_key", "group", "map", "local_id", "object",
            "interaction_execution", "branches",
        }
        enriched_keys = {
            "non_product_shadow_alias", "expected_template_raw_hex",
        }
        if not isinstance(entry, Mapping) or frozenset(entry) not in {
            frozenset(legacy_keys), frozenset(final_keys),
            frozenset(compact_final_keys),
            frozenset(final_keys | enriched_keys),
            frozenset(compact_final_keys | enriched_keys),
        }:
            _fail(f"NPC catalog {label} keys不一致")
        case_id = entry["case_id"]
        owner_key = entry["owner_key"]
        if not isinstance(case_id, str) or _CASE_ID.fullmatch(case_id) is None:
            _fail(f"NPC catalog {label}.case_idは安全なASCII IDではありません")
        if not isinstance(owner_key, str) or _OWNER_ID.fullmatch(owner_key) is None:
            _fail(f"NPC catalog {label}.owner_keyは安全なASCII IDではありません")
        if case_id in base_ids:
            _fail(f"NPC catalog case_id重複: {case_id}")
        base_ids.add(case_id)
        interaction = _catalog_interaction_execution(entry, label)
        branches = entry["branches"]
        if not isinstance(branches, list) or not branches:
            _fail(f"NPC catalog {label}.branchesは非空listが必要です")
        normalized_branches: list[dict[str, Any]] = []
        local_branches: set[str] = set()
        branch_contract_kinds: set[str] = set()
        for branch_index, branch in enumerate(branches):
            branch_label = f"{label}.branches[{branch_index}]"
            identity_only_keys = {
                "branch_id", "identity_only", "semantic_contract",
                "matrix_case_ids", "matrix_case_binding_sha256",
            }
            required_branch_keys = {
                "branch_id", "flags", "choice", "terminal",
                "expected_raw_sha256_any", "expected_utf8_contains_any",
                "require_visible_text", "expect_object_visible",
            }
            optional_branch_keys = {"expected_var_result_values_exact"}
            if not isinstance(branch, Mapping) or not (
                set(branch) == identity_only_keys
                or (
                    required_branch_keys.issubset(branch)
                    and not set(branch)
                    - required_branch_keys - optional_branch_keys
                )
            ):
                _fail(f"NPC catalog {branch_label} keys不一致")
            branch_id = branch["branch_id"]
            if not isinstance(branch_id, str) \
                    or _CASE_ID.fullmatch(branch_id) is None:
                _fail(f"NPC catalog {branch_label}.branch_id不正")
            if branch_id in local_branches:
                _fail(f"NPC catalog branch_id重複: {case_id}/{branch_id}")
            local_branches.add(branch_id)
            if set(branch) == identity_only_keys:
                branch_contract_kinds.add("IDENTITY_ONLY")
                matrix_case_ids = branch["matrix_case_ids"]
                if branch.get("identity_only") is not True \
                        or branch.get("semantic_contract") \
                            != _IDENTITY_ONLY_BRANCH_CONTRACT \
                        or not isinstance(matrix_case_ids, list) \
                        or not matrix_case_ids \
                        or matrix_case_ids != sorted(matrix_case_ids) \
                        or len(matrix_case_ids) != len(set(matrix_case_ids)) \
                        or any(
                            not isinstance(matrix_case_id, str)
                            or _CASE_ID.fullmatch(matrix_case_id) is None
                            for matrix_case_id in matrix_case_ids
                        ):
                    _fail(
                        f"NPC catalog {branch_label} identity-only case binding不正"
                    )
                duplicate_matrix_ids = (
                    set(matrix_case_ids) & bound_matrix_case_ids
                )
                if duplicate_matrix_ids:
                    _fail(
                        "NPC catalog identity-only matrix case重複: "
                        f"{sorted(duplicate_matrix_ids)}"
                    )
                binding_sha256 = branch["matrix_case_binding_sha256"]
                if not isinstance(binding_sha256, str) \
                        or _RAW_SHA256.fullmatch(binding_sha256) is None:
                    _fail(
                        f"NPC catalog {branch_label} matrix binding SHA-256不正"
                    )
                bound_matrix_case_ids.update(matrix_case_ids)
                normalized_branch = {
                    "branch_id": branch_id,
                    "identity_only": True,
                    "semantic_contract": _IDENTITY_ONLY_BRANCH_CONTRACT,
                    "matrix_case_ids": list(matrix_case_ids),
                    "matrix_case_binding_sha256": binding_sha256,
                }
                normalized_branches.append(normalized_branch)
                expanded_id = f"{case_id}--{branch_id}"
                if expanded_id in expanded:
                    _fail(f"NPC catalog expanded case重複: {expanded_id}")
                expanded[expanded_id] = {
                    "case_id": expanded_id,
                    "base_case_id": case_id,
                    "owner_key": owner_key,
                    "interaction": interaction,
                    "branch": normalized_branch,
                }
                continue
            branch_contract_kinds.add("LEGACY_EXPECTATION")
            choice = branch["choice"]
            terminal = branch["terminal"]
            if choice not in {"ADVANCE", "NO", "YES", "CANCEL"}:
                _fail(f"NPC catalog {branch_label}.choice不正")
            if terminal not in {"FIELD_RELEASE", "BATTLE_START"}:
                _fail(f"NPC catalog {branch_label}.terminal不正")
            if branch["require_visible_text"] is not True \
                    or branch["expect_object_visible"] is not True:
                _fail(f"NPC catalog {branch_label} は可視会話branchである必要があります")
            flags = branch["flags"]
            if not isinstance(flags, list) or len(flags) > 64:
                _fail(f"NPC catalog {branch_label}.flagsは0..64 rowsです")
            normalized_flags = []
            flag_ids: set[int] = set()
            for flag_index, flag in enumerate(flags):
                if not isinstance(flag, Mapping) or set(flag) != {"id", "value"}:
                    _fail(f"NPC catalog {branch_label}.flags[{flag_index}]不正")
                flag_id = _int(
                    flag["id"], f"{branch_label}.flags[{flag_index}].id", 65535,
                )
                if not isinstance(flag["value"], bool):
                    _fail(f"NPC catalog {branch_label}.flags[{flag_index}].value不正")
                if flag_id in flag_ids:
                    _fail(f"NPC catalog {branch_label} flag重複: {flag_id}")
                flag_ids.add(flag_id)
                normalized_flags.append({"id": flag_id, "value": flag["value"]})
            raw_hashes = branch["expected_raw_sha256_any"]
            contains = branch["expected_utf8_contains_any"]
            if not isinstance(raw_hashes, list) or any(
                not isinstance(item, str) or _RAW_SHA256.fullmatch(item) is None
                for item in raw_hashes
            ):
                _fail(f"NPC catalog {branch_label}.expected raw SHA不正")
            if not isinstance(contains, list) or any(
                not isinstance(item, str) or not item
                for item in contains
            ):
                _fail(f"NPC catalog {branch_label}.expected UTF-8 token不正")
            if not raw_hashes and not contains:
                _fail(f"NPC catalog {branch_label} は期待表示根拠がありません")
            expected_var_values = branch.get(
                "expected_var_result_values_exact",
            )
            if expected_var_values is not None and (
                not isinstance(expected_var_values, list)
                or len(expected_var_values) > 32
                or any(
                    isinstance(item, bool) or not isinstance(item, int)
                    or item < 0 or item > 65535
                    for item in expected_var_values
                )
                or any(
                    left == right
                    for left, right in zip(
                        expected_var_values, expected_var_values[1:],
                    )
                )
            ):
                _fail(
                    f"NPC catalog {branch_label}.expected VAR_RESULT trace不正"
                )
            expanded_id = f"{case_id}--{branch_id}"
            if expanded_id in expanded:
                _fail(f"NPC catalog expanded case重複: {expanded_id}")
            normalized_branch = {
                "branch_id": branch_id,
                "flags": normalized_flags,
                "choice": choice,
                "terminal": terminal,
                "expected_raw_sha256_any": list(raw_hashes),
                "expected_utf8_contains_any": list(contains),
                "expected_var_result_values_exact": (
                    None if expected_var_values is None
                    else list(expected_var_values)
                ),
                "require_visible_text": True,
                "expect_object_visible": True,
            }
            normalized_branches.append(normalized_branch)
            expanded[expanded_id] = {
                "case_id": expanded_id,
                "base_case_id": case_id,
                "owner_key": owner_key,
                "interaction": interaction,
                "branch": normalized_branch,
            }
        if len(branch_contract_kinds) != 1:
            _fail(
                f"NPC catalog {label} legacy/identity-only branch混在"
            )
        normalized_entry = {
            "case_id": case_id,
            "owner_key": owner_key,
            "group": interaction["group"], "map": interaction["map"],
            "local_id": interaction["local_id"],
            "object": list(interaction["object"]),
            "start": list(interaction["start"]),
            "action": interaction["action"],
            "approach_steps": interaction["approach_steps"],
            "branches": normalized_branches,
        }
        if "interaction_execution" in entry:
            normalized_entry["interaction_execution"] = {
                "trigger": interaction["trigger"],
                "start": list(interaction["start"]),
                "walk_sequence": list(interaction["walk_sequence"]),
                "stance": list(interaction["stance"]),
                "action": interaction["action"],
                "interaction_distance": interaction["interaction_distance"],
                "counter_tile": (
                    None if interaction["counter_tile"] is None
                    else list(interaction["counter_tile"])
                ),
                "actual_walk_required": interaction["actual_walk_required"],
                "actual_walk_exception": deepcopy(
                    interaction["actual_walk_exception"]
                ),
                "walk_path_basis": interaction["walk_path_basis"],
                "direct_script_call_forbidden": True,
            }
        if enriched_keys <= set(entry):
            normalized_entry["non_product_shadow_alias"] = deepcopy(
                interaction["non_product_shadow_alias"],
            )
            normalized_entry["expected_template_raw_hex"] = interaction[
                "expected_template_raw_hex"
            ]
        normalized_entries.append(normalized_entry)
    normalized = {
        "schema_version": 1,
        "task": TASK,
        "stage": STAGE,
        "rom_sha256": catalog_rom,
        "entries": normalized_entries,
    }
    return normalized, expanded


def load_catalog(
    path: Path, *, expected_rom_sha256: str,
) -> tuple[dict[str, Any], dict[str, dict[str, Any]]]:
    if not path.is_file():
        _fail(f"全NPC catalogがありません: {path}")
    try:
        source = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as error:
        _fail(f"全NPC catalogを読めません: {error}")
    normalized, expanded = validate_catalog_document(
        source, expected_rom_sha256=expected_rom_sha256,
    )
    entries = normalized["entries"]
    if any(
        "expected_template_raw_hex" not in entry
        or "non_product_shadow_alias" not in entry
        for entry in entries
    ):
        _fail("strict NPC catalogに独立template/alias契約がありません")
    by_owner = {str(entry["owner_key"]): entry for entry in entries}
    sources = {
        owner_id: entry["non_product_shadow_alias"]
        for owner_id, entry in by_owner.items()
        if isinstance(entry["non_product_shadow_alias"], Mapping)
        and entry["non_product_shadow_alias"].get("role")
            == "NON_PRODUCT_SOURCE"
    }
    canonicals = {
        owner_id: entry["non_product_shadow_alias"]
        for owner_id, entry in by_owner.items()
        if isinstance(entry["non_product_shadow_alias"], Mapping)
        and entry["non_product_shadow_alias"].get("role")
            == "CANONICAL_PHYSICAL_OWNER"
    }
    if set(sources) != {"OBJECT:003/022:000", "OBJECT:003/022:003"} \
            or set(canonicals) != {
                "OBJECT:096/015:007", "OBJECT:096/015:008",
            }:
        _fail("strict NPC catalog canonical shadow exact owner集合drift")
    for source_id, alias in sources.items():
        canonical_id = str(alias["canonical_owner_id"])
        canonical = canonicals.get(canonical_id)
        if canonical is None \
                or canonical.get("source_owner_id") != source_id \
                or canonical.get("canonical_owner_id") != canonical_id \
                or by_owner[source_id]["interaction_execution"][
                    "actual_walk_required"
                ] is not False \
                or by_owner[canonical_id]["interaction_execution"][
                    "actual_walk_required"
                ] is not True:
            _fail(f"strict NPC catalog canonical shadow pair不一致:{source_id}")
    return normalized, expanded


