def _facility_canonical_bytes(value: Any) -> bytes:
    return (
        json.dumps(
            value, ensure_ascii=False, sort_keys=True,
            separators=(",", ":"),
        ) + "\n"
    ).encode("utf-8")


def _facility_component_sha256(value: Any) -> str:
    return _sha256(_facility_canonical_bytes(value))


def _facility_session_scenario_payload(
    family: str, scenario_id: str,
) -> dict[str, Any]:
    try:
        if str(ROOT) not in sys.path:
            sys.path.insert(0, str(ROOT))
        from tools.stage61_interaction_oracle import (
            _facility_scenario_payload as oracle_payload,
        )

        return deepcopy(oracle_payload(family, scenario_id))
    except (ImportError, AttributeError, KeyError, RuntimeError,
            TypeError, ValueError) as error:
        _fail(f"FACILITY_SESSION helper/source payload不一致:{error}")


def _facility_session_manifest() -> dict[str, Any]:
    try:
        if str(ROOT) not in sys.path:
            sys.path.insert(0, str(ROOT))
        from tools.stage61_facility_sessions import SCENARIO_REGISTRIES
    except (ImportError, AttributeError) as error:
        _fail(f"FACILITY_SESSION registry import不一致:{error}")
    rows: list[dict[str, Any]] = []
    for family in ("mirage", "factory", "codex"):
        registry = SCENARIO_REGISTRIES.get(family)
        if not isinstance(registry, Mapping):
            _fail(f"FACILITY_SESSION family registry不正:{family}")
        root = _FACILITY_MIRAGE_ROOT \
            if family == "mirage" else _FACILITY_SHARED_ROOT
        for scenario_id in registry:
            rows.append({
                "ordinal": len(rows),
                "scenario_key": f"{family}/{scenario_id}",
                "family": family,
                "scenario_id": scenario_id,
                "root_address": f"0x{root:08X}",
                "control_id": _FACILITY_CONTROL_IDS[root],
                "prepare_fault_wrapper_required": (
                    family == "factory" and scenario_id == "prepare_error"
                ),
            })
    counts = Counter(row["family"] for row in rows)
    if counts != {"mirage": 33, "factory": 10, "codex": 6} \
            or len(rows) != _FACILITY_SESSION_COUNT \
            or any(
                row["root_address"] != f"0x{_FACILITY_SHARED_ROOT:08X}"
                for row in rows if row["family"] in {"factory", "codex"}
            ):
        _fail("FACILITY_SESSION 33+10+6 registry closure不一致")
    manifest = {
        "schema_version": 1,
        "kind": "STAGE61_FACILITY_SESSION_PRODUCTION_MANIFEST",
        "scenario_count": len(rows),
        "family_counts": dict(counts),
        "shared_root_single_domain": True,
        "cartesian_product_forbidden": True,
        "scenarios": rows,
    }
    manifest["manifest_sha256"] = _facility_component_sha256(manifest)
    return manifest


def _facility_manifest_row(scenario_key: str) -> dict[str, Any]:
    matches = [
        row for row in _facility_session_manifest()["scenarios"]
        if row["scenario_key"] == scenario_key
    ]
    if len(matches) != 1:
        _fail(f"FACILITY_SESSION manifest scenario過不足:{scenario_key}")
    return deepcopy(matches[0])


def _facility_transport_projection(payload: Mapping[str, Any]) -> dict[str, Any]:
    scenario_key = payload["scenario_key"]
    manifest = _facility_manifest_row(scenario_key)
    regions = payload["source_binding"]["ram_regions"]
    if not isinstance(regions, list) or not 1 <= len(regions) <= 3:
        _fail(f"FACILITY_SESSION EWRAM region count不一致:{scenario_key}")
    return {
        "manifest_ordinal": manifest["ordinal"],
        "root_address": payload["source_binding"]["root_address"],
        "trace_sha256": payload["trace_sha256"],
        "resume_points_sha256": _facility_component_sha256(
            payload["resume_points"]
        ),
        "fields_sha256": _facility_component_sha256(payload["fields"]),
        "source_binding_sha256": _facility_component_sha256(
            payload["source_binding"]
        ),
        "initialization_sha256": _facility_component_sha256(
            payload["initialization"]
        ),
        "registry_sha256": _FACILITY_SESSION_REGISTRY_SOURCE_SHA256,
        "region_count": len(regions),
        "regions": deepcopy(regions),
        "source_count": len(payload["source_binding"]["sources"]),
        "export_count": len(payload["source_binding"]["exports"]),
        "prepare_fault_wrapper_required": manifest[
            "prepare_fault_wrapper_required"
        ],
        "payload_size": len(_facility_canonical_bytes(payload)),
    }


def _facility_session_present(value: Any) -> bool:
    if isinstance(value, Mapping):
        return value.get("kind") == "FACILITY_SESSION" or any(
            _facility_session_present(child) for child in value.values()
        )
    if isinstance(value, list):
        return any(_facility_session_present(child) for child in value)
    return False


def _facility_runtime_symbol_environment(
    metadata: Mapping[str, Any], *, required: bool,
    rom_raw: bytes | None = None,
    interaction_abi_path: Path | None = None,
) -> dict[str, str]:
    if not required:
        return {}
    if not isinstance(rom_raw, bytes) or len(rom_raw) != 32 * 1024 * 1024:
        _fail(f"{_FACILITY_PREPARE_ERROR_SEAM}:ROM_REQUIRED")
    runtime = metadata.get("runtime")
    symbols = runtime.get("symbols") if isinstance(runtime, Mapping) else None
    resolved: dict[str, int] = {}
    for environment_name, symbol_name in _FACILITY_RUNTIME_SYMBOLS.items():
        symbol = symbols.get(symbol_name) \
            if isinstance(symbols, Mapping) else None
        if isinstance(symbol, bool) or not isinstance(symbol, int) \
                or not 0x09000000 <= symbol < 0x0A000000 \
                or symbol & 1:
            _fail(f"{_FACILITY_PREPARE_ERROR_SEAM}:{symbol_name}")
        resolved[symbol_name] = symbol
    audit_root = metadata.get("audit")
    audit = audit_root.get("factory_prepare_error_adapter") \
        if isinstance(audit_root, Mapping) else None
    audit_keys = {
        "status", "physical_script", "pointer_patch", "adapter",
        "fault_setter", "original_delegate", "arm_schema",
        "source_binding", "assertions",
    }
    if not isinstance(audit, Mapping) or set(audit) != audit_keys \
            or audit.get("status") != "PASS":
        _fail(f"{_FACILITY_PREPARE_ERROR_SEAM}:AUDIT_SCHEMA")
    adapter_name = _FACILITY_RUNTIME_SYMBOLS[
        "S61_FACTORY_PREPARE_BATTLE_STAGE61_ADAPTER_SYMBOL"
    ]
    setter_name = _FACILITY_RUNTIME_SYMBOLS[
        "S61_FACILITY_TEST_SET_FACTORY_PREPARE_FAULT_SYMBOL"
    ]
    adapter_address = resolved[adapter_name]
    setter_address = resolved[setter_name]
    replacement = struct.pack("<I", adapter_address | 1)
    expected_script = bytearray(_FACILITY_PREPARE_SCRIPT_PREIMAGE)
    expected_script[1:5] = replacement
    script_offset = _FACILITY_PREPARE_SCRIPT_ADDRESS - 0x08000000
    physical_script = audit["physical_script"]
    pointer_patch = audit["pointer_patch"]
    if not isinstance(physical_script, Mapping) \
            or set(physical_script) != {
                "address", "byte_length", "stage60_sha256", "stage61_sha256",
            } \
            or dict(physical_script) != {
                "address": f"0x{_FACILITY_PREPARE_SCRIPT_ADDRESS:08X}",
                "byte_length": len(_FACILITY_PREPARE_SCRIPT_PREIMAGE),
                "stage60_sha256": _FACILITY_PREPARE_SCRIPT_STAGE60_SHA256,
                "stage61_sha256": _sha256(bytes(expected_script)),
            } \
            or rom_raw[
                script_offset:script_offset + len(expected_script)
            ] != bytes(expected_script) \
            or not isinstance(pointer_patch, Mapping) \
            or dict(pointer_patch) != {
                "address": f"0x{_FACILITY_PREPARE_POINTER_SITE:08X}",
                "expected_hex": _FACILITY_PREPARE_POINTER_PREIMAGE,
                "replacement_hex": replacement.hex(),
                "original_target": (
                    f"0x{_FACILITY_PREPARE_ORIGINAL_ENTRY:08X}"
                ),
                "adapter_target": f"0x{adapter_address | 1:08X}",
            }:
        _fail(f"{_FACILITY_PREPARE_ERROR_SEAM}:PHYSICAL_POINTER")

    def span(
        value: Any, *, name: str, address: int, extra: Mapping[str, Any],
    ) -> None:
        if not isinstance(value, Mapping) \
                or set(value) != {
                    "symbol", "address", "byte_length", "sha256", *extra,
                } \
                or value.get("symbol") != name \
                or value.get("address") != f"0x{address:08X}" \
                or isinstance(value.get("byte_length"), bool) \
                or not isinstance(value.get("byte_length"), int) \
                or value["byte_length"] <= 0 \
                or value.get("sha256") != _sha256(rom_raw[
                    address - 0x08000000:
                    address - 0x08000000 + value["byte_length"]
                ]) \
                or any(value.get(key) != expected
                       for key, expected in extra.items()):
            _fail(f"{_FACILITY_PREPARE_ERROR_SEAM}:{name}_SPAN")

    span(
        audit["adapter"], name=adapter_name, address=adapter_address,
        extra={
            "normal_delegate": f"0x{_FACILITY_PREPARE_ORIGINAL_ENTRY:08X}",
        },
    )
    span(
        audit["fault_setter"], name=setter_name, address=setter_address,
        extra={"lifecycle_calls": 0},
    )
    delegate_offset = _FACILITY_PREPARE_ORIGINAL_ENTRY - 0x08000000
    if audit["original_delegate"] != {
        "address": f"0x{_FACILITY_PREPARE_ORIGINAL_ENTRY:08X}",
        "byte_length": _FACILITY_PREPARE_ORIGINAL_SIZE,
        "sha256": _FACILITY_PREPARE_ORIGINAL_SHA256,
    } or _sha256(rom_raw[
        delegate_offset:delegate_offset + _FACILITY_PREPARE_ORIGINAL_SIZE
    ]) != _FACILITY_PREPARE_ORIGINAL_SHA256:
        _fail(f"{_FACILITY_PREPARE_ERROR_SEAM}:ORIGINAL_DELEGATE")
    if audit["arm_schema"] != _FACILITY_PREPARE_ARM_SCHEMA:
        _fail(f"{_FACILITY_PREPARE_ERROR_SEAM}:ARM_SCHEMA")
    assertions = audit["assertions"]
    if not isinstance(assertions, Mapping) \
            or set(assertions) != _FACILITY_PREPARE_ASSERTIONS \
            or any(value is not True for value in assertions.values()):
        _fail(f"{_FACILITY_PREPARE_ERROR_SEAM}:ASSERTIONS")
    sources = audit["source_binding"]
    if not isinstance(sources, list) \
            or [row.get("path") if isinstance(row, Mapping) else None
                for row in sources] != list(_FACILITY_PREPARE_SOURCE_PATHS):
        _fail(f"{_FACILITY_PREPARE_ERROR_SEAM}:SOURCE_BINDING")
    for row in sources:
        path = ROOT / row["path"]
        raw = path.read_bytes()
        if set(row) != {"path", "size", "sha256"} \
                or row["size"] != len(raw) \
                or row["sha256"] != _sha256(raw):
            _fail(f"{_FACILITY_PREPARE_ERROR_SEAM}:SOURCE_SHA")
    environment = {
        environment_name: str(resolved[symbol_name])
        for environment_name, symbol_name in _FACILITY_RUNTIME_SYMBOLS.items()
    }
    if interaction_abi_path is None:
        return environment
    try:
        abi_raw = interaction_abi_path.read_bytes()
        abi = json.loads(abi_raw)
    except (OSError, UnicodeDecodeError, json.JSONDecodeError) as error:
        _fail(f"FACILITY_SESSION_NATIVE_ABI_UNREADABLE:{error}")
    if not isinstance(abi, Mapping) \
            or abi.get("kind") != "STAGE61_INTERACTION_ABI_MANIFEST" \
            or abi.get("status") != "PASS" \
            or abi.get("stage61_sha256") != _sha256(rom_raw) \
            or not isinstance(abi.get("native_abis"), list):
        _fail("FACILITY_SESSION_NATIVE_ABI_ROOT_DRIFT")
    expected_operations = {
        (family, row["operation"])
        for family in ("mirage", "factory", "codex")
        for scenario_id in (
            manifest_id.split("/", 1)[1]
            for manifest_id in (
                item["scenario_key"]
                for item in _facility_session_manifest()["scenarios"]
                if item["family"] == family
            )
        )
        for row in _facility_session_scenario_payload(
            family, scenario_id,
        )["trace"]
        if row["operation"] not in _FACILITY_NON_NATIVE_OPERATIONS
    }
    if expected_operations != set(_FACILITY_NATIVE_OPERATION_SYMBOLS):
        _fail("FACILITY_SESSION_NATIVE_OPERATION_REGISTRY_DRIFT")
    native_by_symbol: dict[str, Mapping[str, Any]] = {}
    for entry in abi["native_abis"]:
        symbol = entry.get("symbol") if isinstance(entry, Mapping) else None
        if symbol not in set(_FACILITY_NATIVE_OPERATION_SYMBOLS.values()) \
                - {adapter_name}:
            continue
        if symbol in native_by_symbol:
            _fail(f"FACILITY_SESSION_NATIVE_ABI_DUPLICATE:{symbol}")
        native_by_symbol[symbol] = entry
    for (family, operation), symbol_name in (
        _FACILITY_NATIVE_OPERATION_SYMBOLS.items()
    ):
        environment_name = _facility_native_environment_name(
            family, operation,
        )
        if symbol_name == adapter_name:
            environment[environment_name] = str(adapter_address)
            continue
        entry = native_by_symbol.get(symbol_name)
        binding = entry.get("rom_binding") \
            if isinstance(entry, Mapping) else None
        source = entry.get("source") if isinstance(entry, Mapping) else None
        try:
            target = int(entry["target_pointer"], 16)
            address = int(binding["address"], 16)
            length = binding["byte_length"]
            source_path = ROOT / source["path"]
            source_raw = source_path.read_bytes()
        except (KeyError, TypeError, ValueError, OSError) as error:
            _fail(f"FACILITY_SESSION_NATIVE_ABI_SCHEMA:{symbol_name}:{error}")
        if entry.get("complete") is not True \
                or entry.get("symbol") != symbol_name \
                or target != address | 1 \
                or isinstance(length, bool) or not isinstance(length, int) \
                or length <= 0 \
                or not 0x09000000 <= address < 0x0A000000 \
                or address & 1 \
                or binding.get("sha256") != _sha256(rom_raw[
                    address - 0x08000000:
                    address - 0x08000000 + length
                ]) \
                or source.get("sha256") != _sha256(source_raw):
            _fail(f"FACILITY_SESSION_NATIVE_ABI_BINDING:{symbol_name}")
        environment[environment_name] = str(address)
    if len(environment) != (
        len(_FACILITY_RUNTIME_SYMBOLS)
        + len(_FACILITY_NATIVE_OPERATION_SYMBOLS)
    ) or environment[
        _facility_native_environment_name("factory", "PrepareBattle")
    ] != environment[
        "S61_FACTORY_PREPARE_BATTLE_STAGE61_ADAPTER_SYMBOL"
    ]:
        _fail("FACILITY_SESSION_NATIVE_ENVIRONMENT_CLOSURE_DRIFT")
    return environment


def _ruin_seal_scenario_payload(
    root: int, scenario_id: str,
) -> dict[str, Any]:
    scenarios = _RUIN_SEAL_SCENARIO_IDS.get(root)
    if scenarios is None or scenario_id not in scenarios:
        _fail(f"RUIN_SEAL_PREFIX scenario未登録:0x{root:08X}:{scenario_id}")
    if scenario_id.startswith("missing_"):
        first_missing = int(scenario_id.rsplit("_", 1)[1])
        seal_values = [index < first_missing for index in range(14)]
        completed = False
    else:
        first_missing = None
        seal_values = [True] * 14
        completed = scenario_id == "completed"
    if completed and (root != _RUIN_SEAL_OBJECT_ROOT
                      or not all(seal_values)):
        _fail("RUIN_SEAL_PREFIX completion prefix不正")
    flags = [
        {"id": identifier, "value": value}
        for identifier, value in zip(
            _RUIN_SEAL_FLAGS, seal_values, strict=True,
        )
    ]
    if root == _RUIN_SEAL_OBJECT_ROOT:
        flags.append({
            "id": _RUIN_SEAL_COMPLETION_FLAG, "value": completed,
        })
    return {
        "fixture_kind": "RUIN_SEAL_PREFIX",
        "root_address": f"0x{root:08X}",
        "scenario_id": scenario_id,
        "first_missing_index": first_missing,
        "all_seals": all(seal_values),
        "completed": completed if root == _RUIN_SEAL_OBJECT_ROOT else None,
        "flags": flags,
        "seal_flag_ids": list(_RUIN_SEAL_FLAGS),
        "completion_flag_id": (
            _RUIN_SEAL_COMPLETION_FLAG
            if root == _RUIN_SEAL_OBJECT_ROOT else None
        ),
        "root_source_binding": deepcopy(dict(
            _RUIN_SEAL_ROOT_ROM_BINDINGS[root]
        )),
        "relation": _RUIN_SEAL_PREFIX_RELATION,
    }


def _fossil_revival_scenario_payload(scenario_id: str) -> dict[str, Any]:
    """Rebuild one of the 13 closed Cinnabar prefix prestates."""
    if scenario_id not in _FOSSIL_REVIVAL_SCENARIO_IDS:
        _fail(f"FOSSIL_REVIVAL scenario未登録:{scenario_id}")
    all_revived = scenario_id == "idle_all_revived"
    if scenario_id.startswith("idle_"):
        revive_state, which = 0, 0
        available = {
            "idle_none": set(),
            "idle_available_helix": {1},
            "idle_available_dome": {2},
            "idle_available_amber": {3},
            "idle_available_helix_amber": {1, 3},
            "idle_available_dome_amber": {2, 3},
            "idle_all_revived": {1, 3},
        }[scenario_id]
    else:
        prefix, name = scenario_id.split("_", 1)
        revive_state = 1 if prefix == "reviving" else 2
        which = {"helix": 1, "dome": 2, "amber": 3}[name]
        available = {which}
    flags: dict[int, bool] = {}
    for fossil_id in (1, 2, 3):
        flags[_FOSSIL_REVIVAL_GOT_FLAGS[fossil_id]] = (
            fossil_id in available
        )
        flags[_FOSSIL_REVIVAL_REVIVED_FLAGS[fossil_id]] = (
            all_revived and fossil_id in available
        )
    items = {
        _FOSSIL_REVIVAL_ITEM_IDS[fossil_id]: int(
            revive_state == 0 and not all_revived
            and fossil_id in available
        )
        for fossil_id in (1, 2, 3)
    }
    return {
        "fixture_kind": "FOSSIL_REVIVAL_STATE",
        "scenario_id": scenario_id,
        "revive_state": revive_state,
        "which_fossil": which,
        "flags": [
            {"id": identifier, "value": value}
            for identifier, value in sorted(flags.items())
        ],
        "items": [
            {"id": identifier, "count": count}
            for identifier, count in sorted(items.items())
        ],
        "prefix_class": (
            "ALL_REVIVED_TERMINAL" if all_revived else
            "IDLE_AVAILABILITY" if revive_state == 0 else
            "REVIVING_SELECTED" if revive_state == 1 else
            "READY_SELECTED"
        ),
        "source_path": _FOSSIL_REVIVAL_MODEL_SOURCE_PATH,
        "source_sha256": _FOSSIL_REVIVAL_MODEL_SOURCE_SHA256,
    }


def _build_gift_storage_transaction_scenarios() -> dict[str, dict[str, Any]]:
    """Return the closed 30-layout GiveMon placement registry.

    This registry contains layout semantics only.  Generated-mon personality,
    OT/profile, Pokédex, and RNG expectations are intentionally owned by the
    pending source-derived opcode-79 oracle ABI and cannot be injected through
    this transport.
    """
    result: dict[str, dict[str, Any]] = {}
    for scenario_id in _GIFT_STORAGE_TRANSACTION_RUNNER_SCENARIO_IDS:
        party_count = 5 if scenario_id == "party_space" else 6
        current_box = 0
        expected_result = 0 if party_count == 5 else 1
        expected_box: int | None = None
        expected_pos: int | None = None
        if scenario_id.startswith("pc_current_box_"):
            current_box = int(scenario_id[-2:])
            equivalence = "PC_CURRENT_BOX"
            expected_box, expected_pos = current_box, 0
        elif scenario_id.startswith("pc_next_box_"):
            current_box = int(scenario_id[-2:])
            equivalence = (
                "PC_NEXT_BOX_WRAP" if current_box == 13 else "PC_NEXT_BOX"
            )
            expected_box, expected_pos = (current_box + 1) % 14, 0
        elif scenario_id == "party_space":
            equivalence = "PARTY_SPACE"
        else:
            equivalence = "STORAGE_FULL"
            expected_result = 2
        result[scenario_id] = {
            "scenario_id": scenario_id,
            "executor_equivalence_class": equivalence,
            "party_count": party_count,
            "current_box": current_box,
            "var_pc_box_to_send_mon": current_box,
            "shown_box_was_full_message": False,
            "expected_result": expected_result,
            "expected_original_box": current_box if party_count == 6 else None,
            "expected_mon_box_id": expected_box,
            "expected_mon_box_pos": expected_pos,
            "expected_var_pc_box_after": (
                expected_box if expected_box is not None else current_box
            ),
            "expected_shown_box_full_after_give": False,
        }
    return result


_GIFT_STORAGE_TRANSACTION_SCENARIOS = (
    _build_gift_storage_transaction_scenarios()
)


def _gift_storage_transaction_sweep_manifest() -> list[dict[str, Any]]:
    """Build the explicit production order for the 30-layout private sweep."""
    if tuple(_GIFT_STORAGE_TRANSACTION_SCENARIOS) \
            != _GIFT_STORAGE_TRANSACTION_RUNNER_SCENARIO_IDS \
            or len(_GIFT_STORAGE_TRANSACTION_SCENARIOS) != 30:
        raise AssertionError("gift/storage 30-layout registry drift")
    return [
        {
            "ordinal": ordinal,
            **deepcopy(_GIFT_STORAGE_TRANSACTION_SCENARIOS[scenario_id]),
        }
        for ordinal, scenario_id in enumerate(
            _GIFT_STORAGE_TRANSACTION_RUNNER_SCENARIO_IDS
        )
    ]


def _normalize_gift_storage_transaction_sweep_manifest(
    value: Any,
) -> list[dict[str, Any]]:
    expected = _gift_storage_transaction_sweep_manifest()
    if not isinstance(value, list) or len(value) != len(expected) \
            or any(not isinstance(row, Mapping) for row in value):
        _fail("GIFT_STORAGE runner sweep manifestはexactly 30 rowsです")
    scenario_ids = [row.get("scenario_id") for row in value]
    if scenario_ids != list(_GIFT_STORAGE_TRANSACTION_RUNNER_SCENARIO_IDS) \
            or len(set(scenario_ids)) != 30:
        _fail("GIFT_STORAGE runner sweep scenario欠落/重複/順序不一致")
    normalized = [deepcopy(dict(row)) for row in value]
    if normalized != expected:
        _fail("GIFT_STORAGE runner sweep expected layout/result不一致")
    result_counts = {
        result: sum(row["expected_result"] == result for row in normalized)
        for result in (0, 1, 2)
    }
    class_counts = {
        name: sum(
            row["executor_equivalence_class"] == name for row in normalized
        )
        for name in (
            "PARTY_SPACE", "PC_CURRENT_BOX", "PC_NEXT_BOX",
            "PC_NEXT_BOX_WRAP", "STORAGE_FULL",
        )
    }
    if result_counts != {0: 1, 1: 28, 2: 1} \
            or class_counts != {
                "PARTY_SPACE": 1, "PC_CURRENT_BOX": 14,
                "PC_NEXT_BOX": 13, "PC_NEXT_BOX_WRAP": 1,
                "STORAGE_FULL": 1,
            }:
        _fail("GIFT_STORAGE runner sweep aggregate不一致")
    return normalized


_GIFT_STORAGE_TRANSACTION_SWEEP_MANIFEST = tuple(
    _normalize_gift_storage_transaction_sweep_manifest(
        _gift_storage_transaction_sweep_manifest()
    )
)


def _normalize_gift_storage_dedicated_fixture_sweep(
    value: Any, registry: Mapping[str, Mapping[str, Any]],
) -> dict[str, Any]:
    """Bind the oracle's 30 private fixtures to the fixed runner order."""
    keys = {
        "schema_version", "fixture_kind", "relation",
        "executor_representative_count", "runner_exhaustive_layout_count",
        "executor_representative_scenario_ids",
        "runner_exhaustive_scenario_ids", "runner_sweep_root",
        "runner_sweep_map_section_id", "scenarios", "assertions",
    }
    if not isinstance(value, Mapping) or set(value) != keys or (
        value.get("schema_version"), value.get("fixture_kind"),
        value.get("relation"), value.get("executor_representative_count"),
        value.get("runner_exhaustive_layout_count"),
        value.get("executor_representative_scenario_ids"),
        value.get("runner_exhaustive_scenario_ids"),
        value.get("runner_sweep_root"),
        value.get("runner_sweep_map_section_id"),
    ) != (
        1, "GIFT_STORAGE_TRANSACTION_STATE",
        _GIFT_STORAGE_TRANSACTION_RELATION, 4, 30,
        list(_GIFT_STORAGE_TRANSACTION_EXECUTOR_SCENARIO_IDS),
        list(_GIFT_STORAGE_TRANSACTION_RUNNER_SCENARIO_IDS),
        _GIFT_STORAGE_TRANSACTION_MAP_SECTION_SOURCE_ROOT,
        _GIFT_STORAGE_TRANSACTION_MAP_SECTION_ID,
    ):
        _fail("GIFT_STORAGE dedicated fixture sweep root schema不一致")
    if value.get("assertions") != {
        "root_executor_uses_four_quotient_representatives": True,
        "runner_registry_contains_all_thirty_layouts": True,
        "runner_layout_fixture_keys_are_unique": True,
        "c6_box_name_never_forks_independently": True,
    }:
        _fail("GIFT_STORAGE dedicated fixture sweep assertions不一致")
    rows = value.get("scenarios")
    row_keys = {
        "scenario_id", "fixture_key", "executor_representative",
        "executor_equivalence_class", "expected_result", "current_box",
        "expected_mon_box_id", "expected_mon_box_pos",
    }
    if not isinstance(rows, list) or len(rows) != 30 \
            or any(not isinstance(row, Mapping) or set(row) != row_keys
                   for row in rows):
        _fail("GIFT_STORAGE dedicated fixture sweep 30-row schema不一致")
    normalized_rows: list[dict[str, Any]] = []
    fixture_keys: list[str] = []
    for ordinal, (raw, layout) in enumerate(zip(
        rows, _GIFT_STORAGE_TRANSACTION_SWEEP_MANIFEST, strict=True,
    )):
        scenario_id = layout["scenario_id"]
        reference = raw.get("fixture_key")
        fixture = registry.get(reference) if isinstance(reference, str) \
            else None
        expected = {
            "scenario_id": scenario_id,
            "fixture_key": reference,
            "executor_representative": scenario_id
                in _GIFT_STORAGE_TRANSACTION_EXECUTOR_SCENARIO_IDS,
            "executor_equivalence_class": layout[
                "executor_equivalence_class"
            ],
            "expected_result": layout["expected_result"],
            "current_box": layout["current_box"],
            "expected_mon_box_id": layout["expected_mon_box_id"],
            "expected_mon_box_pos": layout["expected_mon_box_pos"],
        }
        if dict(raw) != expected \
                or fixture is None \
                or fixture.get("fixture_kind") \
                    != "GIFT_STORAGE_TRANSACTION_STATE" \
                or fixture.get("scenario_id") != scenario_id \
                or _runner_fixture_key(fixture) != reference:
            _fail(
                "GIFT_STORAGE dedicated fixture sweep row不一致:"
                f"{ordinal}:{scenario_id}"
            )
        fixture_keys.append(reference)
        normalized_rows.append(deepcopy(expected))
    if len(set(fixture_keys)) != 30:
        _fail("GIFT_STORAGE dedicated fixture sweep fixture重複")
    result = deepcopy(dict(value))
    result["scenarios"] = normalized_rows
    return result


def _build_rfu_session_scenarios() -> dict[str, dict[str, Any]]:
    """Return the closed, source-derived RFU scenario registry.

    SPECIAL363 is the leader role and SPECIAL364 is the join role.  Mode is
    independent of role: mode 0 (Pokemon Jump) needs two active endpoints and
    mode 1 (Dodrio) needs three.  A direct result 5 is the sole one-endpoint
    cancel case; retry-to-cancel still starts with the real peer topology that
    produced result 8.  The TSV carries only an identifier plus a redundant
    exact tuple, never an executable or user-provided RFU program.
    """
    result: dict[str, dict[str, Any]] = {}
    role_sequences: Mapping[int, tuple[tuple[int, ...], ...]] = {
        363: ((1,), (5,), (8, 1), (8, 5)),
        364: ((1,), (5,), (6,), (8, 1), (8, 5), (8, 6)),
    }
    role_names = {363: "leader", 364: "join"}
    suffixes = {
        (1,): "result1", (5,): "result5", (6,): "result6",
        (8, 1): "retry-result1", (8, 5): "retry-result5",
        (8, 6): "retry-result6",
    }
    for special, sequences in role_sequences.items():
        for mode in (0, 1):
            for sequence in sequences:
                scenario_id = (
                    f"mode{mode}-{role_names[special]}-{suffixes[sequence]}"
                )
                fault_code = (
                    3 if sequence == (8, 6) else
                    2 if sequence[0] == 8 else
                    1 if sequence == (6,) else 0
                )
                result[scenario_id] = {
                    "scenario_id": scenario_id,
                    "special": special,
                    "endpoint_count": (
                        1 if sequence == (5,) else 2 if mode == 0 else 3
                    ),
                    "activity_mode": mode,
                    "result_sequence": list(sequence),
                    "fault_code": fault_code,
                }
    return result


_RFU_SESSION_SCENARIOS = _build_rfu_session_scenarios()


_CENTER_LINK_GROUP_CAPACITIES: Mapping[int, tuple[int, int]] = {
    0: (2, 2),
    1: (2, 2),
    2: (4, 4),
    3: (2, 2),
    5: (2, 5),
}
_CENTER_LINK_GROUP_NAMES: Mapping[int, str] = {
    0: "single-battle",
    1: "double-battle",
    2: "multi-battle",
    3: "trade",
    5: "berry-crush",
}
_CENTER_LINK_SESSION_RELATION = \
    "NATURAL_CENTER_LINK_GROUP_ROLE_RESULT_SEQUENCE"


def _build_center_link_session_scenarios() -> dict[str, dict[str, Any]]:
    """Return the closed Pokemon Center link scenario registry.

    Unlike the Joyful Game Corner RFU profile, these scripts choose their
    activity through VAR_8004 and never write VAR_8005.  Keep the 50 cases in
    a separate kind so an absent minigame-mode writer cannot be fabricated.
    """
    result: dict[str, dict[str, Any]] = {}
    role_sequences: Mapping[int, tuple[tuple[int, ...], ...]] = {
        363: ((1,), (5,), (8, 1), (8, 5)),
        364: ((1,), (5,), (6,), (8, 1), (8, 5), (8, 6)),
    }
    role_names = {363: "leader", 364: "join"}
    suffixes = {
        (1,): "result1", (5,): "result5", (6,): "result6",
        (8, 1): "retry-result1", (8, 5): "retry-result5",
        (8, 6): "retry-result6",
    }
    for special, sequences in role_sequences.items():
        for link_group, (capacity_min, capacity_max) in sorted(
            _CENTER_LINK_GROUP_CAPACITIES.items()
        ):
            for sequence in sequences:
                scenario_id = (
                    f"group{link_group}-{role_names[special]}-"
                    f"{suffixes[sequence]}"
                )
                result[scenario_id] = {
                    "scenario_id": scenario_id,
                    "special": special,
                    "link_group": link_group,
                    "activity": _CENTER_LINK_GROUP_NAMES[link_group],
                    "capacity_min": capacity_min,
                    "capacity_max": capacity_max,
                    "topology_policy": (
                        "LOCAL_CANCEL_BEFORE_DISCOVERY"
                        if sequence == (5,) else
                        "EXACT_SOURCE_CAPACITY"
                        if capacity_min == capacity_max else
                        "MINIMUM_SOURCE_VALID_REPRESENTATIVE"
                    ),
                    "endpoint_count": (
                        1 if sequence == (5,) else capacity_min
                    ),
                    "result_sequence": list(sequence),
                    "fault_code": (
                        3 if sequence == (8, 6) else
                        2 if sequence[0] == 8 else
                        1 if sequence == (6,) else 0
                    ),
                }
    if len(result) != 50:
        raise AssertionError("center link session scenario cardinality drift")
    return result


_CENTER_LINK_SESSION_SCENARIOS = _build_center_link_session_scenarios()


def _rfu_production_sweep_manifest() -> dict[str, Any]:
    scenarios = [{
        "scenario_id": scenario_id,
        "role": "LEADER" if row["special"] == 363 else "JOIN",
        "special": row["special"],
        "activity_mode": row["activity_mode"],
        "result_sequence": list(row["result_sequence"]),
        "fault_code": row["fault_code"],
        "endpoint_count": row["endpoint_count"],
    } for scenario_id, row in sorted(_RFU_SESSION_SCENARIOS.items())]
    manifest = {
        "schema_version": 1,
        "kind": "STAGE61_RFU_PRODUCTION_SWEEP_MANIFEST",
        "required_scenario_ids": [row["scenario_id"] for row in scenarios],
        "required_scenarios": scenarios,
        "count": len(scenarios),
    }
    manifest["manifest_sha256"] = _sha256(
        _stable(manifest).encode("utf-8")
    )
    return manifest


def _rfu_catalog_expected_scenario_ids(
    expected: Mapping[str, Mapping[str, Any]],
) -> list[str]:
    identifiers: list[str] = []
    for case_id in sorted(expected):
        row = expected[case_id]
        controls = row.get("control_requirements", {}).get("external", [])
        rfu = [control for control in controls
               if isinstance(control, Mapping)
               and control.get("kind") == "RFU_SESSION"]
        if len(rfu) > 1:
            _fail(f"RFU production sweep case owner重複: {case_id}")
        if not rfu:
            continue
        scenario_id = rfu[0].get(
            "required_value_in_matrix_case", {}
        ).get("scenario_id")
        sequences = row.get("input_sequences", [])
        if not isinstance(scenario_id, str) \
                or scenario_id not in _RFU_SESSION_SCENARIOS \
                or not isinstance(sequences, list) or len(sequences) != 1:
            _fail(f"RFU production sweep case/sequence不正: {case_id}")
        identifiers.append(scenario_id)
    return identifiers


def _validate_rfu_catalog_exact_set(
    observations: Sequence[Mapping[str, Any]],
    required_scenario_ids: Sequence[str], *, label: str,
) -> dict[str, Any]:
    manifest = _rfu_production_sweep_manifest()
    required = list(required_scenario_ids)
    if any(not isinstance(identifier, str)
           or identifier not in _RFU_SESSION_SCENARIOS
           for identifier in required):
        _fail(f"{label} RFU required scenario ID不正")
    required_counter = Counter(required)
    if any(count != 1 for count in required_counter.values()):
        _fail(f"{label} RFU required scenario ID重複")
    tuples: list[dict[str, Any]] = []
    for index, observation in enumerate(observations):
        if not isinstance(observation, Mapping):
            _fail(f"{label} RFU observation[{index}]不正")
        scenario_id = observation.get("scenario_id")
        expected = _RFU_SESSION_SCENARIOS.get(str(scenario_id))
        row = {
            "scenario_id": scenario_id,
            "role": observation.get("role"),
            "special": observation.get("special"),
            "activity_mode": observation.get("activity_mode"),
            "result_sequence": deepcopy(observation.get("observed_results")),
            "fault_code": observation.get("fault_code"),
            "endpoint_count": observation.get("endpoint_count"),
        }
        expected_row = None if expected is None else {
            "scenario_id": scenario_id,
            "role": "LEADER" if expected["special"] == 363 else "JOIN",
            "special": expected["special"],
            "activity_mode": expected["activity_mode"],
            "result_sequence": list(expected["result_sequence"]),
            "fault_code": expected["fault_code"],
            "endpoint_count": expected["endpoint_count"],
        }
        if row != expected_row or observation.get("exact") is not True \
                or observation.get("actual_validation_gate") \
                    != "_validate_rfu_session_observation" \
                or observation.get("host_memory_writes") != 0:
            _fail(f"{label} RFU scenario ID/tuple/runtime provenance不一致")
        tuples.append(row)
    observed_ids = [str(row["scenario_id"]) for row in tuples]
    observed_counter = Counter(observed_ids)
    if observed_counter != required_counter \
            or any(count != 1 for count in observed_counter.values()):
        _fail(
            f"{label} RFU exact-set不一致: required={sorted(required)} "
            f"observed={sorted(observed_ids)}"
        )
    tuples.sort(key=lambda row: str(row["scenario_id"]))
    complete = sorted(required) == manifest["required_scenario_ids"]
    if complete and (len(tuples) != 20 or len(_RFU_SESSION_SCENARIOS) != 20):
        _fail(f"{label} RFU production 20 scenario closure不一致")
    return {
        "manifest": manifest,
        "required_scenario_ids": sorted(required),
        "observed_scenario_ids": sorted(observed_ids),
        "observed_scenarios": tuples,
        "count": len(tuples),
        "exact_once": True,
        "all_real_mgba": True,
        "failed": 0,
        "host_memory_writes": 0,
        "production_registry_complete": complete,
    }


def _validate_rfu_catalog_two_run_exact_set(
    sweeps: Sequence[Mapping[str, Any]],
) -> None:
    if len(sweeps) < 2:
        _fail("RFU production sweepは独立2 run必須")
    first = sweeps[0]
    if any(sweep != first for sweep in sweeps[1:]):
        _fail("RFU production sweep run間 exact-set drift")


def _rfu_observations_from_catalog_rows(
    rows: Sequence[Mapping[str, Any]],
) -> list[Mapping[str, Any]]:
    observations: list[Mapping[str, Any]] = []
    for row in rows:
        attempts = row.get("input_sequence_attempts", []) \
            if isinstance(row, Mapping) else []
        if not isinstance(attempts, list):
            _fail("RFU catalog aggregate input attempts不正")
        for attempt in attempts:
            observation = attempt.get("rfu_session") \
                if isinstance(attempt, Mapping) else None
            if observation is not None:
                observations.append(observation)
    return observations


