def _validate_center_link_catalog_exact_set(
    observations: Sequence[Mapping[str, Any]],
    required_scenario_ids: Sequence[str], *, label: str,
) -> dict[str, Any]:
    manifest = _center_link_production_sweep_manifest()
    required = list(required_scenario_ids)
    if any(not isinstance(identifier, str)
           or identifier not in _CENTER_LINK_SESSION_SCENARIOS
           for identifier in required):
        _fail(f"{label} CENTER_LINK_SESSION required scenario ID不正")
    tuples: list[dict[str, Any]] = []
    owner_roots: dict[str, set[str]] = {}
    owner_counts: Counter[str] = Counter()
    for index, observation in enumerate(observations):
        if not isinstance(observation, Mapping):
            _fail(f"{label} CENTER_LINK_SESSION observation[{index}]不正")
        scenario_id = observation.get("scenario_id")
        expected = _CENTER_LINK_SESSION_SCENARIOS.get(str(scenario_id))
        row = {
            "scenario_id": scenario_id,
            "role": observation.get("role"),
            "special": observation.get("special"),
            "link_group": observation.get("link_group"),
            "activity": observation.get("activity"),
            "capacity_min": observation.get("capacity_min"),
            "capacity_max": observation.get("capacity_max"),
            "topology_policy": observation.get("topology_policy"),
            "endpoint_count": observation.get("endpoint_count"),
            "result_sequence": deepcopy(observation.get("observed_results")),
            "fault_code": observation.get("fault_code"),
            "calling_root": observation.get("calling_root"),
            "owner_key": observation.get("owner_key"),
        }
        expected_row = None if expected is None else {
            "scenario_id": scenario_id,
            "role": "LEADER" if expected["special"] == 363 else "JOIN",
            "special": expected["special"],
            "link_group": expected["link_group"],
            "activity": expected["activity"],
            "capacity_min": expected["capacity_min"],
            "capacity_max": expected["capacity_max"],
            "topology_policy": expected["topology_policy"],
            "endpoint_count": expected["endpoint_count"],
            "result_sequence": list(expected["result_sequence"]),
            "fault_code": expected["fault_code"],
            "calling_root": observation.get("calling_root"),
            "owner_key": observation.get("owner_key"),
        }
        owner = observation.get("owner_key")
        root = observation.get("calling_root")
        if row != expected_row or observation.get("exact") is not True \
                or observation.get("actual_validation_gate") \
                    != "_validate_center_link_session_observation" \
                or observation.get("host_memory_writes") != 0 \
                or observation.get("host_selector_value_writes") != 0 \
                or not isinstance(owner, str) or not owner \
                or not isinstance(root, str) \
                or re.fullmatch(r"0x[0-9A-F]{8}", root) is None:
            _fail(
                f"{label} CENTER_LINK_SESSION tuple/runtime provenance不一致"
            )
        owner_roots.setdefault(owner, set()).add(root)
        owner_counts[owner] += 1
        tuples.append(row)
    observed_ids = [str(row["scenario_id"]) for row in tuples]
    if Counter(observed_ids) != Counter(required):
        _fail(
            f"{label} CENTER_LINK_SESSION case exact-set不一致: "
            f"required={len(required)} observed={len(observed_ids)}"
        )
    unique_ids = sorted(set(observed_ids))
    complete = unique_ids == manifest["required_scenario_ids"]
    if complete and (
        len(unique_ids) != 50 or len(_CENTER_LINK_SESSION_SCENARIOS) != 50
    ):
        _fail(f"{label} CENTER_LINK_SESSION logical 50 closure不一致")
    tuples.sort(key=lambda row: (
        str(row["scenario_id"]), str(row["owner_key"]),
        str(row["calling_root"]),
    ))
    return {
        "manifest": manifest,
        "required_case_scenario_ids": sorted(required),
        "observed_case_scenario_ids": sorted(observed_ids),
        "observed_scenarios": tuples,
        "attempt_count": len(tuples),
        "logical_unique_scenario_ids": unique_ids,
        "logical_unique_count": len(unique_ids),
        "exact_once_per_catalog_case": True,
        "all_real_mgba": True,
        "failed": 0,
        "host_memory_writes": 0,
        "host_selector_value_writes": 0,
        "physical_owner_count": len(owner_roots),
        "owner_coverage": [{
            "owner_key": owner,
            "calling_roots": sorted(owner_roots[owner]),
            "attempt_count": owner_counts[owner],
        } for owner in sorted(owner_roots)],
        "production_registry_complete": complete,
    }


