def _runner_fixture_key(payload: Mapping[str, Any]) -> str:
    raw = (
        json.dumps(
            payload, ensure_ascii=False, sort_keys=True,
            separators=(",", ":"),
        ) + "\n"
    ).encode("utf-8")
    return _sha256(raw)


def _pokemon_crc16(raw: bytes) -> int:
    """FireRed CalcCRC16WithTableと独立なbitwise CRC witness。"""
    crc = 0x1121
    for value in raw:
        crc ^= value
        for _bit in range(8):
            crc = ((crc >> 1) ^ 0x8408) if crc & 1 else crc >> 1
    return (~crc) & 0xFFFF


def _pc_capacity_runtime_contract(rom_raw: bytes) -> dict[str, Any]:
    """独立oracleのAddPCItem ABIをROM byteへ結び、実mGBAへ渡す。"""
    abi = _runner_control_abi_contract()
    producer = abi["mutation_safe_producers"]["PC_CAPACITY"]
    binding = producer["rom_binding"]
    address = int(binding["address"], 16)
    size = binding["byte_length"]
    offset = address - 0x08000000
    if offset < 0 or offset + size > len(rom_raw):
        _fail("PC_CAPACITY AddPCItem ROM spanが範囲外です")
    digest = _sha256(rom_raw[offset:offset + size])
    if digest != binding["sha256"]:
        _fail(
            "PC_CAPACITY AddPCItem ROM binding SHA-256不一致: "
            f"expected={binding['sha256']} actual={digest}"
        )
    return deepcopy(dict(producer))


def _link_save_cow_runtime_contract(
    metadata: Mapping[str, Any],
) -> dict[str, int]:
    audit = metadata.get("audit")
    contract_owner = audit if isinstance(audit, Mapping) else metadata
    compatibility = contract_owner.get("persistent_state_compatibility")
    contract = compatibility.get("link_save_record_commit") \
        if isinstance(compatibility, Mapping) else None
    if not isinstance(contract, Mapping):
        _fail("metadata SAVE_LINK copy-on-write contractがありません")
    if contract.get("stock_damaged_side_channel_normalized_to_error") \
            is not True:
        _fail("metadata SAVE_LINK stock damaged戻り値正規化契約不一致")
    preflight = contract.get("preflight_before_stock")
    transaction = contract.get("record_only_transaction")
    if not isinstance(preflight, Mapping) or (
        preflight.get("runtime_function"),
        preflight.get("required_complete_generation_count_before_stock"),
        preflight.get("stock_called_when_preflight_fails"),
        preflight.get("preflight_promotes_global_counter"),
        preflight.get("fresh_boot_during_stock_selects"),
        preflight.get("backup_action"),
        preflight.get("stock_partial_logical_ids"),
    ) != (
        "Stage61State_EnsureBackupGeneration", 2, False, False,
        "PROTECTED_EXACT_OLD_BACKUP_C_PLUS_ONE",
        (
            "ALWAYS_SELECT_NEWEST_COMPLETE_THEN_REFRESH_OPPOSITE_AS_"
            "COUNTER_PLUS_ONE_EXACT_OLD_CLONE_WITHOUT_RECORD_INJECTION"
        ),
        [0, 1, 2, 3, 4],
    ):
        _fail("metadata SAVE_LINK preflight契約不一致")
    if not isinstance(transaction, Mapping) or (
        transaction.get("strategy"),
        transaction.get("preflight_callback_boundaries"),
        transaction.get("stock_callback_boundaries"),
        transaction.get("post_callback_boundaries"),
        transaction.get("post_early_invalidation_erase_count"),
        transaction.get("required_backup_initial_states"),
        transaction.get("flash_operations_per_sector"),
        transaction.get("logical_sector_order"),
        transaction.get("per_sector_commit_marker_offset"),
        transaction.get("per_sector_commit_marker_programmed_last"),
        transaction.get("record_bearing_logical_sector"),
        transaction.get("record_bearing_sector_committed_last"),
        transaction.get("source_generation_erased_or_programmed"),
        transaction.get("source_generation_remains_valid_at_every_fault_offset"),
        transaction.get("global_counter_and_first_sector_switch"),
    ) != (
        "COPY_ON_WRITE_COMPLETE_GENERATION_TO_INACTIVE_SLOT",
        57358, 20485, 57359, 1,
        ["TWO_VALID", "EMPTY", "ERROR", "PARTIAL_OR_SINGLE_GENERATION",
         "TORN_STOCK_RETRY"],
        4097, list(range(14)),
        "0x0FF8", True, 13, True,
        False, True, "AFTER_ALL_14_TARGET_SIGNATURE_COMMITS",
    ):
        _fail("metadata SAVE_LINK full COW transaction契約不一致")
    if transaction.get("fresh_boot_selection_by_phase") != {
        "preflight": "EXACT_OLD_SOURCE_OR_COMPLETED_BACKUP",
        "stock": "EXACT_OLD_BACKUP_C_PLUS_ONE",
        "post_before_final_id13_signature": "STOCK_COMPLETE_SOURCE_C",
        "post_after_final_id13_signature":
            "STOCK_AND_S61E_COMPLETE_TARGET_C_PLUS_ONE",
    } or transaction.get("target_invalidated_before_first_clone") != {
        "logical_sector": 13,
        "operation": "ERASE_TARGET_RECORD_SECTOR",
        "purpose": (
            "PREVENT_COUNTER_PLUS_ONE_MIXED_FULL_GENERATION_"
            "BETWEEN_CALLBACK_RETURNS"
        ),
    }:
        _fail("metadata SAVE_LINK fresh selector/early invalidation契約不一致")
    if (
        contract.get("runtime_symbol"), contract.get("record_only_symbol"),
        contract.get("save_type"), contract.get("stock_entry_thumb_pointer"),
        contract.get("stock_entry_modified"),
        contract.get("transaction_sequence"),
    ) != (
        "Stage61State_HandleSavingData", "Stage61State_UpdateRecordOnly",
        "SAVE_LINK_ONLY_1", "0x080DB231", False,
        [
            "PREFLIGHT_ENSURE_TWO_COMPLETE_GENERATIONS",
            "STOCK_SAVE_LINK_IDS_0_TO_4_IN_PLACE",
            "POST_STOCK_COPY_ON_WRITE_FULL_GENERATION_WITH_S61E",
        ],
    ):
        _fail("metadata SAVE_LINK wrapper sequence契約不一致")
    runtime = metadata.get("runtime")
    audit_runtime = contract_owner.get("runtime")
    if not isinstance(runtime, Mapping):
        runtime = audit_runtime
    elif isinstance(audit_runtime, Mapping) \
            and runtime.get("symbols") != audit_runtime.get("symbols"):
        _fail("metadata root/audit runtime symbol集合不一致")
    symbols = runtime.get("symbols") if isinstance(runtime, Mapping) else None
    names = {
        "handle_saving": "Stage61State_HandleSavingData",
        "ensure_backup": "Stage61State_EnsureBackupGeneration",
        "handle_write_sector": "Stage61State_HandleWriteSector",
        "update_record": "Stage61State_UpdateRecordOnly",
    }
    result: dict[str, int] = {}
    for key, name in names.items():
        symbol = symbols.get(name) if isinstance(symbols, Mapping) else None
        if isinstance(symbol, bool) or not isinstance(symbol, int) \
                or symbol < 0x09000000 or symbol >= 0x0A000000:
            _fail(f"metadata {name} symbol不正")
        result[key] = symbol
    result.update({
        "preflight_callbacks": transaction["preflight_callback_boundaries"],
        "stock_callbacks": transaction["stock_callback_boundaries"],
        "post_callbacks": transaction["post_callback_boundaries"],
    })
    return result


def _validate_map_popup_rom_bindings(
    rom_raw: bytes, fixtures: Mapping[str, Any],
) -> None:
    popup = fixtures.get("map_popup_regressions")
    if not isinstance(popup, Mapping):
        _fail("map_popup実走にはbuilder生成map_popup_regressionsが必要です")
    for row in popup["cases"]:
        label = row["case_id"]
        header_offset = row["header_address"] - 0x08000000
        header = rom_raw[header_offset:header_offset + 0x1C]
        if len(header) != 0x1C \
                or _sha256(header) != row["header_sha256"] \
                or header[0x14] != row["runtime_map_section"] \
                or bool(header[0x19] & 0x04) is not row["show_map_name"]:
            _fail(f"map_popup {label} physical header ROM binding不一致")
        pointer = row["expected_name_pointer"]
        pointer_offset = pointer - 0x08000000
        size = row["expected_name_raw_size"]
        raw = rom_raw[pointer_offset:pointer_offset + size]
        if len(raw) != size or not raw or raw[-1] != 0xFF \
                or _sha256(raw) != row["expected_name_raw_sha256"]:
            _fail(f"map_popup {label} independent name raw ROM binding不一致")
        warp = row["stock_warp"]
        record_offset = warp["source_warp_record_address"] - 0x08000000
        record = rom_raw[record_offset:record_offset + 8]
        if record.hex() != warp["source_warp_record_hex"] \
                or record[5] != warp["destination_warp_id"] \
                or record[6] != row["map"] or record[7] != row["group"]:
            _fail(f"map_popup {label} stock warp ROM binding不一致")


def _validate_bill_scope_rom_binding(
    rom: bytes, fixture: Mapping[str, Any], charmap: Mapping[int, str],
) -> dict[str, Any]:
    adapter = fixture["adapter_address"]
    offset = adapter - 0x08000000
    raw = bytes.fromhex(fixture["adapter_raw_hex"])
    if offset < 0 or offset + len(raw) > len(rom) \
            or rom[offset:offset + len(raw)] != raw \
            or _sha256(raw) != fixture["adapter_sha256"]:
        _fail("Bill scope adapter final ROM binding不一致")
    pointer = fixture["text_pointer"]
    text_offset = pointer - 0x08000000
    if text_offset < 0 or text_offset >= len(rom):
        _fail("Bill scope text pointerがROM外です")
    end = rom.find(b"\xFF", text_offset, min(text_offset + 512, len(rom)))
    if end < 0:
        _fail("Bill scope text EOS欠落")
    text_raw = rom[text_offset:end + 1]
    if _sha256(text_raw) != fixture["visible_text_sha256"] \
            or decode_text(text_raw, charmap) != fixture["expected_text_utf8"]:
        _fail("Bill scope independent visible text ROM binding不一致")
    return {"raw": text_raw, "sha256": _sha256(text_raw)}


def _pokedex_bitmap_flag(raw: bytes, national: int) -> bool:
    if not 1 <= national <= len(raw) * 8:
        raise AssertionError(national)
    index = national - 1
    return bool(raw[index // 8] & (1 << (index % 8)))


def _pokedex_bitmap_metrics(
    owned: bytes, seen: bytes,
) -> dict[str, int | bool]:
    return {
        "kanto_seen": sum(
            _pokedex_bitmap_flag(seen, national)
            for national in range(1, _POKEDEX_KANTO_COUNT + 1)
        ),
        "kanto_caught": sum(
            _pokedex_bitmap_flag(owned, national)
            for national in range(1, _POKEDEX_KANTO_COUNT + 1)
        ),
        "national_seen": sum(
            _pokedex_bitmap_flag(seen, national)
            for national in range(1, _POKEDEX_NATIONAL_COUNT + 1)
        ),
        "national_caught": sum(
            _pokedex_bitmap_flag(owned, national)
            for national in range(1, _POKEDEX_NATIONAL_COUNT + 1)
        ),
        "mew_caught": _pokedex_bitmap_flag(owned, 151),
        "has_all_required": all(
            _pokedex_bitmap_flag(owned, national)
            for national in _POKEDEX_HAS_ALL_REQUIRED
        ),
    }


def _normalize_pokedex_fixture(
    raw: Mapping[str, Any], label: str,
) -> dict[str, Any]:
    required = {
        "fixture_kind", "scenario_id", "national_enabled",
        "national_magic", "national_var", "national_flag",
        "owned_hex", "seen_hex", "seen1_hex", "seen2_hex",
        "kanto_seen", "kanto_caught", "national_seen",
        "national_caught", "mew_caught", "has_all_required",
    }
    if set(raw) != required:
        _fail(f"state matrix {label} POKEDEX_LAYOUT keys不正")
    scenario_id = raw["scenario_id"]
    if not isinstance(scenario_id, str) or not scenario_id \
            or len(scenario_id) > 128 \
            or _CASE_ID.fullmatch(scenario_id) is None:
        _fail(f"state matrix {label} POKEDEX_LAYOUT scenario_id不正")
    for key in (
        "national_enabled", "national_flag", "mew_caught",
        "has_all_required",
    ):
        if not isinstance(raw[key], bool):
            _fail(f"state matrix {label} POKEDEX_LAYOUT {key}不正")
    national_magic = _int(
        raw["national_magic"], f"{label}.national_magic", 0xFF,
    )
    national_var = _int(
        raw["national_var"], f"{label}.national_var", 0xFFFF,
    )
    expected_triple = (
        (0xB9, 0x6258, True)
        if raw["national_enabled"] else (0, 0, False)
    )
    if (national_magic, national_var, raw["national_flag"]) \
            != expected_triple:
        _fail(f"state matrix {label} POKEDEX_LAYOUT national triple不一致")
    bitmaps: dict[str, bytes] = {}
    for key in ("owned_hex", "seen_hex", "seen1_hex", "seen2_hex"):
        value = raw[key]
        if not isinstance(value, str) or re.fullmatch(
            rf"[0-9a-f]{{{_POKEDEX_BITMAP_BYTES * 2}}}", value,
        ) is None:
            _fail(f"state matrix {label} POKEDEX_LAYOUT {key}不正")
        bitmaps[key] = bytes.fromhex(value)
    owned = bitmaps["owned_hex"]
    seen = bitmaps["seen_hex"]
    if seen != bitmaps["seen1_hex"] or seen != bitmaps["seen2_hex"]:
        _fail(f"state matrix {label} POKEDEX_LAYOUT seen mirror drift")
    if any(owned_byte & ~seen_byte for owned_byte, seen_byte in zip(
        owned, seen,
    )):
        _fail(f"state matrix {label} POKEDEX_LAYOUT owned⊆seen不一致")
    if any(
        _pokedex_bitmap_flag(bitmap, national)
        for bitmap in (owned, seen)
        for national in range(
            _POKEDEX_NATIONAL_COUNT + 1, _POKEDEX_BITMAP_BYTES * 8 + 1,
        )
    ):
        _fail(f"state matrix {label} POKEDEX_LAYOUT unused tail bit非zero")
    metrics = _pokedex_bitmap_metrics(owned, seen)
    for key, maximum in (
        ("kanto_seen", _POKEDEX_KANTO_COUNT),
        ("kanto_caught", _POKEDEX_KANTO_COUNT),
        ("national_seen", _POKEDEX_NATIONAL_COUNT),
        ("national_caught", _POKEDEX_NATIONAL_COUNT),
    ):
        if _int(raw[key], f"{label}.{key}", maximum) != metrics[key]:
            _fail(f"state matrix {label} POKEDEX_LAYOUT {key} bitmap不一致")
    for key in ("mew_caught", "has_all_required"):
        if raw[key] is not metrics[key]:
            _fail(f"state matrix {label} POKEDEX_LAYOUT {key} bitmap不一致")
    return {
        "fixture_kind": "POKEDEX_LAYOUT", "scenario_id": scenario_id,
        "national_enabled": raw["national_enabled"],
        "national_magic": national_magic, "national_var": national_var,
        "national_flag": raw["national_flag"],
        **{key: raw[key] for key in (
            "owned_hex", "seen_hex", "seen1_hex", "seen2_hex",
        )},
        **metrics,
    }


def _normalize_control_fixture_registry(value: Any) -> dict[str, dict[str, Any]]:
    if value is None:
        return {}
    if not isinstance(value, Mapping) or len(value) > 4096:
        _fail("state matrix runner_fixturesはbounded objectが必要です")
    result: dict[str, dict[str, Any]] = {}
    for digest, raw in sorted(value.items()):
        label = f"runner_fixtures[{digest!r}]"
        if not isinstance(digest, str) or _RAW_SHA256.fullmatch(digest) is None \
                or not isinstance(raw, Mapping):
            _fail(f"state matrix {label} key/payload不正")
        kind = raw.get("fixture_kind")
        if kind not in _CONTROL_FIXTURE_KINDS:
            _fail(f"state matrix {label}.fixture_kind未知")
        if kind == "BAG":
            if set(raw) != {"fixture_kind", "pockets"} \
                    or not isinstance(raw["pockets"], list) \
                    or len(raw["pockets"]) != 5:
                _fail(f"state matrix {label} BAG shape不正")
            pockets = []
            for index, (pocket, count) in enumerate(zip(
                raw["pockets"], _CONTROL_FIXTURE_SLOT_COUNTS,
            )):
                if not isinstance(pocket, Mapping) \
                        or set(pocket) != {"index", "slots"} \
                        or pocket["index"] != index \
                        or not isinstance(pocket["slots"], list) \
                        or len(pocket["slots"]) != count:
                    _fail(f"state matrix {label} BAG pocket[{index}]不正")
                pockets.append({
                    "index": index,
                    "slots": _normalize_control_item_slots(
                        pocket["slots"], f"{label}.pockets[{index}]",
                    ),
                })
            normalized: dict[str, Any] = {
                "fixture_kind": kind, "pockets": pockets,
            }
        elif kind == "PC_ITEMS":
            if set(raw) != {"fixture_kind", "slots"} \
                    or not isinstance(raw["slots"], list) \
                    or len(raw["slots"]) != 30:
                _fail(f"state matrix {label} PC_ITEMS shape不正")
            normalized = {
                "fixture_kind": kind,
                "slots": _normalize_control_item_slots(
                    raw["slots"], f"{label}.slots",
                ),
            }
        elif kind == "PARTY":
            if set(raw) != {"fixture_kind", "count", "raw_hex"}:
                _fail(f"state matrix {label} PARTY keys不正")
            count = _int(raw["count"], f"{label}.count", 6)
            raw_hex = raw["raw_hex"]
            if not isinstance(raw_hex, str) \
                    or re.fullmatch(r"[0-9a-f]{1200}", raw_hex) is None:
                _fail(f"state matrix {label} PARTY raw_hex不正")
            normalized = {
                "fixture_kind": kind, "count": count, "raw_hex": raw_hex,
            }
        elif kind == "STORAGE":
            if set(raw) != {"fixture_kind", "raw_hex"}:
                _fail(f"state matrix {label} STORAGE keys不正")
            raw_hex = raw["raw_hex"]
            if not isinstance(raw_hex, str) \
                    or re.fullmatch(
                        rf"[0-9a-f]{{{0x83D0 * 2}}}", raw_hex,
                    ) is None:
                _fail(f"state matrix {label} STORAGE raw_hex不正")
            normalized = {"fixture_kind": kind, "raw_hex": raw_hex}
        elif kind == "DAYCARE_TRANSACTION_STATE":
            required = {
                "fixture_kind", "scenario_id", "party_count",
                "party_raw_hex", "daycare_raw_hex", "money",
                "pending_daycare_egg_flag", "queued_egg_count",
                "pc_has_space",
            }
            if set(raw) != required \
                    or raw.get("scenario_id") \
                        not in _ALL_DAYCARE_TRANSACTION_SCENARIO_IDS \
                    or not isinstance(
                        raw.get("pending_daycare_egg_flag"), bool
                    ) \
                    or not isinstance(raw.get("pc_has_space"), bool):
                _fail(f"state matrix {label} DAYCARE_TRANSACTION schema不正")
            party_count = _int(
                raw["party_count"], f"{label}.party_count", 6,
            )
            money = _int(raw["money"], f"{label}.money", 999999)
            queued_egg_count = _int(
                raw["queued_egg_count"], f"{label}.queued_egg_count", 5,
            )
            decoded: dict[str, bytes] = {}
            for field, size in (
                ("party_raw_hex", _DAYCARE_TRANSACTION_PARTY_BYTES),
                ("daycare_raw_hex", _DAYCARE_TRANSACTION_DAYCARE_BYTES),
            ):
                raw_hex = raw[field]
                if not isinstance(raw_hex, str) \
                        or re.fullmatch(
                            rf"[0-9a-f]{{{size * 2}}}", raw_hex,
                        ) is None:
                    _fail(
                        f"state matrix {label} DAYCARE_TRANSACTION "
                        f"{field}不正"
                    )
                decoded[field] = bytes.fromhex(raw_hex)
            normalized = {
                "fixture_kind": kind,
                "scenario_id": raw["scenario_id"],
                "party_count": party_count,
                "party_raw_hex": decoded["party_raw_hex"].hex(),
                "daycare_raw_hex": decoded["daycare_raw_hex"].hex(),
                "money": money,
                "pending_daycare_egg_flag": raw[
                    "pending_daycare_egg_flag"
                ],
                "queued_egg_count": queued_egg_count,
                "pc_has_space": raw["pc_has_space"],
            }
            # The binary transport is deliberately not a programmable daycare
            # image.  Reuse the oracle's public fixture validator to bind every
            # byte and scalar to one of the six source-derived representatives.
            try:
                if str(ROOT) not in sys.path:
                    sys.path.insert(0, str(ROOT))
                from tools.stage61_interaction_oracle import runner_fixture_key

                oracle_digest = runner_fixture_key(normalized)
            except (ImportError, AttributeError, RuntimeError,
                    TypeError, ValueError) as error:
                _fail(
                    "state matrix DAYCARE_TRANSACTION source fixture不一致:"
                    f"{error}"
                )
            if oracle_digest != digest:
                _fail(
                    f"state matrix {label} DAYCARE_TRANSACTION oracle SHA不一致"
                )
        elif kind == "PARTY_MOVE_TRANSACTION_STATE":
            required = {
                "fixture_kind", "scenario_id", "family", "party_count",
                "party_raw_hex", "party_selection_sequence",
                "selected_move_slot", "selected_relearn_move",
                "teach_outcome", "expected_relearnable_count",
                "payment_policy", "expected_action",
            }
            scenario_id = raw.get("scenario_id")
            family = raw.get("family")
            sequence = raw.get("party_selection_sequence")
            raw_hex = raw.get("party_raw_hex")
            action = raw.get("expected_action")
            if set(raw) != required \
                    or scenario_id not in \
                        _PARTY_MOVE_TRANSACTION_SCENARIO_IDS \
                    or family not in {"RELEARNER", "DELETER"} \
                    or not isinstance(sequence, list) \
                    or not 1 <= len(sequence) <= 2 \
                    or not isinstance(raw_hex, str) \
                    or re.fullmatch(r"[0-9a-f]{1200}", raw_hex) is None \
                    or not isinstance(action, str) \
                    or re.fullmatch(r"[A-Z][A-Z0-9_]{0,63}", action) is None:
                _fail(
                    f"state matrix {label} PARTY_MOVE_TRANSACTION schema不正"
                )
            party_count = _int(
                raw["party_count"], f"{label}.party_count", 6,
            )
            normalized_sequence = [
                _int(slot, f"{label}.party_selection_sequence[{index}]", 7)
                for index, slot in enumerate(sequence)
            ]
            if any(slot == 6 for slot in normalized_sequence):
                _fail(
                    f"state matrix {label} PARTY_MOVE_TRANSACTION "
                    "party selection範囲外"
                )

            def nullable_uint(
                field: str, maximum: int,
            ) -> int | None:
                field_value = raw[field]
                return None if field_value is None else _int(
                    field_value, f"{label}.{field}", maximum,
                )

            selected_move_slot = nullable_uint("selected_move_slot", 4)
            selected_relearn_move = nullable_uint(
                "selected_relearn_move", 0xFFFF,
            )
            teach_outcome = nullable_uint("teach_outcome", 1)
            expected_relearnable_count = nullable_uint(
                "expected_relearnable_count", 0xFF,
            )
            payment_policy = raw["payment_policy"]
            if payment_policy not in {
                None, "FREE_OVERLAY_NO_MUSHROOM_CONSUMPTION",
            }:
                _fail(
                    f"state matrix {label} PARTY_MOVE_TRANSACTION "
                    "payment policy不正"
                )
            normalized = {
                "fixture_kind": kind,
                "scenario_id": scenario_id,
                "family": family,
                "party_count": party_count,
                "party_raw_hex": raw_hex,
                "party_selection_sequence": normalized_sequence,
                "selected_move_slot": selected_move_slot,
                "selected_relearn_move": selected_relearn_move,
                "teach_outcome": teach_outcome,
                "expected_relearnable_count": expected_relearnable_count,
                "payment_policy": payment_policy,
                "expected_action": action,
            }
            try:
                if str(ROOT) not in sys.path:
                    sys.path.insert(0, str(ROOT))
                from tools.stage61_interaction_oracle import runner_fixture_key

                oracle_digest = runner_fixture_key(normalized)
            except (ImportError, AttributeError, RuntimeError,
                    TypeError, ValueError) as error:
                _fail(
                    "state matrix PARTY_MOVE_TRANSACTION source fixture不一致:"
                    f"{error}"
                )
            if oracle_digest != digest:
                _fail(
                    f"state matrix {label} PARTY_MOVE_TRANSACTION "
                    "oracle SHA不一致"
                )
        elif kind == "GIFT_STORAGE_TRANSACTION_STATE":
            required = {
                "fixture_kind", "scenario_id", "executor_equivalence_class",
                "party_count", "party_raw_hex", "storage_raw_hex",
                "current_box", "var_pc_box_to_send_mon",
                "shown_box_was_full_message", "expected_result",
                "expected_original_box", "expected_mon_box_id",
                "expected_mon_box_pos", "expected_var_pc_box_after",
                "expected_shown_box_full_after_give",
                "fixed_rng_seed", "player_name_hex", "player_gender",
                "player_trainer_id", "map_section_id",
                "map_section_source_root", "lead_has_synchronize",
                "custom_creation_flags", "shiny_charm", "fishing_streak",
                "pokedex_owned_raw_hex", "pokedex_seen_raw_hex",
                "pokedex_seen1_raw_hex", "pokedex_seen2_raw_hex",
            }
            scenario_id = raw.get("scenario_id")
            party_hex = raw.get("party_raw_hex")
            storage_hex = raw.get("storage_raw_hex")
            if set(raw) != required \
                    or scenario_id not in \
                        _GIFT_STORAGE_TRANSACTION_RUNNER_SCENARIO_IDS \
                    or not isinstance(
                        raw.get("shown_box_was_full_message"), bool
                    ) \
                    or not isinstance(
                        raw.get("expected_shown_box_full_after_give"), bool
                    ) \
                    or any(not isinstance(raw.get(field), bool) for field in (
                        "lead_has_synchronize", "custom_creation_flags",
                        "shiny_charm",
                    )) \
                    or not isinstance(party_hex, str) \
                    or re.fullmatch(r"[0-9a-f]{1200}", party_hex) is None \
                    or not isinstance(storage_hex, str) \
                    or re.fullmatch(
                        rf"[0-9a-f]{{{_GIFT_STORAGE_TRANSACTION_STORAGE_BYTES * 2}}}",
                        storage_hex,
                    ) is None:
                _fail(f"state matrix {label} GIFT_STORAGE schema/raw不正")
            pokedex_hex: dict[str, str] = {}
            for field in (
                "pokedex_owned_raw_hex", "pokedex_seen_raw_hex",
                "pokedex_seen1_raw_hex", "pokedex_seen2_raw_hex",
            ):
                field_value = raw[field]
                if not isinstance(field_value, str) \
                        or re.fullmatch(
                            rf"[0-9a-f]{{{_GIFT_STORAGE_TRANSACTION_POKEDEX_BYTES * 2}}}",
                            field_value,
                        ) is None:
                    _fail(f"state matrix {label} GIFT_STORAGE {field}不正")
                pokedex_hex[field] = field_value

            def nullable_uint(field: str, maximum: int) -> int | None:
                field_value = raw[field]
                return None if field_value is None else _int(
                    field_value, f"{label}.{field}", maximum,
                )

            normalized = {
                "fixture_kind": kind,
                "scenario_id": scenario_id,
                "executor_equivalence_class": raw[
                    "executor_equivalence_class"
                ],
                "party_count": _int(
                    raw["party_count"], f"{label}.party_count", 6,
                ),
                "party_raw_hex": party_hex,
                "storage_raw_hex": storage_hex,
                "current_box": _int(
                    raw["current_box"], f"{label}.current_box", 13,
                ),
                "var_pc_box_to_send_mon": _int(
                    raw["var_pc_box_to_send_mon"],
                    f"{label}.var_pc_box_to_send_mon", 13,
                ),
                "shown_box_was_full_message": raw[
                    "shown_box_was_full_message"
                ],
                "expected_result": _int(
                    raw["expected_result"], f"{label}.expected_result", 2,
                ),
                "expected_original_box": nullable_uint(
                    "expected_original_box", 13,
                ),
                "expected_mon_box_id": nullable_uint(
                    "expected_mon_box_id", 13,
                ),
                "expected_mon_box_pos": nullable_uint(
                    "expected_mon_box_pos", 29,
                ),
                "expected_var_pc_box_after": _int(
                    raw["expected_var_pc_box_after"],
                    f"{label}.expected_var_pc_box_after", 13,
                ),
                "expected_shown_box_full_after_give": raw[
                    "expected_shown_box_full_after_give"
                ],
                "fixed_rng_seed": _int(
                    raw["fixed_rng_seed"], f"{label}.fixed_rng_seed",
                    0xFFFFFFFF,
                ),
                "player_name_hex": raw["player_name_hex"],
                "player_gender": _int(
                    raw["player_gender"], f"{label}.player_gender", 1,
                ),
                "player_trainer_id": _int(
                    raw["player_trainer_id"],
                    f"{label}.player_trainer_id", 0xFFFFFFFF,
                ),
                "map_section_id": _int(
                    raw["map_section_id"], f"{label}.map_section_id", 0xFF,
                ),
                "map_section_source_root": raw["map_section_source_root"],
                "lead_has_synchronize": raw["lead_has_synchronize"],
                "custom_creation_flags": raw["custom_creation_flags"],
                "shiny_charm": raw["shiny_charm"],
                "fishing_streak": _int(
                    raw["fishing_streak"], f"{label}.fishing_streak", 0xFF,
                ),
                **pokedex_hex,
            }
            scenario = _GIFT_STORAGE_TRANSACTION_SCENARIOS[scenario_id]
            if {
                key: normalized[key] for key in scenario
            } != scenario:
                _fail(
                    f"state matrix {label} GIFT_STORAGE fixed registry不一致"
                )
            if normalized["fixed_rng_seed"] \
                    != _GIFT_STORAGE_TRANSACTION_RNG_SEED \
                    or normalized["player_name_hex"] \
                    != _GIFT_STORAGE_TRANSACTION_PLAYER_NAME_HEX \
                    or normalized["player_gender"] \
                    != _GIFT_STORAGE_TRANSACTION_PLAYER_GENDER \
                    or normalized["player_trainer_id"] \
                    != _GIFT_STORAGE_TRANSACTION_PLAYER_TRAINER_ID \
                    or normalized["map_section_id"] \
                    != _GIFT_STORAGE_TRANSACTION_MAP_SECTION_ID \
                    or normalized["map_section_source_root"] \
                    != _GIFT_STORAGE_TRANSACTION_MAP_SECTION_SOURCE_ROOT \
                    or normalized["lead_has_synchronize"] is not False \
                    or normalized["custom_creation_flags"] is not False \
                    or normalized["shiny_charm"] is not False \
                    or normalized["fishing_streak"] != 0 \
                    or any(bytes.fromhex(normalized[field]) != bytes(
                        _GIFT_STORAGE_TRANSACTION_POKEDEX_BYTES
                    ) for field in pokedex_hex):
                _fail(
                    f"state matrix {label} GIFT_STORAGE "
                    "RNG/profile/map/Pokedex preimage不一致"
                )
            # Reuse the oracle's public fixture validator so every prestate
            # byte is bound to the canonical 30-layout registry.  The future
            # generated-mon/RNG ABI cannot alter this prestate transport.
            try:
                if str(ROOT) not in sys.path:
                    sys.path.insert(0, str(ROOT))
                from tools.stage61_interaction_oracle import runner_fixture_key

                oracle_digest = runner_fixture_key(normalized)
            except (ImportError, AttributeError, RuntimeError,
                    TypeError, ValueError) as error:
                _fail(
                    "state matrix GIFT_STORAGE source fixture不一致:"
                    f"{error}"
                )
            if oracle_digest != digest:
                _fail(f"state matrix {label} GIFT_STORAGE oracle SHA不一致")
        elif kind == "FOSSIL_REVIVAL_STATE":
            required = {
                "fixture_kind", "scenario_id", "revive_state",
                "which_fossil", "flags", "items", "prefix_class",
                "source_path", "source_sha256",
            }
            scenario_id = raw.get("scenario_id")
            if set(raw) != required \
                    or scenario_id not in _FOSSIL_REVIVAL_SCENARIO_IDS:
                _fail(f"state matrix {label} FOSSIL_REVIVAL schema不一致")
            expected = _fossil_revival_scenario_payload(str(scenario_id))
            normalized = deepcopy(dict(raw))
            if normalized != expected:
                _fail(
                    f"state matrix {label} FOSSIL_REVIVAL source prefix不一致"
                )
            try:
                if str(ROOT) not in sys.path:
                    sys.path.insert(0, str(ROOT))
                from tools.stage61_interaction_oracle import runner_fixture_key

                oracle_digest = runner_fixture_key(normalized)
            except (ImportError, AttributeError, RuntimeError,
                    TypeError, ValueError) as error:
                _fail(
                    "state matrix FOSSIL_REVIVAL source fixture不一致:"
                    f"{error}"
                )
            if oracle_digest != digest:
                _fail(f"state matrix {label} FOSSIL_REVIVAL oracle SHA不一致")
        elif kind == "RUIN_SEAL_PREFIX":
            required = {
                "fixture_kind", "root_address", "scenario_id",
                "first_missing_index", "all_seals", "completed", "flags",
                "seal_flag_ids", "completion_flag_id",
                "root_source_binding", "relation",
            }
            root_text = raw.get("root_address")
            try:
                root = int(root_text, 0) if isinstance(root_text, str) else -1
            except ValueError:
                root = -1
            scenario_id = raw.get("scenario_id")
            if set(raw) != required or root not in _RUIN_SEAL_ROOTS \
                    or scenario_id not in _RUIN_SEAL_SCENARIO_IDS[root]:
                _fail(f"state matrix {label} RUIN_SEAL_PREFIX schema不一致")
            expected = _ruin_seal_scenario_payload(root, str(scenario_id))
            normalized = deepcopy(dict(raw))
            if normalized != expected:
                _fail(
                    f"state matrix {label} RUIN_SEAL_PREFIX "
                    "prefix/root binding不一致"
                )
            try:
                if str(ROOT) not in sys.path:
                    sys.path.insert(0, str(ROOT))
                from tools.stage61_interaction_oracle import runner_fixture_key

                oracle_digest = runner_fixture_key(normalized)
            except (ImportError, AttributeError, RuntimeError,
                    TypeError, ValueError) as error:
                _fail(
                    "state matrix RUIN_SEAL_PREFIX source fixture不一致:"
                    f"{error}"
                )
            if oracle_digest != digest:
                _fail(f"state matrix {label} RUIN_SEAL_PREFIX oracle SHA不一致")
        elif kind == "FACILITY_SESSION":
            required = {
                "fixture_kind", "scenario_key", "family", "scenario_id",
                "reception_branch", "fields", "field_schema", "trace",
                "trace_count", "trace_sha256", "resume_points",
                "source_binding", "initialization", "relation",
            }
            family = raw.get("family")
            scenario_id = raw.get("scenario_id")
            scenario_key = raw.get("scenario_key")
            if set(raw) != required \
                    or family not in {"mirage", "factory", "codex"} \
                    or not isinstance(scenario_id, str) \
                    or scenario_key != f"{family}/{scenario_id}":
                _fail(f"state matrix {label} FACILITY_SESSION schema不一致")
            expected = _facility_session_scenario_payload(
                str(family), scenario_id,
            )
            normalized = deepcopy(dict(raw))
            if _facility_canonical_bytes(normalized) \
                    != _facility_canonical_bytes(expected):
                _fail(
                    f"state matrix {label} FACILITY_SESSION "
                    "helper/source/trace不一致"
                )
            try:
                if str(ROOT) not in sys.path:
                    sys.path.insert(0, str(ROOT))
                from tools.stage61_interaction_oracle import runner_fixture_key

                oracle_digest = runner_fixture_key(normalized)
            except (ImportError, AttributeError, RuntimeError,
                    TypeError, ValueError) as error:
                _fail(
                    "state matrix FACILITY_SESSION source fixture不一致:"
                    f"{error}"
                )
            if oracle_digest != digest:
                _fail(f"state matrix {label} FACILITY_SESSION oracle SHA不一致")
        elif kind == "SIGNED_RAM_SCRIPT":
            required = {
                "fixture_kind", "variant", "wonder_card_offset",
                "wonder_card_raw_hex", "wonder_card_crc_offset",
                "wonder_card_crc", "ram_script_offset",
                "ram_script_raw_hex", "ram_script_data_crc",
                "stored_ram_script_crc", "program_hex", "program_relation",
            }
            variants = {
                "ABSENT_OR_ZERO", "VALID_SET_VAR_RETURN",
                "CORRUPTED_CHECKSUM",
            }
            if set(raw) != required or raw.get("variant") not in variants:
                _fail(f"state matrix {label} SIGNED_RAM_SCRIPT keys不正")
            if raw.get("wonder_card_offset") != 0x32E4 \
                    or raw.get("wonder_card_crc_offset") != 0x32E0 \
                    or raw.get("ram_script_offset") != 0x361C:
                _fail(f"state matrix {label} signed RAM owner offset不正")
            card_hex = raw.get("wonder_card_raw_hex")
            script_hex = raw.get("ram_script_raw_hex")
            program_hex = raw.get("program_hex")
            if not isinstance(card_hex, str) \
                    or re.fullmatch(r"[0-9a-f]{664}", card_hex) is None \
                    or not isinstance(script_hex, str) \
                    or re.fullmatch(r"[0-9a-f]{2008}", script_hex) is None \
                    or not isinstance(program_hex, str) \
                    or re.fullmatch(r"(?:[0-9a-f]{12})?", program_hex) is None:
                _fail(f"state matrix {label} signed RAM raw hex不正")
            card = bytes.fromhex(card_hex)
            script = bytes.fromhex(script_hex)
            program = bytes.fromhex(program_hex)
            card_crc = _int(raw.get("wonder_card_crc"),
                            f"{label}.wonder_card_crc", 0xFFFF)
            data_crc = _int(raw.get("ram_script_data_crc"),
                            f"{label}.ram_script_data_crc", 0xFFFF)
            stored_crc = _int(raw.get("stored_ram_script_crc"),
                              f"{label}.stored_ram_script_crc", 0xFFFFFFFF)
            if card_crc != _pokemon_crc16(card) \
                    or data_crc != _pokemon_crc16(script[4:1003]) \
                    or int.from_bytes(script[:4], "little") != stored_crc:
                _fail(f"state matrix {label} signed RAM CRC不正")
            variant = raw["variant"]
            if variant == "ABSENT_OR_ZERO":
                if any(script[4:]) or program \
                        or raw.get("program_relation") != "NO_RAM_SCRIPT":
                    _fail(f"state matrix {label} absent RAM script不正")
            else:
                expected_stored = data_crc \
                    if variant == "VALID_SET_VAR_RETURN" else data_crc ^ 1
                if script[4:8] != bytes((0x33, 0xFF, 0xFF, 0xFF)) \
                        or program != bytes.fromhex("160480a5610c") \
                        or script[8:14] != program \
                        or stored_crc != expected_stored \
                        or raw.get("program_relation") \
                            != "SET_VAR_8004_61A5_THEN_RETURNRAM":
                    _fail(f"state matrix {label} signed RAM program不正")
            normalized = {
                "fixture_kind": kind, "variant": variant,
                "wonder_card_offset": 0x32E4,
                "wonder_card_raw_hex": card_hex,
                "wonder_card_crc_offset": 0x32E0,
                "wonder_card_crc": card_crc,
                "ram_script_offset": 0x361C,
                "ram_script_raw_hex": script_hex,
                "ram_script_data_crc": data_crc,
                "stored_ram_script_crc": stored_crc,
                "program_hex": program_hex,
                "program_relation": raw["program_relation"],
            }
        else:
            normalized = _normalize_pokedex_fixture(raw, label)
        if _runner_fixture_key(normalized) != digest:
            _fail(f"state matrix {label} canonical SHA-256不一致")
        result[digest] = normalized
    return result


def _normalize_control_item_slots(value: Any, label: str) -> list[dict[str, int]]:
    if not isinstance(value, list):
        _fail(f"state matrix {label} slots不正")
    result = []
    for index, row in enumerate(value):
        if not isinstance(row, Mapping) or set(row) != {
            "item_id", "quantity",
        }:
            _fail(f"state matrix {label}[{index}] slot keys不正")
        result.append({
            "item_id": _int(row["item_id"], f"{label}[{index}].item_id", 0xFFFF),
            "quantity": _int(
                row["quantity"], f"{label}[{index}].quantity", 0xFFFF,
            ),
        })
    return result


def _normalize_input_tokens(value: Any, label: str) -> list[str]:
    if not isinstance(value, list) or not value or len(value) > 128:
        _fail(f"state matrix {label} tokensは1..128です")
    normalized: list[str] = []
    repeated = re.compile(r"(UP|DOWN|LEFT|RIGHT)\*([1-9][0-9]?)\+A\Z")
    for index, raw in enumerate(value):
        if not isinstance(raw, str):
            _fail(f"state matrix {label}.tokens[{index}]文字列不正")
        if raw in _SIMPLE_INPUT_TOKENS:
            normalized.append(raw)
            continue
        if re.fullmatch(r"WAIT_([1-9][0-9]{0,3})", raw):
            if int(raw[5:]) > 3600:
                _fail(f"state matrix {label}.tokens[{index}] WAIT範囲外")
            normalized.append(raw)
            continue
        match = repeated.fullmatch(raw)
        if match is not None:
            count = int(match.group(2))
            normalized.extend([match.group(1)] * count)
            normalized.append("A")
            if len(normalized) > 128:
                _fail(f"state matrix {label} expanded tokensが128超過")
            continue
        _fail(f"state matrix {label}.tokens[{index}]未知token: {raw!r}")
    if normalized[0] not in {"A", "ADVANCE_TEXT"}:
        _fail(f"state matrix {label} は実interaction開始Aが先頭必須です")
    return normalized


def _normalize_input_sequences(value: Any, label: str) -> list[dict[str, Any]]:
    if not isinstance(value, list) or not value or len(value) > 64:
        _fail(f"state matrix {label} input_sequencesは1..64です")
    result = []
    seen: set[str] = set()
    for index, raw in enumerate(value):
        item_label = f"{label}.input_sequences[{index}]"
        if not isinstance(raw, Mapping) or set(raw) != {
            "sequence_id", "tokens", "expected_static_branch_token", "basis",
            "visible_text_expected", "silent_text_basis",
            "text_oracle", "required_postconditions",
            "battle_start_required_postconditions",
            "post_battle_continuation",
        }:
            _fail(f"state matrix {item_label} schema不一致")
        sequence_id = raw["sequence_id"]
        branch_token = raw["expected_static_branch_token"]
        if not isinstance(sequence_id, str) \
                or _CASE_ID.fullmatch(sequence_id) is None \
                or sequence_id in seen:
            _fail(f"state matrix {item_label}.sequence_id不正/重複")
        seen.add(sequence_id)
        if not isinstance(branch_token, str) \
                or _OWNER_ID.fullmatch(branch_token) is None:
            _fail(f"state matrix {item_label}.expected branch token不正")
        basis = raw["basis"]
        required_basis = {"kind", "source_instruction_address"}
        optional_basis = {"menu_id", "result_value"}
        if not isinstance(basis, Mapping) \
                or not required_basis.issubset(basis) \
                or set(basis) - required_basis - optional_basis:
            _fail(f"state matrix {item_label}.basis schema不一致")
        kind = basis["kind"]
        if not isinstance(kind, str) or _CASE_ID.fullmatch(kind) is None:
            _fail(f"state matrix {item_label}.basis.kind不正")
        address = basis["source_instruction_address"]
        if isinstance(address, str) and re.fullmatch(
            r"0x0[89][0-9A-Fa-f]{6}", address,
        ):
            address = int(address, 16)
        address = _int(address, f"{item_label}.basis.address", 0x09FFFFFF)
        if address < 0x08000000:
            _fail(f"state matrix {item_label}.basis.address ROM外")
        normalized_basis: dict[str, Any] = {
            "kind": kind, "source_instruction_address": address,
        }
        for key in optional_basis:
            if key in basis:
                normalized_basis[key] = _int(
                    basis[key], f"{item_label}.basis.{key}", 65535,
                )
        visible_text_expected = raw["visible_text_expected"]
        if not isinstance(visible_text_expected, bool):
            _fail(f"state matrix {item_label}.visible_text_expected不正")
        raw_silent_basis = raw["silent_text_basis"]
        normalized_silent_basis = None
        if visible_text_expected:
            if raw_silent_basis is not None:
                _fail(
                    f"state matrix {item_label} visible pathにsilent basisがあります"
                )
        else:
            if not isinstance(raw_silent_basis, Mapping) or set(
                raw_silent_basis
            ) != {"kind", "source_instruction_addresses", "reason"}:
                _fail(f"state matrix {item_label}.silent_text_basis schema不一致")
            if raw_silent_basis["kind"] != "STATIC_NO_TEXT_PATH":
                _fail(f"state matrix {item_label}.silent_text_basis kind不正")
            silent_addresses = raw_silent_basis[
                "source_instruction_addresses"
            ]
            if not isinstance(silent_addresses, list) or not silent_addresses \
                    or len(silent_addresses) != len(set(silent_addresses)):
                _fail(f"state matrix {item_label}.silent address不正")
            normalized_silent_addresses = []
            for address_index, silent_address in enumerate(silent_addresses):
                if isinstance(silent_address, str) and re.fullmatch(
                    r"0x0[89][0-9A-Fa-f]{6}", silent_address,
                ):
                    silent_address = int(silent_address, 16)
                silent_address = _int(
                    silent_address,
                    f"{item_label}.silent address[{address_index}]",
                    0x09FFFFFF,
                )
                if silent_address < 0x08000000:
                    _fail(f"state matrix {item_label}.silent address ROM外")
                normalized_silent_addresses.append(silent_address)
            reason = raw_silent_basis["reason"]
            if not isinstance(reason, str) or not reason.strip():
                _fail(f"state matrix {item_label}.silent reason不正")
            normalized_silent_basis = {
                "kind": "STATIC_NO_TEXT_PATH",
                "source_instruction_addresses": normalized_silent_addresses,
                "reason": reason,
            }
        battle_start = (
            None
            if raw["battle_start_required_postconditions"] is None
            else _normalize_required_postconditions(
                raw["battle_start_required_postconditions"],
                f"{item_label}.battle_start",
            )
        )
        post_battle = _normalize_post_battle_continuation(
            raw["post_battle_continuation"],
            f"{item_label}.post_battle_continuation",
        )
        if (battle_start is not None) is not (post_battle is not None):
            _fail(f"state matrix {item_label} battle continuation不一致")
        result.append({
            "sequence_id": sequence_id,
            "tokens": _normalize_input_tokens(raw["tokens"], item_label),
            "expected_static_branch_token": branch_token,
            "basis": normalized_basis,
            "visible_text_expected": visible_text_expected,
            "silent_text_basis": normalized_silent_basis,
            "text_oracle": _normalize_text_oracle(
                raw["text_oracle"], item_label,
                visible_text_expected=visible_text_expected,
                expected_sequence_id=sequence_id,
            ),
            "required_postconditions": _normalize_required_postconditions(
                raw["required_postconditions"], item_label,
            ),
            "battle_start_required_postconditions": battle_start,
            "post_battle_continuation": post_battle,
        })
    return result


def _normalize_printer_oracle(value: Any, label: str) -> dict[str, Any]:
    required = {
        "kind", "instruction_address", "caller_instruction_address",
        "source_pointer", "raw_hex", "raw_sha256", "expanded_hex",
        "expanded_sha256", "provenance",
    }
    optional = {
        "ui_coordinates", "menu_id", "menu_choice_index", "runtime_pointer",
        "engine_printer_entries", "engine_printer_abi",
    }
    if not isinstance(value, Mapping) or not required.issubset(value) \
            or set(value) - required - optional:
        _fail(f"state matrix {label}.ordered_printer schema不一致")

    def address(raw: Any, field: str, *, runtime: bool = False) -> int:
        if isinstance(raw, str) and re.fullmatch(
            r"0x[0-9A-Fa-f]{8}", raw,
        ):
            raw = int(raw, 16)
        maximum = 0x0A000000 if runtime else 0x09FFFFFF
        result = _int(raw, f"{label}.{field}", maximum)
        if runtime:
            if not (
                0x02000000 <= result < 0x02040000
                or 0x03000000 <= result < 0x03008000
                or 0x08000000 <= result < 0x0A000000
            ):
                _fail(f"state matrix {label}.{field} GBA owner範囲外")
        elif not 0x08000000 <= result < 0x0A000000:
            _fail(f"state matrix {label}.{field} ROM範囲外")
        return result

    kind = value["kind"]
    if not isinstance(kind, str) \
            or re.fullmatch(r"[A-Z][A-Z0-9_]*", kind) is None:
        _fail(f"state matrix {label}.ordered_printer kind不正")
    instruction = address(value["instruction_address"], "instruction_address")
    if instruction not in {
        int(_TEXT_PRINTER_ENTRY, 16),
        int(_TEMPLATE_TEXT_PRINTER_ENTRY, 16),
    }:
        _fail(f"state matrix {label}.ordered_printer entry不一致")
    caller = address(
        value["caller_instruction_address"], "caller_instruction_address",
    )
    source_pointer = address(value["source_pointer"], "source_pointer")
    raw_hex = value["raw_hex"]
    expanded_hex = value["expanded_hex"]
    if not isinstance(raw_hex, str) or not isinstance(expanded_hex, str):
        _fail(f"state matrix {label}.ordered_printer raw hex不正")
    try:
        raw = bytes.fromhex(raw_hex)
        expanded = bytes.fromhex(expanded_hex)
    except ValueError as error:
        _fail(f"state matrix {label}.ordered_printer hex不正: {error}")
    if not raw or raw[-1] != 0xFF or not expanded or expanded[-1] != 0xFF \
            or len(raw) > 512 or len(expanded) > 512:
        _fail(f"state matrix {label}.ordered_printer EOS/size不正")
    raw_sha = value["raw_sha256"]
    expanded_sha = value["expanded_sha256"]
    if raw_sha != _sha256(raw) or expanded_sha != _sha256(expanded):
        _fail(f"state matrix {label}.ordered_printer SHA-256不一致")
    provenance = value["provenance"]
    if not isinstance(provenance, Mapping) or not provenance:
        _fail(f"state matrix {label}.ordered_printer provenance不正")
    result: dict[str, Any] = {
        "kind": kind,
        "instruction_address": instruction,
        "caller_instruction_address": caller,
        "source_pointer": source_pointer,
        "raw_hex": raw.hex().upper(), "raw_sha256": raw_sha,
        "expanded_hex": expanded.hex().upper(),
        "expanded_sha256": expanded_sha,
        "provenance": deepcopy(dict(provenance)),
    }
    if "runtime_pointer" in value:
        result["runtime_pointer"] = address(
            value["runtime_pointer"], "runtime_pointer", runtime=True,
        )
    if "engine_printer_entries" in value or "engine_printer_abi" in value:
        entries = value.get("engine_printer_entries")
        abi = value.get("engine_printer_abi")
        if not isinstance(entries, list) or not entries \
                or len(entries) != len(set(map(str, entries))) \
                or not isinstance(abi, Mapping) or not abi:
            _fail(f"state matrix {label}.engine printer ABI不正")
        normalized_entries = [
            address(entry, f"engine_printer_entries[{index}]")
            for index, entry in enumerate(entries)
        ]
        allowed_entries = {
            int(_TEXT_PRINTER_ENTRY, 16),
            int(_TEMPLATE_TEXT_PRINTER_ENTRY, 16),
        }
        if not set(normalized_entries) <= allowed_entries \
                or instruction not in normalized_entries:
            _fail(f"state matrix {label}.engine printer entry集合不一致")
        result["engine_printer_entries"] = normalized_entries
        result["engine_printer_abi"] = deepcopy(dict(abi))
    for key in ("menu_id", "menu_choice_index"):
        if key in value:
            result[key] = _int(value[key], f"{label}.{key}", 0xFFFF)
    if "ui_coordinates" in value:
        coordinates = value["ui_coordinates"]
        if type(coordinates) is not list or len(coordinates) != 2:
            _fail(f"state matrix {label}.ui_coordinates不正")
        result["ui_coordinates"] = [
            _int(coordinates[index], f"{label}.ui_coordinates[{index}]", 0xFF)
            for index in range(2)
        ]
    return result


def _normalize_text_oracle(
    value: Any, label: str, *, visible_text_expected: bool = True,
    require_ordered_printers: bool = True,
    expected_sequence_id: str | None = None,
) -> dict[str, Any]:
    required_keys = {
        "meaning_source", "provenance", "ordered_raw_sha256s",
        "allowed_ordered_raw_sha256_sequences", "visible_text_count",
    }
    optional_keys = {"ordered_printers", "allowed_runtime_buffer_ranges"}
    if not isinstance(value, Mapping) \
            or not required_keys.issubset(value) \
            or set(value) - required_keys - optional_keys \
            or (require_ordered_printers and "ordered_printers" not in value):
        _fail(f"state matrix {label}.text_oracle schema不一致")
    meaning = value["meaning_source"]
    if not isinstance(meaning, str) or not meaning.strip():
        _fail(f"state matrix {label}.text_oracle meaning source不正")
    provenance = value["provenance"]
    legacy_provenance_keys = {
        "kind", "source_root", "source_text_addresses", "raw_sha256s",
    }
    independent_provenance_keys = {
        "kind", "source_root", "stage61_root", "sequence_id",
        "not_learned_from_mgba_calibration",
    }
    if not isinstance(provenance, Mapping) or set(provenance) not in {
        frozenset(legacy_provenance_keys),
        frozenset(independent_provenance_keys),
    }:
        _fail(f"state matrix {label}.text_oracle provenance schema不一致")
    for key in ("kind", "source_root"):
        if not isinstance(provenance[key], str) or not provenance[key].strip():
            _fail(f"state matrix {label}.text_oracle provenance {key}不正")
    independent_provenance = set(provenance) \
        == independent_provenance_keys
    if independent_provenance:
        source_root = provenance["source_root"]
        stage61_root = provenance["stage61_root"]
        sequence_id = provenance["sequence_id"]
        if provenance.get("kind") != "INDEPENDENT_STATIC_ORACLE" \
                or provenance.get(
                    "not_learned_from_mgba_calibration"
                ) is not True \
                or not isinstance(source_root, str) \
                or re.fullmatch(r"0x0[89][0-9A-F]{6}", source_root) is None \
                or not isinstance(stage61_root, str) \
                or re.fullmatch(r"0x0[89][0-9A-F]{6}", stage61_root) is None \
                or not isinstance(sequence_id, str) \
                or _CASE_ID.fullmatch(sequence_id) is None \
                or expected_sequence_id is not None \
                and sequence_id != expected_sequence_id:
            _fail(
                f"state matrix {label}.text_oracle independent provenance不正"
            )
        normalized_provenance: dict[str, Any] = {
            "kind": "INDEPENDENT_STATIC_ORACLE",
            "source_root": source_root,
            "stage61_root": stage61_root,
            "sequence_id": sequence_id,
            "not_learned_from_mgba_calibration": True,
        }
    else:
        addresses = provenance["source_text_addresses"]
        if not isinstance(addresses, list) \
                or len(addresses) != len(set(addresses)) \
                or (visible_text_expected and not addresses) \
                or (not visible_text_expected and addresses):
            _fail(f"state matrix {label}.text source address不正")
        normalized_addresses = []
        for index, address in enumerate(addresses):
            if isinstance(address, str) and re.fullmatch(
                r"0x0[89][0-9A-Fa-f]{6}", address,
            ):
                address = int(address, 16)
            address = _int(
                address, f"{label}.text address[{index}]", 0x09FFFFFF,
            )
            if address < 0x08000000:
                _fail(f"state matrix {label}.text address ROM外")
            normalized_addresses.append(address)
        raw_hashes = provenance["raw_sha256s"]
        if not isinstance(raw_hashes, list) \
                or (visible_text_expected and not raw_hashes) \
                or (not visible_text_expected and raw_hashes) \
                or any(not isinstance(item, str)
                       or _RAW_SHA256.fullmatch(item) is None
                       for item in raw_hashes):
            _fail(f"state matrix {label}.text provenance raw hash不正")
        normalized_provenance = {
            "kind": provenance["kind"],
            "source_root": provenance["source_root"],
            "source_text_addresses": normalized_addresses,
            "raw_sha256s": list(raw_hashes),
        }
    ordered = value["ordered_raw_sha256s"]
    allowed = value["allowed_ordered_raw_sha256_sequences"]
    if not isinstance(ordered, list) \
            or (visible_text_expected and not ordered) \
            or (not visible_text_expected and ordered != []) \
            or any(not isinstance(item, str)
                   or _RAW_SHA256.fullmatch(item) is None for item in ordered) \
            or not isinstance(allowed, list) or not allowed \
            or (not visible_text_expected and allowed != [[]]):
        _fail(f"state matrix {label}.text ordered oracle不正")
    normalized_allowed = []
    for index, sequence in enumerate(allowed):
        if not isinstance(sequence, list) \
                or (visible_text_expected and not sequence) \
                or (not visible_text_expected and sequence != []) \
                or any(not isinstance(item, str)
                       or _RAW_SHA256.fullmatch(item) is None
                       for item in sequence):
            _fail(f"state matrix {label}.text allowed[{index}]不正")
        normalized_allowed.append(list(sequence))
    if list(ordered) not in normalized_allowed:
        _fail(f"state matrix {label}.ordered textがallowed集合にありません")
    visible_count = _int(
        value["visible_text_count"], f"{label}.visible_text_count", 64,
    )
    if visible_count != (len(ordered) if visible_text_expected else 0) \
            or (visible_text_expected and visible_count == 0):
        _fail(f"state matrix {label}.visible_text_count不一致")
    printers = value.get("ordered_printers", [])
    if not isinstance(printers, list) \
            or (require_ordered_printers and len(printers) != visible_count) \
            or (not visible_text_expected and printers != []):
        _fail(f"state matrix {label}.ordered_printers count不一致")
    normalized_printers = [
        _normalize_printer_oracle(printer, f"{label}.ordered_printers[{index}]")
        for index, printer in enumerate(printers)
    ]
    printer_hash_key = "raw_sha256" if independent_provenance \
        else "expanded_sha256"
    if require_ordered_printers \
            and [printer[printer_hash_key] for printer in normalized_printers] \
                != list(ordered):
        _fail(f"state matrix {label}.ordered_printers/hash順序不一致")
    runtime_ranges = value.get("allowed_runtime_buffer_ranges", [])
    if not isinstance(runtime_ranges, list) or runtime_ranges:
        _fail(f"state matrix {label}.runtime buffer range未対応/不正")
    result = {
        "meaning_source": meaning,
        "provenance": normalized_provenance,
        "ordered_printers": normalized_printers,
        "ordered_raw_sha256s": list(ordered),
        "allowed_ordered_raw_sha256_sequences": normalized_allowed,
        "visible_text_count": visible_count,
    }
    if "allowed_runtime_buffer_ranges" in value:
        result["allowed_runtime_buffer_ranges"] = []
    return result


_EFFECT_FIELD_WHITELISTS: Mapping[str, set[str]] = {
    "objects": {
        "map", "current", "previous", "invisible", "visible",
        "template", "template_hide_flag", "template_graphics",
    },
    "warps": {
        "position", "location", "continue", "dynamic", "last_heal",
        "escape", "destination", "group", "map", "warp_id", "x", "y",
    },
    "battles": {"active", "trainer_opponent", "enemy_species", "outcome"},
    "party": {"count", "records", "slots"},
    "storage": {"hash"},
}
_EFFECT_OPERATIONS: Mapping[str, set[str]] = {
    "flags": {"SET", "CLEAR"},
    "engine_special_flags": {"SET", "CLEAR"},
    "vars": {"ASSIGN", "INCREMENT", "DECREMENT"},
    "items": {"ADD", "REMOVE", "ASSIGN"},
    "trainers": {"SET", "CLEAR"},
    "money": {"INCREASE", "DECREASE", "ASSIGN"},
    "berry_powder": {"INCREASE", "DECREASE", "ASSIGN"},
    "coins": {"INCREASE", "DECREASE", "ASSIGN"},
}


def _normalize_effect_operations(
    value: Any, *, kind: str, label: str,
) -> list[str]:
    allowed = _EFFECT_OPERATIONS[kind]
    if not isinstance(value, list) or not value \
            or any(item not in allowed for item in value) \
            or len(value) != len(set(value)):
        _fail(f"state matrix {label}.operations不正")
    return sorted(value)


def _normalize_allowed_post_effects(value: Any, label: str) -> dict[str, Any]:
    if not isinstance(value, Mapping) or set(value) != _POST_EFFECT_KEYS:
        _fail(f"state matrix {label}.allowed_post_effects keys不一致")
    normalized: dict[str, Any] = {}
    for kind in sorted(_POST_EFFECT_KEYS):
        rows = value[kind]
        if not isinstance(rows, list) or len(rows) > 128:
            _fail(f"state matrix {label}.allowed_post_effects.{kind}不正")
        result = []
        seen: set[Any] = set()
        for index, row in enumerate(rows):
            row_label = f"{label}.allowed_post_effects.{kind}[{index}]"
            if not isinstance(row, Mapping):
                _fail(f"state matrix {row_label} schema不一致")
            normalized_row: dict[str, Any]
            if kind in {
                "flags", "engine_special_flags", "vars", "items", "trainers",
            }:
                if set(row) not in ({"id", "operations"},
                                    {"id", "operations", "meaning"}):
                    _fail(f"state matrix {row_label} keys不一致")
                maximum = {
                    "flags": 0x18FF, "engine_special_flags": 0x407F,
                    "vars": 0x51FF,
                    "items": 0xFFFF, "trainers": 0x2FF,
                }[kind]
                identifier = _int(row["id"], f"{row_label}.id", maximum)
                if kind == "engine_special_flags" and not (
                    0x4000 <= identifier <= 0x407F
                ):
                    _fail(f"state matrix {row_label}.id engine flag範囲外")
                if kind == "vars" and not (
                    0x4000 <= identifier <= 0x40FF
                    or 0x5000 <= identifier <= 0x51FF
                ):
                    _fail(f"state matrix {row_label}.id var namespace gap")
                normalized_row = {
                    "id": identifier,
                    "operations": _normalize_effect_operations(
                        row["operations"], kind=kind, label=row_label,
                    ),
                }
                identity: Any = identifier
            elif kind == "objects":
                if set(row) != {"local_id", "meaning", "allowed_fields"}:
                    _fail(f"state matrix {row_label} keys不一致")
                identity = _int(row["local_id"], f"{row_label}.local_id", 255)
                normalized_row = {"local_id": identity}
            elif kind == "warps":
                if set(row) != {"owner", "meaning", "allowed_fields"}:
                    _fail(f"state matrix {row_label} keys不一致")
                owner = row["owner"]
                if owner not in {
                    "position", "location", "continue", "dynamic",
                    "last_heal", "escape", "destination",
                }:
                    _fail(f"state matrix {row_label}.owner不正")
                identity = owner
                normalized_row = {"owner": owner}
            elif kind == "battles":
                if set(row) != {"meaning", "allowed_fields"}:
                    _fail(f"state matrix {row_label} keys不一致")
                identity = index
                normalized_row = {}
            elif kind in {"party", "storage"}:
                if set(row) != {"meaning", "allowed_fields"}:
                    _fail(f"state matrix {row_label} keys不一致")
                identity = index
                normalized_row = {}
            elif kind in {"money", "berry_powder", "coins"}:
                required = {"meaning", "operations"}
                required |= {"owner"} if kind == "berry_powder" else set()
                optional = {"owner"} if kind == "coins" else set()
                if not required.issubset(row) or set(row) - required - optional:
                    _fail(f"state matrix {row_label} keys不一致")
                owner = row.get("owner", kind)
                if kind == "coins" and owner not in {"vega", "cfru"}:
                    _fail(f"state matrix {row_label}.owner不正")
                if kind == "berry_powder" and owner != "BERRY_POWDER:0":
                    _fail(f"state matrix {row_label}.owner不正")
                identity = owner
                normalized_row = {
                    **({"owner": owner}
                       if kind in {"berry_powder", "coins"} else {}),
                    "operations": _normalize_effect_operations(
                        row["operations"], kind=kind, label=row_label,
                    ),
                }
            elif kind == "persistent":
                if set(row) != {"block", "start", "end", "meaning"}:
                    _fail(f"state matrix {row_label} keys不一致")
                block = row["block"]
                if block not in _SAVE_BLOCK_SIZES:
                    _fail(f"state matrix {row_label}.block不正")
                start = _int(
                    row["start"], f"{row_label}.start",
                    _SAVE_BLOCK_SIZES[block] - 1,
                )
                end = _int(
                    row["end"], f"{row_label}.end",
                    _SAVE_BLOCK_SIZES[block],
                )
                if end <= start:
                    _fail(f"state matrix {row_label} range不正")
                if any(
                    prior["block"] == block
                    and start < prior["end"] and prior["start"] < end
                    for prior in result
                ):
                    _fail(f"state matrix {row_label} persistent range重複")
                identity = (block, start, end)
                normalized_row = {
                    "block": block, "start": start, "end": end,
                }
            elif kind in {"sounds", "graphics"}:
                if set(row) != {"id", "meaning"}:
                    _fail(f"state matrix {row_label} keys不一致")
                identity = _int(row["id"], f"{row_label}.id", 0xFFFFFFFF)
                normalized_row = {"id": identity}
            elif kind == "specials":
                if set(row) != {
                    "id", "meaning", "allowed_logical_fields",
                }:
                    _fail(f"state matrix {row_label} keys不一致")
                identity = _int(row["id"], f"{row_label}.id", 0xFFFF)
                normalized_row = {"id": identity}
            elif kind == "natives":
                if set(row) != {
                    "pointer", "symbol", "meaning", "allowed_logical_fields",
                }:
                    _fail(f"state matrix {row_label} keys不一致")
                pointer = row["pointer"]
                if isinstance(pointer, str) and re.fullmatch(
                    r"0x0[89][0-9A-Fa-f]{6}", pointer,
                ):
                    pointer = int(pointer, 16)
                pointer = _int(pointer, f"{row_label}.pointer", 0x09FFFFFF)
                if pointer < 0x08000000:
                    _fail(f"state matrix {row_label}.pointer ROM外")
                symbol = row["symbol"]
                if not isinstance(symbol, str) or _OWNER_ID.fullmatch(symbol) is None:
                    _fail(f"state matrix {row_label}.symbol不正")
                identity = pointer
                normalized_row = {"pointer": pointer, "symbol": symbol}
            else:  # pragma: no cover - exhaustive constant contract
                raise AssertionError(kind)
            if identity in seen:
                _fail(f"state matrix {row_label} owner/ID重複")
            seen.add(identity)
            if "meaning" in row:
                if not isinstance(row["meaning"], str) or not row["meaning"].strip():
                    _fail(f"state matrix {row_label}.meaning不正")
                normalized_row["meaning"] = row["meaning"]
            fields_key = "allowed_logical_fields" \
                if kind in {"specials", "natives"} else "allowed_fields"
            if fields_key in row:
                fields = row[fields_key]
                if not isinstance(fields, list) or not fields \
                        or len(fields) != len(set(fields)) \
                        or any(not isinstance(field, str)
                               or _CASE_ID.fullmatch(field) is None
                               for field in fields):
                    _fail(f"state matrix {row_label}.{fields_key}不正")
                whitelist = _EFFECT_FIELD_WHITELISTS.get(kind)
                if whitelist is not None and not set(fields) <= whitelist:
                    _fail(f"state matrix {row_label}.{fields_key}未知field")
                normalized_row[fields_key] = sorted(fields)
            result.append(normalized_row)
        normalized[kind] = result
    return normalized


def _normalize_required_postconditions(value: Any, label: str) -> dict[str, Any]:
    keys = {
        "flags", "engine_special_flags", "vars", "items", "trainers",
        "objects", "warp",
        "battle", "money", "berry_powder", "coins", "party", "storage",
        "persistent",
    }
    if not isinstance(value, Mapping) or set(value) != keys:
        _fail(f"state matrix {label}.required_postconditions keys不一致")
    result: dict[str, Any] = {}
    for kind, value_key, maximum, value_maximum in (
        ("flags", "value", 0x18FF, None),
        ("engine_special_flags", "value", 0x407F, None),
        ("vars", "value", 0x51FF, 0xFFFF),
        ("items", "count", 0xFFFF, 999),
        ("trainers", "defeated", 0x2FF, None),
    ):
        rows = value[kind]
        if not isinstance(rows, list) or len(rows) > 128:
            _fail(f"state matrix {label}.required.{kind}不正")
        identifiers: list[int] = []
        normalized_rows = []
        for index, row in enumerate(rows):
            if not isinstance(row, Mapping) or set(row) != {"id", value_key}:
                _fail(f"state matrix {label}.required.{kind}[{index}]不正")
            identifier = _int(
                row["id"], f"{label}.required.{kind}[{index}].id", maximum,
            )
            if kind == "engine_special_flags" and not (
                0x4000 <= identifier <= 0x407F
            ):
                _fail(f"state matrix {label}.required.{kind} ID範囲外")
            if kind == "vars" and not (
                0x4000 <= identifier <= 0x40FF
                or 0x5000 <= identifier <= 0x51FF
            ):
                _fail(f"state matrix {label}.required.vars namespace gap")
            identifiers.append(identifier)
            expected = row[value_key]
            if kind in {"flags", "engine_special_flags", "trainers"}:
                if not isinstance(expected, bool):
                    _fail(f"state matrix {label}.required.{kind} bool不正")
            else:
                expected = _int(
                    expected, f"{label}.required.{kind}[{index}].{value_key}",
                    int(value_maximum),
                )
            normalized_rows.append({"id": identifier, value_key: expected})
        if identifiers != sorted(set(identifiers)):
            _fail(f"state matrix {label}.required.{kind} ID順序/重複不正")
        result[kind] = normalized_rows

    objects = value["objects"]
    if not isinstance(objects, list) or len(objects) > 128:
        _fail(f"state matrix {label}.required.objects不正")
    normalized_objects: list[dict[str, Any]] = []
    object_ids: list[int] = []
    object_key_sets = {
        frozenset({"local_id", "after"}),
        frozenset({"local_id", "template_after_fnv1a64"}),
        frozenset({"local_id", "after", "template_after_fnv1a64"}),
    }
    runtime_after_keys = {
        "map", "invisible", "visible", "current", "previous",
    }
    for index, row in enumerate(objects):
        row_label = f"{label}.required.objects[{index}]"
        if not isinstance(row, Mapping) \
                or frozenset(row) not in object_key_sets:
            _fail(f"state matrix {row_label} nested exact schema不一致")
        local_id = _int(row["local_id"], f"{row_label}.local_id", 255)
        normalized_row: dict[str, Any] = {"local_id": local_id}
        if "after" in row:
            after = row["after"]
            if after is None:
                normalized_row["after"] = None
            else:
                if not isinstance(after, Mapping) \
                        or set(after) != runtime_after_keys:
                    _fail(f"state matrix {row_label}.after schema不一致")
                map_id = after["map"]
                match = re.fullmatch(
                    r"([0-9]{1,3})/([0-9]{1,3})", map_id,
                ) if isinstance(map_id, str) else None
                if match is None \
                        or any(int(item) > 255 for item in match.groups()) \
                        or map_id != f"{int(match.group(1))}/{int(match.group(2))}":
                    _fail(f"state matrix {row_label}.after.map不正")
                invisible = after["invisible"]
                visible = after["visible"]
                if not isinstance(invisible, bool) \
                        or not isinstance(visible, bool) \
                        or visible is not (not invisible):
                    _fail(f"state matrix {row_label}.after visibility不正")
                points: dict[str, list[int]] = {}
                for key in ("current", "previous"):
                    point = after[key]
                    if not isinstance(point, list) or len(point) != 2 \
                            or any(isinstance(item, bool)
                                   or not isinstance(item, int)
                                   or not -32768 <= item <= 32767
                                   for item in point):
                        _fail(f"state matrix {row_label}.after.{key}不正")
                    points[key] = list(point)
                normalized_row["after"] = {
                    "map": map_id,
                    "invisible": invisible,
                    "visible": visible,
                    **points,
                }
        if "template_after_fnv1a64" in row:
            digest = row["template_after_fnv1a64"]
            if not isinstance(digest, str) \
                    or re.fullmatch(r"[0-9A-F]{16}", digest) is None:
                _fail(
                    f"state matrix {row_label}.template_after_fnv1a64不正"
                )
            normalized_row["template_after_fnv1a64"] = digest
        object_ids.append(local_id)
        normalized_objects.append(normalized_row)
    if object_ids != sorted(set(object_ids)):
        _fail(f"state matrix {label}.required.objects ID順序/重複不正")
    result["objects"] = normalized_objects

    warp = value["warp"]
    warp_owners = {
        "position", "location", "continue", "dynamic", "last_heal",
        "escape", "destination",
    }
    if warp is None:
        result["warp"] = None
    else:
        if not isinstance(warp, Mapping) or not warp \
                or not set(warp) <= warp_owners:
            _fail(f"state matrix {label}.required.warp owner schema不正")
        normalized_warp: dict[str, Any] = {}
        for owner in sorted(warp):
            raw_owner = warp[owner]
            owner_label = f"{label}.required.warp.{owner}"
            if owner == "position":
                if not isinstance(raw_owner, list) or len(raw_owner) != 2:
                    _fail(f"state matrix {owner_label} point schema不正")
                normalized_warp[owner] = [
                    _int(item, f"{owner_label}[{index}]", 0xFFFF)
                    for index, item in enumerate(raw_owner)
                ]
                continue
            if not isinstance(raw_owner, Mapping) or set(raw_owner) != {
                "group", "map", "warp_id", "x", "y",
            }:
                _fail(f"state matrix {owner_label} nested exact schema不正")
            normalized_owner = {
                key: _int(raw_owner[key], f"{owner_label}.{key}", 255)
                for key in ("group", "map", "warp_id")
            }
            for key in ("x", "y"):
                coordinate = raw_owner[key]
                if isinstance(coordinate, bool) \
                        or not isinstance(coordinate, int) \
                        or not -32768 <= coordinate <= 32767:
                    _fail(f"state matrix {owner_label}.{key}範囲外")
                normalized_owner[key] = coordinate
            normalized_warp[owner] = normalized_owner
        result["warp"] = normalized_warp

    battle = value["battle"]
    if battle is None:
        result["battle"] = None
    else:
        if not isinstance(battle, Mapping) or set(battle) != {
            "active", "trainer_opponent", "enemy_species", "outcome",
        } or not isinstance(battle["active"], bool):
            _fail(f"state matrix {label}.required.battle schema不一致")
        result["battle"] = {
            "active": battle["active"],
            "trainer_opponent": _int(
                battle["trainer_opponent"],
                f"{label}.required.battle.trainer_opponent", 0xFFFF,
            ),
            "enemy_species": _int(
                battle["enemy_species"],
                f"{label}.required.battle.enemy_species", 0xFFFF,
            ),
            "outcome": _int(
                battle["outcome"], f"{label}.required.battle.outcome", 0xFF,
            ),
        }

    money = value["money"]
    result["money"] = None if money is None else _int(
        money, f"{label}.required.money", 999999,
    )
    berry_powder = value["berry_powder"]
    result["berry_powder"] = (
        None if berry_powder is None else _int(
            berry_powder, f"{label}.required.berry_powder", 99999,
        )
    )
    coins = value["coins"]
    if coins is None:
        result["coins"] = None
    else:
        if not isinstance(coins, Mapping) or not coins \
                or not set(coins) <= {"vega", "cfru"}:
            _fail(f"state matrix {label}.required.coins owner schema不正")
        result["coins"] = {
            owner: _int(
                coins[owner], f"{label}.required.coins.{owner}",
                9999 if owner == "vega" else 0xFFFFFFFF,
            )
            for owner in sorted(coins)
        }

    party = value["party"]
    if party is None:
        result["party"] = None
    else:
        if not isinstance(party, Mapping) or set(party) != {
            "count", "raw_sha256", "raw_byte_length",
        }:
            _fail(f"state matrix {label}.required.party schema不一致")
        digest = party["raw_sha256"]
        if not isinstance(digest, str) \
                or _RAW_SHA256.fullmatch(digest) is None \
                or party["raw_byte_length"] != 600:
            _fail(f"state matrix {label}.required.party raw SHA/length不正")
        result["party"] = {
            "count": _int(
                party["count"], f"{label}.required.party.count", 6,
            ),
            "raw_sha256": digest,
            "raw_byte_length": 600,
        }

    storage = value["storage"]
    if storage is None:
        result["storage"] = None
    else:
        if not isinstance(storage, Mapping) or set(storage) != {
            "raw_sha256", "raw_byte_length",
        } or not isinstance(storage["raw_sha256"], str) \
                or _RAW_SHA256.fullmatch(storage["raw_sha256"]) is None \
                or storage["raw_byte_length"] != 0x83D0:
            _fail(f"state matrix {label}.required.storage schema不一致")
        result["storage"] = deepcopy(dict(storage))

    persistent = value["persistent"]
    if not isinstance(persistent, list) or len(persistent) > 512:
        _fail(f"state matrix {label}.required.persistent不正")
    normalized_persistent = []
    persistent_ids: list[tuple[str, int]] = []
    for index, row in enumerate(persistent):
        row_label = f"{label}.required.persistent[{index}]"
        if not isinstance(row, Mapping) or set(row) != {
            "block", "offset", "value",
        }:
            _fail(f"state matrix {row_label} schema不一致")
        block = row["block"]
        if block not in _SAVE_BLOCK_SIZES:
            _fail(f"state matrix {row_label}.block不正")
        offset = _int(
            row["offset"], f"{row_label}.offset",
            _SAVE_BLOCK_SIZES[block] - 1,
        )
        identity = (block, offset)
        persistent_ids.append(identity)
        normalized_persistent.append({
            "block": block, "offset": offset,
            "value": _int(row["value"], f"{row_label}.value", 255),
        })
    result["persistent"] = normalized_persistent
    if persistent_ids != sorted(set(persistent_ids)):
        _fail(f"state matrix {label}.required.persistent順序/重複不正")
    return result


def _normalize_state_rows(value: Any, label: str) -> dict[str, list[dict[str, Any]]]:
    if not isinstance(value, Mapping) or set(value) != set(_STATE_KINDS):
        _fail(f"state matrix {label} state keys不一致")
    result: dict[str, list[dict[str, Any]]] = {}
    for kind, (value_key, maximum) in _STATE_KINDS.items():
        source = value[kind]
        if not isinstance(source, list) or len(source) > 64:
            _fail(f"state matrix {label}.{kind}は0..64 rowsです")
        seen: set[int] = set()
        normalized = []
        for index, raw in enumerate(source):
            item_label = f"{label}.{kind}[{index}]"
            if not isinstance(raw, Mapping) or set(raw) != {"id", value_key}:
                _fail(f"state matrix {item_label} schema不一致")
            identifier = _int(raw["id"], f"{item_label}.id", 65535)
            if identifier in seen:
                _fail(f"state matrix {label}.{kind} ID重複: {identifier}")
            seen.add(identifier)
            raw_value = raw[value_key]
            if value_key in {"value", "defeated"} and kind != "vars":
                if not isinstance(raw_value, bool):
                    _fail(f"state matrix {item_label}.{value_key}はboolです")
                normalized_value: int | bool = raw_value
            else:
                normalized_value = _int(
                    raw_value, f"{item_label}.{value_key}", maximum,
                )
            normalized.append({"id": identifier, value_key: normalized_value})
        normalized.sort(key=lambda item: item["id"])
        result[kind] = normalized
    return result


def _control_rom_address(value: Any, label: str) -> int:
    if isinstance(value, str) and re.fullmatch(r"0x0[89][0-9A-F]{6}", value):
        return int(value, 16)
    _fail(f"state matrix {label} はuppercase ROM addressではありません")


def _control_fixture_ref(
    value: Any, expected_kind: str, registry: Mapping[str, Mapping[str, Any]],
    label: str,
) -> str:
    if not isinstance(value, str) or _RAW_SHA256.fullmatch(value) is None:
        _fail(f"state matrix {label} fixture_ref不正")
    fixture = registry.get(value)
    if fixture is None or fixture.get("fixture_kind") != expected_kind:
        _fail(f"state matrix {label} fixture_ref owner不一致")
    return value


def _normalize_control_required_value(
    kind: str, value: Any, registry: Mapping[str, Mapping[str, Any]],
    label: str,
) -> Any:
    if kind in {
        "FLAG", "ENGINE_SPECIAL_FLAG", "TRAINER", "DAYCARE_OCCUPIED",
    }:
        if not isinstance(value, bool):
            _fail(f"state matrix {label} bool required value不正")
        if kind == "ENGINE_SPECIAL_FLAG":
            # Range validation is performed against row.id in the caller.
            pass
        return value
    if kind in {"VAR", "ITEM"}:
        return _int(value, f"{label}.required_value", 0xFFFF)
    if kind == "MONEY":
        return _int(value, f"{label}.required_value", 999999)
    if kind == "BERRY_POWDER":
        return _int(value, f"{label}.required_value", 99999)
    if kind == "PLAYER_GENDER":
        return _int(value, f"{label}.required_value", 1)
    if kind == "QUEST_LOG_STATE":
        return _int(value, f"{label}.required_value", 3)
    if kind == "REMATCH_STATE":
        keys = {"ready", "local_id", "saveblock1_offset", "ready_byte"}
        if not isinstance(value, Mapping) or set(value) != keys \
                or not isinstance(value["ready"], bool):
            _fail(f"state matrix {label} REMATCH_STATE required value不正")
        local_id = _int(value["local_id"], f"{label}.local_id", 99)
        offset = _int(
            value["saveblock1_offset"], f"{label}.saveblock1_offset", 0xFFFF,
        )
        ready_byte = _int(
            value["ready_byte"], f"{label}.ready_byte", 0xFF,
        )
        if offset != 0x063A + local_id \
                or (ready_byte != 0) is not value["ready"]:
            _fail(f"state matrix {label} REMATCH_STATE owner/value関係不一致")
        return {
            "ready": value["ready"], "local_id": local_id,
            "saveblock1_offset": offset, "ready_byte": ready_byte,
        }
    if kind == "PARTY_USABLE_FOR_DOUBLE":
        if not isinstance(value, Mapping) or set(value) != {
            "mons_state", "party_layout_ref",
        }:
            _fail(f"state matrix {label} PARTY_USABLE required value不正")
        reference = _control_fixture_ref(
            value["party_layout_ref"], "PARTY", registry, label,
        )
        return {
            "mons_state": _int(value["mons_state"], f"{label}.mons_state", 2),
            "party_layout_ref": reference,
            # Private TSV transport field; the public oracle value remains
            # the exact two-key mapping above.
            "party_count": registry[reference]["count"],
        }
    if kind == "PLAYER_POSITION":
        keys = {"x", "y", "group", "map", "apply_relation"}
        if not isinstance(value, Mapping) or set(value) != keys \
                or value.get("apply_relation") \
                    != "ACTUAL_STOCK_WARP_THEN_REAL_MOVEMENT":
            _fail(f"state matrix {label} PLAYER_POSITION required value不正")
        return {
            "x": _int(value["x"], f"{label}.x", 0xFFFF),
            "y": _int(value["y"], f"{label}.y", 0xFFFF),
            "group": _int(value["group"], f"{label}.group", 0xFF),
            "map": _int(value["map"], f"{label}.map", 0xFF),
            "apply_relation": "ACTUAL_STOCK_WARP_THEN_REAL_MOVEMENT",
        }
    if kind == "SIGNED_RAM_SCRIPT":
        keys = {
            "variant", "layout_ref", "expected_dispatch",
            "expected_var_8004", "expected_ram_script_after",
        }
        variants = {
            "ABSENT_OR_ZERO", "VALID_SET_VAR_RETURN",
            "CORRUPTED_CHECKSUM",
        }
        if not isinstance(value, Mapping) or set(value) != keys \
                or value.get("variant") not in variants \
                or not isinstance(value.get("expected_dispatch"), bool):
            _fail(f"state matrix {label} SIGNED_RAM_SCRIPT required value不正")
        variant = value["variant"]
        expected_dispatch = variant == "VALID_SET_VAR_RETURN"
        expected_var = 0x61A5 if expected_dispatch else None
        expected_after = (
            "CLEARED_BY_VALIDATOR"
            if variant == "CORRUPTED_CHECKSUM" else "UNCHANGED"
        )
        if value["expected_dispatch"] is not expected_dispatch \
                or value["expected_var_8004"] != expected_var \
                or value["expected_ram_script_after"] != expected_after:
            _fail(f"state matrix {label} signed RAM result関係不正")
        reference = _control_fixture_ref(
            value["layout_ref"], "SIGNED_RAM_SCRIPT", registry, label,
        )
