def _normalize_control_relations(value: Any, kind: str, label: str) -> list[dict[str, Any]]:
    if not isinstance(value, list) or len(value) > 32:
        _fail(f"state matrix {label}.relations不正")
    normalized = []
    for index, row in enumerate(value):
        row_label = f"{label}.relations[{index}]"
        if not isinstance(row, Mapping) or not isinstance(row.get("operator"), str):
            _fail(f"state matrix {row_label} schema不正")
        operator = row["operator"]
        if operator not in _CONTROL_RELATIONS_BY_KIND[kind] \
                or set(row) != _CONTROL_RELATION_KEYS[operator]:
            _fail(f"state matrix {row_label} unknown relation/field")
        result = deepcopy(dict(row))
        if operator == "ENGINE_SPECIAL_FLAG_BOOL":
            if row["source_abi"] != _ENGINE_SPECIAL_FLAG_SOURCE:
                _fail(f"state matrix {row_label} engine flag source ABI不一致")
            normalized.append(result)
            continue
        if operator == "GET_MONS_STATE_TO_DOUBLES":
            meanings = row["result_meanings"]
            if meanings != {
                "0": "TWO_USABLE_MONS", "1": "ONLY_ONE_MON",
                "2": "ONLY_ONE_USABLE_MON",
            }:
                _fail(f"state matrix {row_label} doubles meanings不一致")
            result["trainerbattle_type"] = _int(
                row["trainerbattle_type"],
                f"{row_label}.trainerbattle_type", 0xFF,
            )
            normalized.append(result)
            continue
        if operator == "GET_SAVED_RAM_SCRIPT_IF_VALID_THREE_WAY":
            source = _runner_control_abi_contract()["layouts"][
                "signed_ram_script"
            ]["source"]
            if row["source"] != source \
                    or row["valid_program_hex"] != "160480a5610c":
                _fail(f"state matrix {row_label} signed RAM source不一致")
            normalized.append(result)
            continue
        if operator in {
            _DAYCARE_TRANSACTION_RELATION,
            _ROUTE5_DAYCARE_TRANSACTION_RELATION,
        }:
            expected_owners = (
                _ROUTE5_DAYCARE_TRANSACTION_STATE_OWNERS
                if operator == _ROUTE5_DAYCARE_TRANSACTION_RELATION
                else _DAYCARE_TRANSACTION_STATE_OWNERS
            )
            if row["state_owners"] != expected_owners:
                _fail(
                    f"state matrix {row_label} DAYCARE_TRANSACTION owner集合不一致"
                )
            normalized.append(result)
            continue
        if operator == _PARTY_MOVE_TRANSACTION_RELATION:
            if row["state_owners"] \
                    != _PARTY_MOVE_TRANSACTION_STATE_OWNERS \
                    or row["model_sources"] \
                    != _PARTY_MOVE_TRANSACTION_MODEL_SOURCES:
                _fail(
                    f"state matrix {row_label} PARTY_MOVE_TRANSACTION "
                    "owner/source集合不一致"
                )
            normalized.append(result)
            continue
        if operator == _GIFT_STORAGE_TRANSACTION_RELATION:
            if row["state_owners"] \
                    != _GIFT_STORAGE_TRANSACTION_STATE_OWNERS \
                    or row["executor_representatives"] \
                    != list(
                        _GIFT_STORAGE_TRANSACTION_EXECUTOR_SCENARIO_IDS
                    ) \
                    or row["runner_exhaustive_layouts"] \
                    != list(_GIFT_STORAGE_TRANSACTION_RUNNER_SCENARIO_IDS) \
                    or row["model_sources"] \
                    != _GIFT_STORAGE_TRANSACTION_MODEL_SOURCES:
                _fail(
                    f"state matrix {row_label} GIFT_STORAGE "
                    "owner/scenario/source集合不一致"
                )
            normalized.append(result)
            continue
        if operator == _RUIN_SEAL_PREFIX_RELATION:
            root_text = row["root_address"]
            try:
                root = int(root_text, 0) \
                    if isinstance(root_text, str) else -1
            except ValueError:
                root = -1
            expected = {
                "operator": _RUIN_SEAL_PREFIX_RELATION,
                "root_address": f"0x{root:08X}",
                "seal_flag_ids": list(_RUIN_SEAL_FLAGS),
                "completion_flag_id": (
                    _RUIN_SEAL_COMPLETION_FLAG
                    if root == _RUIN_SEAL_OBJECT_ROOT else None
                ),
                "scenario_count": len(_RUIN_SEAL_SCENARIO_IDS.get(root, ())),
            }
            if root not in _RUIN_SEAL_ROOTS \
                    or _stable(dict(row)) != _stable(expected):
                _fail(f"state matrix {row_label} RUIN_SEAL_PREFIX relation不一致")
            normalized.append(deepcopy(expected))
            continue
        if operator == _FACILITY_SESSION_RELATION:
            root_text = row["root_address"]
            try:
                root = int(root_text, 0) \
                    if isinstance(root_text, str) else -1
            except ValueError:
                root = -1
            families = ("mirage",) if root == _FACILITY_MIRAGE_ROOT \
                else ("factory", "codex") \
                if root == _FACILITY_SHARED_ROOT else ()
            scenario_keys = [
                manifest_row["scenario_key"]
                for manifest_row in _facility_session_manifest()["scenarios"]
                if manifest_row["family"] in families
            ]
            expected = {
                "operator": _FACILITY_SESSION_RELATION,
                "root_address": f"0x{root:08X}",
                "scenario_keys": scenario_keys,
                "source_identity_owner": (
                    _FACILITY_SESSION_REGISTRY_SOURCE_PATH
                ),
                "raw_ewram_preimage_policy": (
                    "UNDEFINED_RAW_BYTES_FORBIDDEN;CALL_EXACT_EXPORT_SEQUENCE"
                ),
            }
            if root not in _FACILITY_CONTROL_IDS \
                    or _stable(dict(row)) != _stable(expected):
                _fail(f"state matrix {row_label} FACILITY_SESSION relation不一致")
            normalized.append(deepcopy(expected))
            continue
        for key in set(row) - {"operator", "exact_seed_or_stub_required"}:
            result[key] = _int(row[key], f"{row_label}.{key}", 0xFFFFFFFF)
        if "exact_seed_or_stub_required" in row \
                and row["exact_seed_or_stub_required"] is not True:
            _fail(f"state matrix {row_label} RNG exact seed契約不一致")
        normalized.append(result)
    if kind != "FLAG" and not normalized:
        _fail(f"state matrix {label}.{kind} relationが空です")
    return normalized


_COINS_PREDICATE_RESULT: Mapping[str, int] = {
    "CURRENT_COINS_BELOW_MAX": 0,
    "CURRENT_COINS_AT_MAX": 1,
    "CURRENT_COINS_AT_LEAST_AMOUNT": 0,
    "CURRENT_COINS_BELOW_AMOUNT": 1,
}


def _validate_coins_control_relations(
    identifier: int, required_value: Any,
    relations: Sequence[Mapping[str, Any]], label: str,
) -> None:
    """COINSの物理prestateとsource predicateを同じ境界で閉じる。"""
    if identifier != 0 or not isinstance(required_value, Mapping) \
            or set(required_value) != {"vega", "cfru"}:
        _fail(f"state matrix {label} COINS singleton/value schema不一致")
    vega = required_value["vega"]
    identities = [
        json.dumps(row, sort_keys=True, separators=(",", ":"))
        for row in relations
    ]
    if len(identities) != len(set(identities)):
        _fail(f"state matrix {label} COINS relation重複")
    for index, relation in enumerate(relations):
        operator = relation["operator"]
        relation_label = f"{label}.relations[{index}]"
        if operator == "WRITE_CURRENT_COINS_TO_VAR":
            _int(
                relation["destination_var"],
                f"{relation_label}.destination_var", 0xFFFF,
            )
            continue
        expected_result = _COINS_PREDICATE_RESULT.get(operator)
        if expected_result is None:
            _fail(f"state matrix {relation_label} COINS operator未登録")
        amount = _int(
            relation["amount"], f"{relation_label}.amount", 0xFFFF,
        )
        result_value = _int(
            relation["result_value"],
            f"{relation_label}.result_value", 1,
        )
        if result_value != expected_result:
            _fail(f"state matrix {relation_label} COINS reverse bool不一致")
        predicate = {
            "CURRENT_COINS_BELOW_MAX": vega < 9999,
            "CURRENT_COINS_AT_MAX": vega == 9999,
            "CURRENT_COINS_AT_LEAST_AMOUNT": vega >= amount,
            "CURRENT_COINS_BELOW_AMOUNT": vega < amount,
        }[operator]
        if not predicate:
            _fail(f"state matrix {relation_label} COINS predicate不一致")


def _validate_party_minigame_control(
    identifier: int, required_value: Any,
    relations: Sequence[Mapping[str, Any]], label: str,
) -> None:
    """Wireless minigameの物理partyとUI選択メタデータを閉じる。"""
    expected_relations = [{
        "operator": "WIRELESS_MINIGAME_PARTY_ELIGIBILITY_AND_SELECTION",
    }]
    if not isinstance(required_value, Mapping) \
            or identifier != required_value.get("mode"):
        _fail(f"state matrix {label} PARTY_MINIGAME ID/mode不一致")
    if list(relations) != expected_relations:
        _fail(f"state matrix {label} PARTY_MINIGAME relation不一致")


def _validate_rfu_session_control(
    identifier: int, required_value: Any,
    relations: Sequence[Mapping[str, Any]], candidates: Any | None, label: str,
) -> None:
    """Close role, mode, topology, result language, and natural producer."""
    if identifier not in {363, 364} or not isinstance(required_value, Mapping):
        _fail(f"state matrix {label} RFU_SESSION special/value不一致")
    scenario = _RFU_SESSION_SCENARIOS.get(
        str(required_value.get("scenario_id", ""))
    )
    if scenario is None or scenario["special"] != identifier:
        _fail(f"state matrix {label} RFU_SESSION role/scenario不一致")
    expected_candidates = [1, 5, 8] if identifier == 363 else [1, 5, 6, 8]
    if candidates is not None and candidates != expected_candidates:
        _fail(f"state matrix {label} RFU_SESSION result domain不一致")
    if list(relations) != [{"operator": "NATURAL_RFU_ROLE_RESULT_SEQUENCE"}]:
        _fail(f"state matrix {label} RFU_SESSION relation不一致")


def _validate_center_link_session_control(
    identifier: int, required_value: Any,
    relations: Sequence[Mapping[str, Any]], candidates: Any | None, label: str,
) -> None:
    """Close Pokemon Center activity, source capacity, role, and result."""
    if identifier not in {363, 364} or not isinstance(required_value, Mapping):
        _fail(f"state matrix {label} CENTER_LINK_SESSION special/value不一致")
    scenario = _CENTER_LINK_SESSION_SCENARIOS.get(
        str(required_value.get("scenario_id", ""))
    )
    if scenario is None or scenario["special"] != identifier:
        _fail(f"state matrix {label} CENTER_LINK_SESSION role/scenario不一致")
    expected_candidates = [1, 5, 8] if identifier == 363 else [1, 5, 6, 8]
    if candidates is not None and candidates != expected_candidates:
        _fail(f"state matrix {label} CENTER_LINK_SESSION result domain不一致")
    if list(relations) != [{"operator": _CENTER_LINK_SESSION_RELATION}]:
        _fail(f"state matrix {label} CENTER_LINK_SESSION relation不一致")


def _validate_daycare_transaction_control(
    identifier: int, required_value: Any,
    relations: Sequence[Mapping[str, Any]], candidates: Any | None, label: str,
) -> None:
    """Close both source daycare families and their exact physical owners."""
    contracts = {
        0: (
            _DAYCARE_TRANSACTION_SCENARIO_IDS,
            _DAYCARE_TRANSACTION_RELATION,
            _DAYCARE_TRANSACTION_STATE_OWNERS,
        ),
        1: (
            _ROUTE5_DAYCARE_TRANSACTION_SCENARIO_IDS,
            _ROUTE5_DAYCARE_TRANSACTION_RELATION,
            _ROUTE5_DAYCARE_TRANSACTION_STATE_OWNERS,
        ),
    }
    contract = contracts.get(identifier)
    if contract is None or not isinstance(required_value, Mapping):
        _fail(f"state matrix {label} DAYCARE_TRANSACTION ID/value不一致")
    scenario_ids, relation, state_owners = contract
    if required_value.get("scenario_id") not in scenario_ids:
        _fail(f"state matrix {label} DAYCARE_TRANSACTION scenario/ID不一致")
    if candidates is not None \
            and candidates != list(scenario_ids):
        _fail(f"state matrix {label} DAYCARE_TRANSACTION scenario domain不一致")
    if list(relations) != [{
        "operator": relation,
        "state_owners": list(state_owners),
    }]:
        _fail(f"state matrix {label} DAYCARE_TRANSACTION relation不一致")


