def _validate_ruin_seal_prefix_control(
    identifier: int, required_value: Any,
    relations: Sequence[Mapping[str, Any]], candidates: Any | None, label: str,
) -> None:
    """Close the root-specific 14-seal prefix and object completion flag."""
    if not isinstance(required_value, Mapping):
        _fail(f"state matrix {label} RUIN_SEAL_PREFIX value不一致")
    root_text = required_value.get("root_address")
    try:
        root = int(root_text, 0) if isinstance(root_text, str) else -1
    except ValueError:
        root = -1
    expected_id = _RUIN_SEAL_CONTROL_IDS.get(root)
    if expected_id is None or identifier != expected_id:
        _fail(f"state matrix {label} RUIN_SEAL_PREFIX root/ID不一致")
    expected_candidates = sorted(
        _RUIN_SEAL_SCENARIO_IDS[root], key=_stable,
    )
    if candidates is not None and candidates != expected_candidates:
        _fail(f"state matrix {label} RUIN_SEAL_PREFIX scenario domain不一致")
    expected_relation = [{
        "operator": _RUIN_SEAL_PREFIX_RELATION,
        "root_address": f"0x{root:08X}",
        "seal_flag_ids": list(_RUIN_SEAL_FLAGS),
        "completion_flag_id": (
            _RUIN_SEAL_COMPLETION_FLAG
            if root == _RUIN_SEAL_OBJECT_ROOT else None
        ),
        "scenario_count": len(_RUIN_SEAL_SCENARIO_IDS[root]),
    }]
    if list(relations) != expected_relation:
        _fail(f"state matrix {label} RUIN_SEAL_PREFIX relation不一致")


def _validate_facility_session_control(
    identifier: int, required_value: Any,
    relations: Sequence[Mapping[str, Any]], candidates: Any | None, label: str,
) -> None:
    """Close one of the fixed 33 Mirage + 10 Factory + 6 Codex sessions."""
    if not isinstance(required_value, Mapping):
        _fail(f"state matrix {label} FACILITY_SESSION value不一致")
    scenario_key = required_value.get("scenario_key")
    if not isinstance(scenario_key, str):
        _fail(f"state matrix {label} FACILITY_SESSION scenario key不一致")
    manifest_row = _facility_manifest_row(scenario_key)
    root = int(manifest_row["root_address"], 0)
    if identifier != _FACILITY_CONTROL_IDS[root]:
        _fail(f"state matrix {label} FACILITY_SESSION root/ID不一致")
    families = ("mirage",) if root == _FACILITY_MIRAGE_ROOT \
        else ("factory", "codex")
    expected_candidates = sorted([
        row["scenario_key"]
        for row in _facility_session_manifest()["scenarios"]
        if row["family"] in families
    ], key=_stable)
    if candidates is not None and candidates != expected_candidates:
        _fail(f"state matrix {label} FACILITY_SESSION scenario domain不一致")
    expected_relation = [{
        "operator": _FACILITY_SESSION_RELATION,
        "root_address": f"0x{root:08X}",
        "scenario_keys": [
            row["scenario_key"]
            for row in _facility_session_manifest()["scenarios"]
            if row["family"] in families
        ],
        "source_identity_owner": _FACILITY_SESSION_REGISTRY_SOURCE_PATH,
        "raw_ewram_preimage_policy": (
            "UNDEFINED_RAW_BYTES_FORBIDDEN;CALL_EXACT_EXPORT_SEQUENCE"
        ),
    }]
    if list(relations) != expected_relation:
        _fail(f"state matrix {label} FACILITY_SESSION relation不一致")


def _normalize_external_controls(
    value: Any, state: Mapping[str, list[dict[str, Any]]],
    registry: Mapping[str, Mapping[str, Any]], label: str,
) -> list[dict[str, Any]]:
    if not isinstance(value, list) or len(value) > 256:
        _fail(f"state matrix {label}.externalは0..256 rowsです")
    result = []
    identities: set[tuple[str, int]] = set()
    required_keys = {
        "kind", "id", "source_ids", "read_addresses", "candidate_values",
        "relations", "required_value_in_matrix_case", "requirement_basis",
    }
    optional_keys = {"basis", "object_visibility_required_value"}
    for index, raw in enumerate(value):
        row_label = f"{label}.external[{index}]"
        if not isinstance(raw, Mapping) or not required_keys.issubset(raw) \
                or set(raw) - required_keys - optional_keys:
            _fail(f"state matrix {row_label} keys不一致")
        kind = raw["kind"]
        if kind not in _CONTROL_EXTERNAL_KINDS:
            _fail(f"state matrix {row_label}.kind未知")
        identifier = _int(
            raw["id"], f"{row_label}.id",
            0xFFFFFFFF if kind == "SIGNED_RAM_SCRIPT" else 0xFFFF,
        )
        if kind == "ENGINE_SPECIAL_FLAG" and not 0x4000 <= identifier <= 0x407F:
            _fail(f"state matrix {row_label}.id engine special flag範囲外")
        identity = (kind, identifier)
        if identity in identities:
            _fail(f"state matrix {row_label} control owner重複")
        identities.add(identity)
        source_ids = raw["source_ids"]
        source_id_maximum = (
            0xFFFFFFFF if kind == "SIGNED_RAM_SCRIPT" else 0xFFFF
        )
        if not isinstance(source_ids, list) \
                or len(source_ids) != len(set(source_ids)) \
                or any(isinstance(item, bool) or not isinstance(item, int)
                       or not 0 <= item <= source_id_maximum
                       for item in source_ids):
            _fail(f"state matrix {row_label}.source_ids不正")
        addresses = raw["read_addresses"]
        if not isinstance(addresses, list) \
                or len(addresses) != len(set(addresses)):
            _fail(f"state matrix {row_label}.read_addresses不正")
        normalized_addresses = [
            _control_rom_address(item, f"{row_label}.read_addresses")
            for item in addresses
        ]
        candidates = raw["candidate_values"]
        if not isinstance(candidates, (list, str)):
            _fail(f"state matrix {row_label}.candidate_values不正")
        if isinstance(candidates, str) and candidates \
                != "TELEPORT_FIXTURE_COORDINATES" \
                and not candidates.endswith(
                    ("FIXTURE_REQUIRED", "LAYOUT_REQUIRED")
                ):
            _fail(f"state matrix {row_label}.candidate marker不正")
        basis = raw["requirement_basis"]
        if not isinstance(basis, str) or not basis.strip():
            _fail(f"state matrix {row_label}.requirement_basis不正")
        required_value = _normalize_control_required_value(
            kind, raw["required_value_in_matrix_case"], registry, row_label,
        )
        relations = _normalize_control_relations(
            raw["relations"], kind, row_label,
        )
        if kind == "COINS":
            _validate_coins_control_relations(
                identifier, required_value, relations, row_label,
            )
        if kind == "PARTY_MINIGAME":
            _validate_party_minigame_control(
                identifier, required_value, relations, row_label,
            )
        if kind == "RFU_SESSION":
            _validate_rfu_session_control(
                identifier, required_value, relations, candidates, row_label,
            )
        if kind == "CENTER_LINK_SESSION":
            _validate_center_link_session_control(
                identifier, required_value, relations, candidates, row_label,
            )
        if kind == "DAYCARE_TRANSACTION_STATE":
            _validate_daycare_transaction_control(
                identifier, required_value, relations, candidates, row_label,
            )
        if kind == "PARTY_MOVE_TRANSACTION_STATE":
            _validate_party_move_transaction_control(
                identifier, required_value, relations, candidates, row_label,
            )
        if kind == "GIFT_STORAGE_TRANSACTION_STATE":
            _validate_gift_storage_transaction_control(
                identifier, required_value, relations, candidates, row_label,
            )
        if kind == "FOSSIL_REVIVAL_STATE":
            _validate_fossil_revival_control(
                identifier, required_value, relations, candidates, row_label,
            )
        if kind == "RUIN_SEAL_PREFIX":
            _validate_ruin_seal_prefix_control(
                identifier, required_value, relations, candidates, row_label,
            )
        if kind == "FACILITY_SESSION":
            _validate_facility_session_control(
                identifier, required_value, relations, candidates, row_label,
            )
        relation_operators = [row["operator"] for row in relations]
        event_design_operators = {
            "EVENT_DESIGN_SOURCE_PHYSICAL_BOOL",
            "CERT_OWNER_FLAG_TO_MODERN_CERTIFICATION_BIT_MIRROR",
            "KANTO_LEAGUE_STATE_TO_LEAGUE_I_II_SAVE_MIRROR",
        }
        if event_design_operators & set(relation_operators) \
                and candidates != [False, True]:
            _fail(
                f"state matrix {row_label} EventDesign bool domain不一致"
            )
        if kind == "DAYCARE_OCCUPIED" and (
            identifier != 0
            or relation_operators != ["EVENT_DESIGN_SOURCE_PHYSICAL_BOOL"]
        ):
            _fail(f"state matrix {row_label} DAYCARE_OCCUPIED owner/relation不一致")
        if kind == "FLAG":
            expected_mirror = (
                "CERT_OWNER_FLAG_TO_MODERN_CERTIFICATION_BIT_MIRROR"
                if 0x1400 <= identifier <= 0x1407 else
                "KANTO_LEAGUE_STATE_TO_LEAGUE_I_II_SAVE_MIRROR"
                if identifier == 0x13FA else None
            )
            mirror_operators = {
                "CERT_OWNER_FLAG_TO_MODERN_CERTIFICATION_BIT_MIRROR",
                "KANTO_LEAGUE_STATE_TO_LEAGUE_I_II_SAVE_MIRROR",
            }
            observed_mirrors = mirror_operators & set(relation_operators)
            if (expected_mirror is None and observed_mirrors) \
                    or (expected_mirror is not None
                        and relation_operators != [expected_mirror]):
                _fail(
                    f"state matrix {row_label} EventDesign flag mirror不一致"
                )
        if kind == "REMATCH_STATE" \
                and (identifier != required_value["local_id"]
                     or any(
                         relation["save_block1_offset"]
                             != required_value["saveblock1_offset"]
                         for relation in raw["relations"]
                     )):
            _fail(f"state matrix {row_label} REMATCH ID/offset不一致")
        if kind == "PLAYER_POSITION" and identifier != 0:
            _fail(f"state matrix {row_label} PLAYER_POSITION idは0必須です")
        if kind == "QUEST_LOG_STATE" and identifier != 0:
            _fail(f"state matrix {row_label} QUEST_LOG_STATE idは0必須です")
        if kind == "POKEDEX_STATE" and identifier != 0:
            _fail(f"state matrix {row_label} POKEDEX_STATE idは0必須です")
        if kind == "POKEDEX_STATE" and relations != [{
            "operator": "EXACT_POKEDEX_SAVE_STATE",
        }]:
            _fail(f"state matrix {row_label} POKEDEX_STATE relation不一致")
        if kind == "BERRY_POWDER":
            if identifier != 0:
                _fail(f"state matrix {row_label} BERRY_POWDER idは0必須です")
            if relations != [{
                "operator": "EXACT_DECRYPTED_BERRY_POWDER",
            }]:
                _fail(
                    f"state matrix {row_label} BERRY_POWDER relation不一致"
                )
            if not isinstance(candidates, list) \
                    or not candidates \
                    or any(isinstance(item, bool) or not isinstance(item, int)
                           or not 0 <= item <= 99999 for item in candidates) \
                    or candidates != sorted(set(candidates)) \
                    or required_value not in candidates:
                _fail(
                    f"state matrix {row_label} BERRY_POWDER candidate domain不一致"
                )
        if kind == "SIGNED_RAM_SCRIPT" \
                and (not 0x08000000 <= identifier < 0x0A000000
                     or identifier not in normalized_addresses):
            _fail(f"state matrix {row_label} signed RAM opcode owner不一致")
        normalized_row = {
            "kind": kind, "id": identifier,
            "source_ids": list(source_ids),
            "read_addresses": normalized_addresses,
            "candidate_values": deepcopy(candidates),
            "relations": relations,
            "required_value_in_matrix_case": required_value,
            "requirement_basis": basis,
        }
        for key in optional_keys:
            if key not in raw:
                continue
            if key == "object_visibility_required_value":
                if not isinstance(raw[key], bool):
                    _fail(f"state matrix {row_label}.{key}不正")
            elif not isinstance(raw[key], str) or not raw[key].strip():
                _fail(f"state matrix {row_label}.{key}不正")
            normalized_row[key] = raw[key]
        result.append(normalized_row)

    ruin_owned_flags: set[int] = set()
    for control in result:
        if control["kind"] != "RUIN_SEAL_PREFIX":
            continue
        root = int(
            control["required_value_in_matrix_case"]["root_address"], 0,
        )
        ruin_owned_flags.update(_RUIN_SEAL_FLAGS)
        if root == _RUIN_SEAL_OBJECT_ROOT:
            ruin_owned_flags.add(_RUIN_SEAL_COMPLETION_FLAG)
    generic_flag_controls = {
        control["id"] for control in result if control["kind"] == "FLAG"
    }
    state_flag_ids = {
        row["id"] for row in state.get("flags", [])
        if isinstance(row, Mapping) and isinstance(row.get("id"), int)
    }
    if ruin_owned_flags & (generic_flag_controls | state_flag_ids):
        _fail(
            f"state matrix {label} RUIN_SEAL_PREFIX flagの"
            "generic independent二重適用"
        )

    simple_expected = {
        (kind, row["id"]): row[value_key]
        for kind, (state_key, value_key) in _CONTROL_SIMPLE_STATE_KIND.items()
        for row in state[state_key]
    }
    simple_actual = {
        (row["kind"], row["id"]): row["required_value_in_matrix_case"]
        for row in result if row["kind"] in _CONTROL_SIMPLE_STATE_KIND
    }
    if simple_actual != simple_expected:
        _fail(
            f"state matrix {label} 4domain state/control one-to-one不一致"
        )
    return sorted(result, key=lambda row: (row["kind"], row["id"]))


def _normalize_internal_controls(
    value: Any, input_sequences: Sequence[Mapping[str, Any]], label: str,
) -> list[dict[str, Any]]:
    if not isinstance(value, list) or len(value) > 256:
        _fail(f"state matrix {label}.internalは0..256 rowsです")
    result = []
    identities: set[tuple[str | None, int, str, int, int, int]] = set()
    required = {
        "instruction_address", "writer", "candidate_values", "producer",
        "def_use_status", "capture",
    }
    optional = {"kind", "sequence_id"}
    sequence_ids = {row["sequence_id"] for row in input_sequences}
    for index, raw in enumerate(value):
        row_label = f"{label}.internal[{index}]"
        if not isinstance(raw, Mapping) or not required.issubset(raw) \
                or set(raw) - required - optional:
            _fail(f"state matrix {row_label} keys不一致")
        address = _control_rom_address(
            raw["instruction_address"], f"{row_label}.instruction_address",
        )
        writer = raw["writer"]
        if not isinstance(writer, str) or not writer \
                or any(marker in writer for marker in ("UNKNOWN", "UNRESOLVED", "REQUIRED")):
            _fail(f"state matrix {row_label}.writer未解決")
        candidates = raw["candidate_values"]
        if not isinstance(candidates, list) or not candidates \
                or any(isinstance(item, bool) or not isinstance(item, int)
                       or not 0 <= item <= 0xFFFF for item in candidates):
            _fail(f"state matrix {row_label}.candidate_values未解決")
        producer = raw["producer"]
        if not isinstance(producer, Mapping) or not producer \
                or any(
                    isinstance(item, str)
                    and any(marker in item for marker in (
                        "UNKNOWN", "UNRESOLVED", "REQUIRED",
                    ))
                    for item in producer.values()
                ):
            _fail(f"state matrix {row_label}.producer未解決")
        status = raw["def_use_status"]
        if status not in {"LOCAL_EXACT", "CROSS_NODE_EXACT"}:
            _fail(f"state matrix {row_label}.def_use_status未解決")
        capture = raw["capture"]
        if not isinstance(capture, Mapping) or set(capture) != {
            "before_pc", "after_pc", "owner_address", "expected_value",
            "expected_token_index", "expected_execution_ordinal",
        }:
            _fail(f"state matrix {row_label}.capture keys不一致")
        owner = capture["owner_address"]
        if isinstance(owner, str):
            try:
                owner = int(owner, 16)
            except ValueError:
                _fail(f"state matrix {row_label}.capture owner不正")
        special_var_owners = set(range(0x02036FEC, 0x02037004, 2))
        if owner not in special_var_owners | {0x02037004}:
            _fail(f"state matrix {row_label}.capture owner不一致")
        before = capture["before_pc"]
        after = capture["after_pc"]
        if isinstance(before, str):
            before = _control_rom_address(before, f"{row_label}.before_pc")
        else:
            before = _int(before, f"{row_label}.before_pc", 0x09FFFFFF)
        if isinstance(after, str):
            after = _control_rom_address(after, f"{row_label}.after_pc")
        else:
            after = _int(after, f"{row_label}.after_pc", 0x09FFFFFF)
        if not 0x08000000 <= before < after <= 0x0A000000:
            _fail(f"state matrix {row_label}.capture PC range不正")
        expected = _int(
            capture["expected_value"], f"{row_label}.expected_value", 0xFFFF,
        )
        token_index = _int(
            capture["expected_token_index"],
            f"{row_label}.expected_token_index", 127,
        )
        execution_ordinal = _int(
            capture["expected_execution_ordinal"],
            f"{row_label}.expected_execution_ordinal", 255,
        )
        sequence_id = raw.get("sequence_id")
        if sequence_id is not None and sequence_id not in sequence_ids:
            _fail(f"state matrix {row_label}.sequence_id不在")
        if len(sequence_ids) > 1 and sequence_id is None:
            _fail(f"state matrix {row_label} sequence_id曖昧")
        identity_sequence_id = sequence_id
        if identity_sequence_id is None and len(sequence_ids) == 1:
            identity_sequence_id = next(iter(sequence_ids))
        identity = (
            identity_sequence_id, address, writer, owner, token_index,
            execution_ordinal,
        )
        if identity in identities:
            _fail(f"state matrix {row_label} internal control重複")
        identities.add(identity)
        result.append({
            "instruction_address": address, "writer": writer,
            "candidate_values": list(candidates),
            "producer": deepcopy(dict(producer)),
            "def_use_status": status,
            "capture": {
                "before_pc": before, "after_pc": after,
                "owner_address": owner, "expected_value": expected,
                "expected_token_index": token_index,
                "expected_execution_ordinal": execution_ordinal,
            },
            **({"kind": raw["kind"]} if "kind" in raw else {}),
            **({"sequence_id": sequence_id} if sequence_id is not None else {}),
        })
    ordinal_groups: dict[tuple[str | None, int, str, int, int], list[int]] = {}
    for row in result:
        sequence_id = row.get("sequence_id")
        if sequence_id is None and len(sequence_ids) == 1:
            sequence_id = next(iter(sequence_ids))
        key = (
            sequence_id, row["instruction_address"], row["writer"],
            row["capture"]["owner_address"],
            row["capture"]["expected_token_index"],
        )
        ordinal_groups.setdefault(key, []).append(
            row["capture"]["expected_execution_ordinal"]
        )
    if any(sorted(ordinals) != list(range(len(ordinals)))
           for ordinals in ordinal_groups.values()):
        _fail(f"state matrix {label} internal execution ordinal closure不一致")
    return sorted(result, key=lambda row: (
        row.get("sequence_id", ""), row["instruction_address"], row["writer"],
        row["capture"]["owner_address"],
        row["capture"]["expected_token_index"],
        row["capture"]["expected_execution_ordinal"],
    ))


def _normalize_control_requirements(
    value: Any, state: Mapping[str, list[dict[str, Any]]],
    input_sequences: Sequence[Mapping[str, Any]],
    registry: Mapping[str, Mapping[str, Any]], label: str,
) -> dict[str, Any]:
    if not isinstance(value, Mapping) or not {"external", "internal"} <= set(value) \
            or set(value) - {
                "external", "internal", "missing_external",
                "all_external_requirements_materialized",
            }:
        _fail(f"state matrix {label}.control_requirements keys不一致")
    if value.get("missing_external", []) != [] \
            or value.get("all_external_requirements_materialized", True) is not True:
        _fail(f"state matrix {label} external control未materialize")
    external = _normalize_external_controls(
        value["external"], state, registry, label,
    )
    _validate_facility_continuation_terminals(
        input_sequences, external, label,
    )
    internal = _normalize_internal_controls(
        value["internal"], input_sequences, label,
    )
    internal_results = {
        row["capture"]["expected_value"] for row in internal
    }
    for row in external:
        if row["kind"] != "PARTY_OR_STORAGE_CAPACITY":
            continue
        expected = row["required_value_in_matrix_case"]["expected_result"]
        if expected not in internal_results:
            _fail(
                f"state matrix {label} giveegg result {expected}に"
                "実producer VAR_RESULT captureがありません"
            )
    return {"external": external, "internal": internal}


def validate_state_matrix_document(
    value: Any, *, expected_rom_sha256: str | None = None,
) -> tuple[dict[str, Any], dict[str, dict[str, Any]]]:
    """state-matrix plannerのrunner ABIを厳格化し、全caseを保持する。"""
    if not isinstance(value, Mapping) or (
        value.get("schema_version"), value.get("task"), value.get("stage"),
        value.get("status"),
    ) != (1, TASK, STAGE, "PASS"):
        _fail("state matrix schema/task/stage/status不一致")
    matrix_rom = value.get("rom_sha256")
    if not isinstance(matrix_rom, str) \
            or _RAW_SHA256.fullmatch(matrix_rom) is None:
        _fail("state matrix rom_sha256不正")
    if expected_rom_sha256 is not None and matrix_rom != expected_rom_sha256:
        _fail("state matrix/Stage61 ROM SHA-256不一致")
    control_abi = _runner_control_abi_contract()
    oracle_root = value.get("oracle")
    oracle_registry = oracle_root.get("runner_fixtures") \
        if isinstance(oracle_root, Mapping) else None
    direct_registry = value.get("runner_fixtures")
    if direct_registry is not None and oracle_registry is not None \
            and direct_registry != oracle_registry:
        _fail("state matrix runner_fixtures二重正本が不一致です")
    fixture_registry = _normalize_control_fixture_registry(
        direct_registry if direct_registry is not None else oracle_registry,
    )
    sweep_sources: list[Any] = []
    for container in (
        value,
        value.get("runtime_control_expansion"),
        oracle_root,
    ):
        if not isinstance(container, Mapping):
            continue
        sweeps = container.get("dedicated_fixture_sweeps")
        if isinstance(sweeps, Mapping) \
                and "GIFT_STORAGE_TRANSACTION_STATE" in sweeps:
            sweep_sources.append(sweeps["GIFT_STORAGE_TRANSACTION_STATE"])
    if sweep_sources and any(source != sweep_sources[0]
                             for source in sweep_sources[1:]):
        _fail("state matrix GIFT_STORAGE dedicated sweep二重正本不一致")
    gift_storage_sweep = None if not sweep_sources else \
        _normalize_gift_storage_dedicated_fixture_sweep(
            sweep_sources[0], fixture_registry,
        )
    projection = value.get("runner_projection")
    required_columns = {
        "flags", "vars", "items", "trainers",
        "expect_visible", "expect_interaction",
        "runtime_position_control", "interaction_execution",
    }
    if not isinstance(projection, Mapping) \
            or projection.get("mode") != "EXTENDED_STATE_TSV_REQUIRED" \
            or not required_columns.issubset(
                set(projection.get("required_columns", []))
            ):
        _fail("state matrix runner_projection契約不一致")
    assertions = value.get("assertions")
    if not isinstance(assertions, Mapping) or not assertions \
            or any(item is not True for item in assertions.values()):
        _fail("state matrix assertionがPASSではありません")
    try:
        if str(ROOT) not in sys.path:
            sys.path.insert(0, str(ROOT))
        from tools.stage61_catalog_state_matrix import runner_state_rows

        source_rows = runner_state_rows(value)
    except (ImportError, KeyError, TypeError, ValueError, RuntimeError) as error:
        _fail(f"state matrix runner_state_rows失敗: {error}")
    counts = value.get("counts")
    if not isinstance(counts, Mapping) \
            or counts.get("matrix_case_count") != len(source_rows):
        _fail("state matrix case count不一致")

    source_cases = value.get("cases")
    if not isinstance(source_cases, list):
        _fail("state matrix source cases不正")
    source_by_id = {
        row.get("case_id"): row for row in source_cases
        if isinstance(row, Mapping) and isinstance(row.get("case_id"), str)
    }
    if len(source_by_id) != len(source_cases):
        _fail("state matrix source case ID重複/不正")
    normalized: dict[str, dict[str, Any]] = {}
    interactive_count = 0
    hidden_count = 0
    shadow_pairs = {
        "OBJECT:003/022:000": "OBJECT:096/015:007",
        "OBJECT:003/022:003": "OBJECT:096/015:008",
    }
    shadow_by_owner: dict[str, dict[str, Any]] = {}
    for source_owner, canonical_owner in shadow_pairs.items():
        common = {
            "classification": "CANONICAL_SHADOW_NON_PRODUCT_SOURCE",
            "source_owner_id": source_owner,
            "canonical_owner_id": canonical_owner,
        }
        shadow_by_owner[source_owner] = {
            **common, "role": "NON_PRODUCT_SOURCE",
        }
        shadow_by_owner[canonical_owner] = {
            **common, "role": "CANONICAL_PHYSICAL_OWNER",
        }
    for index, raw in enumerate(source_rows):
        label = f"runner_state_rows[{index}]"
        required = {
            "case_id", "base_case_id", "owner_key", "catalog_branch",
            "group", "map", "object_index", "local_id", "object",
            "runtime_root", "state",
            "expect_visible", "expect_interaction", "choice_candidates",
            "expected_terminal",
        }
        optional_contract_keys = {
            "input_sequences", "text_oracle",
            "allowed_post_effect_families", "allowed_post_effects",
            "required_postconditions", "control_requirements",
            "interaction_execution", "runtime_position_variant",
            "runtime_position_map_load_required",
            "runtime_map_lifecycle",
        }
        if not isinstance(raw, Mapping) or not required.issubset(raw) \
                or set(raw) - required - optional_contract_keys:
            _fail(f"state matrix {label} keys不一致")
        case_id = raw["case_id"]
        base_case_id = raw["base_case_id"]
        owner_key = raw["owner_key"]
        catalog_branch = raw["catalog_branch"]
        if not isinstance(case_id, str) or _CASE_ID.fullmatch(case_id) is None \
                or not isinstance(base_case_id, str) \
                or _CASE_ID.fullmatch(base_case_id) is None:
            _fail(f"state matrix {label} case ID不正")
        if not isinstance(owner_key, str) \
                or _OWNER_ID.fullmatch(owner_key) is None \
                or not isinstance(catalog_branch, str) \
                or _CASE_ID.fullmatch(catalog_branch) is None:
            _fail(f"state matrix {label} owner/branch ID不正")
        if case_id in normalized:
            _fail(f"state matrix case_id重複: {case_id}")
        group = _int(raw["group"], f"{label}.group", 255)
        map_number = _int(raw["map"], f"{label}.map", 255)
        object_index = _int(raw["object_index"], f"{label}.object_index", 255)
        local_id = _int(raw["local_id"], f"{label}.local_id", 255)
        object_position = _pair(raw["object"], f"{label}.object")
        runtime_root_raw = raw["runtime_root"]
        if not isinstance(runtime_root_raw, str) \
                or re.fullmatch(r"0x0[89][0-9A-F]{6}", runtime_root_raw) is None:
            _fail(f"state matrix {label}.runtime_root canonical ROM address不正")
        runtime_root = int(runtime_root_raw, 16)
        if not isinstance(raw["expect_visible"], bool) \
                or not isinstance(raw["expect_interaction"], bool):
            _fail(f"state matrix {label} visibility/interaction不正")
        expect_visible = raw["expect_visible"]
        expect_interaction = raw["expect_interaction"]
        choices = raw["choice_candidates"]
        if not isinstance(choices, list) or any(
            choice not in _CHOICES for choice in choices
        ) or len(choices) != len(set(choices)):
            _fail(f"state matrix {label}.choice_candidates不正")
        terminal = raw["expected_terminal"]
        if expect_interaction:
            interactive_count += 1
            if not expect_visible or not choices \
                    or terminal not in {
                        "CALIBRATE", "FIELD_RELEASE", "BATTLE_START",
                    }:
                _fail(f"state matrix {label} interactive契約不一致")
        else:
            hidden_count += 1
            if expect_visible or choices \
                    or terminal != "NO_INTERACTION_HIDDEN":
                _fail(f"state matrix {label} hidden契約不一致")
        source_case = source_by_id.get(case_id)
        if source_case is None:
            _fail(f"state matrix {label} source case不在")
        contract_source = {
            key: raw[key] if key in raw else source_case.get(key)
            for key in optional_contract_keys
        }
        case_contract_keys = {
            "input_sequences", "allowed_post_effect_families",
            "allowed_post_effects",
        }
        contract_complete = all(
            contract_source[key] is not None for key in case_contract_keys
        )
        if contract_complete and (
            contract_source["text_oracle"] is not None
            or contract_source["required_postconditions"] is not None
        ):
            _fail(
                f"state matrix {label} text/required oracleは"
                "input sequence別に格納してください"
            )
        contract: dict[str, Any] = {"oracle_complete": contract_complete}
        normalized_state = _normalize_state_rows(raw["state"], label)
        runtime_position_required = raw.get(
            "runtime_position_map_load_required", False,
        )
        runtime_position_variant = raw.get("runtime_position_variant")
        runtime_position_execution = raw.get("interaction_execution")
        runtime_map_lifecycle = raw.get("runtime_map_lifecycle")
        if not isinstance(runtime_position_required, bool):
            _fail(f"state matrix {label} runtime position required不正")
        if runtime_position_required:
            trainer_tower_lifecycle = (
                isinstance(runtime_map_lifecycle, Mapping)
                and runtime_map_lifecycle.get("kind")
                    == "TRAINER_TOWER_ON_TRANSITION"
            )
            if trainer_tower_lifecycle:
                normalized_lifecycle = (
                    _validate_trainer_tower_runtime_map_lifecycle(
                        runtime_map_lifecycle, group=group,
                        map_number=map_number,
                        expected_object=object_position,
                        label=f"state matrix {label}",
                    )
                )
                if runtime_position_variant is not None \
                        or not isinstance(runtime_position_execution, Mapping):
                    _fail(
                        f"state matrix {label} Trainer Tower lifecycle不一致"
                    )
                execution_interaction = _catalog_interaction_execution({
                    "owner_key": owner_key,
                    "group": group, "map": map_number,
                    "local_id": local_id, "object": object_position,
                    "interaction_execution": runtime_position_execution,
                    "non_product_shadow_alias": shadow_by_owner.get(owner_key),
                }, f"state matrix {label}.trainer_tower_lifecycle")
                normalized_position_variant = None
                normalized_position_execution = {
                    key: deepcopy(execution_interaction[key]) for key in (
                        "trigger", "start", "walk_sequence", "stance", "action",
                        "interaction_distance", "counter_tile",
                        "actual_walk_required", "actual_walk_exception",
                        "walk_path_basis", "direct_script_call_forbidden",
                    )
                }
                normalized_runtime_map_lifecycle = normalized_lifecycle
            elif not owner_key.startswith("OBJECT:") \
                    or runtime_map_lifecycle is not None \
                    or not isinstance(runtime_position_variant, Mapping) \
                    or set(runtime_position_variant) != {
                        "variant_id", "control",
                    } \
                    or runtime_position_variant.get("variant_id") \
                        not in {"STATIC", "RUNTIME"} \
                    or not isinstance(runtime_position_execution, Mapping):
                _fail(f"state matrix {label} runtime position variant不正")
            else:
                expected_control = _RUNTIME_POSITION_EXPECTED_CONTROLS.get(
                    (group, map_number),
                )
                variant_id = str(runtime_position_variant["variant_id"])
                if expected_control is None:
                    _fail(f"state matrix {label} 未登録runtime position map")
                control = _validate_runtime_position_control(
                    runtime_position_variant.get("control"),
                    required=True, label=f"state matrix {label}",
                    state=normalized_state,
                )
                expected_value = bool(expected_control[
                    "runtime_value" if variant_id == "RUNTIME"
                    else "static_value"
                ])
                if control != {
                    "kind": expected_control["kind"],
                    "id": int(expected_control["id"]),
                    "value": expected_value,
                }:
                    _fail(f"state matrix {label} runtime position control不一致")
                execution_interaction = _catalog_interaction_execution({
                    "owner_key": owner_key,
                    "group": group, "map": map_number,
                    "local_id": local_id, "object": object_position,
                    "interaction_execution": runtime_position_execution,
                    "non_product_shadow_alias": shadow_by_owner.get(owner_key),
                }, f"state matrix {label}.runtime_position")
                normalized_position_execution = {
                    key: deepcopy(execution_interaction[key]) for key in (
                        "trigger", "start", "walk_sequence", "stance", "action",
                        "interaction_distance", "counter_tile",
                        "actual_walk_required", "actual_walk_exception",
                        "walk_path_basis", "direct_script_call_forbidden",
                    )
                }
                normalized_position_variant = {
                    "variant_id": variant_id, "control": control,
                }
                normalized_runtime_map_lifecycle = None
        else:
            if runtime_position_variant is not None \
                    or runtime_map_lifecycle is not None \
                    or not isinstance(runtime_position_execution, Mapping):
                _fail(f"state matrix {label} 非条件caseへposition契約過剰")
            execution_interaction = _catalog_interaction_execution({
                "owner_key": owner_key,
                "group": group, "map": map_number,
                "local_id": local_id, "object": object_position,
                "interaction_execution": runtime_position_execution,
                "non_product_shadow_alias": shadow_by_owner.get(owner_key),
            }, f"state matrix {label}.interaction")
            normalized_position_variant = None
            normalized_runtime_map_lifecycle = None
            normalized_position_execution = {
                key: deepcopy(execution_interaction[key]) for key in (
                    "trigger", "start", "walk_sequence", "stance", "action",
                    "interaction_distance", "counter_tile",
                    "actual_walk_required", "actual_walk_exception",
                    "walk_path_basis", "direct_script_call_forbidden",
                )
            }
        if contract_complete:
            families = contract_source["allowed_post_effect_families"]
            if not isinstance(families, list) \
                    or len(families) != len(set(families)) \
                    or any(family not in _POST_EFFECT_FAMILIES
                           for family in families):
                _fail(f"state matrix {label} allowed effect families不正")
            contract.update({
                "input_sequences": _normalize_input_sequences(
                    contract_source["input_sequences"], label,
                ),
                "allowed_post_effect_families": sorted(families),
                "allowed_post_effects": _normalize_allowed_post_effects(
                    contract_source["allowed_post_effects"], label,
                ),
            })
        normalized_sequences = contract.get("input_sequences", [])
        if terminal in {"FIELD_RELEASE", "BATTLE_START"} and any(
            (sequence["battle_start_required_postconditions"] is not None)
                is not (terminal == "BATTLE_START")
            for sequence in normalized_sequences
        ):
            _fail(
                f"state matrix {label} battle-start postcondition/terminal不一致"
            )
        raw_controls = contract_source["control_requirements"]
        if raw_controls is not None:
            contract["control_requirements"] = _normalize_control_requirements(
                raw_controls, normalized_state, normalized_sequences,
                fixture_registry, label,
            )
            contract["control_abi_complete"] = True
        else:
            contract["control_requirements"] = {"external": [], "internal": []}
            contract["control_abi_complete"] = False
        normalized[case_id] = {
            "case_id": case_id,
            "base_case_id": base_case_id,
            "owner_key": owner_key,
            "catalog_branch": catalog_branch,
            "group": group,
            "map": map_number,
            "object_index": object_index,
            "local_id": local_id,
            "object": object_position,
            "runtime_root": runtime_root,
            "state": normalized_state,
            "expect_visible": expect_visible,
            "expect_interaction": expect_interaction,
            "choice_candidates": list(choices),
            "expected_terminal": terminal,
            "interaction_execution": normalized_position_execution,
            "runtime_position_variant": normalized_position_variant,
            "runtime_position_map_load_required": runtime_position_required,
            "runtime_map_lifecycle": normalized_runtime_map_lifecycle,
            **contract,
        }
    if counts.get("interactive_case_count") != interactive_count \
            or counts.get("hidden_assertion_count") != hidden_count \
            or interactive_count + hidden_count != len(normalized):
        _fail("state matrix interactive/hidden count不一致")
    position_groups: dict[tuple[str, str], list[Mapping[str, Any]]] = {}
    conditioned_owners: dict[tuple[int, int], set[str]] = {}
    for row in normalized.values():
        if not row["runtime_position_map_load_required"]:
            continue
        if row["runtime_map_lifecycle"] is not None:
            continue
        key = (str(row["base_case_id"]), str(row["catalog_branch"]))
        position_groups.setdefault(key, []).append(row)
        map_key = (int(row["group"]), int(row["map"]))
        conditioned_owners.setdefault(map_key, set()).add(
            str(row["owner_key"]),
        )
    for key, rows in position_groups.items():
        variant_ids = [
            row["runtime_position_variant"]["variant_id"] for row in rows
        ]
        if set(variant_ids) \
                    != {"STATIC", "RUNTIME"} \
                or variant_ids.count("STATIC") \
                    != variant_ids.count("RUNTIME") \
                or len({tuple(row["object"]) for row in rows}) != 2:
            _fail(f"state matrix runtime position pair不一致:{key}")
    expected_owner_counts = {
        key: int(value["owner_count"])
        for key, value in _RUNTIME_POSITION_EXPECTED_CONTROLS.items()
    }
    actual_owner_counts = {
        key: len(owners) for key, owners in conditioned_owners.items()
    }
    production_matrix = counts.get("catalog_object_count") == 3108
    runtime_control_expansion = value.get("runtime_control_expansion")
    if runtime_control_expansion is not None and not isinstance(
        runtime_control_expansion, Mapping,
    ):
        _fail("state matrix runtime_control_expansion schema不一致")
    runtime_control_phase = (
        runtime_control_expansion.get("phase")
        if isinstance(runtime_control_expansion, Mapping) else None
    )
    runtime_control_expanded = runtime_control_phase is not None
    if runtime_control_expanded and runtime_control_phase \
            != "CONTROL_EXPANDED_ORACLE_CASE_BINDING_REQUIRED":
        _fail("state matrix runtime_control_expansion phase不一致")
    position_case_count = sum(
        row["runtime_position_map_load_required"]
        and row["runtime_map_lifecycle"] is None
        for row in normalized.values()
    )
    declared_owner_count = counts.get(
        "runtime_position_conditioned_owner_count", 0,
    )
    declared_base_case_count = counts.get(
        "runtime_position_variant_case_count", 0,
    )
    declared_expanded_count = counts.get(
        "runtime_position_expanded_case_count", position_case_count,
    )
    invalid_position_coverage = (
        any(
            count > expected_owner_counts.get(key, -1)
            for key, count in actual_owner_counts.items()
        )
        or declared_base_case_count != position_case_count
        or declared_expanded_count != position_case_count
        or declared_owner_count != sum(actual_owner_counts.values())
        or (
            "all_runtime_position_variants_expanded_exactly_once"
            in assertions
            and assertions[
                "all_runtime_position_variants_expanded_exactly_once"
            ] is not True
        )
        or (
            runtime_control_expanded
            and assertions.get(
                "all_runtime_position_base_cases_survive_runtime_expansion"
            ) is not True
        )
    )
    if production_matrix:
        invalid_position_coverage = invalid_position_coverage or (
            actual_owner_counts != expected_owner_counts
            or sum(actual_owner_counts.values()) != 16
            or declared_owner_count != 16
            or declared_base_case_count != 34
            or assertions.get(
                "all_runtime_position_variants_expanded_exactly_once"
            ) is not True
            or runtime_control_expanded and assertions.get(
                "all_runtime_position_base_cases_survive_runtime_expansion"
            ) is not True
        )
    elif not position_groups:
        invalid_position_coverage = invalid_position_coverage or (
            declared_owner_count != 0 or declared_base_case_count != 0
        )
    if invalid_position_coverage:
        _fail(
            "state matrix runtime position owner coverage不一致:"
            f"{actual_owner_counts}"
        )
    control_declared = bool(fixture_registry) or any(
        row["control_abi_complete"] for row in normalized.values()
    ) or "control_requirements" in set(projection.get("required_columns", []))
    if control_declared and any(
        not row["control_abi_complete"] for row in normalized.values()
    ):
        _fail("state matrix control ABIが全caseへone-to-one materializeされていません")
    referenced_fixtures: set[str] = set()
    for row in normalized.values():
        for external in row["control_requirements"]["external"]:
            required_value = external["required_value_in_matrix_case"]
            if isinstance(required_value, Mapping):
                referenced_fixtures.update(
                    reference for key, reference in required_value.items()
                    if key.endswith("_ref") and isinstance(reference, str)
                )
    dedicated_fixture_refs: set[str] = set()
    if gift_storage_sweep is not None:
        dedicated_fixture_refs = {
            row["fixture_key"] for row in gift_storage_sweep["scenarios"]
        }
    gift_fixture_refs = {
        reference for reference, fixture in fixture_registry.items()
        if fixture.get("fixture_kind") == "GIFT_STORAGE_TRANSACTION_STATE"
    }
    if gift_fixture_refs != dedicated_fixture_refs:
        _fail("state matrix GIFT_STORAGE dedicated fixture参照集合不一致")
    all_referenced_fixtures = referenced_fixtures | dedicated_fixture_refs
    if not all_referenced_fixtures <= set(fixture_registry) \
            or (all_referenced_fixtures != set(fixture_registry)
                and not isinstance(value.get("event_runtime_cases"), list)):
        _fail("state matrix runner_fixturesに未参照/欠落entryがあります")
    document = deepcopy(dict(value))
    document["runner_fixtures"] = fixture_registry
    if gift_storage_sweep is not None:
        document["dedicated_fixture_sweeps"] = {
            "GIFT_STORAGE_TRANSACTION_STATE": gift_storage_sweep,
        }
    document["runner_control_abi_sha256"] = _sha256(
        _stable(control_abi).encode("utf-8")
    )
    document["runner_control_abi_complete"] = control_declared
    return document, normalized


def load_state_matrix(
    path: Path, *, expected_rom_sha256: str,
) -> tuple[dict[str, Any], dict[str, dict[str, Any]]]:
    if not path.is_file():
        _fail(f"全NPC state matrixがありません: {path}")
    try:
        source = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as error:
        _fail(f"全NPC state matrixを読めません: {error}")
    return validate_state_matrix_document(
        source, expected_rom_sha256=expected_rom_sha256,
    )


def _event_rom_address(value: Any, label: str) -> int:
    if isinstance(value, str) and re.fullmatch(r"0x0[89][0-9A-Fa-f]{6}", value):
        value = int(value, 16)
    result = _int(value, label, 0x09FFFFFF)
    if result < 0x08000000:
        _fail(f"event runtime {label} ROM範囲外")
    return result


def _event_direction(value: Any, label: str) -> str:
    if value not in {"UP", "DOWN", "LEFT", "RIGHT"}:
        _fail(f"event runtime {label} cardinal direction不正")
    return str(value)


def _event_point(value: Any, label: str) -> dict[str, int]:
    if not isinstance(value, Mapping) or set(value) != {"x", "y"}:
        _fail(f"event runtime {label} point schema不正")
    return {
        axis: _int(value[axis], f"{label}.{axis}", 65535)
        for axis in ("x", "y")
    }


def _normalize_event_walk(
    value: Mapping[str, Any], label: str, *, endpoint: Mapping[str, int],
    allow_empty: bool = False,
) -> tuple[dict[str, int], list[str]]:
    start = _event_point(value.get("start_tile"), f"{label}.start_tile")
    tokens = value.get("walk_sequence")
    if not isinstance(tokens, list) or (not tokens and not allow_empty) \
            or len(tokens) > 128:
        _fail(f"event runtime {label}.walk_sequence不正")
    normalized = [
        _event_direction(token, f"{label}.walk_sequence[{index}]")
        for index, token in enumerate(tokens)
    ]
    cursor = [start["x"], start["y"]]
    deltas = {
        "UP": (0, -1), "DOWN": (0, 1),
        "LEFT": (-1, 0), "RIGHT": (1, 0),
    }
    for index, token in enumerate(normalized):
        dx, dy = deltas[token]
        cursor[0] += dx
        cursor[1] += dy
        if not 0 <= cursor[0] <= 65535 or not 0 <= cursor[1] <= 65535:
            _fail(f"event runtime {label}.walk_sequence[{index}]座標範囲外")
    if cursor != [endpoint["x"], endpoint["y"]]:
        _fail(
            f"event runtime {label}.walk終点不一致: "
            f"expected={[endpoint['x'], endpoint['y']]} actual={cursor}"
        )
    return start, normalized


def _normalize_event_map_transition_seed(
    value: Any, label: str,
) -> tuple[str, dict[str, Any]]:
    if not isinstance(value, Mapping):
        _fail(f"event runtime {label} MAP transition seed不正")
    def map_warp(raw: Any, row_label: str) -> dict[str, int]:
        if not isinstance(raw, Mapping) or set(raw) != {
            "group", "map", "warp_id",
        }:
            _fail(f"event runtime {row_label} map/warp schema不正")
        return {
            key: _int(raw[key], f"{row_label}.{key}", 255)
            for key in ("group", "map", "warp_id")
        }

    def map_identity(raw: Any, row_label: str) -> dict[str, int]:
        if not isinstance(raw, Mapping) or set(raw) != {"group", "map"}:
            _fail(f"event runtime {row_label} map schema不正")
        return {
            key: _int(raw[key], f"{row_label}.{key}", 255)
            for key in ("group", "map")
        }

    def point(raw: Any, row_label: str) -> dict[str, int]:
        if not isinstance(raw, Mapping) or set(raw) != {"x", "y"}:
            _fail(f"event runtime {row_label} point schema不正")
        return {
            "x": _int(raw["x"], f"{row_label}.x", 65535),
            "y": _int(raw["y"], f"{row_label}.y", 65535),
        }

    def provenance(raw: Any, row_label: str) -> dict[str, Any]:
        if not isinstance(raw, Mapping) or not raw:
            _fail(f"event runtime {row_label} provenance不正")
        return deepcopy(dict(raw))

    def boundary_step(
        *, seed_kind: str, explicit_kind: str | None,
    ) -> tuple[str, dict[str, Any]]:
        keys = {
            "source", "predecessor_tile", "trigger_tile", "trigger_key",
            "destination", "arrival_tile", "connection_or_warp_record_address",
            "source_provenance",
        } | ({"kind"} if explicit_kind is not None else set())
        if set(value) != keys or (
            explicit_kind is not None and value.get("kind") != explicit_kind
        ):
            _fail(f"event runtime {label}.{seed_kind} schema不一致")
        predecessor = point(value["predecessor_tile"], f"{label}.predecessor")
        trigger = point(value["trigger_tile"], f"{label}.trigger")
        key = _event_direction(value["trigger_key"], f"{label}.trigger_key")
        dx, dy = {
            "UP": (0, -1), "DOWN": (0, 1),
            "LEFT": (-1, 0), "RIGHT": (1, 0),
        }[key]
        if (predecessor["x"] + dx, predecessor["y"] + dy) != (
            trigger["x"], trigger["y"],
        ):
            _fail(f"event runtime {label}.{seed_kind} step geometry不一致")
        map_parser = map_warp if seed_kind == "stock_warp" else map_identity
        normalized = {
            "source": map_parser(value["source"], f"{label}.source"),
            "predecessor_tile": predecessor,
            "trigger_tile": trigger,
            "trigger_key": key,
            "destination": map_parser(
                value["destination"], f"{label}.destination",
            ),
            "arrival_tile": point(value["arrival_tile"], f"{label}.arrival"),
            "connection_or_warp_record_address": _event_rom_address(
                value["connection_or_warp_record_address"],
                f"{label}.connection_or_warp_record_address",
            ),
            "source_provenance": provenance(
                value["source_provenance"], f"{label}.{seed_kind}",
            ),
        }
        if explicit_kind is not None:
            normalized = {"kind": explicit_kind, **normalized}
        return seed_kind, normalized

    if value.get("kind") == "STOCK_CONNECTION_BOUNDARY_STEP":
        return boundary_step(
            seed_kind="stock_connection",
            explicit_kind="STOCK_CONNECTION_BOUNDARY_STEP",
        )
    if value.get("kind") == "ENGINE_PLAYER_TELEPORT_MAP_LOAD":
        keys = {
            "kind", "destination", "start_tile", "engine_entry",
            "source_provenance",
        }
        source = value.get("source_provenance")
        destination = map_identity(
            value.get("destination"), f"{label}.destination",
        )
        stock_scan = source.get("foreign_stock_warp_scan") \
            if isinstance(source, Mapping) else None
        stock_scan_keys = {
            "destination", "foreign_warp_reference_count",
            "usable_stock_warp_count", "invalid_source_warp_view_count",
            "unusable_reason_counts",
        }
        stock_scan_exact = (
            isinstance(stock_scan, Mapping)
            and set(stock_scan) == stock_scan_keys
            and stock_scan.get("destination")
                == [destination["group"], destination["map"]]
            and type(stock_scan.get("foreign_warp_reference_count")) is int
            and stock_scan["foreign_warp_reference_count"] >= 0
            and type(stock_scan.get("usable_stock_warp_count")) is int
            and stock_scan["usable_stock_warp_count"] == 0
            and type(stock_scan.get("invalid_source_warp_view_count")) is int
            and stock_scan["invalid_source_warp_view_count"] >= 0
            and isinstance(stock_scan.get("unusable_reason_counts"), Mapping)
            and all(
                isinstance(reason, str) and reason
                and type(count) is int and count >= 0
                for reason, count in stock_scan["unusable_reason_counts"].items()
            )
        )
        provenance_keys = {
            "kind", "rom_sha256", "layout_address", "block_address",
            "block_raw_hex", "block_raw_sha256", "base_collision",
            "base_elevation", "foreign_stock_warp_scan",
            "usable_stock_connection_count",
            "incoming_usable_zero_reason_bound",
            "first_root_hit_map_identity_required",
            "settled_map_identity_not_substituted_for_first_root_hit",
            "direct_root_call_forbidden", "direct_callback_call_forbidden",
        }
        if set(value) != keys \
                or value.get("engine_entry") != "BOOTSTRAP_KANTO_WARP" \
                or not isinstance(source, Mapping) \
                or set(source) != provenance_keys \
                or source.get("kind") \
                    != (
                        "FINAL_ROM_GEOMETRY_BOUND_ENGINE_PLAYER_"
                        "TELEPORT_MAP_LOAD"
                    ) \
                or not isinstance(source.get("rom_sha256"), str) \
                or _RAW_SHA256.fullmatch(source["rom_sha256"]) is None \
                or type(source.get("base_collision")) is not int \
                or source["base_collision"] != 0 \
                or type(source.get("base_elevation")) is not int \
                or not 0 <= source["base_elevation"] <= 15 \
                or not stock_scan_exact \
                or type(source.get("usable_stock_connection_count")) is not int \
                or source["usable_stock_connection_count"] != 0 \
                or any(source.get(key) is not True for key in (
                    "incoming_usable_zero_reason_bound",
                    "first_root_hit_map_identity_required",
                    "settled_map_identity_not_substituted_for_first_root_hit",
                    "direct_root_call_forbidden",
                    "direct_callback_call_forbidden",
                )):
            _fail(f"event runtime {label}.engine_teleport schema不一致")
        layout_address = _event_rom_address(
            source["layout_address"], f"{label}.layout_address",
        )
        block_address = _event_rom_address(
            source["block_address"], f"{label}.block_address",
        )
        try:
            block_raw = bytes.fromhex(source["block_raw_hex"])
        except (TypeError, ValueError):
            _fail(f"event runtime {label}.engine_teleport block raw不正")
        if len(block_raw) != 2 \
                or source["block_raw_hex"] != block_raw.hex() \
                or source.get("block_raw_sha256") != _sha256(block_raw):
            _fail(f"event runtime {label}.engine_teleport block hash不一致")
        normalized_source = deepcopy(dict(source))
        normalized_source["layout_address"] = f"0x{layout_address:08X}"
        normalized_source["block_address"] = f"0x{block_address:08X}"
        return "engine_teleport", {
            "kind": "ENGINE_PLAYER_TELEPORT_MAP_LOAD",
            "destination": destination,
            "start_tile": point(value["start_tile"], f"{label}.start_tile"),
            "engine_entry": "BOOTSTRAP_KANTO_WARP",
            "source_provenance": normalized_source,
        }
    if "source" in value:
        return boundary_step(seed_kind="stock_warp", explicit_kind=None)
    keys = {
        "callback_address", "actual_predecessor_consumer",
        "normal_trigger_tokens", "source_provenance",
    }
    if set(value) != keys \
            or value.get("normal_trigger_tokens") != ["START", "B"] \
            or not isinstance(value["source_provenance"], Mapping) \
            or not value["source_provenance"]:
        _fail(f"event runtime {label}.resume_callback schema不一致")
    predecessor = value["actual_predecessor_consumer"]
    predecessor_contracts = {
        "STOCK_WARP_THEN_FIELD_RETURN": "stock_warp",
        "STOCK_CONNECTION_THEN_FIELD_RETURN": "stock_connection",
        "ENGINE_TELEPORT_THEN_FIELD_RETURN": "engine_teleport",
    }
    predecessor_kind = predecessor.get("kind") \
        if isinstance(predecessor, Mapping) else None
    predecessor_key = predecessor_contracts.get(predecessor_kind)
    if predecessor_key is None or set(predecessor) != {
        "kind", predecessor_key, "field_return",
    }:
        _fail(f"event runtime {label}.resume predecessor schema不一致")
    normalized_kind, normalized_predecessor = _normalize_event_map_transition_seed(
        predecessor[predecessor_key],
        f"{label}.actual_predecessor.{predecessor_key}",
    )
    if normalized_kind != predecessor_key:
        _fail(f"event runtime {label}.resume predecessor discriminator不正")
    field_return = predecessor["field_return"]
    field_keys = {
        "kind", "normal_trigger_tokens",
        "callback_install_instruction_pc",
        "callback_dispatch_instruction_pc", "expected_map",
    }
    if not isinstance(field_return, Mapping) \
            or set(field_return) != field_keys \
            or field_return.get("kind") != "START_MENU_OPEN_CLOSE" \
            or field_return.get("normal_trigger_tokens") != ["START", "B"]:
        _fail(f"event runtime {label}.field_return schema不一致")
    expected_map = map_identity(
        field_return["expected_map"], f"{label}.field_return.expected_map",
    )
    destination = normalized_predecessor["destination"]
    if expected_map != {
        "group": destination["group"], "map": destination["map"],
    }:
        _fail(f"event runtime {label}.field_return destination不一致")
    return "resume_callback", {
        "callback_address": _event_rom_address(
            value["callback_address"], f"{label}.callback_address",
        ),
        "actual_predecessor_consumer": {
            "kind": predecessor_kind,
            predecessor_key: normalized_predecessor,
            "field_return": {
                "kind": "START_MENU_OPEN_CLOSE",
                "normal_trigger_tokens": ["START", "B"],
                "callback_install_instruction_pc": _event_rom_address(
                    field_return["callback_install_instruction_pc"],
                    f"{label}.field_return.callback_install_instruction_pc",
                ),
                "callback_dispatch_instruction_pc": _event_rom_address(
                    field_return["callback_dispatch_instruction_pc"],
                    f"{label}.field_return.callback_dispatch_instruction_pc",
                ),
                "expected_map": expected_map,
            },
        },
        "normal_trigger_tokens": ["START", "B"],
        "source_provenance": deepcopy(dict(value["source_provenance"])),
    }


def _normalize_event_trigger_path(
    value: Any, label: str, *, nested: bool = False,
) -> dict[str, Any]:
    if not isinstance(value, Mapping) or not isinstance(value.get("kind"), str):
        _fail(f"event runtime {label}.trigger_path schema不正")
    kind = value["kind"]
    if kind not in _EVENT_TRIGGER_KINDS:
        _fail(f"event runtime {label}.trigger_path kind未知: {kind!r}")
    common = {"kind", "group", "map"}
    if kind == "MAP_LIFECYCLE_COMPOSITE_TRIGGER":
        keys = {
            "kind", "map", "producer_contracts", "field_return_contract",
        }
        if nested or set(value) != keys:
            _fail(f"event runtime {label} MAP composite trigger schema不一致")
        raw_map = value["map"]
        if not isinstance(raw_map, Mapping) or set(raw_map) != {"group", "map"}:
            _fail(f"event runtime {label} MAP composite map schema不正")
        map_id = {
            "group": _int(raw_map["group"], f"{label}.map.group", 255),
            "map": _int(raw_map["map"], f"{label}.map.map", 255),
        }
        raw_producers = value["producer_contracts"]
        producer_keys = {
            "producer_ordinal", "producer_kind", "trigger_tokens",
            "source_trigger_path", "producer_evidence",
        }
        if not isinstance(raw_producers, list) or not raw_producers:
            _fail(f"event runtime {label} MAP composite producer列不正")
        producers: list[dict[str, Any]] = []
        for index, raw in enumerate(raw_producers):
            producer_label = f"{label}.producer_contracts[{index}]"
            if not isinstance(raw, Mapping) or set(raw) != producer_keys \
                    or raw["producer_ordinal"] != index \
                    or raw["producer_kind"] not in {
                        "STOCK_WARP", "ENGINE_TELEPORT", "CONNECTION",
                    }:
                _fail(f"event runtime {producer_label} exact schema不正")
            source = _normalize_event_trigger_path(
                raw["source_trigger_path"],
                f"{producer_label}.source_trigger_path", nested=True,
            )
            if source["kind"] != "MAP_TRANSITION_LOAD" \
                    or {"group": source["group"], "map": source["map"]} \
                        != map_id:
                _fail(f"event runtime {producer_label} source map不正")
            raw_source = raw["source_trigger_path"]
            if "resume_callback" in source:
                predecessor = source["resume_callback"][
                    "actual_predecessor_consumer"
                ]
                raw_predecessor = raw_source["resume_callback"][
                    "actual_predecessor_consumer"
                ]
                seed_key = next((key for key in _EVENT_MAP_LOAD_SEED_KEYS
                                 if key in predecessor), None)
                evidence = raw_predecessor.get(seed_key) \
                    if seed_key is not None else None
            else:
                seed_key = next((key for key in _EVENT_MAP_LOAD_SEED_KEYS
                                 if key in source), None)
                evidence = raw_source.get(seed_key) \
                    if seed_key is not None else None
            expected_kind = {
                "stock_warp": "STOCK_WARP",
                "stock_connection": "CONNECTION",
                "engine_teleport": "ENGINE_TELEPORT",
            }.get(seed_key)
            tokens = raw["trigger_tokens"]
            if expected_kind != raw["producer_kind"] \
                    or not isinstance(tokens, list) \
                    or tokens != list(_MAP_LIFECYCLE_PRODUCER_TOKENS[
                        raw["producer_kind"]
                    ]) \
                    or raw["producer_evidence"] != evidence:
                _fail(f"event runtime {producer_label} producer binding不正")
            producers.append({
                "producer_ordinal": index,
                "producer_kind": raw["producer_kind"],
                "trigger_tokens": list(tokens),
                "source_trigger_path": source,
                "producer_evidence": deepcopy(evidence),
            })
        field_return_raw = value["field_return_contract"]
        field_return = None
        if field_return_raw is not None:
            if not isinstance(field_return_raw, Mapping) or set(field_return_raw) != {
                "normal_trigger_tokens", "source_trigger_path",
            } or field_return_raw.get("normal_trigger_tokens") != ["START", "B"]:
                _fail(f"event runtime {label} field-return contract schema不正")
            source = _normalize_event_trigger_path(
                field_return_raw["source_trigger_path"],
                f"{label}.field_return.source_trigger_path", nested=True,
            )
            if source["kind"] != "MAP_TRANSITION_LOAD" \
                    or "resume_callback" not in source \
                    or {"group": source["group"], "map": source["map"]} \
                        != map_id:
                _fail(f"event runtime {label} field-return source不正")
            field_return = {
                "normal_trigger_tokens": ["START", "B"],
                "source_trigger_path": source,
            }
        result = {
            "kind": kind,
            "map": map_id,
            "producer_contracts": producers,
            "field_return_contract": field_return,
        }
    elif kind == "OBJECT_FACE_A":
        keys = common | {
            "local_id", "object_index", "root_pc", "approach",
            "start_tile", "walk_sequence", "stance_tile",
            "required_facing", "runtime_topology_probe_required",
        }
        if set(value) != keys or value.get("approach") \
                != "WALK_ADJACENT_FACE_A":
            _fail(f"event runtime {label} OBJECT trigger schema不一致")
        stance = _event_point(value["stance_tile"], f"{label}.stance_tile")
        start, walk = _normalize_event_walk(
            value, label, endpoint=stance, allow_empty=True,
        )
        probe = value["runtime_topology_probe_required"]
        if not isinstance(probe, bool) or (
            not walk and (not probe or start != stance)
        ):
            _fail(f"event runtime {label} OBJECT walk/topology probe不正")
        result = {
            "kind": kind,
            "group": _int(value["group"], f"{label}.group", 255),
            "map": _int(value["map"], f"{label}.map", 255),
            "local_id": _int(value["local_id"], f"{label}.local_id", 255),
            "object_index": _int(
                value["object_index"], f"{label}.object_index", 255,
            ),
            "root_pc": _event_rom_address(value["root_pc"], f"{label}.root_pc"),
            "approach": "WALK_ADJACENT_FACE_A",
            "start_tile": start, "walk_sequence": walk,
            "stance_tile": stance,
            "required_facing": _event_direction(
                value["required_facing"], f"{label}.required_facing",
            ),
            "runtime_topology_probe_required": probe,
        }
    elif kind == "BG_FACE_A":
        keys = common | {
            "x", "y", "elevation", "start_tile", "walk_sequence",
            "stance_tile", "required_facing", "root_pc",
        }
        if set(value) != keys:
            _fail(f"event runtime {label} BG trigger schema不一致")
        target = {
            "x": _int(value["x"], f"{label}.x", 65535),
            "y": _int(value["y"], f"{label}.y", 65535),
        }
        stance = _event_point(value["stance_tile"], f"{label}.stance_tile")
        start, walk = _normalize_event_walk(
            value, label, endpoint=stance,
        )
        facing = _event_direction(
            value["required_facing"], f"{label}.required_facing",
        )
        dx, dy = {
            "UP": (0, -1), "DOWN": (0, 1),
            "LEFT": (-1, 0), "RIGHT": (1, 0),
        }[facing]
        if (stance["x"] + dx, stance["y"] + dy) != (
            target["x"], target["y"],
        ):
            _fail(f"event runtime {label} BG stance/facing/target不一致")
        result = {
            "kind": kind,
            "group": _int(value["group"], f"{label}.group", 255),
            "map": _int(value["map"], f"{label}.map", 255),
            **target,
            "elevation": _int(value["elevation"], f"{label}.elevation", 15),
            "start_tile": start, "walk_sequence": walk,
            "stance_tile": stance, "required_facing": facing,
            "root_pc": _event_rom_address(value["root_pc"], f"{label}.root_pc"),
        }
    elif kind == "COORD_STEP":
        keys = common | {
            "x", "y", "elevation", "trigger_var", "trigger_value",
            "start_tile", "walk_sequence", "trigger_key", "root_pc",
        }
        if set(value) != keys:
            _fail(f"event runtime {label} COORD trigger schema不一致")
        target = {
            "x": _int(value["x"], f"{label}.x", 65535),
            "y": _int(value["y"], f"{label}.y", 65535),
        }
        start, walk = _normalize_event_walk(value, label, endpoint=target)
        trigger_key = _event_direction(
            value["trigger_key"], f"{label}.trigger_key",
        )
        if walk[-1] != trigger_key:
            _fail(f"event runtime {label} COORD final walk/trigger key不一致")
        result = {
            "kind": kind,
            "group": _int(value["group"], f"{label}.group", 255),
            "map": _int(value["map"], f"{label}.map", 255),
            **target,
            "elevation": _int(value["elevation"], f"{label}.elevation", 15),
            "trigger_var": _int(
                value["trigger_var"], f"{label}.trigger_var", 0xFFFF,
            ),
            "trigger_value": _int(
                value["trigger_value"], f"{label}.trigger_value", 0xFFFF,
            ),
            "start_tile": start, "walk_sequence": walk,
            "trigger_key": trigger_key,
            "root_pc": _event_rom_address(value["root_pc"], f"{label}.root_pc"),
        }
    elif kind == "MAP_TRANSITION_LOAD":
        subkind = value.get("root_subkind")
        base_keys = common | {
            "root_subkind", "map_script_tag", "entry", "root_pc",
        }
        mechanism_keys = {
            "stock_warp", "stock_connection", "engine_teleport",
            "resume_callback",
        } & set(value)
        if len(mechanism_keys) != 1:
            _fail(f"event runtime {label} MAP transition seed過不足")
        mechanism_key = next(iter(mechanism_keys))
        base_keys = base_keys | {mechanism_key}
        condition_keys = base_keys | {
            "left_operand", "right_operand", "required_relation",
            "precedence_guards",
        }
        if subkind == "DIRECT":
            if set(value) != base_keys:
                _fail(f"event runtime {label} MAP DIRECT schema不一致")
        elif subkind == "CONDITION":
            if set(value) != condition_keys \
                    or value.get("required_relation") != "EQUAL":
                _fail(f"event runtime {label} MAP CONDITION schema不一致")
        else:
            _fail(f"event runtime {label} MAP root_subkind未知")
        entry = "STOCK_WARP_OR_CONNECTION_OR_ENGINE_TELEPORT_OR_RESUME_CALLBACK"
        if value.get("entry") != entry:
            _fail(f"event runtime {label} MAP entry不一致")
        result = {
            "kind": kind,
            "group": _int(value["group"], f"{label}.group", 255),
            "map": _int(value["map"], f"{label}.map", 255),
            "root_subkind": subkind,
            "map_script_tag": _int(
                value["map_script_tag"], f"{label}.map_script_tag", 255,
            ),
            "entry": entry,
            "root_pc": _event_rom_address(value["root_pc"], f"{label}.root_pc"),
        }
        normalized_seed_key, normalized_seed = _normalize_event_map_transition_seed(
            value[mechanism_key], f"{label}.{mechanism_key}",
        )
        if normalized_seed_key != mechanism_key:
            _fail(f"event runtime {label} MAP seed discriminator不一致")
        result[mechanism_key] = normalized_seed
        if mechanism_key == "resume_callback":
            predecessor = normalized_seed["actual_predecessor_consumer"]
            nested_key = next(
                key for key in (
                    "stock_warp", "stock_connection", "engine_teleport",
                ) if key in predecessor
            )
            transition_seed = predecessor[nested_key]
        else:
            transition_seed = normalized_seed
        if transition_seed["destination"]["group"] != result["group"] \
                or transition_seed["destination"]["map"] != result["map"]:
            _fail(f"event runtime {label} MAP destination/root map不一致")
        if mechanism_key == "resume_callback":
            expected_map = normalized_seed[
                "actual_predecessor_consumer"
            ]["field_return"]["expected_map"]
            if expected_map != {
                "group": result["group"], "map": result["map"],
            }:
                _fail(f"event runtime {label} MAP field-return map不一致")
        if subkind == "CONDITION":
            left_operand = _int(
                value["left_operand"], f"{label}.left_operand", 0xFFFF,
            )
            right_operand = _int(
                value["right_operand"], f"{label}.right_operand", 0xFFFF,
            )
            if not (0x4000 <= left_operand <= 0x40FF
                    or 0x5000 <= left_operand <= 0x51FF) \
                    or not 0 <= right_operand < 0x4000:
                _fail(f"event runtime {label} MAP condition operand不正")
            raw_guards = value["precedence_guards"]
            if not isinstance(raw_guards, list) or len(raw_guards) > 8:
                _fail(f"event runtime {label} MAP precedence guard数不正")
            guards: list[dict[str, Any]] = []
            previous_variable = -1
            for guard_index, raw_guard in enumerate(raw_guards):
                guard_label = f"{label}.precedence_guards[{guard_index}]"
                if not isinstance(raw_guard, Mapping) or set(raw_guard) != {
                    "variable", "required_value", "forbidden_values",
                    "relation", "source_conditions",
                } or raw_guard.get("relation") != \
                        "NOT_EQUAL_ALL_PRECEDING_VALUES":
                    _fail(f"event runtime {guard_label} schema不一致")
                variable = _int(
                    raw_guard["variable"], f"{guard_label}.variable", 0xFFFF,
                )
                required_value = _int(
                    raw_guard["required_value"],
                    f"{guard_label}.required_value", 0xFFFF,
                )
                forbidden = raw_guard["forbidden_values"]
                sources = raw_guard["source_conditions"]
                forbidden_values_valid = isinstance(forbidden, list) \
                    and bool(forbidden) and all(
                        not isinstance(item, bool) and isinstance(item, int)
                        and 0 <= item < 0x4000 for item in forbidden
                    )
                if not (0x4000 <= variable <= 0x40FF
                        or 0x5000 <= variable <= 0x51FF) \
                        or variable <= previous_variable \
                        or variable == left_operand \
                        or not forbidden_values_valid \
                        or forbidden != sorted(set(forbidden)) \
                        or required_value in forbidden \
                        or required_value >= 0x4000 \
                        or not isinstance(sources, list) or not sources:
                    _fail(f"event runtime {guard_label} value/order不一致")
                normalized_sources: list[dict[str, Any]] = []
                previous_condition_index = -1
                for source_index, raw_source in enumerate(sources):
                    source_label = (
                        f"{guard_label}.source_conditions[{source_index}]"
                    )
                    if not isinstance(raw_source, Mapping) or set(raw_source) != {
                        "condition_index", "record_address", "record_raw_hex",
                        "record_raw_sha256", "variable", "value", "root_pc",
                    }:
                        _fail(f"event runtime {source_label} schema不一致")
                    condition_index = _int(
                        raw_source["condition_index"],
                        f"{source_label}.condition_index", 255,
                    )
                    record_address = _event_rom_address(
                        raw_source["record_address"],
                        f"{source_label}.record_address",
                    )
                    root_pc = _event_rom_address(
                        raw_source["root_pc"], f"{source_label}.root_pc",
                    )
                    source_variable = _int(
                        raw_source["variable"],
                        f"{source_label}.variable", 0xFFFF,
                    )
                    source_value = _int(
                        raw_source["value"], f"{source_label}.value", 0xFFFF,
                    )
                    raw_hex, raw_sha = (
                        raw_source["record_raw_hex"],
                        raw_source["record_raw_sha256"],
                    )
                    try:
                        record_raw = bytes.fromhex(raw_hex)
                    except (TypeError, ValueError):
                        _fail(f"event runtime {source_label} raw hex不正")
                    if condition_index <= previous_condition_index \
                            or source_variable != variable \
                            or source_value >= 0x4000 \
                            or len(record_raw) != 8 \
                            or int.from_bytes(record_raw[0:2], "little") != variable \
                            or int.from_bytes(record_raw[2:4], "little") != source_value \
                            or int.from_bytes(record_raw[4:8], "little") != root_pc \
                            or not isinstance(raw_sha, str) \
                            or hashlib.sha256(record_raw).hexdigest() != raw_sha:
                        _fail(f"event runtime {source_label} ROM evidence不一致")
                    normalized_sources.append({
                        "condition_index": condition_index,
                        "record_address": record_address,
                        "record_raw_hex": raw_hex,
                        "record_raw_sha256": raw_sha,
                        "variable": source_variable,
                        "value": source_value,
                        "root_pc": root_pc,
                    })
                    previous_condition_index = condition_index
                if forbidden != sorted({
                    source["value"] for source in normalized_sources
                }):
                    _fail(f"event runtime {guard_label} forbidden evidence不一致")
                guards.append({
                    "variable": variable,
                    "required_value": required_value,
                    "forbidden_values": list(forbidden),
                    "relation": "NOT_EQUAL_ALL_PRECEDING_VALUES",
                    "source_conditions": normalized_sources,
                })
                previous_variable = variable
            result.update({
                "left_operand": left_operand,
                "right_operand": right_operand,
                "required_relation": "EQUAL",
                "precedence_guards": guards,
            })
    elif kind == "COMMON_CALLER_TRIGGER":
        keys = {
            "kind", "standard_index", "caller_owner_id", "caller_owner_kind",
            "caller_instruction_pc", "caller_trigger_path", "root_pc",
        }
        if set(value) != keys or nested:
            _fail(f"event runtime {label} COMMON direct/nested schema不一致")
        owner_kind = value["caller_owner_kind"]
        if owner_kind not in {"OBJECT", "BG", "COORD", "MAP"}:
            _fail(f"event runtime {label} COMMON caller owner kind不正")
        caller = _normalize_event_trigger_path(
            value["caller_trigger_path"], f"{label}.caller_trigger_path",
            nested=True,
        )
        expected_caller_kind = {
            "OBJECT": "OBJECT_FACE_A", "BG": "BG_FACE_A",
            "COORD": "COORD_STEP", "MAP": "MAP_TRANSITION_LOAD",
        }[owner_kind]
        if caller["kind"] != expected_caller_kind:
            _fail(f"event runtime {label} COMMON caller trigger/kind不一致")
        owner_id = value["caller_owner_id"]
        if not isinstance(owner_id, str) or _OWNER_ID.fullmatch(owner_id) is None:
            _fail(f"event runtime {label} COMMON caller owner ID不正")
        result = {
            "kind": kind,
            "standard_index": _int(
                value["standard_index"], f"{label}.standard_index", 255,
            ),
            "caller_owner_id": owner_id,
            "caller_owner_kind": owner_kind,
            "caller_instruction_pc": _event_rom_address(
                value["caller_instruction_pc"],
                f"{label}.caller_instruction_pc",
            ),
            "caller_trigger_path": caller,
            "root_pc": _event_rom_address(value["root_pc"], f"{label}.root_pc"),
        }
    else:
        base_keys = common | {
            "variant", "x", "y", "elevation", "underfoot", "item_id",
            "quantity", "collection_flag", "entry", "consumer_script_root",
            "consumer_root_expected_hit", "source_provenance", "start_tile",
            "walk_sequence",
        }
        keys = base_keys | ({"trigger_key"} if value.get("underfoot") else {
            "stance_tile", "required_facing",
        })
        if set(value) != keys:
            _fail(f"event runtime {label} HIDDEN schema不一致")
        variant = value["variant"]
        if variant not in {
            "AVAILABLE_SUCCESS", "AVAILABLE_BAG_FULL",
            "AVAILABLE_COIN_FULL", "AVAILABLE_NO_COIN_CASE",
            "ALREADY_COLLECTED",
        } or not isinstance(value["underfoot"], bool) \
                or not isinstance(value["consumer_root_expected_hit"], bool) \
                or not isinstance(value["source_provenance"], Mapping) \
                or not value["source_provenance"]:
            _fail(f"event runtime {label} HIDDEN variant/underfoot不正")
        if value["consumer_root_expected_hit"] \
                is not (variant != "ALREADY_COLLECTED"):
            _fail(
                f"event runtime {label} HIDDEN variant/consumer root hit不一致"
            )
        expected_entry = "ITEMFINDER_UNDERFOOT" \
            if value["underfoot"] else "FACE_A"
        if value["entry"] != expected_entry:
            _fail(f"event runtime {label} HIDDEN entry/underfoot不一致")
        target = {
            "x": _int(value["x"], f"{label}.x", 65535),
            "y": _int(value["y"], f"{label}.y", 65535),
        }
        if value["underfoot"]:
            start, walk = _normalize_event_walk(value, label, endpoint=target)
            trigger_key = _event_direction(
                value["trigger_key"], f"{label}.trigger_key",
            )
            if walk[-1] != trigger_key:
                _fail(f"event runtime {label} HIDDEN final walk/trigger key不一致")
            geometry = {
                "start_tile": start, "walk_sequence": walk,
                "trigger_key": trigger_key,
            }
        else:
            stance = _event_point(
                value["stance_tile"], f"{label}.stance_tile",
            )
            start, walk = _normalize_event_walk(
                value, label, endpoint=stance,
            )
            facing = _event_direction(
                value["required_facing"], f"{label}.required_facing",
            )
            dx, dy = {
                "UP": (0, -1), "DOWN": (0, 1),
                "LEFT": (-1, 0), "RIGHT": (1, 0),
            }[facing]
            if (stance["x"] + dx, stance["y"] + dy) != (
                target["x"], target["y"],
            ):
                _fail(f"event runtime {label} HIDDEN stance/facing不一致")
            geometry = {
                "start_tile": start, "walk_sequence": walk,
                "stance_tile": stance, "required_facing": facing,
            }
        result = {
            "kind": kind,
            "variant": variant,
            "group": _int(value["group"], f"{label}.group", 255),
            "map": _int(value["map"], f"{label}.map", 255),
            **target,
            "elevation": _int(value["elevation"], f"{label}.elevation", 15),
            "underfoot": value["underfoot"],
            "item_id": _int(value["item_id"], f"{label}.item_id", 0xFFFF),
            "quantity": _int(value["quantity"], f"{label}.quantity", 0xFFFF),
            "collection_flag": _int(
                value["collection_flag"], f"{label}.collection_flag", 0x18FF,
            ),
            "consumer_root_expected_hit": value[
                "consumer_root_expected_hit"
            ],
            "entry": expected_entry,
            "consumer_script_root": _event_rom_address(
                value["consumer_script_root"],
                f"{label}.consumer_script_root",
            ),
            "source_provenance": deepcopy(dict(value["source_provenance"])),
            **geometry,
        }
    return result


def _event_trigger_tokens(trigger: Mapping[str, Any]) -> tuple[str, ...]:
    kind = str(trigger["kind"])
    if kind == "MAP_LIFECYCLE_COMPOSITE_TRIGGER":
        producers = trigger.get("producer_contracts")
        if not isinstance(producers, list) or not producers:
            _fail("event runtime MAP composite producer contract欠落")
        return tuple(producers[0]["trigger_tokens"])
    if kind == "COMMON_CALLER_TRIGGER":
        return _event_trigger_tokens(trigger["caller_trigger_path"])
    if kind == "HIDDEN_ITEM":
        return (
            ("WALK_ONTO_COORD", "USE_ITEMFINDER")
            if trigger["underfoot"] else
            ("WALK_TO_ADJACENT", "FACE_REQUIRED_DIRECTION", "A")
        )
    if kind == "MAP_TRANSITION_LOAD":
        if "resume_callback" in trigger:
            return tuple(trigger["resume_callback"]["normal_trigger_tokens"])
        if "engine_teleport" in trigger:
            return (
                "ENGINE_PLAYER_TELEPORT_MAP_LOAD", "WAIT_FIRST_ROOT_HIT",
            )
        if "stock_connection" in trigger:
            return ("WALK_ACROSS_CONNECTION", "WAIT_FIRST_ROOT_HIT")
    return _EVENT_TRIGGER_TOKEN_PREFIXES[kind]


def _normalize_post_battle_continuation(
    value: Any, label: str,
) -> dict[str, Any] | None:
    """通常interactionと混ぜず、battle後だけのsource契約を保持する。"""

    if value is None:
        return None
    keys = {
        "phase", "runner_capture_required", "tokens", "visible_printers",
        "decision_trace", "effect_relations", "field_terminal_kind",
        "resume_kind", "resume_pc", "chained_battles",
    }
    if not isinstance(value, Mapping) or set(value) != keys \
            or value.get("phase") != "POST_BATTLE_CONTINUATION" \
            or value.get("runner_capture_required") is not True \
            or not isinstance(value.get("tokens"), list) \
            or any(not isinstance(token, str) or not token
                   for token in value["tokens"]) \
            or not isinstance(value.get("visible_printers"), list) \
            or any(not isinstance(row, Mapping)
                   for row in value["visible_printers"]) \
            or not isinstance(value.get("decision_trace"), list) \
            or any(not isinstance(row, Mapping)
                   for row in value["decision_trace"]) \
            or not isinstance(value.get("effect_relations"), list) \
            or any(not isinstance(row, Mapping)
                   for row in value["effect_relations"]) \
            or not isinstance(value.get("chained_battles"), list) \
            or len(value["chained_battles"]) > _MAX_CHAINED_BATTLES \
            or value.get("field_terminal_kind") not in {
                "FIELD_RELEASE", _FACILITY_ACTIVE_CONTINUATION_TERMINAL,
            } \
            or value.get("resume_kind") not in {
                "STANDARD", "EXPLICIT", "NEXT_PC",
            }:
        _fail(f"event runtime {label} post-battle continuation exact schema不正")
    resume_pc = value["resume_pc"]
    if value["resume_kind"] == "STANDARD":
        if resume_pc is not None:
            _fail(f"event runtime {label} STANDARD resume PCはnull必須")
    elif not isinstance(resume_pc, str) \
            or re.fullmatch(r"0x0[89][0-9A-F]{6}", resume_pc) is None:
        _fail(f"event runtime {label} explicit/next resume PC不正")
    chained_keys = {
        "phase_index", "battle_kind", "trainer_id",
        "start_instruction_address", "resume_kind", "resume_pc",
    }
    for index, battle in enumerate(value["chained_battles"], start=2):
        if not isinstance(battle, Mapping) or set(battle) != chained_keys \
                or battle.get("phase_index") != index \
                or battle.get("battle_kind") not in {
                    "TRAINER", "TRAINER_TOWER", "SCRIPTED_WILD",
                } \
                or not isinstance(
                    battle.get("start_instruction_address"), str,
                ) \
                or re.fullmatch(
                    r"0x0[89][0-9A-F]{6}",
                    battle["start_instruction_address"],
                ) is None \
                or battle.get("resume_kind") not in {
                    "STANDARD", "EXPLICIT", "NEXT_PC",
                }:
            _fail(f"event runtime {label} chained battle[{index}] schema不正")
        trainer_id = battle["trainer_id"]
        chained_pc = battle["resume_pc"]
        if battle["battle_kind"] == "TRAINER":
            if isinstance(trainer_id, bool) \
                    or not isinstance(trainer_id, int) \
                    or not 0 <= trainer_id < 0x300:
                _fail(
                    f"event runtime {label} chained trainer[{index}]不正"
                )
        elif trainer_id is not None \
                or battle["resume_kind"] != "NEXT_PC":
            _fail(
                f"event runtime {label} chained non-trainer[{index}]不正"
            )
        if battle["resume_kind"] == "STANDARD":
            if chained_pc is not None:
                _fail(
                    f"event runtime {label} chained STANDARD PC非null"
                )
        elif not isinstance(chained_pc, str) \
                or re.fullmatch(r"0x0[89][0-9A-F]{6}", chained_pc) is None:
            _fail(f"event runtime {label} chained resume PC不正")
    return deepcopy(dict(value))


def _validate_facility_continuation_terminals(
    sequences: Sequence[Mapping[str, Any]],
    external_controls: Sequence[Mapping[str, Any]], label: str,
) -> None:
    """Bind the exceptional active endpoint to its exact helper fixture.

    A Facility session normally closes at field release.  Three Factory
    scenarios intentionally stop at the native return that begins the next
    transaction.  The terminal is therefore derived from the final immutable
    helper trace row, never accepted as a free-standing sequence property.
    """

    facility_controls = [
        row for row in external_controls
        if row.get("kind") == "FACILITY_SESSION"
    ]
    if len(facility_controls) > 1:
        _fail(f"{label} FACILITY_SESSION controlはattemptごとに1件以下です")
    expected_terminal = "FIELD_RELEASE"
    if facility_controls:
        required = facility_controls[0].get("required_value_in_matrix_case")
        trace = required.get("trace") if isinstance(required, Mapping) else None
        scenario_key = required.get("scenario_key") \
            if isinstance(required, Mapping) else None
        if not isinstance(trace, list) or not trace \
                or not isinstance(trace[-1], Mapping) \
                or not isinstance(scenario_key, str):
            _fail(f"{label} FACILITY_SESSION terminal source trace不正")
        final_operation = trace[-1].get("operation")
        final_active = trace[-1].get("active")
        declared_operation = _FACILITY_ACTIVE_CONTINUATION_SCENARIOS.get(
            scenario_key,
        )
        if not isinstance(final_active, bool) \
                or not isinstance(final_operation, str) \
                or (declared_operation is not None) is not final_active \
                or declared_operation is not None \
                and final_operation != declared_operation:
            _fail(f"{label} FACILITY_SESSION active endpoint registry drift")
        if final_active:
            expected_terminal = _FACILITY_ACTIVE_CONTINUATION_TERMINAL
    for index, sequence in enumerate(sequences):
        continuation = sequence.get("post_battle_continuation")
        if continuation is None:
            continue
        if not isinstance(continuation, Mapping) \
                or continuation.get("field_terminal_kind") \
                    != expected_terminal:
            _fail(
                f"{label}.input_sequences[{index}] FACILITY_SESSION "
                "post-battle terminal相関不一致"
            )


def _map_lifecycle_hex_address(value: Any, label: str) -> str | None:
    if value is None:
        return None
    address = _event_rom_address(value, label)
    canonical = f"0x{address:08X}"
    if value != canonical:
        _fail(f"event runtime {label} canonical ROM address不正")
    return canonical


def _normalize_map_lifecycle_topology(
    value: Any, label: str,
) -> dict[str, Any]:
    """ROM decoder出力をnested keyまでexactに固定する。"""

    root_keys = {
        "schema_version", "kind", "map", "map_id", "header_address",
        "table_pointer", "outer_rows", "by_tag", "rom_sha256",
    }
    if not isinstance(value, Mapping) or set(value) != root_keys \
            or value.get("schema_version") != 1 \
            or value.get("kind") != "STAGE61_MAP_LIFECYCLE_TOPOLOGY":
        _fail(f"event runtime {label} topology root exact schema不正")
    raw_map = value["map"]
    if not isinstance(raw_map, Mapping) or set(raw_map) != {"group", "map"}:
        _fail(f"event runtime {label}.map exact schema不正")
    group = _int(raw_map["group"], f"{label}.map.group", 255)
    number = _int(raw_map["map"], f"{label}.map.map", 255)
    map_id = f"{group:03d}/{number:03d}"
    header = _event_rom_address(value["header_address"], f"{label}.header")
    table_raw = value["table_pointer"]
    table = None if table_raw is None else _event_rom_address(
        table_raw, f"{label}.table_pointer",
    )
    digest = value["rom_sha256"]
    if value["map_id"] != map_id \
            or not isinstance(digest, str) \
            or re.fullmatch(r"[0-9a-f]{64}", digest) is None:
        _fail(f"event runtime {label} topology map/hash不正")
    rows = value["outer_rows"]
    by_tag = value["by_tag"]
    if not isinstance(rows, list) or len(rows) > 64 \
            or not isinstance(by_tag, Mapping):
        _fail(f"event runtime {label} topology row/table不正")
    normalized_rows: list[dict[str, Any]] = []
    tags: list[int] = []
    for index, raw in enumerate(rows):
        row_label = f"{label}.outer_rows[{index}]"
        if not isinstance(raw, Mapping):
            _fail(f"event runtime {row_label} mapping不正")
        dispatch_kind = raw.get("dispatch_kind")
        common_keys = {
            "outer_index", "tag", "record_address", "pointer_field_address",
            "record_raw_hex", "record_raw_sha256", "dispatch_kind",
        }
        keys = common_keys | (
            {"condition_table_pointer", "conditions"}
            if dispatch_kind == "CONDITION_TABLE" else
            {"root_pc", "root_field_address", "owner_id"}
            if dispatch_kind == "DIRECT" else set()
        )
        if dispatch_kind not in {"DIRECT", "CONDITION_TABLE"} \
                or set(raw) != keys:
            _fail(f"event runtime {row_label} exact schema不正")
        outer_index = _int(raw["outer_index"], f"{row_label}.outer_index", 63)
        tag = _int(raw["tag"], f"{row_label}.tag", 7)
        if outer_index != index or tag == 0 or tag in tags:
            _fail(f"event runtime {row_label} ordinal/tag不正")
        record_address = _event_rom_address(
            raw["record_address"], f"{row_label}.record_address",
        )
        pointer_field = _event_rom_address(
            raw["pointer_field_address"], f"{row_label}.pointer_field",
        )
        try:
            record_raw = bytes.fromhex(raw["record_raw_hex"])
        except (TypeError, ValueError):
            _fail(f"event runtime {row_label}.record_raw_hex不正")
        if len(record_raw) != 5 or record_raw[0] != tag \
                or pointer_field != record_address + 1 \
                or raw["record_raw_hex"] != record_raw.hex() \
                or raw["record_raw_sha256"] != _sha256(record_raw):
            _fail(f"event runtime {row_label} outer ROM evidence不正")
        row: dict[str, Any] = {
            "outer_index": outer_index, "tag": tag,
            "record_address": record_address,
            "pointer_field_address": pointer_field,
            "record_raw_hex": record_raw.hex(),
            "record_raw_sha256": raw["record_raw_sha256"],
            "dispatch_kind": dispatch_kind,
        }
        pointer = int.from_bytes(record_raw[1:5], "little")
        if dispatch_kind == "DIRECT":
            root_pc = _event_rom_address(raw["root_pc"], f"{row_label}.root_pc")
            root_field = _event_rom_address(
                raw["root_field_address"], f"{row_label}.root_field_address",
            )
            owner_id = raw["owner_id"]
            expected_owner = f"MAP:{map_id}:{outer_index:03d}:DIRECT"
            if pointer != root_pc or root_field != pointer_field \
                    or owner_id != expected_owner:
                _fail(f"event runtime {row_label} direct identity不正")
            row.update({
                "root_pc": root_pc, "root_field_address": root_field,
                "owner_id": owner_id,
            })
        else:
            if tag not in {2, 4}:
                _fail(f"event runtime {row_label} conditional tag不正")
            table_pointer = _event_rom_address(
                raw["condition_table_pointer"],
                f"{row_label}.condition_table_pointer",
            )
            conditions = raw["conditions"]
            if pointer != table_pointer or not isinstance(conditions, list) \
                    or len(conditions) > 256:
                _fail(f"event runtime {row_label} conditional table不正")
            normalized_conditions: list[dict[str, Any]] = []
            for condition_index, condition in enumerate(conditions):
                condition_label = f"{row_label}.conditions[{condition_index}]"
                condition_keys = {
                    "condition_index", "tag", "record_address",
                    "root_field_address", "record_raw_hex",
                    "record_raw_sha256", "variable", "value", "root_pc",
                    "owner_id",
                }
                if not isinstance(condition, Mapping) \
                        or set(condition) != condition_keys:
                    _fail(f"event runtime {condition_label} exact schema不正")
                record = _event_rom_address(
                    condition["record_address"],
                    f"{condition_label}.record_address",
                )
                root_field = _event_rom_address(
                    condition["root_field_address"],
                    f"{condition_label}.root_field_address",
                )
                root_pc = _event_rom_address(
                    condition["root_pc"], f"{condition_label}.root_pc",
                )
                variable = _int(
                    condition["variable"], f"{condition_label}.variable",
                    0xFFFF,
                )
                required_value = _int(
                    condition["value"], f"{condition_label}.value", 0x3FFF,
                )
                try:
                    raw_bytes = bytes.fromhex(condition["record_raw_hex"])
                except (TypeError, ValueError):
                    _fail(f"event runtime {condition_label}.raw不正")
                expected_owner = (
                    f"MAP:{map_id}:{outer_index:03d}:"
                    f"{condition_index:03d}"
                )
                if condition["condition_index"] != condition_index \
                        or condition["tag"] != tag \
                        or root_field != record + 4 \
                        or not (0x4000 <= variable <= 0x40FF
                                or 0x5000 <= variable <= 0x51FF) \
                        or len(raw_bytes) != 8 \
                        or int.from_bytes(raw_bytes[0:2], "little") != variable \
                        or int.from_bytes(raw_bytes[2:4], "little") \
                            != required_value \
                        or int.from_bytes(raw_bytes[4:8], "little") != root_pc \
                        or condition["record_raw_hex"] != raw_bytes.hex() \
                        or condition["record_raw_sha256"] != _sha256(raw_bytes) \
                        or condition["owner_id"] != expected_owner:
                    _fail(f"event runtime {condition_label} ROM identity不正")
                normalized_conditions.append({
                    "condition_index": condition_index, "tag": tag,
                    "record_address": record, "root_field_address": root_field,
                    "record_raw_hex": raw_bytes.hex(),
                    "record_raw_sha256": condition["record_raw_sha256"],
                    "variable": variable, "value": required_value,
                    "root_pc": root_pc, "owner_id": expected_owner,
                })
            row.update({
                "condition_table_pointer": table_pointer,
                "conditions": normalized_conditions,
            })
        tags.append(tag)
        normalized_rows.append(row)
    normalized_by_tag = {str(row["tag"]): row for row in normalized_rows}
    if set(by_tag) != set(normalized_by_tag) \
            or any(by_tag[key] != normalized_by_tag[key]
                   for key in normalized_by_tag):
        _fail(f"event runtime {label} topology by_tag二重正本drift")
    if (table is None) is not (not normalized_rows):
        _fail(f"event runtime {label} topology table/row不一致")
    return {
        "schema_version": 1,
        "kind": "STAGE61_MAP_LIFECYCLE_TOPOLOGY",
        "map": {"group": group, "map": number}, "map_id": map_id,
        "header_address": header, "table_pointer": table,
        "outer_rows": normalized_rows, "by_tag": normalized_by_tag,
        "rom_sha256": digest,
    }


def _normalize_map_lifecycle_phase_controls(
    value: Any, label: str,
) -> list[dict[str, Any]]:
    if not isinstance(value, list) or len(value) != 2:
        _fail(f"event runtime {label} phase controls exact 2行不正")
    normalized: list[dict[str, Any]] = []
    for index, row in enumerate(value):
        row_label = f"{label}[{index}]"
        if not isinstance(row, Mapping) \
                or set(row) != {"phase_marker", "variables", "flags"}:
            _fail(f"event runtime {row_label} exact schema不正")
        marker = ("PRE_TRANSITION", "PRE_FIELD_INPUT")[index]
        if row["phase_marker"] != marker:
            _fail(f"event runtime {row_label} phase順不正")
        result: dict[str, Any] = {"phase_marker": marker}
        for key, value_key, maximum in (
            ("variables", "value", 0xFFFF), ("flags", "value", 1),
        ):
            rows = row[key]
            if not isinstance(rows, list) or len(rows) > 512:
                _fail(f"event runtime {row_label}.{key} list不正")
            values: list[dict[str, Any]] = []
            ids: list[int] = []
            for item_index, item in enumerate(rows):
                item_label = f"{row_label}.{key}[{item_index}]"
                if not isinstance(item, Mapping) \
                        or set(item) != {"id", value_key}:
                    _fail(f"event runtime {item_label} exact schema不正")
                identifier = _int(item["id"], f"{item_label}.id", 0xFFFF)
                raw_value = item[value_key]
                if key == "flags":
                    if not isinstance(raw_value, bool):
                        _fail(f"event runtime {item_label}.value bool不正")
                    normalized_value: Any = raw_value
                else:
                    normalized_value = _int(
                        raw_value, f"{item_label}.value", maximum,
                    )
                ids.append(identifier)
                values.append({"id": identifier, value_key: normalized_value})
            if ids != sorted(set(ids)):
                _fail(f"event runtime {row_label}.{key} ID順/重複不正")
            result[key] = values
        normalized.append(result)
    return normalized


def _normalize_map_lifecycle_write_rows(
    value: Any, label: str, *, identifiers: Sequence[int], boolean: bool,
) -> list[dict[str, Any]]:
    if not isinstance(value, list) or len(value) != len(identifiers):
        _fail(f"event runtime {label} write行数不正")
    result: list[dict[str, Any]] = []
    for index, (row, identifier) in enumerate(zip(value, identifiers, strict=True)):
        if not isinstance(row, Mapping) or set(row) != {"id", "value"} \
                or row["id"] != identifier \
                or (boolean and row["value"] is not False) \
                or (not boolean and (
                    row["value"] != 0
                    or isinstance(row["value"], bool)
                )):
            _fail(f"event runtime {label}[{index}] engine write不正")
        result.append({"id": identifier, "value": False if boolean else 0})
    return result


def _normalize_map_lifecycle_expected_ordered_projection(
    value: Any, sequence: Mapping[str, Any], label: str,
) -> dict[str, Any]:
    """Strictly bind the oracle projection to its normalized source rows."""

    root_keys = {
        "schema_version", "kind", "capacity", "capacity_scope",
        "producer_kind", "include_field_return", "engine_transform",
        "phase_boundaries", "ordered_attempts", "ordered_dispatches",
        "attempt_count", "dispatch_count", "projection_sha256",
    }
    if not isinstance(value, Mapping) or set(value) != root_keys \
            or value.get("schema_version") != 1 \
            or value.get("kind") \
                != "STAGE61_MAP_LIFECYCLE_EXPECTED_ORDERED_PROJECTION" \
            or value.get("capacity") != _MAP_LIFECYCLE_ATTEMPT_CAP \
            or value.get("capacity_scope") \
                != "PRE_FIELD_INPUT_ON_FRAME_TAG2_ATTEMPTS" \
            or value.get("producer_kind") != sequence["producer_kind"] \
            or value.get("include_field_return") \
                is not sequence["include_field_return"] \
            or value.get("engine_transform") \
                != sequence["engine_transforms"][0]:
        _fail(f"event runtime {label} ordered projection root不正")

    source_attempts = sequence["ordered_attempts"][1:]
    raw_attempts = value["ordered_attempts"]
    attempt_keys = {
        "observed_attempt_ordinal", "source_attempt_ordinal",
        "phase_marker", "source_phase_marker", "tag", "result",
        "outer_index", "outer_record_address",
        "selected_condition_index", "selected_condition_record_address",
        "root_field_address", "root_pc", "owner_id",
    }
    if not isinstance(raw_attempts, list) \
            or len(raw_attempts) != len(source_attempts) \
            or value.get("attempt_count") != len(raw_attempts):
        _fail(f"event runtime {label} ordered projection attempt count不正")
    tag2_count = sum(
        row["phase_marker"] == "PRE_FIELD_INPUT_ON_FRAME"
        and row["tag"] == 2 for row in source_attempts
    )
    if tag2_count == 0 or tag2_count > _MAP_LIFECYCLE_ATTEMPT_CAP:
        _fail(f"event runtime {label} ordered projection tag2 cap不正")
    normalized_attempts: list[dict[str, Any]] = []
    payload_keys = (
        "tag", "result", "outer_index", "outer_record_address",
        "selected_condition_index", "selected_condition_record_address",
        "root_field_address", "root_pc", "owner_id",
    )
    for observed_ordinal, (raw, source) in enumerate(zip(
        raw_attempts, source_attempts, strict=True,
    )):
        source_phase = source["phase_marker"]
        phase = "FIELD_RETURN" \
            if source_phase.startswith("FIELD_RETURN") else "INITIAL_LOAD"
        expected = {
            "observed_attempt_ordinal": observed_ordinal,
            "source_attempt_ordinal": observed_ordinal + 1,
            "phase_marker": phase,
            "source_phase_marker": source_phase,
            **{key: source[key] for key in payload_keys},
        }
        if not isinstance(raw, Mapping) or set(raw) != attempt_keys \
                or dict(raw) != expected:
            _fail(
                f"event runtime {label}.ordered_attempts"
                f"[{observed_ordinal}] source binding不正"
            )
        normalized_attempts.append(expected)

    expected_boundaries = [{
        "boundary_ordinal": 0,
        "phase_marker": "INITIAL_LOAD",
        "before_observed_attempt_ordinal": 0,
        "before_source_attempt_ordinal": 1,
    }]
    if sequence["include_field_return"]:
        return_ordinal = next((
            index for index, row in enumerate(source_attempts)
            if row["phase_marker"] == "FIELD_RETURN_RESUME"
        ), None)
        if return_ordinal is None:
            _fail(f"event runtime {label} ordered projection return欠落")
        expected_boundaries.append({
            "boundary_ordinal": 1,
            "phase_marker": "FIELD_RETURN",
            "before_observed_attempt_ordinal": return_ordinal,
            "before_source_attempt_ordinal": return_ordinal + 1,
        })
    if value["phase_boundaries"] != expected_boundaries:
        _fail(f"event runtime {label} ordered projection phase boundary不正")

    raw_dispatches = value["ordered_dispatches"]
    source_dispatches = sequence["ordered_dispatches"]
    dispatch_keys = {
        "dispatch_ordinal", "observed_attempt_ordinal",
        "source_attempt_ordinal", "phase_marker", "source_phase_marker",
        "tag", "owner_id", "outer_record_address",
        "selected_condition_index", "selected_condition_record_address",
        "root_field_address", "root_pc",
    }
    if not isinstance(raw_dispatches, list) \
            or len(raw_dispatches) != len(source_dispatches) \
            or value.get("dispatch_count") != len(raw_dispatches):
        _fail(f"event runtime {label} ordered projection dispatch count不正")
    normalized_dispatches: list[dict[str, Any]] = []
    for ordinal, (raw, source_dispatch) in enumerate(zip(
        raw_dispatches, source_dispatches, strict=True,
    )):
        source_ordinal = source_dispatch["attempt_ordinal"]
        source_attempt = sequence["ordered_attempts"][source_ordinal]
        source_phase = source_attempt["phase_marker"]
        expected = {
            "dispatch_ordinal": ordinal,
            "observed_attempt_ordinal": source_ordinal - 1,
            "source_attempt_ordinal": source_ordinal,
            "phase_marker": "FIELD_RETURN"
                if source_phase.startswith("FIELD_RETURN")
                else "INITIAL_LOAD",
            "source_phase_marker": source_phase,
            "tag": source_attempt["tag"],
            "owner_id": source_attempt["owner_id"],
            "outer_record_address": source_attempt["outer_record_address"],
            "selected_condition_index": source_attempt[
                "selected_condition_index"
            ],
            "selected_condition_record_address": source_attempt[
                "selected_condition_record_address"
            ],
            "root_field_address": source_attempt["root_field_address"],
            "root_pc": source_attempt["root_pc"],
        }
        if not isinstance(raw, Mapping) or set(raw) != dispatch_keys \
                or dict(raw) != expected:
            _fail(
                f"event runtime {label}.ordered_dispatches"
                f"[{ordinal}] source binding不正"
            )
        normalized_dispatches.append(expected)

    normalized = {
        "schema_version": 1,
        "kind": "STAGE61_MAP_LIFECYCLE_EXPECTED_ORDERED_PROJECTION",
        "capacity": _MAP_LIFECYCLE_ATTEMPT_CAP,
        "capacity_scope": "PRE_FIELD_INPUT_ON_FRAME_TAG2_ATTEMPTS",
        "producer_kind": sequence["producer_kind"],
        "include_field_return": sequence["include_field_return"],
        "engine_transform": deepcopy(sequence["engine_transforms"][0]),
        "phase_boundaries": deepcopy(expected_boundaries),
        "ordered_attempts": normalized_attempts,
        "ordered_dispatches": normalized_dispatches,
        "attempt_count": len(normalized_attempts),
        "dispatch_count": len(normalized_dispatches),
    }
    digest = value["projection_sha256"]
    if not isinstance(digest, str) \
            or digest != _sha256(_stable(normalized).encode("utf-8")):
        _fail(f"event runtime {label} ordered projection SHA不正")
    normalized["projection_sha256"] = digest
    return normalized


def _normalize_map_lifecycle_sequence(
    value: Any, label: str,
) -> dict[str, Any]:
    keys = {
        "schema_version", "kind", "producer_ordinal", "producer_kind",
        "control_variant_id", "include_field_return", "attempt_cap",
        "phase_controls", "engine_transforms", "ordered_attempts",
        "ordered_dispatches", "ordered_effect_instances",
        "dispatched_owner_ids", "attempt_count", "dispatch_count",
    }
    if not isinstance(value, Mapping) or set(value) != keys \
            or value.get("schema_version") != 1 \
            or value.get("kind") != "STAGE61_MAP_LIFECYCLE_SEQUENCE" \
            or isinstance(value.get("producer_ordinal"), bool) \
            or not isinstance(value.get("producer_ordinal"), int) \
            or value["producer_ordinal"] < 0 \
            or value.get("producer_kind") \
                not in {"STOCK_WARP", "ENGINE_TELEPORT", "CONNECTION"} \
            or not isinstance(value.get("control_variant_id"), str) \
            or not value["control_variant_id"] \
            or not isinstance(value.get("include_field_return"), bool) \
            or value.get("attempt_cap") != _MAP_LIFECYCLE_ATTEMPT_CAP:
        _fail(f"event runtime {label} sequence lifecycle exact schema不正")
    phase_controls = _normalize_map_lifecycle_phase_controls(
        value["phase_controls"], f"{label}.phase_controls",
    )
    transforms = value["engine_transforms"]
    transform_keys = {
        "transform_ordinal", "attempt_ordinal", "phase_marker", "kind",
        "operation", "variable_writes", "temporary_flag_writes",
        "system_flag_writes", "before_state_sha256", "after_state_sha256",
    }
    if not isinstance(transforms, list) or len(transforms) != 1 \
            or not isinstance(transforms[0], Mapping) \
            or set(transforms[0]) != transform_keys:
        _fail(f"event runtime {label}.engine_transforms exact-one不正")
    transform = transforms[0]
    if (transform["transform_ordinal"], transform["attempt_ordinal"],
        transform["phase_marker"], transform["kind"], transform["operation"]) \
            != (0, 0, "DESTINATION_TEMP_CLEAR",
                "STAGE61_MAP_ENGINE_TRANSFORM",
                "CLEAR_TEMP_FIELD_EVENT_DATA"):
        _fail(f"event runtime {label}.engine_transform identity不正")
    normalized_transform = {
        **{key: transform[key] for key in (
            "transform_ordinal", "attempt_ordinal", "phase_marker", "kind",
            "operation",
        )},
        "variable_writes": _normalize_map_lifecycle_write_rows(
            transform["variable_writes"], f"{label}.variable_writes",
            identifiers=range(0x4000, 0x4010), boolean=False,
        ),
        "temporary_flag_writes": _normalize_map_lifecycle_write_rows(
            transform["temporary_flag_writes"], f"{label}.temporary_flags",
            identifiers=range(0x20), boolean=True,
        ),
        "system_flag_writes": _normalize_map_lifecycle_write_rows(
            transform["system_flag_writes"], f"{label}.system_flags",
            identifiers=_MAP_LIFECYCLE_SYSTEM_FLAG_IDS, boolean=True,
        ),
    }
    for digest_key in ("before_state_sha256", "after_state_sha256"):
        digest = transform[digest_key]
        if not isinstance(digest, str) \
                or re.fullmatch(r"[0-9a-f]{64}", digest) is None:
            _fail(f"event runtime {label}.{digest_key}不正")
        normalized_transform[digest_key] = digest

    attempts = value["ordered_attempts"]
    attempt_keys = {
        "attempt_ordinal", "phase_marker", "tag", "result", "outer_index",
        "outer_record_address", "selected_condition_index",
        "selected_condition_record_address", "root_field_address", "root_pc",
        "owner_id",
    }
    if not isinstance(attempts, list) or not attempts \
            or len(attempts) > _MAP_LIFECYCLE_ATTEMPT_CAP + 7:
        _fail(f"event runtime {label}.ordered_attempts count不正")
    normalized_attempts: list[dict[str, Any]] = []
    for index, raw in enumerate(attempts):
        row_label = f"{label}.ordered_attempts[{index}]"
        if not isinstance(raw, Mapping) or set(raw) != attempt_keys \
                or raw["attempt_ordinal"] != index \
                or raw["phase_marker"] not in _MAP_LIFECYCLE_PHASES \
                or raw["result"] not in _MAP_LIFECYCLE_ATTEMPT_RESULTS:
            _fail(f"event runtime {row_label} exact schema/ordinal不正")
        engine = index == 0
        tag = raw["tag"]
        if engine:
            if (raw["phase_marker"], tag, raw["result"]) != (
                "DESTINATION_TEMP_CLEAR", None, "ENGINE_TRANSFORM",
            ):
                _fail(f"event runtime {row_label} TEMP attempt不正")
        elif isinstance(tag, bool) or not isinstance(tag, int) \
                or not 1 <= tag <= 7 or raw["result"] == "ENGINE_TRANSFORM":
            _fail(f"event runtime {row_label} tag/result不正")
        normalized_row = {
            "attempt_ordinal": index, "phase_marker": raw["phase_marker"],
            "tag": tag, "result": raw["result"],
        }
        for key in ("outer_index", "selected_condition_index"):
            item = raw[key]
            if item is not None:
                item = _int(item, f"{row_label}.{key}", 255)
            normalized_row[key] = item
        for key in (
            "outer_record_address", "selected_condition_record_address",
            "root_field_address", "root_pc",
        ):
            normalized_row[key] = _map_lifecycle_hex_address(
                raw[key], f"{row_label}.{key}",
            )
        owner_id = raw["owner_id"]
        if owner_id is not None and (
            not isinstance(owner_id, str) or _OWNER_ID.fullmatch(owner_id) is None
        ):
            _fail(f"event runtime {row_label}.owner_id不正")
        normalized_row["owner_id"] = owner_id
        present = raw["result"] == "DISPATCH"
        if present is not (owner_id is not None and raw["root_pc"] is not None
                           and raw["root_field_address"] is not None) \
                or (raw["result"] == "TAG_ABSENT" and any(
                    raw[key] is not None for key in attempt_keys - {
                        "attempt_ordinal", "phase_marker", "tag", "result",
                    }
                )) \
                or (raw["result"] == "NO_CONDITION_MATCH" and (
                    raw["outer_index"] is None
                    or raw["outer_record_address"] is None
                    or any(raw[key] is not None for key in (
                        "selected_condition_index",
                        "selected_condition_record_address",
                        "root_field_address", "root_pc", "owner_id",
                    ))
                )):
            _fail(f"event runtime {row_label} result/payload不一致")
        normalized_attempts.append(normalized_row)

    dispatches = value["ordered_dispatches"]
    dispatch_keys = {
        "dispatch_ordinal", "attempt_ordinal", "phase_marker", "tag",
        "owner_id", "root_pc", "root_field_address", "trace_start_index",
        "trace_end_index", "effect_start_index", "effect_end_index",
        "printer_start_index", "printer_end_index", "decision_start_index",
        "decision_end_index", "state_before_sha256", "state_after_sha256",
    }
    if not isinstance(dispatches, list) or len(dispatches) > len(attempts):
        _fail(f"event runtime {label}.ordered_dispatches count不正")
    normalized_dispatches: list[dict[str, Any]] = []
    previous_attempt = -1
    for index, raw in enumerate(dispatches):
        row_label = f"{label}.ordered_dispatches[{index}]"
        if not isinstance(raw, Mapping) or set(raw) != dispatch_keys \
                or raw["dispatch_ordinal"] != index:
            _fail(f"event runtime {row_label} exact schema/ordinal不正")
        attempt_ordinal = _int(
            raw["attempt_ordinal"], f"{row_label}.attempt_ordinal",
            len(attempts) - 1,
        )
        attempt = normalized_attempts[attempt_ordinal]
        if attempt_ordinal <= previous_attempt \
                or attempt["result"] != "DISPATCH" \
                or any(raw[key] != attempt[key] for key in (
                    "phase_marker", "tag", "owner_id", "root_pc",
                    "root_field_address",
                )):
            _fail(f"event runtime {row_label} attempt binding不正")
        normalized_row = {
            key: raw[key] for key in (
                "dispatch_ordinal", "attempt_ordinal", "phase_marker", "tag",
                "owner_id", "root_pc", "root_field_address",
            )
        }
        for prefix in ("trace", "effect", "printer", "decision"):
            start = _int(raw[f"{prefix}_start_index"], f"{row_label}.{prefix}_start", 0xFFFFFFFF)
            end = _int(raw[f"{prefix}_end_index"], f"{row_label}.{prefix}_end", 0xFFFFFFFF)
            if end < start:
                _fail(f"event runtime {row_label}.{prefix} range不正")
            normalized_row[f"{prefix}_start_index"] = start
            normalized_row[f"{prefix}_end_index"] = end
        for digest_key in ("state_before_sha256", "state_after_sha256"):
            digest = raw[digest_key]
            if not isinstance(digest, str) \
                    or re.fullmatch(r"[0-9a-f]{64}", digest) is None:
                _fail(f"event runtime {row_label}.{digest_key}不正")
            normalized_row[digest_key] = digest
        normalized_dispatches.append(normalized_row)
        previous_attempt = attempt_ordinal

    effects = value["ordered_effect_instances"]
    effect_keys = {
        "effect_instance_ordinal", "dispatch_ordinal", "owner_id",
        "root_pc", "effect",
    }
    if not isinstance(effects, list):
        _fail(f"event runtime {label}.ordered_effect_instances list不正")
    normalized_effects: list[dict[str, Any]] = []
    previous_dispatch = -1
    for index, raw in enumerate(effects):
        row_label = f"{label}.ordered_effect_instances[{index}]"
        if not isinstance(raw, Mapping) or set(raw) != effect_keys \
                or raw["effect_instance_ordinal"] != index:
            _fail(f"event runtime {row_label} exact schema/ordinal不正")
        dispatch_ordinal = _int(
            raw["dispatch_ordinal"], f"{row_label}.dispatch_ordinal",
            max(0, len(dispatches) - 1),
        )
        if not dispatches or dispatch_ordinal < previous_dispatch:
            _fail(f"event runtime {row_label} dispatch order不正")
        dispatch = normalized_dispatches[dispatch_ordinal]
        if raw["owner_id"] != dispatch["owner_id"] \
                or raw["root_pc"] != dispatch["root_pc"] \
                or not isinstance(raw["effect"], Mapping) \
                or not raw["effect"]:
            _fail(f"event runtime {row_label} dispatch/effect binding不正")
        normalized_effects.append(deepcopy(dict(raw)))
        previous_dispatch = dispatch_ordinal

    dispatched = value["dispatched_owner_ids"]
    expected_dispatched = sorted({row["owner_id"] for row in normalized_dispatches})
    if not isinstance(dispatched, list) \
            or dispatched != expected_dispatched \
            or value["attempt_count"] != len(normalized_attempts) \
            or value["dispatch_count"] != len(normalized_dispatches):
        _fail(f"event runtime {label}.dispatched_owner_ids不正")
    return {
        "schema_version": 1,
        "kind": "STAGE61_MAP_LIFECYCLE_SEQUENCE",
        "producer_ordinal": value["producer_ordinal"],
        "producer_kind": value["producer_kind"],
        "control_variant_id": value["control_variant_id"],
        "include_field_return": value["include_field_return"],
        "attempt_cap": _MAP_LIFECYCLE_ATTEMPT_CAP,
        "phase_controls": phase_controls,
        "engine_transforms": [normalized_transform],
        "ordered_attempts": normalized_attempts,
        "ordered_dispatches": normalized_dispatches,
        "ordered_effect_instances": normalized_effects,
        "dispatched_owner_ids": list(dispatched),
        "attempt_count": len(normalized_attempts),
        "dispatch_count": len(normalized_dispatches),
    }


def _normalize_map_lifecycle_common(
    value: Any, label: str,
) -> dict[str, Any]:
    keys = {
        "schema_version", "kind", "topology", "producer_contracts",
        "include_field_return", "attempt_cap", "engine_transform_contract",
        "phase_control_contract",
    }
    if not isinstance(value, Mapping) or set(value) != keys \
            or value.get("schema_version") != 1 \
            or value.get("kind") \
                != "STAGE61_MAP_LIFECYCLE_COMPOSITE_CONTRACT" \
            or not isinstance(value.get("include_field_return"), bool) \
            or value.get("attempt_cap") != _MAP_LIFECYCLE_ATTEMPT_CAP:
        _fail(f"event runtime {label} common lifecycle exact schema不正")
    engine_contract = value["engine_transform_contract"]
    expected_engine = {
        "kind": "STAGE61_MAP_ENGINE_TRANSFORM",
        "operation": "CLEAR_TEMP_FIELD_EVENT_DATA",
        "phase_marker": "DESTINATION_TEMP_CLEAR",
        "temporary_var_range": [0x4000, 0x400F],
        "temporary_flag_range": [0, 0x1F],
        "system_flag_ids": _MAP_LIFECYCLE_SYSTEM_FLAG_IDS,
    }
    phase_contract = value["phase_control_contract"]
    expected_phase = {
        "ordered_phase_markers": ["PRE_TRANSITION", "PRE_FIELD_INPUT"],
        "pre_transition_relation": "APPLY_BEFORE_PHYSICAL_MAP_PRODUCER",
        "pre_field_input_relation": (
            "APPLY_AFTER_INITIAL_LOAD_QUIESCENCE_BEFORE_FIRST_FIELD_INPUT"
        ),
    }
    if engine_contract != expected_engine or phase_contract != expected_phase:
        _fail(f"event runtime {label} engine/phase contract不正")
    producer_contracts = value["producer_contracts"]
    if not isinstance(producer_contracts, list) or not producer_contracts:
        _fail(f"event runtime {label}.producer_contracts不正")
    return {
        "schema_version": 1,
        "kind": "STAGE61_MAP_LIFECYCLE_COMPOSITE_CONTRACT",
        "topology": _normalize_map_lifecycle_topology(
            value["topology"], f"{label}.topology",
        ),
        # The trigger boundary independently validates every producer row;
        # equality with this duplicate is checked by the composite case gate.
        "producer_contracts": deepcopy(producer_contracts),
        "include_field_return": value["include_field_return"],
        "attempt_cap": _MAP_LIFECYCLE_ATTEMPT_CAP,
        "engine_transform_contract": expected_engine,
        "phase_control_contract": expected_phase,
    }


def _normalize_event_input_sequence(
    value: Any, case_id: str, trigger: Mapping[str, Any], label: str,
    *, map_composite: bool = False,
    expected_trigger_prefix: Sequence[str] | None = None,
) -> dict[str, Any]:
    keys = {
        "sequence_id", "tokens", "expected_static_branch_token", "basis",
        "visible_text_expected", "silent_text_basis", "text_oracle",
        "required_postconditions", "battle_start_required_postconditions",
        "post_battle_continuation",
    }
    if map_composite:
        keys |= {
            "control_requirements", "map_lifecycle", "effect_signature_ids",
        }
    if not isinstance(value, Mapping) or set(value) != keys:
        _fail(f"event runtime {label}.input_sequence exact schema不一致")
    sequence_id = value["sequence_id"]
    if not isinstance(sequence_id, str) \
            or _CASE_ID.fullmatch(sequence_id) is None \
            or not sequence_id.startswith(f"{case_id}-"):
        _fail(f"event runtime {label}.sequence_id case prefix不正")
    branch = value["expected_static_branch_token"]
    if not isinstance(branch, str) or _OWNER_ID.fullmatch(branch) is None:
        _fail(f"event runtime {label}.branch token不正")
    tokens = value["tokens"]
    if not isinstance(tokens, list) or not tokens or len(tokens) > 128 \
            or any(not isinstance(token, str) for token in tokens):
        _fail(f"event runtime {label}.tokens不正")
    prefix = tuple(expected_trigger_prefix) \
        if expected_trigger_prefix is not None else _event_trigger_tokens(trigger)
    if tuple(tokens[:len(prefix)]) != prefix:
        _fail(
            f"event runtime {label}.tokens consumer prefix不一致: "
            f"expected={prefix!r} actual={tokens!r}"
        )
    allowed_tail = _SIMPLE_INPUT_TOKENS | {
        "WALK_TO_ADJACENT", "FACE_REQUIRED_DIRECTION",
        "WALK_FROM_ADJACENT_ONTO_COORD", "WALK_ONTO_WARP",
        "WAIT_MAP_LOAD", "WALK_ONTO_COORD", "USE_ITEMFINDER",
        "WALK_ACROSS_CONNECTION", "ENGINE_PLAYER_TELEPORT_MAP_LOAD",
        "WAIT_FIRST_ROOT_HIT",
    }
    if any(
        token not in allowed_tail
        and re.fullmatch(r"WAIT_[1-9][0-9]{0,3}", token) is None
        for token in tokens
    ):
        _fail(f"event runtime {label}.tokens unknown token")
    basis = value["basis"]
    if not isinstance(basis, (str, Mapping)) or not basis:
        _fail(f"event runtime {label}.basis不正")
    visible = value["visible_text_expected"]
    silent = value["silent_text_basis"]
    if not isinstance(visible, bool):
        _fail(f"event runtime {label}.visible_text_expected不正")
    normalized_silent = None
    if visible:
        if silent is not None:
            _fail(f"event runtime {label} visible pathにsilent basisあり")
    else:
        if not isinstance(silent, Mapping) or set(silent) != {
            "kind", "source_instruction_addresses", "reason",
        } or silent.get("kind") != "STATIC_NO_TEXT_PATH" \
                or not isinstance(silent.get("source_instruction_addresses"), list) \
                or not silent["source_instruction_addresses"] \
                or not isinstance(silent.get("reason"), str) \
                or not silent["reason"].strip():
            _fail(f"event runtime {label}.silent_text_basis不正")
        normalized_silent = {
            "kind": "STATIC_NO_TEXT_PATH",
            "source_instruction_addresses": [
                _event_rom_address(address, f"{label}.silent_address")
                for address in silent["source_instruction_addresses"]
            ],
            "reason": silent["reason"],
        }
        if len(set(normalized_silent["source_instruction_addresses"])) \
                != len(normalized_silent["source_instruction_addresses"]):
            _fail(f"event runtime {label}.silent address重複")
    result = {
        "sequence_id": sequence_id,
        "tokens": list(tokens),
        "expected_static_branch_token": branch,
        "basis": deepcopy(basis),
        "visible_text_expected": visible,
        "silent_text_basis": normalized_silent,
        "text_oracle": _normalize_text_oracle(
            value["text_oracle"], label, visible_text_expected=visible,
        ),
        "required_postconditions": _normalize_required_postconditions(
            value["required_postconditions"], label,
        ),
        "battle_start_required_postconditions": (
            None
            if value["battle_start_required_postconditions"] is None
            else _normalize_required_postconditions(
                value["battle_start_required_postconditions"],
                f"{label}.battle_start",
            )
        ),
        "post_battle_continuation": _normalize_post_battle_continuation(
            value["post_battle_continuation"],
            f"{label}.post_battle_continuation",
        ),
    }
    if map_composite:
        effects = value["effect_signature_ids"]
        if not isinstance(effects, list) or not effects \
                or len(effects) != len(set(effects)) \
                or any(not isinstance(effect, str)
                       or _OWNER_ID.fullmatch(effect) is None
                       for effect in effects):
            _fail(f"event runtime {label}.effect_signature_ids不正")
        result["control_requirements"] = deepcopy(
            value["control_requirements"]
        )
        result["effect_signature_ids"] = list(effects)
        result["map_lifecycle"] = _normalize_map_lifecycle_sequence(
            value["map_lifecycle"], f"{label}.map_lifecycle",
        )
        raw_basis = result["basis"]
        if not isinstance(raw_basis, Mapping) \
                or "map_lifecycle_expected_ordered_projection" \
                    not in raw_basis:
            _fail(f"event runtime {label}.basis MAP ordered projection欠落")
        normalized_basis = deepcopy(dict(raw_basis))
        normalized_basis["map_lifecycle_expected_ordered_projection"] = (
            _normalize_map_lifecycle_expected_ordered_projection(
                raw_basis["map_lifecycle_expected_ordered_projection"],
                result["map_lifecycle"],
                f"{label}.basis.map_lifecycle_expected_ordered_projection",
            )
        )
        result["basis"] = normalized_basis
    return result


def _state_from_event_external_controls(value: Any, label: str) \
        -> dict[str, list[dict[str, Any]]]:
    if not isinstance(value, list):
        _fail(f"event runtime {label}.external controls不正")
    state: dict[str, list[dict[str, Any]]] = {
        kind: [] for kind in _STATE_KINDS
    }
    for index, row in enumerate(value):
        if not isinstance(row, Mapping):
            _fail(f"event runtime {label}.external[{index}]不正")
        kind = row.get("kind")
        mapping = _CONTROL_SIMPLE_STATE_KIND.get(str(kind))
        if mapping is None:
            continue
        state_kind, value_key = mapping
        state[state_kind].append({
            "id": row.get("id"),
            value_key: row.get("required_value_in_matrix_case"),
        })
    return _normalize_state_rows(state, f"{label}.derived_state")


def _normalize_event_compact_external_controls(
    value: Any, registry: Mapping[str, Mapping[str, Any]], label: str,
    *, allowed_owner_ids: set[str], require_owner_subset: bool = False,
    map_phase_marker: str | None = None,
) -> list[dict[str, Any]]:
    """Normalize the oracle's path-exact compact event control rows.

    Object matrix rows carry the complete domain metadata used by set-cover.
    Event rows instead carry only the controls consumed by one concrete path;
    requiring (or fabricating) the wider domain here would change that source
    contract.  Preserve its compact provenance while projecting only the
    fields needed by the C ABI.
    """

    if not isinstance(value, list) or len(value) > 256:
        _fail(f"event runtime {label}.external compact list不正")
    result: list[dict[str, Any]] = []
    identities: list[tuple[str, int]] = []
    for index, raw in enumerate(value):
        row_label = f"{label}.external[{index}]"
        keys = {
            "kind", "id", "value", "owner_keys", "relation_evidence",
            "fixture_keys",
        }
        if not isinstance(raw, Mapping) or set(raw) != keys:
            _fail(f"event runtime {row_label} compact exact schema不正")
        kind = raw["kind"]
        if kind not in _CONTROL_EXTERNAL_KINDS:
            _fail(f"event runtime {row_label}.kind未知")
        identifier = _int(
            raw["id"], f"{row_label}.id",
            0xFFFFFFFF if kind == "SIGNED_RAM_SCRIPT" else 0xFFFF,
        )
        owner_keys = raw["owner_keys"]
        if not isinstance(owner_keys, list) \
                or owner_keys != sorted(set(owner_keys)) \
                or any(not isinstance(owner, str) or not owner
                       for owner in owner_keys) \
                or owner_keys and (
                    not set(owner_keys) & allowed_owner_ids
                    or require_owner_subset
                    and not set(owner_keys) <= allowed_owner_ids
                ):
            _fail(f"event runtime {row_label}.owner_keys scope不正")
        fixture_keys = raw["fixture_keys"]
        if not isinstance(fixture_keys, list) \
                or fixture_keys != sorted(set(fixture_keys)) \
                or any(not isinstance(digest, str)
                       or re.fullmatch(r"[0-9a-f]{64}", digest) is None
                       or digest not in registry for digest in fixture_keys):
            _fail(f"event runtime {row_label}.fixture_keys不正")
        required_value = _normalize_control_required_value(
            kind, raw["value"], registry, row_label,
        )
        referenced = sorted({
            child for key, child in required_value.items()
            if key.endswith("_ref") and isinstance(child, str)
        }) if isinstance(required_value, Mapping) else []
        if referenced != fixture_keys:
            _fail(f"event runtime {row_label} fixture ref二重正本drift")
        if map_phase_marker is None:
            relations = _normalize_control_relations(
                raw["relation_evidence"], kind, row_label,
            )
            if kind == "COINS":
                _validate_coins_control_relations(
                    identifier, required_value, relations, row_label,
                )
            if kind == "PARTY_MINIGAME":
                _validate_party_minigame_control(
                    identifier, required_value, relations, row_label,
                )
            if kind == "RFU_SESSION":
                _validate_rfu_session_control(
                    identifier, required_value, relations, None, row_label,
                )
            if kind == "CENTER_LINK_SESSION":
                _validate_center_link_session_control(
                    identifier, required_value, relations, None, row_label,
                )
            if kind == "DAYCARE_TRANSACTION_STATE":
                _validate_daycare_transaction_control(
                    identifier, required_value, relations, None, row_label,
                )
            if kind == "PARTY_MOVE_TRANSACTION_STATE":
                _validate_party_move_transaction_control(
                    identifier, required_value, relations, None, row_label,
                )
            if kind == "GIFT_STORAGE_TRANSACTION_STATE":
                _validate_gift_storage_transaction_control(
                    identifier, required_value, relations, None, row_label,
                )
            if kind == "FOSSIL_REVIVAL_STATE":
                _validate_fossil_revival_control(
                    identifier, required_value, relations, None, row_label,
                )
            if kind == "RUIN_SEAL_PREFIX":
                _validate_ruin_seal_prefix_control(
                    identifier, required_value, relations, None, row_label,
                )
            if kind == "FACILITY_SESSION":
                _validate_facility_session_control(
                    identifier, required_value, relations, None, row_label,
                )
        else:
            expected_relation = [{
                "operator": "MAP_ENGINE_PHASE_CONTROL",
                "instruction_address": None,
                "source": {
                    "kind": "MAP_LIFECYCLE_PHASE_BOUNDARY",
                    "phase_marker": map_phase_marker,
                },
                "abi_key": None,
            }]
            if raw["relation_evidence"] != expected_relation:
                _fail(
                    f"event runtime {row_label} MAP phase relation不一致"
                )
            relations = deepcopy(expected_relation)
        identities.append((str(kind), identifier))
        result.append({
            "kind": str(kind), "id": identifier,
            "required_value_in_matrix_case": required_value,
            "relations": relations,
            "owner_keys": list(owner_keys),
            "fixture_keys": list(fixture_keys),
        })
    if identities != sorted(set(identities)):
        _fail(f"event runtime {label}.external identity順/重複不正")
    return result


def _normalize_event_compact_controls(
    value: Any, sequences: Sequence[Mapping[str, Any]],
    registry: Mapping[str, Mapping[str, Any]], label: str,
    *, allowed_owner_ids: set[str], require_owner_subset: bool = False,
) -> tuple[dict[str, Any], dict[str, list[dict[str, Any]]]]:
    if not isinstance(value, Mapping) or set(value) != {"external", "internal"}:
        _fail(f"event runtime {label}.control_requirements exact schema不正")
    external = _normalize_event_compact_external_controls(
        value["external"], registry, label,
        allowed_owner_ids=allowed_owner_ids,
        require_owner_subset=require_owner_subset,
    )
    _validate_facility_continuation_terminals(sequences, external, label)
    state_source = [{
        "kind": row["kind"], "id": row["id"],
        "required_value_in_matrix_case": row[
            "required_value_in_matrix_case"
        ],
    } for row in external]
    state = _state_from_event_external_controls(state_source, label)
    internal = _normalize_internal_controls(
        value["internal"], sequences, label,
    )
    return {"external": external, "internal": internal}, state


def _normalize_map_phase_scoped_controls(
    value: Any, sequence: Mapping[str, Any],
    registry: Mapping[str, Mapping[str, Any]], label: str,
    *, covered_owner_ids: set[str],
) -> tuple[dict[str, Any], dict[str, list[dict[str, Any]]]]:
    """Separate physical phase writes from the ordinary catalog seed.

    PRE_TRANSITION/PRE_FIELD_INPUT rows are applied by the trigger executor at
    their real engine boundaries.  Keeping them in the catalog base state
    would incorrectly reapply them before/after the stock producer.
    """

    markers = ("PRE_TRANSITION", "PRE_FIELD_INPUT")
    if not isinstance(value, Mapping) or set(value) != set(markers):
        _fail(f"event runtime {label} MAP phase control outer schema不正")
    lifecycle_rows = {
        row["phase_marker"]: row
        for row in sequence["map_lifecycle"]["phase_controls"]
    }
    base_external: list[Mapping[str, Any]] = []
    base_internal: list[Mapping[str, Any]] = []
    for marker in markers:
        phase = value[marker]
        phase_label = f"{label}.{marker}"
        if not isinstance(phase, Mapping) \
                or set(phase) != {"external", "internal"} \
                or not isinstance(phase["external"], list) \
                or not isinstance(phase["internal"], list):
            _fail(f"event runtime {phase_label} exact schema不正")
        if marker == "PRE_FIELD_INPUT" and phase["internal"] != []:
            _fail(f"event runtime {phase_label} internalは空必須")
        expected_values: dict[tuple[str, int], Any] = {}
        lifecycle = lifecycle_rows.get(marker)
        if lifecycle is None:
            _fail(f"event runtime {phase_label} lifecycle phase欠落")
        for state_kind, public_kind in (
            ("variables", "VAR"), ("flags", "FLAG"),
        ):
            for row in lifecycle[state_kind]:
                kind = public_kind
                if state_kind == "flags" and 0x4000 <= row["id"] <= 0x407F:
                    kind = "ENGINE_SPECIAL_FLAG"
                expected_values[(kind, row["id"])] = row["value"]
        actual_values: dict[tuple[str, int], Any] = {}
        phase_only: list[Mapping[str, Any]] = []
        remainder: list[Mapping[str, Any]] = []
        for raw in phase["external"]:
            if not isinstance(raw, Mapping):
                _fail(f"event runtime {phase_label}.external row不正")
            identity = (str(raw.get("kind")), raw.get("id"))
            if identity in expected_values:
                if raw.get("value") != expected_values[identity] \
                        or identity in actual_values:
                    _fail(f"event runtime {phase_label} phase value drift")
                actual_values[identity] = raw.get("value")
                phase_only.append(raw)
            else:
                remainder.append(raw)
        if actual_values != expected_values:
            _fail(f"event runtime {phase_label} phase lifecycle/control不一致")
        # Validate the discarded phase-only rows as strictly as retained rows.
        _normalize_event_compact_external_controls(
            phase_only, registry, f"{phase_label}.phase_only",
            allowed_owner_ids=covered_owner_ids,
            require_owner_subset=True,
            map_phase_marker=marker,
        )
        if marker == "PRE_FIELD_INPUT" and remainder:
            _fail(f"event runtime {phase_label} nonphase control混入")
        if marker == "PRE_TRANSITION":
            base_external.extend(remainder)
            base_internal.extend(phase["internal"])
    return _normalize_event_compact_controls(
        {"external": base_external, "internal": base_internal},
        [sequence], registry, label,
        allowed_owner_ids=covered_owner_ids,
        require_owner_subset=True,
    )


def _event_contract_sha256(value: Any) -> str:
    """Match the producer/oracle compact canonical JSON digest exactly."""
    return _sha256((
        json.dumps(
            value, ensure_ascii=False, sort_keys=True, separators=(",", ":"),
        ) + "\n"
    ).encode("utf-8"))


def _normalize_structural_nontrigger_evidence(
    raw: Mapping[str, Any], label: str, *, null_scope_asserted: bool,
) -> dict[str, Any]:
    owner_id = raw["owner_id"]
    if owner_id != "COMMON:STANDARD:007":
        if raw.get("representative_runtime_root") is not None \
                or "consumer_subkind" in raw \
                or raw.get("trigger_consumer") != {
                    "symbol": "NULL_EVENT_RECORD", "entry": None,
                    "source": None,
                } \
                or raw.get("effect_evidence") != {
                    "relation": "NO_SCRIPT_DISPATCH_NO_MUTATION",
                }:
            _fail(f"event runtime {label} structural NULL consumer不正")
        condition = raw.get("entry_condition")
        if not isinstance(condition, Mapping) or set(condition) != {
            "relation", "record_address",
        } or condition.get("relation") \
                != "ENGINE_TREATS_NULL_AS_NO_EVENT_SCRIPT" \
                or not null_scope_asserted:
            _fail(f"event runtime {label} structural NULL zero raw根拠不正")
        record = _event_rom_address(
            condition["record_address"], f"{label}.record_address",
        )
        return {
            "kind": "EXACT_NULL_SCRIPT_POINTER",
            "owner_id": owner_id,
            "owner_kind": raw["owner_kind"],
            "record_address": f"0x{record:08X}",
            "raw_root": 0,
            "representative_runtime_root": None,
            "engine_no_dispatch_contract": True,
            "zero_raw_proven_by_final_inventory_scope": True,
        }

    if raw.get("owner_kind") != "COMMON" \
            or raw.get("consumer_subkind") \
                != "UNREFERENCED_STANDARD_SCRIPT_TABLE_ENTRY" \
            or _event_rom_address(
                raw.get("representative_runtime_root"),
                f"{label}.representative_runtime_root",
            ) != 0x08194038 \
            or raw.get("effect_evidence") != {
                "relation": "NO_LIVE_DISPATCH_NO_PRODUCT_MUTATION",
                "coverage_only_caller_forbidden": True,
            }:
        _fail(f"event runtime {label} dormant COMMON7 identity不正")
    consumer = raw.get("trigger_consumer")
    condition = raw.get("entry_condition")
    if not isinstance(consumer, Mapping) \
            or consumer.get("symbol") != "Std_ObtainDecoration" \
            or consumer.get("entry") is not None \
            or not isinstance(consumer.get("source"), Mapping) \
            or not isinstance(condition, Mapping) \
            or set(condition) != {"relation", "standard_index", "structural_evidence"} \
            or condition.get("relation") \
                != "ALL_FINAL_NONCOMMON_CFG_CALLER_COUNT_ZERO" \
            or condition.get("standard_index") != 7:
        _fail(f"event runtime {label} dormant COMMON7 consumer不正")
    evidence = condition["structural_evidence"]
    keys = {
        "kind", "owner_id", "standard_index", "record_address",
        "table_raw_hex", "table_raw_sha256", "representative_runtime_root",
        "clean_final_cfg_identical", "cfg_node_count", "cfg_nodes",
        "cfg_sha256", "live_noncommon_root_count", "live_caller_count",
        "live_caller_instruction_addresses", "source_provenance",
        "assertions", "evidence_sha256",
    }
    table_raw = bytes.fromhex("38401908")
    if not isinstance(evidence, Mapping) or set(evidence) != keys \
            or evidence.get("kind") \
                != "UNREFERENCED_STANDARD_SCRIPT_TABLE_ENTRY" \
            or evidence.get("owner_id") != owner_id \
            or evidence.get("standard_index") != 7 \
            or _event_rom_address(
                evidence.get("record_address"), f"{label}.record_address",
            ) != 0x08163774 \
            or evidence.get("table_raw_hex") != table_raw.hex() \
            or evidence.get("table_raw_sha256") != _sha256(table_raw) \
            or _event_rom_address(
                evidence.get("representative_runtime_root"), f"{label}.root",
            ) != 0x08194038 \
            or evidence.get("clean_final_cfg_identical") is not True \
            or evidence.get("cfg_node_count") != 4 \
            or evidence.get("live_caller_count") != 0 \
            or evidence.get("live_caller_instruction_addresses") != [] \
            or not isinstance(evidence.get("live_noncommon_root_count"), int) \
            or evidence["live_noncommon_root_count"] <= 0 \
            or not isinstance(evidence.get("source_provenance"), Mapping) \
            or not evidence["source_provenance"]:
        _fail(f"event runtime {label} dormant COMMON7 evidence不正")
    cfg_nodes = evidence["cfg_nodes"]
    if not isinstance(cfg_nodes, list) or len(cfg_nodes) != 4 \
            or evidence["cfg_sha256"] != _event_contract_sha256(cfg_nodes):
        _fail(f"event runtime {label} dormant COMMON7 CFG digest不正")
    for index, node in enumerate(cfg_nodes):
        if not isinstance(node, Mapping) or set(node) != {
            "address", "end_reason", "raw_hex", "raw_sha256", "edges",
        } or not isinstance(node["edges"], list):
            _fail(f"event runtime {label} dormant COMMON7 CFG node不正")
        try:
            raw_bytes = bytes.fromhex(node["raw_hex"])
        except (TypeError, ValueError):
            _fail(f"event runtime {label} dormant COMMON7 CFG raw不正")
        if node["raw_sha256"] != _sha256(raw_bytes) \
                or (index == 0 and (
                    node["address"] != "0x08194038"
                    or not node["raw_hex"].startswith("4b0080")
                )):
            _fail(f"event runtime {label} dormant COMMON7 CFG binding不正")
    assertions = evidence["assertions"]
    if not isinstance(assertions, Mapping) or set(assertions) != {
        "table_entry_exact", "clean_final_full_cfg_identical",
        "all_noncommon_live_cfg_caller_count_zero",
        "coverage_only_consumer_not_invented",
    } or any(item is not True for item in assertions.values()):
        _fail(f"event runtime {label} dormant COMMON7 assertions不正")
    unhashed = deepcopy(dict(evidence))
    digest = unhashed.pop("evidence_sha256")
    if digest != _event_contract_sha256(unhashed):
        _fail(f"event runtime {label} dormant COMMON7 evidence digest不正")
    return deepcopy(dict(evidence))


def _validate_map_lifecycle_attempt_phase_order(
    lifecycle: Mapping[str, Any], label: str,
) -> None:
    """producer別のengine順序とtag2 quiescenceをsource側で固定する。"""

    attempts = lifecycle["ordered_attempts"]
    producer_kind = lifecycle["producer_kind"]
    include_field_return = lifecycle["include_field_return"]
    expected_prefix = [
        ("DESTINATION_TEMP_CLEAR", None),
        ("INITIAL_TRANSITION", 3),
        ("INITIAL_LOAD", 1),
        ("INITIAL_RESUME", 5),
    ]
    if producer_kind != "CONNECTION":
        expected_prefix.append(("INITIAL_WARP_IN", 4))
    if len(attempts) <= len(expected_prefix) \
            or [(row["phase_marker"], row["tag"])
                for row in attempts[:len(expected_prefix)]] != expected_prefix:
        _fail(f"event runtime {label} lifecycle initial phase順不正")
    cursor = len(expected_prefix)
    tag2_rows: list[Mapping[str, Any]] = []
    while cursor < len(attempts) \
            and attempts[cursor]["phase_marker"] \
                == "PRE_FIELD_INPUT_ON_FRAME" \
            and attempts[cursor]["tag"] == 2:
        tag2_rows.append(attempts[cursor])
        cursor += 1
    if not tag2_rows or len(tag2_rows) > _MAP_LIFECYCLE_ATTEMPT_CAP \
            or any(row["result"] != "DISPATCH" for row in tag2_rows[:-1]) \
            or tag2_rows[-1]["result"] \
                not in {"TAG_ABSENT", "NO_CONDITION_MATCH"}:
        _fail(f"event runtime {label} tag2 repeat/quiescence不正")
    suffix = [("FIELD_RETURN_RESUME", 5),
              ("FIELD_RETURN_RETURN_TO_FIELD", 7)] \
        if include_field_return else []
    if [(row["phase_marker"], row["tag"])
        for row in attempts[cursor:]] != suffix:
        _fail(f"event runtime {label} field-return phase順不正")


def _event_map_player_position_from_producer(
    producer: Mapping[str, Any], map_id: Mapping[str, int], label: str,
) -> dict[str, Any]:
    """Derive the getplayerpos fixture from the normalized MAP seed."""

    source = producer.get("source_trigger_path")
    if not isinstance(source, Mapping):
        _fail(f"event runtime {label} MAP player-position source欠落")
    if "resume_callback" in source:
        resume = source["resume_callback"]
        predecessor = resume.get("actual_predecessor_consumer") \
            if isinstance(resume, Mapping) else None
        if not isinstance(predecessor, Mapping):
            _fail(f"event runtime {label} MAP resume predecessor欠落")
        seed_key = next((
            key for key in _EVENT_MAP_LOAD_SEED_KEYS if key in predecessor
        ), None)
        seed = predecessor.get(seed_key) if seed_key is not None else None
    else:
        seed_key = next((
            key for key in _EVENT_MAP_LOAD_SEED_KEYS if key in source
        ), None)
        seed = source.get(seed_key) if seed_key is not None else None
    expected_kind = {
        "stock_warp": "STOCK_WARP",
        "stock_connection": "CONNECTION",
        "engine_teleport": "ENGINE_TELEPORT",
    }.get(seed_key)
    if expected_kind != producer.get("producer_kind") \
            or not isinstance(seed, Mapping):
        _fail(f"event runtime {label} MAP player-position seed不一致")
    destination = seed.get("destination")
    position = seed.get(
        "start_tile" if seed_key == "engine_teleport" else "arrival_tile"
    )
    if not isinstance(destination, Mapping) \
            or not isinstance(position, Mapping) \
            or {key: destination.get(key) for key in ("group", "map")} \
                != dict(map_id):
        _fail(f"event runtime {label} MAP player-position destination不一致")
    result = {
        "x": position.get("x"), "y": position.get("y"),
        "group": destination.get("group"), "map": destination.get("map"),
        "apply_relation": "ACTUAL_STOCK_WARP_THEN_REAL_MOVEMENT",
    }
    for key, maximum in (
        ("x", 0xFFFF), ("y", 0xFFFF), ("group", 0xFF), ("map", 0xFF),
    ):
        _int(result[key], f"{label}.PLAYER_POSITION.{key}", maximum)
    return result


def _map_lifecycle_player_position_consumers(
    lifecycle: Mapping[str, Any], label: str,
) -> list[str]:
    """Re-derive dynamic getplayerpos consumption from exact effect pairs."""

    rows = lifecycle.get("ordered_effect_instances")
    if not isinstance(rows, list):
        _fail(f"event runtime {label} MAP lifecycle effect列欠落")
    groups: dict[tuple[int, str, int], list[Mapping[str, Any]]] = {}
    for index, row in enumerate(rows):
        row_label = f"{label}.ordered_effect_instances[{index}]"
        if not isinstance(row, Mapping):
            _fail(f"event runtime {row_label} mapping不正")
        effect = row.get("effect")
        if not isinstance(effect, Mapping):
            _fail(f"event runtime {row_label}.effect mapping不正")
        relation = effect.get("relation")
        opcode = effect.get("opcode")
        position_relation = relation in {
            "COPY_CURRENT_PLAYER_X", "COPY_CURRENT_PLAYER_Y",
        }
        if not position_relation and opcode != "0x42":
            continue
        instruction = effect.get("instruction_address")
        trace_index = effect.get("execution_trace_index")
        member = effect.get("group_member_ordinal")
        dispatch = row.get("dispatch_ordinal")
        if opcode != "0x42" or not position_relation \
                or effect.get("domain") != "vars" \
                or effect.get("abi_key") is not None \
                or not isinstance(instruction, str) \
                or re.fullmatch(r"0x0[89][0-9A-F]{6}", instruction) is None \
                or isinstance(trace_index, bool) \
                or not isinstance(trace_index, int) or trace_index < 0 \
                or isinstance(member, bool) \
                or not isinstance(member, int) or member < 0 \
                or isinstance(dispatch, bool) \
                or not isinstance(dispatch, int) or dispatch < 0:
            _fail(f"event runtime {row_label} opcode42 effect不正")
        groups.setdefault((dispatch, instruction, trace_index), []).append(row)

    consumers: set[str] = set()
    for identity, group in groups.items():
        relations = sorted(
            str(row["effect"]["relation"]) for row in group
        )
        members = sorted(
            int(row["effect"]["group_member_ordinal"]) for row in group
        )
        owners = {row.get("owner_id") for row in group}
        roots = {row.get("root_pc") for row in group}
        if relations != [
            "COPY_CURRENT_PLAYER_X", "COPY_CURRENT_PLAYER_Y",
        ] or members != [0, 1] or len(owners) != 1 or len(roots) != 1:
            _fail(
                f"event runtime {label} MAP opcode42 X/Y effect対不正:"
                f"{identity}"
            )
        owner = next(iter(owners))
        if not isinstance(owner, str) or _OWNER_ID.fullmatch(owner) is None:
            _fail(f"event runtime {label} MAP opcode42 owner不正")
        consumers.add(owner)
    return sorted(consumers)


def _validate_event_map_player_position_control(
    controls: Mapping[str, Any], lifecycle: Mapping[str, Any],
    producer: Mapping[str, Any], map_id: Mapping[str, int], label: str,
) -> None:
    """Bind one compact position row to actual lifecycle consumption."""

    external = controls.get("external")
    if not isinstance(external, list):
        _fail(f"event runtime {label} MAP external controls不正")
    consumers = _map_lifecycle_player_position_consumers(lifecycle, label)
    rows = [row for row in external if row.get("kind") == "PLAYER_POSITION"]
    if len(rows) != (1 if consumers else 0):
        _fail(
            f"event runtime {label} "
            "MAP PLAYER_POSITION dynamic consumption/row不一致"
        )
    if not rows:
        return
    expected = _event_map_player_position_from_producer(
        producer, map_id, label,
    )
    row = rows[0]
    if row.get("id") != 0 \
            or row.get("required_value_in_matrix_case") != expected \
            or row.get("owner_keys") != consumers:
        _fail(
            f"event runtime {label} "
            "MAP PLAYER_POSITION/arrival fixture/owner scope不一致"
        )


def _normalize_event_map_composite_case(
    raw: Mapping[str, Any], label: str,
    registry: Mapping[str, Any],
) -> list[dict[str, Any]]:
    keys = {
        "case_id", "case_kind", "map", "covered_owner_ids",
        "dispatched_owner_ids", "trigger_path", "input_sequences",
        "effect_signature_ids", "map_lifecycle", "source_provenance",
    }
    if set(raw) != keys \
            or raw.get("case_kind") != "MAP_LIFECYCLE_COMPOSITE":
        _fail(f"event runtime {label} MAP composite exact schema不正")
    source_case_id = raw["case_id"]
    if not isinstance(source_case_id, str) \
            or re.fullmatch(
                r"map-lifecycle-[0-9]{3}-[0-9]{3}-[0-9a-f]{20}",
                source_case_id,
            ) is None:
        _fail(f"event runtime {label} MAP composite case ID不正")
    raw_map = raw["map"]
    if not isinstance(raw_map, Mapping) or set(raw_map) != {"group", "map"}:
        _fail(f"event runtime {label}.map exact schema不正")
    map_id = {
        "group": _int(raw_map["group"], f"{label}.map.group", 255),
        "map": _int(raw_map["map"], f"{label}.map.map", 255),
    }
    expected_prefix = f"map-lifecycle-{map_id['group']:03d}-{map_id['map']:03d}-"
    if not source_case_id.startswith(expected_prefix):
        _fail(f"event runtime {label} case/map identity不正")
    covered = raw["covered_owner_ids"]
    if not isinstance(covered, list) or not covered \
            or covered != sorted(set(covered)):
        _fail(f"event runtime {label}.covered_owner_ids順/重複不正")
    owner_pattern = re.compile(
        rf"MAP:{map_id['group']:03d}/{map_id['map']:03d}:"
        r"[0-9]{3}:(?:DIRECT|[0-9]{3})\Z"
    )
    if any(not isinstance(owner, str) or owner_pattern.fullmatch(owner) is None
           for owner in covered):
        _fail(f"event runtime {label}.covered_owner_ids map identity不正")
    trigger = _normalize_event_trigger_path(raw["trigger_path"], label)
    if not isinstance(raw["map_lifecycle"], Mapping) \
            or raw["map_lifecycle"].get("producer_contracts") \
            != raw["trigger_path"].get("producer_contracts"):
        _fail(f"event runtime {label} MAP producer contract二重正本drift")
    common = _normalize_map_lifecycle_common(
        raw["map_lifecycle"], f"{label}.map_lifecycle",
    )
    common["producer_contracts"] = deepcopy(trigger["producer_contracts"])
    if trigger["map"] != map_id \
            or common["topology"]["map"] != map_id \
            or trigger["producer_contracts"] != common["producer_contracts"]:
        _fail(f"event runtime {label} MAP trigger/lifecycle二重正本drift")
    has_return_tag = bool(
        {"5", "7"} & set(common["topology"]["by_tag"])
    )
    if common["include_field_return"] is not has_return_tag \
            or (trigger["field_return_contract"] is not None) \
                is not common["include_field_return"]:
        _fail(f"event runtime {label} MAP field-return topology不一致")
    effects = raw["effect_signature_ids"]
    if not isinstance(effects, list) or not effects \
            or len(effects) != len(set(effects)) \
            or any(not isinstance(effect, str)
                   or _OWNER_ID.fullmatch(effect) is None for effect in effects):
        _fail(f"event runtime {label}.effect_signature_ids不正")
    source_provenance = raw["source_provenance"]
    if not isinstance(source_provenance, Mapping) or not source_provenance:
        _fail(f"event runtime {label}.source_provenance不正")
    raw_sequences = raw["input_sequences"]
    if not isinstance(raw_sequences, list) or not raw_sequences:
        _fail(f"event runtime {label}.input_sequences不正")
    normalized_rows: list[dict[str, Any]] = []
    sequence_ids: set[str] = set()
    dispatched_union: set[str] = set()
    producer_contracts = trigger["producer_contracts"]
    for index, raw_sequence in enumerate(raw_sequences):
        sequence_label = f"{label}.input_sequences[{index}]"
        raw_lifecycle = raw_sequence.get("map_lifecycle") \
            if isinstance(raw_sequence, Mapping) else None
        producer_ordinal = raw_lifecycle.get("producer_ordinal") \
            if isinstance(raw_lifecycle, Mapping) else None
        if isinstance(producer_ordinal, bool) \
                or not isinstance(producer_ordinal, int) \
                or not 0 <= producer_ordinal < len(producer_contracts):
            _fail(f"event runtime {sequence_label} producer ordinal不正")
        producer = producer_contracts[producer_ordinal]
        execution_trigger = producer["source_trigger_path"]
        sequence = _normalize_event_input_sequence(
            raw_sequence, source_case_id, execution_trigger, sequence_label,
            map_composite=True,
            expected_trigger_prefix=producer["trigger_tokens"],
        )
        lifecycle = sequence["map_lifecycle"]
        if not set(sequence["effect_signature_ids"]) <= set(effects):
            _fail(f"event runtime {sequence_label} effect signature union外")
        if lifecycle["producer_ordinal"] != producer_ordinal \
                or lifecycle["producer_kind"] != producer["producer_kind"] \
                or lifecycle["include_field_return"] \
                    is not common["include_field_return"] \
                or lifecycle["attempt_cap"] != common["attempt_cap"]:
            _fail(f"event runtime {sequence_label} producer/common join不正")
        _validate_map_lifecycle_attempt_phase_order(lifecycle, sequence_label)
        if sequence["sequence_id"] in sequence_ids \
                or re.fullmatch(
                    re.escape(source_case_id)
                    + rf"--seq-{index:04d}-[0-9a-f]{{16}}",
                    sequence["sequence_id"],
                ) is None:
            _fail(f"event runtime {sequence_label} sequence ID不正/重複")
        sequence_ids.add(sequence["sequence_id"])
        controls, state = _normalize_map_phase_scoped_controls(
            sequence["control_requirements"], sequence, registry,
            sequence_label, covered_owner_ids=set(covered),
        )
        _validate_event_map_player_position_control(
            controls, lifecycle, producer, map_id, sequence_label,
        )
        sequence["control_requirements"] = controls
        dispatched = lifecycle["dispatched_owner_ids"]
        if any(owner not in covered for owner in dispatched):
            _fail(f"event runtime {sequence_label} dispatched owner scope外")
        dispatched_union.update(dispatched)
        terminal = "BATTLE_START" \
            if sequence["battle_start_required_postconditions"] is not None \
            else "FIELD_RELEASE"
        if (sequence["post_battle_continuation"] is not None) \
                is not (terminal == "BATTLE_START"):
            _fail(f"event runtime {sequence_label} battle continuation不一致")
        run_case_id = f"{source_case_id}--run-{index:04d}"
        normalized_rows.append({
            "case_id": run_case_id,
            "source_case_id": source_case_id,
            "source_sequence_ordinal": index,
            "case_kind": "MAP_LIFECYCLE_COMPOSITE",
            "owner_id": (
                f"MAP_LIFECYCLE:{map_id['group']:03d}/{map_id['map']:03d}"
            ),
            "covered_owner_ids": list(covered),
            "dispatched_owner_ids": list(dispatched),
            "source_dispatched_owner_ids": list(raw["dispatched_owner_ids"])
                if isinstance(raw["dispatched_owner_ids"], list) else None,
            "map": map_id,
            "root_assignment_id": (
                f"MAP_LIFECYCLE:{map_id['group']:03d}/{map_id['map']:03d}"
            ),
            "trigger_path": execution_trigger,
            "composite_trigger_path": trigger,
            "input_sequence": sequence,
            "state": state,
            "control_requirements": controls,
            "effect_signature_ids": list(sequence["effect_signature_ids"]),
            "required_postconditions": sequence["required_postconditions"],
            "battle_start_required_postconditions": sequence[
                "battle_start_required_postconditions"
            ],
            "text_oracle": sequence["text_oracle"],
            "terminal_kind": terminal,
            "map_lifecycle": {"common": common, "sequence": lifecycle},
            "source_provenance": deepcopy(dict(source_provenance)),
        })
    source_dispatched = raw["dispatched_owner_ids"]
    if not isinstance(source_dispatched, list) \
            or source_dispatched != sorted(dispatched_union):
        _fail(f"event runtime {label}.dispatched_owner_ids union不正")
    effect_union = sorted({
        effect for row in normalized_rows
        for effect in row["effect_signature_ids"]
    })
    if sorted(effects) != effect_union:
        _fail(f"event runtime {label}.effect_signature_ids union不正")
    for row in normalized_rows:
        row["source_dispatched_owner_ids"] = list(source_dispatched)
    return normalized_rows


def normalize_event_runtime_projection(
    document: Mapping[str, Any], *, require_final_scope: bool = True,
) -> tuple[dict[str, dict[str, Any]], dict[str, Any]]:
    """Final Phase-3 event owner rowsをC runner用にstrict正規化する。"""
    if require_final_scope:
        try:
            if str(ROOT) not in sys.path:
                sys.path.insert(0, str(ROOT))
            from tools.stage61_catalog_state_matrix import runner_event_state_rows

            source_rows = runner_event_state_rows(document)
        except (ImportError, KeyError, TypeError, ValueError, RuntimeError) as error:
            _fail(f"state matrix runner_event_state_rows失敗: {error}")
    else:
        source_rows = document.get("event_runtime_cases")
        if not isinstance(source_rows, list):
            _fail("event runtime unit projection rows不正")
    scope = document.get("event_owner_runtime_scope")
    triggers = document.get("event_owner_trigger_contracts")
    registry = document.get("runner_fixtures", {})
    if not isinstance(scope, Mapping) or not isinstance(triggers, list) \
            or not isinstance(registry, Mapping):
        _fail("event runtime final scope/trigger/fixture不正")

    normalized: dict[str, dict[str, Any]] = {}
    sequence_ids: set[str] = set()
    source_case_ids: set[str] = set()
    event_case_ids_by_owner: dict[str, set[str]] = {}
    map_covered_counts: dict[str, int] = {}
    referenced_fixtures: set[str] = set()
    hidden_variants: dict[str, set[str]] = {}
    for index, raw in enumerate(source_rows):
        label = f"runner_event_state_rows[{index}]"
        if isinstance(raw, Mapping) \
                and raw.get("case_kind") == "MAP_LIFECYCLE_COMPOSITE":
            map_rows = _normalize_event_map_composite_case(
                raw, label, registry,
            )
            source_case_id = str(raw["case_id"])
            if source_case_id in source_case_ids:
                _fail(f"event runtime {label} source case ID重複")
            source_case_ids.add(source_case_id)
            for owner_id in raw["covered_owner_ids"]:
                map_covered_counts[owner_id] = (
                    map_covered_counts.get(owner_id, 0) + 1
                )
                event_case_ids_by_owner.setdefault(owner_id, set()).add(
                    source_case_id
                )
            for row in map_rows:
                case_id = row["case_id"]
                sequence_id = row["input_sequence"]["sequence_id"]
                if case_id in normalized or sequence_id in sequence_ids:
                    _fail(f"event runtime {label} MAP run/sequence ID重複")
                normalized[case_id] = row
                sequence_ids.add(sequence_id)
                for external in row["control_requirements"]["external"]:
                    required_value = external[
                        "required_value_in_matrix_case"
                    ]
                    if isinstance(required_value, Mapping):
                        referenced_fixtures.update(
                            value for key, value in required_value.items()
                            if key.endswith("_ref") and isinstance(value, str)
                        )
            continue
        keys = {
            "case_id", "owner_id", "root_assignment_id", "trigger_path",
            "input_sequence", "control_requirements", "effect_signature_ids",
            "required_postconditions", "battle_start_required_postconditions",
            "text_oracle", "terminal_kind",
            "source_provenance",
        }
        if not isinstance(raw, Mapping) or set(raw) != keys:
            _fail(f"event runtime {label} exact schema不一致")
        case_id = raw["case_id"]
        owner_id = raw["owner_id"]
        if not isinstance(case_id, str) or _CASE_ID.fullmatch(case_id) is None \
                or case_id in normalized \
                or not isinstance(owner_id, str) \
                or _OWNER_ID.fullmatch(owner_id) is None:
            _fail(f"event runtime {label} case/owner ID不正")
        if case_id in source_case_ids:
            _fail(f"event runtime {label} source case ID重複")
        source_case_ids.add(case_id)
        event_case_ids_by_owner.setdefault(owner_id, set()).add(case_id)
        trigger = _normalize_event_trigger_path(raw["trigger_path"], label)
        if trigger["kind"] == "OBJECT_FACE_A":
            _fail(f"event runtime {label} OBJECTはstate matrix rebind専用です")
        assignment = raw["root_assignment_id"]
        if trigger["kind"] == "HIDDEN_ITEM":
            if assignment is not None:
                _fail(f"event runtime {label} hidden assignmentはnull必須")
            hidden_variants.setdefault(owner_id, set()).add(trigger["variant"])
        elif not isinstance(assignment, str) \
                or _OWNER_ID.fullmatch(assignment) is None:
            _fail(f"event runtime {label} root_assignment_id不正")
        sequence = _normalize_event_input_sequence(
            raw["input_sequence"], case_id, trigger, label,
        )
        if sequence["sequence_id"] in sequence_ids:
            _fail(f"event runtime {label} sequence ID global重複")
        sequence_ids.add(sequence["sequence_id"])
        controls, state = _normalize_event_compact_controls(
            raw["control_requirements"], [sequence], registry, label,
            allowed_owner_ids={owner_id},
        )
        for external in controls["external"]:
            required_value = external["required_value_in_matrix_case"]
            if isinstance(required_value, Mapping):
                referenced_fixtures.update(
                    value for key, value in required_value.items()
                    if key.endswith("_ref") and isinstance(value, str)
                )
        effects = raw["effect_signature_ids"]
        if not isinstance(effects, list) or not effects \
                or len(effects) != len(set(effects)) \
                or any(not isinstance(effect, str)
                       or _OWNER_ID.fullmatch(effect) is None for effect in effects):
            _fail(f"event runtime {label}.effect_signature_ids不正")
        required = _normalize_required_postconditions(
            raw["required_postconditions"], label,
        )
        battle_start_raw = raw["battle_start_required_postconditions"]
        battle_start_required = (
            None if battle_start_raw is None else
            _normalize_required_postconditions(
                battle_start_raw, f"{label}.battle_start",
            )
        )
        text_oracle = _normalize_text_oracle(
            raw["text_oracle"], label,
            visible_text_expected=sequence["visible_text_expected"],
        )
        if required != sequence["required_postconditions"] \
                or battle_start_required \
                    != sequence["battle_start_required_postconditions"] \
                or text_oracle != sequence["text_oracle"]:
            _fail(f"event runtime {label} case/sequence oracle drift")
        terminal = raw["terminal_kind"]
        if not isinstance(terminal, str) or _CASE_ID.fullmatch(terminal) is None:
            _fail(f"event runtime {label}.terminal_kind不正")
        if (battle_start_required is not None) \
                is not (terminal == "BATTLE_START") \
                or (sequence["post_battle_continuation"] is not None) \
                    is not (terminal == "BATTLE_START"):
            _fail(f"event runtime {label} battle-start/terminal不一致")
        provenance = raw["source_provenance"]
        if not isinstance(provenance, Mapping) or not provenance:
            _fail(f"event runtime {label}.source_provenance不正")
        normalized[case_id] = {
            "case_id": case_id, "owner_id": owner_id,
            "root_assignment_id": assignment,
            "trigger_path": trigger, "input_sequence": sequence,
            "state": state, "control_requirements": controls,
            "effect_signature_ids": list(effects),
            "required_postconditions": required,
            "battle_start_required_postconditions": battle_start_required,
            "text_oracle": text_oracle, "terminal_kind": terminal,
            "source_provenance": deepcopy(dict(provenance)),
        }

    trigger_owner_ids: set[str] = set()
    runtime_owner_ids: set[str] = set()
    structural_owner_ids: set[str] = set()
    structural_nontrigger_evidence: list[dict[str, Any]] = []
    object_runtime_owner_ids: set[str] = set()
    event_owner_ids = set(event_case_ids_by_owner)
    scope_assertions = scope.get("assertions")
    null_scope_asserted = isinstance(scope_assertions, Mapping) and (
        scope_assertions.get(
            "structural_nontrigger_is_exact_null_1000_plus_dormant_common_1"
        ) is True
    )
    for index, raw in enumerate(triggers):
        label = f"event_owner_trigger_contracts[{index}]"
        if not isinstance(raw, Mapping):
            _fail(f"event runtime {label}不正")
        owner_id = raw.get("owner_id")
        owner_kind = raw.get("owner_kind")
        if not isinstance(owner_id, str) or _OWNER_ID.fullmatch(owner_id) is None \
                or owner_id in trigger_owner_ids \
                or owner_kind not in {"OBJECT", "BG", "COORD", "MAP", "COMMON"}:
            _fail(f"event runtime {label} owner不正/重複")
        trigger_owner_ids.add(owner_id)
        required = raw.get("runtime_case_required")
        case_ids = raw.get("runtime_case_ids")
        if not isinstance(required, bool) or not isinstance(case_ids, list) \
                or case_ids != sorted(set(case_ids)):
            _fail(f"event runtime {label} required/case IDs不正")
        if required:
            runtime_owner_ids.add(owner_id)
            if not case_ids:
                _fail(f"event runtime {label} runtime case欠落")
            if owner_kind == "OBJECT":
                object_runtime_owner_ids.add(owner_id)
            elif owner_id not in event_owner_ids:
                _fail(f"event runtime {label} non-OBJECT event case欠落")
            elif case_ids != sorted(event_case_ids_by_owner[owner_id]):
                _fail(f"event runtime {label} owner/source case binding不一致")
        else:
            structural_owner_ids.add(owner_id)
            if case_ids or raw.get("trigger_class") != "STRUCTURAL_NONTRIGGER":
                _fail(f"event runtime {label} structural nontrigger根拠不正")
            structural_nontrigger_evidence.append(
                _normalize_structural_nontrigger_evidence(
                    raw, label, null_scope_asserted=null_scope_asserted,
                )
            )
    object_matrix_owner_ids = {
        row.get("owner_key") for row in document.get("cases", [])
        if isinstance(row, Mapping) and isinstance(row.get("owner_key"), str)
    }
    if object_runtime_owner_ids != object_matrix_owner_ids:
        _fail("event runtime OBJECT owner/state matrix rebind不一致")
    map_runtime_owner_ids = {
        owner_id for owner_id in runtime_owner_ids
        if owner_id.startswith("MAP:")
    }
    if set(map_covered_counts) != map_runtime_owner_ids \
            or any(count != 1 for count in map_covered_counts.values()):
        _fail("event runtime MAP covered owner exact partition不一致")
    if runtime_owner_ids & structural_owner_ids \
            or trigger_owner_ids != runtime_owner_ids | structural_owner_ids:
        _fail("event runtime owner classification重複/欠落")
    if len(trigger_owner_ids) != scope.get("owner_count") \
            or len(runtime_owner_ids) != scope.get("runtime_required_owner_count") \
            or len(structural_owner_ids) \
                != scope.get("structural_nontrigger_owner_count") \
            or len(object_runtime_owner_ids) != scope.get(
                "runtime_script_owner_kind_counts", {}
            ).get("OBJECT"):
        _fail("event runtime owner aggregate不一致")
    structural_digest = _event_contract_sha256(sorted(structural_owner_ids))
    if structural_digest != scope.get("structural_nontrigger_owner_ids_sha256"):
        _fail("event runtime structural NULL owner SHA-256不一致")
    normal_hidden_variants = {
        "AVAILABLE_SUCCESS", "AVAILABLE_BAG_FULL", "ALREADY_COLLECTED",
    }
    coin_hidden_variants = {
        "AVAILABLE_SUCCESS", "AVAILABLE_COIN_FULL",
        "AVAILABLE_NO_COIN_CASE", "ALREADY_COLLECTED",
    }
    if any(variants not in {frozenset(normal_hidden_variants),
                            frozenset(coin_hidden_variants)}
           for variants in map(frozenset, hidden_variants.values())):
        _fail("event runtime hidden item/coin variant matrix不完備")
    structural_nontrigger_evidence.sort(key=lambda item: item["owner_id"])
    null_evidence = [
        item for item in structural_nontrigger_evidence
        if item["kind"] == "EXACT_NULL_SCRIPT_POINTER"
    ]
    common_evidence = [
        item for item in structural_nontrigger_evidence
        if item["kind"] == "UNREFERENCED_STANDARD_SCRIPT_TABLE_ENTRY"
    ]
    all_null_zero = len(null_evidence) + 1 == len(structural_owner_ids) \
        and all(
            item["raw_root"] == 0
            and item["engine_no_dispatch_contract"] is True
            and item["zero_raw_proven_by_final_inventory_scope"] is True
            for item in null_evidence
        )
    all_common_structural = len(common_evidence) == 1 and all(
        value is True for value in common_evidence[0]["assertions"].values()
    )
    if not all_null_zero or not all_common_structural:
        _fail("event runtime structural nontrigger evidence不完備")
    structural_evidence_digest = _event_contract_sha256(
        structural_nontrigger_evidence,
    )

    object_fixture_refs: set[str] = set()
    for row in document.get("cases", []):
        if not isinstance(row, Mapping):
            continue
        controls = row.get("control_requirements", {})
        for external in controls.get("external", []) \
                if isinstance(controls, Mapping) else []:
            required_value = external.get("required_value_in_matrix_case") \
                if isinstance(external, Mapping) else None
            if isinstance(required_value, Mapping):
                object_fixture_refs.update(
                    value for key, value in required_value.items()
                    if key.endswith("_ref") and isinstance(value, str)
                )
    if object_fixture_refs | referenced_fixtures != set(registry):
        _fail("event runtime/object runner fixture reference過不足")
    proof = {
        "owner_count": len(trigger_owner_ids),
        "runtime_required_owner_count": len(runtime_owner_ids),
        "structural_nontrigger_owner_count": len(structural_owner_ids),
        "object_runtime_owner_count": len(object_runtime_owner_ids),
        "event_runtime_owner_count": len(event_owner_ids),
        "event_runtime_case_count": len(source_case_ids),
        "event_runtime_execution_case_count": len(normalized),
        "event_runtime_sequence_count": len(sequence_ids),
        "runtime_owner_ids": sorted(runtime_owner_ids),
        "object_runtime_owner_ids": sorted(object_runtime_owner_ids),
        "event_runtime_owner_ids": sorted(event_owner_ids),
        "event_runtime_source_case_ids": sorted(source_case_ids),
        "map_covered_owner_ids": sorted(map_covered_counts),
        "structural_nontrigger_owner_ids": sorted(structural_owner_ids),
        "structural_nontrigger_owner_ids_sha256": structural_digest,
        "structural_nontrigger_evidence": structural_nontrigger_evidence,
        "structural_nontrigger_evidence_sha256": structural_evidence_digest,
        "all_1000_null_structural_zero_raw_proven": all_null_zero,
        "dormant_common7_table_abi_and_live_caller_zero_proven": (
            all_common_structural
        ),
        "all_owner_trigger_contracts_bound": True,
    }
    return normalized, proof


def project_event_runtime_matrix(
    rows: Mapping[str, Mapping[str, Any]],
    *, selected_case_ids: Sequence[str] = (),
) -> dict[str, dict[str, Any]]:
    requested = list(dict.fromkeys(selected_case_ids))
    unknown = sorted(set(requested) - set(rows))
    if unknown:
        _fail(f"unknown --event-state-case: {unknown}")
    identifiers = requested or sorted(rows)
    return {case_id: deepcopy(dict(rows[case_id])) for case_id in identifiers}


def _matrix_case_binding_sha256(
    rows: Sequence[Mapping[str, Any]],
) -> str:
    """Bind an identity-only strict branch to the complete normalized rows."""
    return _sha256(_stable([
        deepcopy(dict(row)) for row in sorted(
            rows, key=lambda item: str(item.get("case_id")),
        )
    ]).encode("utf-8"))


def _validate_identity_only_catalog_matrix_binding(
    entries: Sequence[Mapping[str, Any]],
    matrix_rows: Mapping[str, Mapping[str, Any]],
) -> None:
    """Recheck promotion bindings whenever the strict catalog is consumed."""
    identity_entries = [
        entry for entry in entries
        if any(
            isinstance(branch, Mapping)
            and branch.get("identity_only") is True
            for branch in entry.get("branches", [])
        )
    ]
    if not identity_entries:
        return
    if len(identity_entries) != len(entries):
        _fail("strict catalog identity-only/legacy entry混在")
    rows_by_base: dict[str, list[Mapping[str, Any]]] = {}
    for row in matrix_rows.values():
        rows_by_base.setdefault(str(row.get("base_case_id")), []).append(row)
    if set(rows_by_base) != {
        str(entry.get("case_id")) for entry in identity_entries
    }:
        _fail("strict catalog/state matrix base case binding不一致")
    seen_matrix_ids: set[str] = set()
    for entry in identity_entries:
        case_id = str(entry["case_id"])
        branch_rows: dict[str, list[Mapping[str, Any]]] = {}
        for row in rows_by_base[case_id]:
            branch_rows.setdefault(str(row.get("catalog_branch")), []).append(row)
        branches = entry.get("branches", [])
        branch_ids = [
            str(branch.get("branch_id")) for branch in branches
            if isinstance(branch, Mapping)
        ]
        if set(branch_rows) != set(branch_ids) \
                or len(branch_ids) != len(set(branch_ids)):
            _fail(f"strict catalog/state matrix branch binding不一致: {case_id}")
        for branch in branches:
            branch_id = str(branch["branch_id"])
            rows = branch_rows[branch_id]
            matrix_case_ids = sorted(str(row["case_id"]) for row in rows)
            if branch.get("matrix_case_ids") != matrix_case_ids \
                    or branch.get("matrix_case_binding_sha256") \
                        != _matrix_case_binding_sha256(rows):
                _fail(
                    "strict catalog/state matrix semantic binding不一致: "
                    f"{case_id}/{branch_id}"
                )
            duplicate = set(matrix_case_ids) & seen_matrix_ids
            if duplicate:
                _fail(
                    "strict catalog/state matrix case binding重複: "
                    f"{sorted(duplicate)}"
                )
            seen_matrix_ids.update(matrix_case_ids)
    if seen_matrix_ids != set(matrix_rows):
        _fail("strict catalog/state matrix case binding coverage不一致")


def validate_identity_only_strict_catalog_contract(
    catalog: Mapping[str, Any],
    matrix_rows: Mapping[str, Mapping[str, Any]],
) -> bool:
    """Public final-pipeline gate: reject every legacy expectation branch."""
    entries = catalog.get("entries")
    if not isinstance(entries, list) or not entries:
        _fail("identity-only strict catalog entries欠落")
    for entry_index, entry in enumerate(entries):
        branches = entry.get("branches") if isinstance(entry, Mapping) else None
        if not isinstance(branches, list) or not branches or any(
            not isinstance(branch, Mapping)
            or branch.get("identity_only") is not True
            or branch.get("semantic_contract")
                != _IDENTITY_ONLY_BRANCH_CONTRACT
            for branch in branches
        ):
            _fail(
                "final strict catalogにLEGACY_EXPECTATION branchがあります: "
                f"entries[{entry_index}]"
            )
    _validate_identity_only_catalog_matrix_binding(entries, matrix_rows)
    return True


def project_catalog_state_matrix(
    catalog: Mapping[str, Any],
    matrix_rows: Mapping[str, Mapping[str, Any]],
    *, selected_case_ids: Sequence[str] = (),
) -> dict[str, dict[str, Any]]:
    """校正済みlegal portと全stateを結合し、choice probe単位へ射影する。"""
    entries = catalog.get("entries")
    if not isinstance(entries, list) or not entries:
        _fail("state matrix projection用strict catalogが空です")
    by_base: dict[str, Mapping[str, Any]] = {}
    for entry in entries:
        if not isinstance(entry, Mapping) or not isinstance(entry.get("case_id"), str):
            _fail("state matrix projection用strict entry不正")
        if entry["case_id"] in by_base:
            _fail(f"strict base case重複: {entry['case_id']}")
        by_base[entry["case_id"]] = entry
    _validate_identity_only_catalog_matrix_binding(entries, matrix_rows)
    requested = list(dict.fromkeys(selected_case_ids))
    unknown = sorted(set(requested) - set(matrix_rows))
    if unknown:
        _fail(f"unknown --state-case: {unknown}")
    source_ids = requested or sorted(matrix_rows)
    projected: dict[str, dict[str, Any]] = {}
    for case_id in source_ids:
        matrix = matrix_rows[case_id]
        base_id = matrix["base_case_id"]
        entry = by_base.get(base_id)
        if entry is None:
            _fail(f"state matrix {case_id} legal port未校正: {base_id}")
        exact_identity = (
            entry.get("owner_key"), entry.get("group"), entry.get("map"),
            entry.get("local_id"),
        )
        matrix_identity = (
            matrix["owner_key"], matrix["group"], matrix["map"],
            matrix["local_id"],
        )
        if exact_identity != matrix_identity:
            _fail(f"state matrix {case_id}/strict catalog owner identity不一致")
        position_required = bool(
            matrix.get("runtime_position_map_load_required", False)
        )
        variant = matrix.get("runtime_position_variant")
        runtime_map_lifecycle = matrix.get("runtime_map_lifecycle")
        entry_object = _pair(
            entry.get("object"), f"state-matrix.{case_id}.strict_object",
        )
        if position_required:
            if runtime_map_lifecycle is not None:
                if variant is not None \
                        or not isinstance(
                            matrix.get("interaction_execution"), Mapping,
                        ):
                    _fail(
                        f"state matrix {case_id} lifecycle/object不一致"
                    )
                interaction_source = {
                    **dict(entry),
                    "object": list(matrix["object"]),
                    "interaction_execution": deepcopy(
                        matrix["interaction_execution"],
                    ),
                }
            else:
                static_object = _catalog_template_position(
                entry.get("expected_template_raw_hex"),
                f"state-matrix.{case_id}",
                )
                if entry_object == static_object \
                        or tuple(matrix["object"]) not in {
                            tuple(entry_object), tuple(static_object),
                        }:
                    _fail(
                        f"state matrix {case_id}/strict catalog position集合不一致"
                    )
                variant_id = variant.get("variant_id") \
                    if isinstance(variant, Mapping) else None
                expected_variant_object = (
                    static_object if variant_id == "STATIC" else entry_object
                    if variant_id == "RUNTIME" else None
                )
                if matrix["object"] != expected_variant_object \
                        or not isinstance(
                            matrix.get("interaction_execution"), Mapping,
                        ):
                    _fail(
                        f"state matrix {case_id} position variant/object不一致"
                    )
                interaction_source = {
                    **dict(entry),
                    "object": list(matrix["object"]),
                    "interaction_execution": deepcopy(
                        matrix["interaction_execution"],
                    ),
                }
        else:
            if matrix["object"] != entry_object \
                    or variant is not None \
                    or not isinstance(
                        matrix.get("interaction_execution"), Mapping,
                    ):
                _fail(f"state matrix {case_id}/strict catalog object identity不一致")
            strict_interaction = _catalog_interaction_execution(
                entry, f"state-matrix.{case_id}.strict",
            )
            strict_execution = {
                key: deepcopy(strict_interaction[key]) for key in (
                    "trigger", "start", "walk_sequence", "stance", "action",
                    "interaction_distance", "counter_tile",
                    "actual_walk_required", "actual_walk_exception",
                    "walk_path_basis", "direct_script_call_forbidden",
                )
            }
            if matrix["interaction_execution"] != strict_execution:
                _fail(f"state matrix {case_id}/strict execution二重正本不一致")
            interaction_source = {
                **dict(entry),
                "interaction_execution": deepcopy(
                    matrix["interaction_execution"],
                ),
            }
        interaction = _catalog_interaction_execution(
            interaction_source, f"state-matrix.{case_id}",
        )
        # The calibrated catalog owns only the legal physical port.  The
        # executable script root is independently decoded into the state
        # matrix from the final ROM and must travel with every concrete case.
        interaction["runtime_root"] = matrix["runtime_root"]
        interaction["runtime_position_map_load_required"] = position_required
        interaction["runtime_position_control"] = (
            deepcopy(variant["control"])
            if position_required and runtime_map_lifecycle is None
            else _none_runtime_position_control()
        )
        if matrix["expect_interaction"] and not matrix.get("oracle_complete"):
            _fail(
                f"state matrix {case_id} independent input/text/effect oracle未提供"
            )
        projected[case_id] = {
            "case_id": case_id,
            "base_case_id": base_id,
            "owner_key": matrix["owner_key"],
            "catalog_branch": matrix["catalog_branch"],
            "interaction": interaction,
            "state": deepcopy(matrix["state"]),
            "expect_visible": matrix["expect_visible"],
            "expect_interaction": matrix["expect_interaction"],
            "choice_candidates": list(matrix["choice_candidates"]),
            "expected_terminal": matrix["expected_terminal"],
            "oracle_complete": matrix.get("oracle_complete", False),
            "control_abi_complete": matrix.get("control_abi_complete", False),
            "control_requirements": deepcopy(matrix.get(
                "control_requirements", {"external": [], "internal": []},
            )),
            "input_sequences": deepcopy(matrix.get("input_sequences", [])),
            "allowed_post_effect_families": deepcopy(
                matrix.get("allowed_post_effect_families", [])
            ),
            "allowed_post_effects": deepcopy(
                matrix.get("allowed_post_effects")
            ),
            "runtime_map_lifecycle": deepcopy(runtime_map_lifecycle),
        }
    return projected


def _validate_all_domain_state_persistence_inputs(
    *, selected: Sequence[str], requested_case_ids: Sequence[str],
    fixtures: Mapping[str, Mapping[str, Any]],
) -> None:
    """Pin the three reviewed expanded flag/var restart vectors."""
    required = list(_ALL_DOMAIN_STATE_PERSISTENCE_CASE_IDS)
    modes = set(_ALL_DOMAIN_STATE_PERSISTENCE_MODES)
    if not modes <= set(selected) \
            or list(requested_case_ids) != required \
            or list(fixtures) != required:
        _fail(
            "all-domain state persistence case/mode不一致: "
            f"required={required}"
        )
    for index, case_id in enumerate(required, start=1):
        fixture = fixtures.get(case_id)
        state = fixture.get("state") if isinstance(fixture, Mapping) else None
        flags = state.get("flags") if isinstance(state, Mapping) else None
        variables = state.get("vars") if isinstance(state, Mapping) else None
        expanded_flags = [
            row for row in flags if isinstance(row, Mapping)
            and isinstance(row.get("id"), int) and row["id"] >= 0x1000
        ] if isinstance(flags, list) else []
        expanded_vars = [
            row for row in variables if isinstance(row, Mapping)
            and isinstance(row.get("id"), int) and row["id"] > 0x40FF
        ] if isinstance(variables, list) else []
        if expanded_flags != [{"id": 0x18B4, "value": True}] \
                or expanded_vars != [{"id": 0x5170, "value": index}]:
            _fail(
                f"all-domain state persistence {case_id} "
                "expanded flag/var vector不一致"
            )


def _validate_all_domain_state_persistence_output(
    report: Mapping[str, Any],
) -> None:
    """Bind both final payloads and the report summary to the same vectors."""
    required = list(_ALL_DOMAIN_STATE_PERSISTENCE_CASE_IDS)
    summary = report.get("state_persistence")
    if not isinstance(summary, Mapping) \
            or summary.get("selected_case_count") != len(required) \
            or summary.get("case_ids") != required \
            or summary.get("modes") \
                != list(_ALL_DOMAIN_STATE_PERSISTENCE_MODES):
        _fail("all-domain state persistence report summary不一致")
    results = report.get("results")
    if not isinstance(results, Mapping):
        _fail("all-domain state persistence results欠落")
    for mode in _ALL_DOMAIN_STATE_PERSISTENCE_MODES:
        wrapper = results.get(mode)
        payload = wrapper.get("result") if isinstance(wrapper, Mapping) else None
        rows = payload.get("results") if isinstance(payload, Mapping) else None
        case_ids = [
            row.get("case_id") if isinstance(row, Mapping) else None
            for row in rows
        ] if isinstance(rows, list) else []
        if payload is None or payload.get("case") != mode \
                or payload.get("fixture_count") != len(required) \
                or case_ids != required or len(case_ids) != len(set(case_ids)):
            _fail(f"all-domain state persistence {mode} payload不一致")


def _encode_state(rows: Sequence[Mapping[str, Any]], value_key: str) -> str:
    return ",".join(
        f"{row['id']}={int(row[value_key])}" for row in rows
    ) or "-"


def _encode_input_sequence_tsv(sequence: Mapping[str, Any]) -> str:
    continuation = sequence.get("post_battle_continuation")
    if continuation is None:
        resume_kind = "NONE"
        resume_pc = "-"
        post_steps = "-"
        chained_battles = "-"
    else:
        if not isinstance(continuation, Mapping) \
                or continuation.get("resume_kind") not in {
                    "STANDARD", "EXPLICIT", "NEXT_PC",
                }:
            _fail("catalog TSV post-battle resume contract欠落")
        resume_kind = str(continuation["resume_kind"])
        raw_pc = continuation.get("resume_pc")
        if resume_kind == "STANDARD":
            if raw_pc is not None:
                _fail("catalog TSV STANDARD resume PCはnull必須")
            resume_pc = "-"
        else:
            if not isinstance(raw_pc, str) \
                    or re.fullmatch(r"0x0[89][0-9A-F]{6}", raw_pc) is None:
                _fail("catalog TSV explicit/next resume PC不正")
            resume_pc = str(int(raw_pc, 16))
        raw_post_steps = continuation.get("tokens")
        if not isinstance(raw_post_steps, list) \
                or any(not isinstance(token, str) or not token
                       for token in raw_post_steps):
            _fail("catalog TSV post-battle token列不正")
        post_steps = ",".join(raw_post_steps) or "-"
        raw_chained = continuation.get("chained_battles")
        if not isinstance(raw_chained, list):
            _fail("catalog TSV chained battle列不正")
        encoded_chained: list[str] = []
        for index, battle in enumerate(raw_chained, start=2):
            if not isinstance(battle, Mapping) \
                    or battle.get("phase_index") != index:
                _fail("catalog TSV chained battle schema不正")
            encoded_chained.append("|".join((
                str(index), str(battle.get("battle_kind")),
                "-" if battle.get("trainer_id") is None
                else str(int(battle["trainer_id"])),
                str(int(str(battle["start_instruction_address"]), 16)),
                str(battle.get("resume_kind")),
                "-" if battle.get("resume_pc") is None
                else str(int(str(battle["resume_pc"]), 16)),
            )))
        chained_battles = ",".join(encoded_chained) or "-"
    main_steps = sequence.get("tokens")
    if not isinstance(main_steps, list) or not main_steps \
            or any(not isinstance(token, str) or not token
                   for token in main_steps):
        _fail("catalog TSV main input token列不正")
    fields = [
        sequence["sequence_id"],
        sequence["expected_static_branch_token"],
        str(int(sequence["visible_text_expected"])),
        "-" if sequence["silent_text_basis"] is None else _sha256(
            _stable(sequence["silent_text_basis"]).encode("utf-8")
        ),
        ",".join(main_steps), resume_kind, resume_pc, post_steps,
        chained_battles,
    ]
    if len(fields) != 9 or any(
        not isinstance(field, str) or not field
        or any(character in field for character in "@\t\n\r")
        for field in fields
    ):
        _fail("catalog TSV input sequence 9-field schema不正")
    return "@".join(fields)


def _encode_external_control(row: Mapping[str, Any]) -> str:
    kind = row["kind"]
    value = row["required_value_in_matrix_case"]
    if isinstance(value, bool):
        value_fields = [str(int(value))]
    elif isinstance(value, int):
        value_fields = [str(value)]
    elif kind == "COINS":
        value_fields = [str(value["vega"]), str(value["cfru"])]
    elif kind == "RNG":
        value_fields = [
            str(value["state"]), str(value["expected_modulo"]),
            str(value["maximum"]),
        ]
    elif kind in {"BAG_CAPACITY", "PC_CAPACITY"}:
        value_fields = [str(int(value["expected_result"])), value["layout_ref"]]
    elif kind == "PC_ITEM":
        value_fields = [str(value["required_count"]), value["layout_ref"]]
    elif kind == "PARTY_COUNT":
        value_fields = [str(value["count"]), value["party_layout_ref"]]
    elif kind == "PARTY_MINIGAME":
        value_fields = [
            str(value["mode"]), str(int(value["eligible"])),
            str(
                65535
                if value["selected_slot"] is None else value["selected_slot"]
            ),
            str(value["party_count"]), value["party_layout_ref"],
        ]
    elif kind == "RFU_SESSION":
        results = value["result_sequence"]
        value_fields = [
            value["scenario_id"], str(value["endpoint_count"]),
            str(value["activity_mode"]), str(len(results)),
            str(results[0]), str(65535 if len(results) == 1 else results[1]),
            str(value["fault_code"]),
        ]
    elif kind == "CENTER_LINK_SESSION":
        results = value["result_sequence"]
        value_fields = [
            value["scenario_id"], str(value["link_group"]),
            value["activity"], str(value["capacity_min"]),
            str(value["capacity_max"]), value["topology_policy"],
            str(value["endpoint_count"]), str(len(results)),
            str(results[0]), str(65535 if len(results) == 1 else results[1]),
            str(value["fault_code"]),
        ]
    elif kind == "DAYCARE_TRANSACTION_STATE":
        value_fields = [
            value["scenario_id"], value["layout_ref"],
            str(value["party_count"]), str(value["money"]),
            value["party_sha256"], value["daycare_sha256"],
        ]
    elif kind == "PARTY_MOVE_TRANSACTION_STATE":
        sequence = value["party_selection_sequence"]
        nullable = lambda item: str(
            _PARTY_MOVE_TRANSACTION_NULL_U16 if item is None else item
        )
        value_fields = [
            value["scenario_id"], value["layout_ref"], value["family"],
            str(value["party_count"]), value["party_sha256"],
            str(len(sequence)), str(sequence[0]),
            str(
                _PARTY_MOVE_TRANSACTION_NULL_U16
                if len(sequence) == 1 else sequence[1]
            ),
            nullable(value["selected_move_slot"]),
            nullable(value["selected_relearn_move"]),
            nullable(value["teach_outcome"]),
            nullable(value["expected_relearnable_count"]),
            "-" if value["payment_policy"] is None
            else value["payment_policy"],
            value["expected_action"],
        ]
    elif kind == "GIFT_STORAGE_TRANSACTION_STATE":
        nullable = lambda item: str(
            _GIFT_STORAGE_TRANSACTION_NULL_U16 if item is None else item
        )
        value_fields = [
            value["scenario_id"], value["layout_ref"],
            value["executor_equivalence_class"],
            str(value["party_count"]), value["party_sha256"],
            value["storage_sha256"], str(value["current_box"]),
            str(value["var_pc_box_to_send_mon"]),
            str(int(value["shown_box_was_full_message"])),
            str(value["expected_result"]),
            nullable(value["expected_original_box"]),
            nullable(value["expected_mon_box_id"]),
            nullable(value["expected_mon_box_pos"]),
            str(value["expected_var_pc_box_after"]),
            str(int(value["expected_shown_box_full_after_give"])),
            str(value["executor_representative_count"]),
            str(value["runner_exhaustive_layout_count"]),
            str(value["fixed_rng_seed"]),
            str(value["expected_rng_after"]), value["player_name_hex"],
            str(value["player_gender"]), str(value["player_trainer_id"]),
            str(value["map_section_id"]),
            str(int(value["map_header_address"], 16)),
            value["generated_mon_100_raw_hex"],
            value["generated_mon_80_raw_hex"],
            value["generated_mon_100_sha256"],
            value["generated_mon_80_sha256"],
            str(value["national_dex_number"]),
            value["pokedex_preimage_sha256"]["owned"],
            value["pokedex_preimage_sha256"]["seen"],
            value["pokedex_preimage_sha256"]["seen1"],
            value["pokedex_preimage_sha256"]["seen2"],
        ]
    elif kind == "FOSSIL_REVIVAL_STATE":
        value_fields = [
            value["scenario_id"], value["layout_ref"],
            str(value["revive_state"]), str(value["which_fossil"]),
        ]
    elif kind == "RUIN_SEAL_PREFIX":
        flag_by_id = {
            row["id"]: row["value"] for row in value["flag_values"]
        }
        seal_mask = sum(
            (1 << index) if flag_by_id[identifier] else 0
            for index, identifier in enumerate(_RUIN_SEAL_FLAGS)
        )
        binding = value["root_source_binding"]
        value_fields = [
            value["scenario_id"], value["layout_ref"],
            str(int(value["root_address"], 0)),
            str(
                _RUIN_SEAL_PREFIX_NULL_U16
                if value["first_missing_index"] is None
                else value["first_missing_index"]
            ),
            str(int(value["all_seals"])),
            str(
                _RUIN_SEAL_PREFIX_NULL_U16
                if value["completed"] is None else int(value["completed"])
            ),
            str(seal_mask),
            str(
                _RUIN_SEAL_PREFIX_NULL_U16
                if len(value["flag_values"]) == len(_RUIN_SEAL_FLAGS)
                else _RUIN_SEAL_COMPLETION_FLAG
            ),
            str(int(binding["address"], 0)),
            str(binding["byte_length"]), binding["sha256"],
        ]
    elif kind == "FACILITY_SESSION":
        payload = _facility_session_scenario_payload(
            value["family"], value["scenario_id"],
        )
        projection = _facility_transport_projection(payload)
        region_fields: list[str] = []
        for region in projection["regions"]:
            region_fields.extend((
                str(int(region["address"], 0)), str(region["size"]),
            ))
        region_fields.extend(
            ["0", "0"]
            * (_FACILITY_SESSION_MAX_REGIONS - projection["region_count"])
        )
        value_fields = [
            value["scenario_id"], value["layout_ref"], value["family"],
            "-" if value["reception_branch"] is None
            else value["reception_branch"],
            str(int(projection["root_address"], 0)),
            str(projection["manifest_ordinal"]), str(value["trace_count"]),
            projection["trace_sha256"], str(len(value["resume_points"])),
            projection["resume_points_sha256"],
            projection["fields_sha256"],
            projection["source_binding_sha256"],
            projection["initialization_sha256"],
            projection["registry_sha256"],
            str(projection["region_count"]), *region_fields,
            str(projection["source_count"]),
            str(projection["export_count"]),
            str(int(projection["prepare_fault_wrapper_required"])),
            str(projection["payload_size"]),
        ]
    elif kind == "PARTY_MOVE":
        value_fields = [
            str(value["move_id"]), str(value["expected_slot"]),
            value["party_layout_ref"],
        ]
    elif kind == "PARTY_OR_STORAGE_CAPACITY":
        value_fields = [
            str(value["expected_result"]), value["party_layout_ref"],
            value["storage_layout_ref"],
        ]
    elif kind == "REMATCH_STATE":
        value_fields = [
            str(int(value["ready"])), str(value["local_id"]),
            str(value["saveblock1_offset"]), str(value["ready_byte"]),
        ]
    elif kind == "PARTY_USABLE_FOR_DOUBLE":
        value_fields = [
            str(value["mons_state"]), str(value["party_count"]),
            value["party_layout_ref"],
        ]
    elif kind == "PLAYER_POSITION":
        value_fields = [
            str(value["x"]), str(value["y"]), str(value["group"]),
            str(value["map"]),
        ]
    elif kind == "SIGNED_RAM_SCRIPT":
        variants = {
            "ABSENT_OR_ZERO": 0, "VALID_SET_VAR_RETURN": 1,
            "CORRUPTED_CHECKSUM": 2,
        }
        value_fields = [
            str(variants[value["variant"]]),
            str(int(value["expected_dispatch"])),
            str(
                0xFFFFFFFF
                if value["expected_var_8004"] is None
                else value["expected_var_8004"]
            ),
            str(int(value["expected_ram_script_after"]
                    == "CLEARED_BY_VALIDATOR")),
            value["layout_ref"],
        ]
    elif kind == "POKEDEX_STATE":
        value_fields = [
            value["scenario_id"], str(int(value["national_enabled"])),
            str(value["kanto_seen"]), str(value["kanto_caught"]),
            str(value["national_seen"]), str(value["national_caught"]),
            str(int(value["mew_caught"])),
            str(int(value["has_all_required"])), value["layout_ref"],
        ]
    else:  # pragma: no cover - external kind normalizer is exhaustive
        raise AssertionError(kind)
    relation_arguments = {
        "EVENT_DESIGN_SOURCE_PHYSICAL_BOOL": "",
        "CERT_OWNER_FLAG_TO_MODERN_CERTIFICATION_BIT_MIRROR": "",
        "KANTO_LEAGUE_STATE_TO_LEAGUE_I_II_SAVE_MIRROR": "",
        "COMPARE_TO_VALUE": "value", "COMPARE_TO_VAR": "other_id",
        "HAS_SPACE": "quantity", "HAS_COUNT": "quantity",
        "REMOVE_ITEM_COUNT": "quantity", "TRAINERBATTLE_PRE_OR_POST":
            "trainerbattle_type", "AT_LEAST": "amount",
        "WIRELESS_MINIGAME_PARTY_ELIGIBILITY_AND_SELECTION": "",
        "NATURAL_RFU_ROLE_RESULT_SEQUENCE": "",
        _CENTER_LINK_SESSION_RELATION: "",
        _DAYCARE_TRANSACTION_RELATION: "",
        _ROUTE5_DAYCARE_TRANSACTION_RELATION: "",
        _PARTY_MOVE_TRANSACTION_RELATION: "",
        _GIFT_STORAGE_TRANSACTION_RELATION: "",
        _FOSSIL_REVIVAL_RELATION: "",
        _RUIN_SEAL_PREFIX_RELATION: "",
        _FACILITY_SESSION_RELATION: "root_address",
        "RANDOM_MODULO": "maximum_operand", "PC_HAS_COUNT": "quantity",
        "CAN_RECEIVE_MON_OR_EGG": "species_operand",
        "ADD_ITEM_CAPACITY": "quantity", "ADD_PC_ITEM_CAPACITY": "quantity",
        "WRITE_CURRENT_COINS_TO_VAR": "destination_var",
        "SAVEBLOCK1_REMATCH_BYTE_NONZERO": "save_block1_offset",
        "GET_MONS_STATE_TO_DOUBLES": "trainerbattle_type",
        "ACTUAL_PLAYER_COORDINATES_BEFORE_INTERACTION": "",
        "GET_SAVED_RAM_SCRIPT_IF_VALID_THREE_WAY": "",
        "EXACT_POKEDEX_SAVE_STATE": "",
        "EXACT_DECRYPTED_BERRY_POWDER": "",
    }
    encoded_relations = []
    for relation in row["relations"]:
        operator = relation["operator"]
        if operator in _COINS_PREDICATE_RESULT:
            encoded_relations.append(
                f"{operator}:{relation['amount']}:{relation['result_value']}"
            )
        else:
            encoded_relations.append(
                f"{operator}:"
                f"{relation.get(relation_arguments.get(operator, ''), 0)}"
            )
    relations = "+".join(encoded_relations) or "-"
    return "@".join((
        kind, str(row["id"]), ",".join(value_fields), relations,
    ))


def gift_storage_transaction_sweep_controls(
    matrix_schema: Mapping[str, Any],
) -> list[dict[str, Any]]:
    """Materialize the normalized 30-layout opcode-79 runner controls."""
    registry = matrix_schema.get("runner_fixtures")
    sweeps = matrix_schema.get("dedicated_fixture_sweeps")
    sweep = sweeps.get("GIFT_STORAGE_TRANSACTION_STATE") \
        if isinstance(sweeps, Mapping) else None
    rows = sweep.get("scenarios") if isinstance(sweep, Mapping) else None
    if not isinstance(registry, Mapping) or not isinstance(rows, list) \
            or len(rows) != len(_GIFT_STORAGE_TRANSACTION_SWEEP_MANIFEST):
        _fail("GIFT_STORAGE production sweep fixture registry欠落")
    relation = {
        "operator": _GIFT_STORAGE_TRANSACTION_RELATION,
        "state_owners": list(_GIFT_STORAGE_TRANSACTION_STATE_OWNERS),
        "executor_representatives": list(
            _GIFT_STORAGE_TRANSACTION_EXECUTOR_SCENARIO_IDS
        ),
        "runner_exhaustive_layouts": list(
            _GIFT_STORAGE_TRANSACTION_RUNNER_SCENARIO_IDS
        ),
        "model_sources": dict(_GIFT_STORAGE_TRANSACTION_MODEL_SOURCES),
    }
    normalized_relations = _normalize_control_relations(
        [relation], "GIFT_STORAGE_TRANSACTION_STATE",
        "gift_storage_transaction_sweep",
    )
    controls: list[dict[str, Any]] = []
    for ordinal, (sweep_row, layout) in enumerate(zip(
        rows, _GIFT_STORAGE_TRANSACTION_SWEEP_MANIFEST, strict=True,
    )):
        reference = sweep_row.get("fixture_key") \
            if isinstance(sweep_row, Mapping) else None
        fixture = registry.get(reference) \
            if isinstance(reference, str) else None
        if not isinstance(fixture, Mapping) \
                or sweep_row.get("scenario_id") != layout["scenario_id"] \
                or fixture.get("scenario_id") != layout["scenario_id"] \
                or _runner_fixture_key(fixture) != reference:
            _fail(
                "GIFT_STORAGE production sweep fixture/order不一致:"
                f"{ordinal}"
            )
        raw_value = {
            "scenario_id": layout["scenario_id"],
            "layout_ref": reference,
            "executor_equivalence_class": fixture[
                "executor_equivalence_class"
            ],
            "party_count": fixture["party_count"],
            "party_sha256": _sha256(bytes.fromhex(
                fixture["party_raw_hex"]
            )),
            "storage_sha256": _sha256(bytes.fromhex(
                fixture["storage_raw_hex"]
            )),
            "current_box": fixture["current_box"],
            "var_pc_box_to_send_mon": fixture[
                "var_pc_box_to_send_mon"
            ],
            "shown_box_was_full_message": fixture[
                "shown_box_was_full_message"
            ],
            "expected_result": fixture["expected_result"],
            "expected_original_box": fixture["expected_original_box"],
            "expected_mon_box_id": fixture["expected_mon_box_id"],
            "expected_mon_box_pos": fixture["expected_mon_box_pos"],
            "expected_var_pc_box_after": fixture[
                "expected_var_pc_box_after"
            ],
            "expected_shown_box_full_after_give": fixture[
                "expected_shown_box_full_after_give"
            ],
            "fixed_rng_seed": _GIFT_STORAGE_TRANSACTION_RNG_SEED,
            "expected_rng_after": (
                _GIFT_STORAGE_TRANSACTION_EXPECTED_RNG_AFTER
            ),
            "player_name_hex": _GIFT_STORAGE_TRANSACTION_PLAYER_NAME_HEX,
            "player_gender": _GIFT_STORAGE_TRANSACTION_PLAYER_GENDER,
            "player_trainer_id": (
                _GIFT_STORAGE_TRANSACTION_PLAYER_TRAINER_ID
            ),
            "map_section_id": _GIFT_STORAGE_TRANSACTION_MAP_SECTION_ID,
            "map_header_address": (
                _GIFT_STORAGE_TRANSACTION_MAP_HEADER_ADDRESS
            ),
            "generated_mon_100_raw_hex": (
                _GIFT_STORAGE_TRANSACTION_GENERATED_MON_100_HEX
            ),
            "generated_mon_80_raw_hex": (
                _GIFT_STORAGE_TRANSACTION_GENERATED_MON_80_HEX
            ),
            "generated_mon_100_sha256": (
                _GIFT_STORAGE_TRANSACTION_GENERATED_MON_100_SHA256
            ),
            "generated_mon_80_sha256": (
                _GIFT_STORAGE_TRANSACTION_GENERATED_MON_80_SHA256
            ),
            "national_dex_number": 18,
            "pokedex_preimage_sha256": {
                owner: _sha256(bytes.fromhex(fixture[
                    f"pokedex_{owner}_raw_hex"
                ]))
                for owner in ("owned", "seen", "seen1", "seen2")
            },
            "executor_representative_count": len(
                _GIFT_STORAGE_TRANSACTION_EXECUTOR_SCENARIO_IDS
            ),
            "runner_exhaustive_layout_count": len(
                _GIFT_STORAGE_TRANSACTION_RUNNER_SCENARIO_IDS
            ),
        }
        normalized_value = _normalize_control_required_value(
            "GIFT_STORAGE_TRANSACTION_STATE", raw_value, registry,
            f"gift_storage_transaction_sweep[{ordinal}]",
        )
        _validate_gift_storage_transaction_control(
            0, normalized_value, normalized_relations, None,
            f"gift_storage_transaction_sweep[{ordinal}]",
        )
        controls.append({
            "kind": "GIFT_STORAGE_TRANSACTION_STATE",
            "id": 0,
            "required_value_in_matrix_case": normalized_value,
            "relations": deepcopy(normalized_relations),
        })
    if [
        row["required_value_in_matrix_case"]["scenario_id"]
        for row in controls
    ] != list(_GIFT_STORAGE_TRANSACTION_RUNNER_SCENARIO_IDS) \
            or len({
                row["required_value_in_matrix_case"]["layout_ref"]
                for row in controls
            }) != 30:
        _fail("GIFT_STORAGE production sweep control closure不一致")
    return controls


def write_gift_storage_transaction_sweep_manifest(
    path: Path, matrix_schema: Mapping[str, Any],
) -> list[dict[str, Any]]:
    controls = gift_storage_transaction_sweep_controls(matrix_schema)
    path.write_text(
        "".join(f"{_encode_external_control(row)}\n" for row in controls),
        encoding="utf-8", newline="\n",
    )
    return controls


def _encode_internal_control(row: Mapping[str, Any]) -> str:
    capture = row["capture"]
    return "@".join((
        row.get("sequence_id", "-"), str(row["instruction_address"]),
        str(capture["before_pc"]), str(capture["after_pc"]),
        str(capture["expected_value"]), str(capture["expected_token_index"]),
        str(capture["expected_execution_ordinal"]),
        str(capture["owner_address"]), row["writer"],
    ))


def write_control_fixture_files(
    directory: Path, registry: Mapping[str, Mapping[str, Any]],
) -> None:
    directory.mkdir(parents=True, exist_ok=True)
    expected_names = {f"{digest}.bin" for digest in registry}
    if any(path.name not in expected_names for path in directory.glob("*.bin")):
        _fail("control fixture directoryに未所有binaryがあります")
    for digest, fixture in sorted(registry.items()):
        kind = fixture["fixture_kind"]
        if kind == "BAG":
            slots = [
                slot for pocket in fixture["pockets"] for slot in pocket["slots"]
            ]
            raw = b"".join(
                int(slot["item_id"]).to_bytes(2, "little")
                + int(slot["quantity"]).to_bytes(2, "little")
                for slot in slots
            )
        elif kind == "PC_ITEMS":
            raw = b"".join(
                int(slot["item_id"]).to_bytes(2, "little")
                + int(slot["quantity"]).to_bytes(2, "little")
                for slot in fixture["slots"]
            )
        elif kind in {"PARTY", "STORAGE"}:
            raw = bytes.fromhex(fixture["raw_hex"])
        elif kind == "DAYCARE_TRANSACTION_STATE":
            party = bytes.fromhex(fixture["party_raw_hex"])
            daycare = bytes.fromhex(fixture["daycare_raw_hex"])
            scenario = fixture["scenario_id"].encode("ascii")
            if len(scenario) >= _DAYCARE_TRANSACTION_SCENARIO_BYTES:
                _fail(f"control fixture {digest} daycare scenario長不一致")
            raw = (
                _DAYCARE_TRANSACTION_BINARY_MAGIC
                + bytes.fromhex(digest)
                + bytes.fromhex(_sha256(party))
                + bytes.fromhex(_sha256(daycare))
                + scenario.ljust(_DAYCARE_TRANSACTION_SCENARIO_BYTES, b"\0")
                + bytes((
                    fixture["party_count"],
                    int(fixture["pending_daycare_egg_flag"]),
                    fixture["queued_egg_count"],
                    int(fixture["pc_has_space"]),
                ))
                + int(fixture["money"]).to_bytes(4, "little")
                + party + daycare
            )
        elif kind == "PARTY_MOVE_TRANSACTION_STATE":
            party = bytes.fromhex(fixture["party_raw_hex"])
            scenario = fixture["scenario_id"].encode("ascii")
            action = fixture["expected_action"].encode("ascii")
            sequence = fixture["party_selection_sequence"]
            if len(scenario) >= _PARTY_MOVE_TRANSACTION_SCENARIO_BYTES \
                    or len(action) >= _PARTY_MOVE_TRANSACTION_ACTION_BYTES:
                _fail(
                    f"control fixture {digest} party move text長不一致"
                )
            family_code = 0 if fixture["family"] == "RELEARNER" else 1
            raw = (
                _PARTY_MOVE_TRANSACTION_BINARY_MAGIC
                + bytes.fromhex(digest)
                + hashlib.sha256(party).digest()
                + scenario.ljust(
                    _PARTY_MOVE_TRANSACTION_SCENARIO_BYTES, b"\0",
                )
                + bytes((
                    family_code,
                    fixture["party_count"],
                    len(sequence),
                    sequence[0],
                    0xFF if len(sequence) == 1 else sequence[1],
                    0xFF if fixture["selected_move_slot"] is None
                    else fixture["selected_move_slot"],
                    0xFF if fixture["teach_outcome"] is None
                    else fixture["teach_outcome"],
                    0xFF if fixture["expected_relearnable_count"] is None
                    else fixture["expected_relearnable_count"],
                ))
                + int(
                    _PARTY_MOVE_TRANSACTION_NULL_U16
                    if fixture["selected_relearn_move"] is None
                    else fixture["selected_relearn_move"]
                ).to_bytes(2, "little")
                + bytes((
                    int(fixture["payment_policy"] is not None), 0,
                ))
                + action.ljust(_PARTY_MOVE_TRANSACTION_ACTION_BYTES, b"\0")
                + party
            )
        elif kind == "GIFT_STORAGE_TRANSACTION_STATE":
            party = bytes.fromhex(fixture["party_raw_hex"])
            storage = bytes.fromhex(fixture["storage_raw_hex"])
            scenario = fixture["scenario_id"].encode("ascii")
            if len(scenario) >= _GIFT_STORAGE_TRANSACTION_SCENARIO_BYTES:
                _fail(f"control fixture {digest} gift/storage scenario長不一致")
            equivalence_codes = {
                "PARTY_SPACE": 0,
                "PC_CURRENT_BOX": 1,
                "PC_NEXT_BOX": 2,
                "PC_NEXT_BOX_WRAP": 3,
                "STORAGE_FULL": 4,
            }
            equivalence = equivalence_codes.get(
                fixture["executor_equivalence_class"]
            )
            if equivalence is None:
                _fail(f"control fixture {digest} gift/storage class不一致")
            nullable = lambda item: (
                _GIFT_STORAGE_TRANSACTION_NULL_U16
                if item is None else int(item)
            ).to_bytes(2, "little")
            raw = (
                _GIFT_STORAGE_TRANSACTION_BINARY_MAGIC
                + bytes.fromhex(digest)
                + hashlib.sha256(party).digest()
                + hashlib.sha256(storage).digest()
                + scenario.ljust(
                    _GIFT_STORAGE_TRANSACTION_SCENARIO_BYTES, b"\0",
                )
                + bytes((
                    equivalence,
                    fixture["party_count"],
                    fixture["current_box"],
                    int(fixture["shown_box_was_full_message"]),
                    fixture["expected_result"],
                    int(fixture["expected_shown_box_full_after_give"]),
                    int(fixture["lead_has_synchronize"]),
                    int(fixture["custom_creation_flags"]),
                    int(fixture["shiny_charm"]),
                    fixture["fishing_streak"],
                    fixture["player_gender"],
                    fixture["map_section_id"],
                ))
                + int(fixture["var_pc_box_to_send_mon"]).to_bytes(
                    2, "little"
                )
                + nullable(fixture["expected_original_box"])
                + nullable(fixture["expected_mon_box_id"])
                + nullable(fixture["expected_mon_box_pos"])
                + int(fixture["expected_var_pc_box_after"]).to_bytes(
                    2, "little"
                )
                # The actual opcode owns these two EWRAM outputs.  A fixed
                # preimage makes accidental host result injection detectable.
                + _GIFT_STORAGE_TRANSACTION_NULL_U16.to_bytes(2, "little")
                + _GIFT_STORAGE_TRANSACTION_NULL_U16.to_bytes(2, "little")
                + b"\0\0"
                + int(fixture["fixed_rng_seed"]).to_bytes(4, "little")
                + int(fixture["player_trainer_id"]).to_bytes(4, "little")
                + int(fixture["map_section_source_root"], 16).to_bytes(
                    4, "little"
                )
                + bytes.fromhex(fixture["player_name_hex"])
                + bytes(9)
                + party + storage
                + b"".join(bytes.fromhex(fixture[field]) for field in (
                    "pokedex_owned_raw_hex", "pokedex_seen_raw_hex",
                    "pokedex_seen1_raw_hex", "pokedex_seen2_raw_hex",
                ))
            )
        elif kind == "FOSSIL_REVIVAL_STATE":
            scenario = fixture["scenario_id"].encode("ascii")
            if len(scenario) >= _FOSSIL_REVIVAL_SCENARIO_BYTES:
                _fail(f"control fixture {digest} fossil scenario長不一致")
            prefix_codes = {
                "IDLE_AVAILABILITY": 0,
                "REVIVING_SELECTED": 1,
                "READY_SELECTED": 2,
                "ALL_REVIVED_TERMINAL": 3,
            }
            prefix_code = prefix_codes.get(fixture["prefix_class"])
            if prefix_code is None:
                _fail(f"control fixture {digest} fossil prefix class不一致")
            raw = (
                _FOSSIL_REVIVAL_BINARY_MAGIC
                + bytes.fromhex(digest)
                + bytes.fromhex(fixture["source_sha256"])
                + scenario.ljust(_FOSSIL_REVIVAL_SCENARIO_BYTES, b"\0")
                + int(fixture["revive_state"]).to_bytes(2, "little")
                + int(fixture["which_fossil"]).to_bytes(2, "little")
                + bytes((prefix_code, 0, 0, 0))
                + b"".join(
                    int(row["id"]).to_bytes(2, "little")
                    + bytes((int(row["value"]), 0))
                    for row in fixture["flags"]
                )
                + b"".join(
                    int(row["id"]).to_bytes(2, "little")
                    + int(row["count"]).to_bytes(2, "little")
                    for row in fixture["items"]
                )
            )
        elif kind == "RUIN_SEAL_PREFIX":
            scenario = fixture["scenario_id"].encode("ascii")
            if len(scenario) >= _RUIN_SEAL_PREFIX_SCENARIO_BYTES:
                _fail(f"control fixture {digest} ruin seal scenario長不一致")
            root = int(fixture["root_address"], 0)
            binding = fixture["root_source_binding"]
            flags = list(fixture["flags"])
            rows = flags + [{
                "id": _RUIN_SEAL_PREFIX_NULL_U16, "value": False,
            }] * (15 - len(flags))
            raw = (
                _RUIN_SEAL_PREFIX_BINARY_MAGIC
                + bytes.fromhex(digest)
                + bytes.fromhex(binding["sha256"])
                + scenario.ljust(_RUIN_SEAL_PREFIX_SCENARIO_BYTES, b"\0")
                + root.to_bytes(4, "little")
                + int(binding["address"], 0).to_bytes(4, "little")
                + int(binding["byte_length"]).to_bytes(4, "little")
                + int(
                    _RUIN_SEAL_PREFIX_NULL_U16
                    if fixture["first_missing_index"] is None
                    else fixture["first_missing_index"]
                ).to_bytes(2, "little")
                + len(_RUIN_SEAL_FLAGS).to_bytes(2, "little")
                + int(
                    _RUIN_SEAL_PREFIX_NULL_U16
                    if fixture["completion_flag_id"] is None
                    else fixture["completion_flag_id"]
                ).to_bytes(2, "little")
                + len(flags).to_bytes(2, "little")
                + bytes((
                    int(fixture["all_seals"]),
                    0xFF if fixture["completed"] is None
                    else int(fixture["completed"]),
                    _RUIN_SEAL_CONTROL_IDS[root], 0,
                ))
                + b"".join(
                    int(row["id"]).to_bytes(2, "little")
                    + bytes((int(row["value"]), 0))
                    for row in rows
                )
            )
        elif kind == "FACILITY_SESSION":
            payload_raw = _facility_canonical_bytes(fixture)
            projection = _facility_transport_projection(fixture)
            family_codes = {"mirage": 0, "factory": 1, "codex": 2}
            reception_codes = {None: 0, "FACTORY": 1, "CODEX": 2}
            header = bytearray(_FACILITY_SESSION_BINARY_HEADER_BYTES)
            header[:8] = _FACILITY_SESSION_BINARY_MAGIC
            header[8:40] = bytes.fromhex(digest)
            header[40:72] = bytes.fromhex(projection["registry_sha256"])
            header[72:104] = bytes.fromhex(projection["trace_sha256"])
            header[104:136] = bytes.fromhex(
                projection["resume_points_sha256"]
            )
            header[136:168] = bytes.fromhex(projection["fields_sha256"])
            header[168:200] = bytes.fromhex(
                projection["source_binding_sha256"]
            )
            header[200:232] = bytes.fromhex(
                projection["initialization_sha256"]
            )
            struct.pack_into(
                "<IIHHHBBBBBB",
                header, 232,
                len(payload_raw), int(projection["root_address"], 0),
                projection["manifest_ordinal"], fixture["trace_count"],
                len(fixture["resume_points"]),
                family_codes[fixture["family"]],
                reception_codes[fixture["reception_branch"]],
                _FACILITY_CONTROL_IDS[int(projection["root_address"], 0)],
                projection["region_count"], projection["source_count"],
                projection["export_count"],
            )
            header[252] = int(
                projection["prepare_fault_wrapper_required"]
            )
            for index, region in enumerate(projection["regions"]):
                struct.pack_into(
                    "<II", header, 256 + index * 8,
                    int(region["address"], 0), region["size"],
                )
            raw = bytes(header) + payload_raw
        elif kind == "SIGNED_RAM_SCRIPT":
            raw = (
                int(fixture["wonder_card_crc"]).to_bytes(4, "little")
                + bytes.fromhex(fixture["wonder_card_raw_hex"])
                + bytes.fromhex(fixture["ram_script_raw_hex"])
            )
        elif kind == "POKEDEX_LAYOUT":
            raw = (
                bytes((fixture["national_magic"],))
                + int(fixture["national_var"]).to_bytes(2, "little")
                + bytes((int(fixture["national_flag"]),))
                + bytes.fromhex(fixture["owned_hex"])
                + bytes.fromhex(fixture["seen_hex"])
                + bytes.fromhex(fixture["seen1_hex"])
                + bytes.fromhex(fixture["seen2_hex"])
            )
        else:  # pragma: no cover - registry normalizer is exhaustive
            raise AssertionError(kind)
        expected_size = (
            _FACILITY_SESSION_BINARY_HEADER_BYTES
            + len(_facility_canonical_bytes(fixture))
        ) if kind == "FACILITY_SESSION" else {
            "BAG": 186 * 4, "PC_ITEMS": 30 * 4,
            "PARTY": 600, "STORAGE": 0x83D0,
            "SIGNED_RAM_SCRIPT": 4 + 0x14C + 0x3EC,
            "POKEDEX_LAYOUT": 4 + 4 * _POKEDEX_BITMAP_BYTES,
            "DAYCARE_TRANSACTION_STATE": (
                _DAYCARE_TRANSACTION_BINARY_HEADER_BYTES
                + _DAYCARE_TRANSACTION_PARTY_BYTES
                + _DAYCARE_TRANSACTION_DAYCARE_BYTES
            ),
            "PARTY_MOVE_TRANSACTION_STATE": (
                _PARTY_MOVE_TRANSACTION_BINARY_HEADER_BYTES
                + _PARTY_MOVE_TRANSACTION_PARTY_BYTES
            ),
            "GIFT_STORAGE_TRANSACTION_STATE": (
                _GIFT_STORAGE_TRANSACTION_BINARY_HEADER_BYTES
                + _GIFT_STORAGE_TRANSACTION_PARTY_BYTES
                + _GIFT_STORAGE_TRANSACTION_STORAGE_BYTES
                + 4 * _GIFT_STORAGE_TRANSACTION_POKEDEX_BYTES
            ),
            "FOSSIL_REVIVAL_STATE": _FOSSIL_REVIVAL_BINARY_BYTES,
            "RUIN_SEAL_PREFIX": _RUIN_SEAL_PREFIX_BINARY_BYTES,
        }[kind]
        if len(raw) != expected_size:
            _fail(f"control fixture {digest} binary size不一致")
        destination = directory / f"{digest}.bin"
        destination.write_bytes(raw)


