def _none_runtime_position_control() -> dict[str, Any]:
    return {"kind": "NONE", "id": 0, "value": False}


def _validate_trainer_tower_runtime_map_lifecycle(
    value: Any, *, group: int, map_number: int,
    expected_object: Sequence[int], label: str,
) -> dict[str, Any]:
    if not isinstance(value, Mapping):
        _fail(f"{label} Trainer Tower lifecycle schema不一致")
    movement_type = value.get("expected_movement_type")
    expected = {
        "kind": "TRAINER_TOWER_ON_TRANSITION",
        "root": "0x081A96EA",
        "map_script_tag": _TRAINER_TOWER_LIFECYCLE_TAG,
        "layout_id": _TRAINER_TOWER_LAYOUTS.get(map_number),
        "expected_object": list(expected_object),
        "expected_movement_type": movement_type,
        "local_fallback_precondition": {
            "save": _TRAINER_TOWER_LOCAL_FALLBACK_SAVE,
            "runtime_state": _TRAINER_TOWER_RUNTIME_STATE,
        },
    }
    if group != 2 or map_number not in _TRAINER_TOWER_LAYOUTS \
            or not isinstance(movement_type, int) \
            or isinstance(movement_type, bool) \
            or not 0 <= movement_type <= 255 \
            or dict(value) != expected:
        _fail(f"{label} Trainer Tower lifecycle exact mapping不一致")
    return deepcopy(dict(value))


def _validate_runtime_position_control(
    value: Any, *, required: bool, label: str,
    state: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    if value is None:
        value = _none_runtime_position_control()
    if not isinstance(value, Mapping) or set(value) != {"kind", "id", "value"}:
        _fail(f"{label} runtime-position control schema不一致")
    kind = value["kind"]
    control_id = _int(value["id"], f"{label}.control.id", 0xFFFF)
    control_value = value["value"]
    if not isinstance(control_value, bool):
        _fail(f"{label} runtime-position control value不正")
    normalized = {"kind": kind, "id": control_id, "value": control_value}
    if not required:
        if normalized != _none_runtime_position_control():
            _fail(f"{label} 非条件caseへruntime-position control過剰")
        return normalized
    if kind not in {"FLAG", "NATIONAL_DEX"}:
        _fail(f"{label} 条件付きcaseのruntime-position control欠落")
    if kind == "NATIONAL_DEX" and control_id != 0:
        _fail(f"{label} NATIONAL_DEX control ID不正")
    if kind == "FLAG" and control_id == 0:
        _fail(f"{label} FLAG control ID不正")
    if state is not None:
        flags = {
            int(row["id"]): bool(row["value"])
            for row in state.get("flags", [])
        }
        variables = {
            int(row["id"]): int(row["value"])
            for row in state.get("vars", [])
        }
        if kind == "FLAG":
            if flags.get(control_id) is not control_value:
                _fail(f"{label} FLAG control/state不一致")
        elif flags.get(0x0840) is not control_value \
                or variables.get(0x404E) != (0x6258 if control_value else 0):
            _fail(f"{label} NATIONAL_DEX control/state不一致")
    return normalized

_RUNTIME_POSITION_PRODUCER_KEYS = {
    "kind", "root", "source_group", "source_map", "source_warp",
    "predecessor_x", "predecessor_y", "trigger_x", "trigger_y",
    "trigger_key", "destination_group", "destination_map",
    "destination_warp", "arrival_x", "arrival_y", "record_address",
    "map_script_tag", "event_case_id", "source_provenance",
}

_RUNTIME_POSITION_GBA_BASE = 0x08000000
_RUNTIME_POSITION_MAP_GROUPS_POINTER_SITE = 0x00054B0C
_RUNTIME_POSITION_MAP_LAYOUTS_POINTER_SITE = 0x00054A54


def _runtime_position_rom_offset(
    rom: bytes, address: int, size: int, label: str,
) -> int:
    """Resolve one final-ROM pointer without trusting generated metadata."""
    if isinstance(address, bool) or not isinstance(address, int) \
            or isinstance(size, bool) or not isinstance(size, int) \
            or size < 0:
        _fail(f"{label} ROM address/size不正")
    offset = address - _RUNTIME_POSITION_GBA_BASE
    if offset < 0 or offset + size > len(rom):
        _fail(f"{label} final ROM範囲外:0x{address:08X}+{size}")
    return offset


def _runtime_position_rom_u32_offset(
    rom: bytes, offset: int, label: str,
) -> int:
    if isinstance(offset, bool) or not isinstance(offset, int) \
            or offset < 0 or offset + 4 > len(rom):
        _fail(f"{label} final ROM offset範囲外:{offset!r}")
    return struct.unpack_from("<I", rom, offset)[0]


def _runtime_position_map_header_offset(
    rom: bytes, group: int, map_number: int,
) -> int:
    """Decode gMapGroups -> group table -> map header from the final ROM."""
    root_pointer = _runtime_position_rom_u32_offset(
        rom, _RUNTIME_POSITION_MAP_GROUPS_POINTER_SITE,
        "runtime-position gMapGroups pointer",
    )
    root = _runtime_position_rom_offset(
        rom, root_pointer, (group + 1) * 4,
        "runtime-position gMapGroups",
    )
    group_pointer = _runtime_position_rom_u32_offset(
        rom, root + group * 4,
        f"runtime-position map group {group}",
    )
    group_offset = _runtime_position_rom_offset(
        rom, group_pointer, (map_number + 1) * 4,
        f"runtime-position map group {group} table",
    )
    header_pointer = _runtime_position_rom_u32_offset(
        rom, group_offset + map_number * 4,
        f"runtime-position map header {group}/{map_number}",
    )
    return _runtime_position_rom_offset(
        rom, header_pointer, 0x1C,
        f"runtime-position map header {group}/{map_number}",
    )


def _runtime_position_layout_address(
    rom: bytes, group: int, map_number: int, *, layout_id: int | None,
) -> int:
    """Resolve the effective field-engine layout, including gMapLayouts."""
    if layout_id is None:
        header = _runtime_position_map_header_offset(rom, group, map_number)
        address = _runtime_position_rom_u32_offset(
            rom, header, f"runtime-position layout {group}/{map_number}",
        )
    else:
        if isinstance(layout_id, bool) or not isinstance(layout_id, int) \
                or not 1 <= layout_id <= 0xFFFF:
            _fail(f"runtime-position layout ID不正:{layout_id!r}")
        table_pointer = _runtime_position_rom_u32_offset(
            rom, _RUNTIME_POSITION_MAP_LAYOUTS_POINTER_SITE,
            "runtime-position gMapLayouts pointer",
        )
        table = _runtime_position_rom_offset(
            rom, table_pointer, layout_id * 4,
            f"runtime-position gMapLayouts[{layout_id}] table",
        )
        address = _runtime_position_rom_u32_offset(
            rom, table + (layout_id - 1) * 4,
            f"runtime-position gMapLayouts[{layout_id}]",
        )
    _runtime_position_rom_offset(
        rom, address, 0x18,
        f"runtime-position layout {group}/{map_number}",
    )
    return address


def _runtime_position_engine_geometry(
    rom: bytes, *, group: int, map_number: int, start: Sequence[int],
    layout_id: int | None,
) -> dict[str, Any]:
    """Rebuild the exact teleport-start provenance from the effective layout."""
    point = _pair(list(start), "runtime-position ENGINE start")
    layout_address = _runtime_position_layout_address(
        rom, group, map_number, layout_id=layout_id,
    )
    layout = _runtime_position_rom_offset(
        rom, layout_address, 0x18,
        f"runtime-position layout {group}/{map_number}",
    )
    width = _runtime_position_rom_u32_offset(
        rom, layout, f"runtime-position width {group}/{map_number}",
    )
    height = _runtime_position_rom_u32_offset(
        rom, layout + 4, f"runtime-position height {group}/{map_number}",
    )
    if not 0 < width <= 1024 or not 0 < height <= 1024 \
            or width * height > 0x100000:
        _fail(
            "runtime-position layout dimensions不正:"
            f"{group}/{map_number}:{width}x{height}"
        )
    x, y = point
    if not 0 <= x < width or not 0 <= y < height:
        _fail(
            "runtime-position ENGINE startが実効layout範囲外:"
            f"{group}/{map_number}:{point}/{width}x{height}"
        )
    blocks_pointer = _runtime_position_rom_u32_offset(
        rom, layout + 12, f"runtime-position blocks {group}/{map_number}",
    )
    block_address = blocks_pointer + (y * width + x) * 2
    block_offset = _runtime_position_rom_offset(
        rom, block_address, 2,
        f"runtime-position block {group}/{map_number}:{x},{y}",
    )
    block_raw = rom[block_offset:block_offset + 2]
    block = int.from_bytes(block_raw, "little")
    collision = (block >> 10) & 3
    if collision != 0:
        _fail(
            "runtime-position ENGINE startがcollision-zeroでありません:"
            f"{group}/{map_number}:{point}:collision={collision}"
        )
    return {
        "layout_address": f"0x{layout_address:08X}",
        "block_address": f"0x{block_address:08X}",
        "block_raw_hex": block_raw.hex(),
        "block_raw_sha256": _sha256(block_raw),
        "base_collision": collision,
        "base_elevation": (block >> 12) & 0xF,
    }


def _runtime_position_engine_layout_id(
    row: Mapping[str, Any], contract: Mapping[str, Any], *,
    group: int, map_number: int, label: str,
) -> int | None:
    """Select Dunsparce Tunnel's runtime layout from the physical control."""
    variant = contract.get("runtime_position_variant")
    if variant is None:
        variant = row.get("runtime_position_variant")
    if (group, map_number) != (2, 34):
        return None
    raw_control = contract.get("runtime_position_control")
    if raw_control is None:
        raw_control = row.get("runtime_position_control")
    control = _validate_runtime_position_control(
        raw_control, required=True, label=f"{label}.layout-control",
    )
    if control["kind"] != "NATIONAL_DEX" or control["id"] != 0:
        _fail(f"{label} Dunsparce Tunnel layout control不一致")
    expected_variant = "STATIC" if control["value"] else "RUNTIME"
    if variant is None:
        # The calibration catalog intentionally exercises only the authored
        # RUNTIME member, but retains both members in its normalized legacy
        # contract rather than adding a second top-level variant owner.
        legacy = row.get("runtime_position_state_contract")
        variants = legacy.get("variants") \
            if isinstance(legacy, Mapping) else None
        legacy_control = legacy.get("control") \
            if isinstance(legacy, Mapping) else None
        expected_value_key = (
            "static_value" if expected_variant == "STATIC"
            else "runtime_value"
        )
        if not isinstance(legacy_control, Mapping) \
                or legacy_control.get("kind") != control["kind"] \
                or legacy_control.get("id") != control["id"] \
                or legacy_control.get(expected_value_key) \
                    is not control["value"] \
                or not isinstance(variants, list) \
                or len(variants) != 2 \
                or {
                    item.get("variant_id")
                    for item in variants if isinstance(item, Mapping)
                } != {"STATIC", "RUNTIME"}:
            _fail(
                f"{label} Dunsparce Tunnel runtime-position variant欠落"
            )
        selected = next(
            item for item in variants
            if item.get("variant_id") == expected_variant
        )
        if selected.get("interaction_execution") \
                != row.get("interaction_execution"):
            _fail(f"{label} legacy runtime-position variant二重正本不一致")
        variant = {"variant_id": expected_variant, "control": control}
    if not isinstance(variant, Mapping) \
            or set(variant) != {"variant_id", "control"}:
        _fail(f"{label} Dunsparce Tunnel runtime-position variant欠落")
    if variant.get("variant_id") != expected_variant:
        _fail(f"{label} runtime-position variant/control不一致")
    if _validate_runtime_position_control(
        variant.get("control"), required=True,
        label=f"{label}.layout-variant-control",
    ) != control:
        _fail(f"{label} runtime-position variant control二重正本不一致")
    return 319 if expected_variant == "STATIC" else 318


def _none_runtime_position_producer(
    group: int, map_number: int,
) -> dict[str, Any]:
    return {
        "kind": "NONE", "root": 0,
        "source_group": 0, "source_map": 0, "source_warp": 255,
        "predecessor_x": 0, "predecessor_y": 0,
        "trigger_x": 0, "trigger_y": 0, "trigger_key": 0,
        "destination_group": group, "destination_map": map_number,
        "destination_warp": 255,
        "arrival_x": 0, "arrival_y": 0, "record_address": 0,
        "map_script_tag": 0, "event_case_id": None,
        "source_provenance": None,
    }


def _catalog_template_position(
    expected_raw_hex: Any, label: str,
) -> list[int]:
    if not isinstance(expected_raw_hex, str) \
            or re.fullmatch(r"[0-9A-F]{48}", expected_raw_hex) is None:
        _fail(f"{label} independent ObjectEventTemplate raw欠落")
    raw = bytes.fromhex(expected_raw_hex)
    return [
        int.from_bytes(raw[4:6], "little", signed=True),
        int.from_bytes(raw[6:8], "little", signed=True),
    ]


def _validate_runtime_position_producer(
    producer: Any, *, group: int, map_number: int,
    required: bool, label: str, rom_raw: bytes | None = None,
    rom_sha256: str | None = None,
    expected_engine_start: Sequence[int] | None = None,
    engine_layout_id: int | None = None,
) -> dict[str, Any]:
    if not isinstance(producer, Mapping) \
            or set(producer) != _RUNTIME_POSITION_PRODUCER_KEYS:
        _fail(f"{label} runtime-position producer schema不一致")
    normalized = deepcopy(dict(producer))
    kind = normalized["kind"]
    if kind not in {
        "NONE", "STOCK_WARP", "STOCK_CONNECTION", "ENGINE_TELEPORT",
        "TRAINER_TOWER_ON_TRANSITION",
    }:
        _fail(f"{label} runtime-position producer kind不正:{kind!r}")
    numeric_limits = {
        "root": 0x09FFFFFF,
        "source_group": 255, "source_map": 255, "source_warp": 255,
        "predecessor_x": 65535, "predecessor_y": 65535,
        "trigger_x": 65535, "trigger_y": 65535,
        "trigger_key": 1023,
        "destination_group": 255, "destination_map": 255,
        "destination_warp": 255,
        "arrival_x": 65535, "arrival_y": 65535,
        "record_address": 0x09FFFFFF, "map_script_tag": 255,
    }
    for key, limit in numeric_limits.items():
        normalized[key] = _int(
            normalized[key], f"{label}.runtime_position_producer.{key}", limit,
        )
    if (normalized["destination_group"], normalized["destination_map"]) \
            != (group, map_number):
        _fail(f"{label} runtime-position destination map不一致")
    if kind == "NONE":
        expected = _none_runtime_position_producer(group, map_number)
        if normalized != expected or required:
            _fail(f"{label} NONE runtime-position sentinel/条件判定不一致")
        return normalized
    if not required:
        _fail(f"{label} 非条件ownerへruntime-position producer過剰")
    if kind == "TRAINER_TOWER_ON_TRANSITION":
        expected_start = None if expected_engine_start is None else _pair(
            list(expected_engine_start), f"{label}.expected_lifecycle_start",
        )
        provenance = normalized["source_provenance"]
        provenance_rom_sha256 = (
            rom_sha256 if rom_sha256 is not None
            else provenance.get("rom_sha256")
            if isinstance(provenance, Mapping) else None
        )
        provenance_owner_id = provenance.get("owner_id") \
            if isinstance(provenance, Mapping) else None
        expected_provenance = {
            "rom_sha256": provenance_rom_sha256,
            "owner_id": provenance_owner_id,
            "kind": "TRAINER_TOWER_ON_TRANSITION",
            "root": "0x081A96EA",
            "map_script_tag": _TRAINER_TOWER_LIFECYCLE_TAG,
            "local_fallback_precondition": {
                "save": _TRAINER_TOWER_LOCAL_FALLBACK_SAVE,
                "runtime_state": _TRAINER_TOWER_RUNTIME_STATE,
            },
        }
        actual_start = [normalized["arrival_x"], normalized["arrival_y"]]
        if group != 2 or map_number not in _TRAINER_TOWER_LAYOUTS \
                or normalized["root"] != _TRAINER_TOWER_LIFECYCLE_ROOT \
                or normalized["map_script_tag"] \
                    != _TRAINER_TOWER_LIFECYCLE_TAG \
                or normalized["source_group"] != 0 \
                or normalized["source_map"] != 0 \
                or normalized["source_warp"] != 255 \
                or normalized["predecessor_x"] != normalized["trigger_x"] \
                or normalized["predecessor_y"] != normalized["trigger_y"] \
                or normalized["trigger_key"] != 0 \
                or normalized["destination_warp"] != 255 \
                or actual_start != [
                    normalized["trigger_x"], normalized["trigger_y"],
                ] \
                or normalized["record_address"] != 0 \
                or not isinstance(normalized["event_case_id"], str) \
                or _CASE_ID.fullmatch(normalized["event_case_id"]) is None \
                or not isinstance(provenance_rom_sha256, str) \
                or _RAW_SHA256.fullmatch(provenance_rom_sha256) is None \
                or not isinstance(provenance_owner_id, str) \
                or re.fullmatch(
                    rf"OBJECT:002/{map_number:03d}:[0-9]{{3}}",
                    provenance_owner_id,
                ) is None \
                or provenance != expected_provenance \
                or expected_start is not None and actual_start != expected_start:
            _fail(f"{label} Trainer Tower OnTransition producer不一致")
        return normalized
    expected_control = _RUNTIME_POSITION_EXPECTED_CONTROLS.get(
        (group, map_number),
    )
    expected_kind = (
        "ENGINE_TELEPORT" if (group, map_number) in {(2, 34), (2, 35)}
        else "STOCK_WARP"
    )
    if expected_control is None \
            or normalized["root"] != int(expected_control["root"]) \
            or kind != expected_kind:
        _fail(f"{label} runtime-position exact root/producer kind不一致")
    if normalized["map_script_tag"] != 3 \
            or not 0x08000000 <= normalized["root"] < 0x0A000000 \
            or not isinstance(normalized["event_case_id"], str) \
            or _CASE_ID.fullmatch(normalized["event_case_id"]) is None \
            or not isinstance(normalized["source_provenance"], Mapping) \
            or not normalized["source_provenance"]:
        _fail(f"{label} dynamic MAP tag3 producer根拠不正")
    provenance = normalized["source_provenance"]
    if rom_sha256 is not None \
            and provenance.get("rom_sha256") != rom_sha256:
        _fail(f"{label} runtime-position producer ROM provenance不一致")
    if kind == "ENGINE_TELEPORT":
        expected_start = None if expected_engine_start is None else _pair(
            list(expected_engine_start), f"{label}.expected_engine_start",
        )
        if normalized["source_group"] != 0 \
                or normalized["source_map"] != 0 \
                or normalized["source_warp"] != 255 \
                or normalized["predecessor_x"] != normalized["trigger_x"] \
                or normalized["predecessor_y"] != normalized["trigger_y"] \
                or normalized["trigger_key"] != 0 \
                or normalized["destination_warp"] != 255 \
                or normalized["arrival_x"] != normalized["trigger_x"] \
                or normalized["arrival_y"] != normalized["trigger_y"] \
                or normalized["record_address"] != 0 \
                or provenance.get("incoming_usable_zero_reason_bound") \
                    is not True:
            _fail(f"{label} ENGINE_TELEPORT producer sentinel不一致")
        actual_start = [normalized["arrival_x"], normalized["arrival_y"]]
        if expected_start is not None and actual_start != expected_start:
            _fail(f"{label} ENGINE_TELEPORT per-case start不一致")
        stock_scan = provenance.get("foreign_stock_warp_scan")
        if not isinstance(stock_scan, Mapping) \
                or stock_scan.get("usable_stock_warp_count") != 0 \
                or provenance.get("usable_stock_connection_count") != 0:
            _fail(f"{label} ENGINE_TELEPORTはstock incoming存在時に禁止")
        if rom_raw is not None:
            exact_geometry = _runtime_position_engine_geometry(
                rom_raw, group=group, map_number=map_number,
                start=actual_start, layout_id=engine_layout_id,
            )
            if any(
                provenance.get(key) != expected
                for key, expected in exact_geometry.items()
            ):
                _fail(
                    f"{label} ENGINE_TELEPORT final ROM/layout provenance不一致"
                )
        elif engine_layout_id is not None:
            _fail(f"{label} ENGINE layout IDにfinal ROM欠落")
        return normalized
    deltas = {
        KEYS["UP"]: (0, -1), KEYS["DOWN"]: (0, 1),
        KEYS["LEFT"]: (-1, 0), KEYS["RIGHT"]: (1, 0),
    }
    delta = deltas.get(normalized["trigger_key"])
    if delta is None or (
        normalized["predecessor_x"] + delta[0],
        normalized["predecessor_y"] + delta[1],
    ) != (normalized["trigger_x"], normalized["trigger_y"]):
        _fail(f"{label} runtime-position physical step geometry不一致")
    if not 0x08000000 <= normalized["record_address"] < 0x0A000000:
        _fail(f"{label} runtime-position record address範囲外")
    if kind == "STOCK_WARP":
        if normalized["source_warp"] == 255 \
                or normalized["destination_warp"] == 255:
            _fail(f"{label} STOCK_WARP ID欠落")
    elif normalized["source_warp"] != 255 \
            or normalized["destination_warp"] != 255:
        _fail(f"{label} STOCK_CONNECTION warp sentinel不一致")
    address = normalized["record_address"]
    raw_hex = provenance.get("record_raw_hex")
    raw_sha = provenance.get("record_raw_sha256")
    if provenance.get("record_address") != f"0x{address:08X}" \
            or not isinstance(raw_hex, str):
        _fail(f"{label} runtime-position record provenance欠落")
    try:
        record_raw = bytes.fromhex(raw_hex)
    except ValueError:
        _fail(f"{label} runtime-position record raw不正")
    expected_size = 8 if kind == "STOCK_WARP" else 12
    if len(record_raw) != expected_size or _sha256(record_raw) != raw_sha:
        _fail(f"{label} runtime-position record hash/size不一致")
    if rom_raw is not None:
        offset = address - 0x08000000
        if rom_raw[offset:offset + expected_size] != record_raw:
            _fail(f"{label} runtime-position record final ROM不一致")
    return normalized


def _runtime_position_candidate(
    row: Mapping[str, Any], *, case_id: str,
) -> dict[str, Any] | None:
    effective, _common = _event_effective_trigger(row["trigger_path"])
    if effective.get("kind") != "MAP_TRANSITION_LOAD" \
            or effective.get("map_script_tag") != 3:
        return None
    resume, _outer_kind, seed_kind, seed = _event_map_actual_seed(
        effective, case_id,
    )
    if resume:
        return None
    root = effective["root_pc"]
    provenance = deepcopy(dict(seed["source_provenance"]))
    if seed_kind == "engine_teleport":
        start = seed["start_tile"]
        destination = seed["destination"]
        return {
            "kind": "ENGINE_TELEPORT", "root": root,
            "source_group": 0, "source_map": 0, "source_warp": 255,
            "predecessor_x": start["x"], "predecessor_y": start["y"],
            "trigger_x": start["x"], "trigger_y": start["y"],
            "trigger_key": 0,
            "destination_group": destination["group"],
            "destination_map": destination["map"],
            "destination_warp": 255,
            "arrival_x": start["x"], "arrival_y": start["y"],
            "record_address": 0, "map_script_tag": 3,
            "event_case_id": case_id, "source_provenance": provenance,
        }
    if seed_kind not in {"stock_warp", "stock_connection"}:
        _fail(f"event {case_id} runtime-position seed未知:{seed_kind}")
    source = seed["source"]
    destination = seed["destination"]
    predecessor = seed["predecessor_tile"]
    trigger = seed["trigger_tile"]
    arrival = seed["arrival_tile"]
    return {
        "kind": "STOCK_WARP" if seed_kind == "stock_warp"
            else "STOCK_CONNECTION",
        "root": root,
        "source_group": source["group"], "source_map": source["map"],
        "source_warp": source.get("warp_id", 255),
        "predecessor_x": predecessor["x"],
        "predecessor_y": predecessor["y"],
        "trigger_x": trigger["x"], "trigger_y": trigger["y"],
        "trigger_key": KEYS[seed["trigger_key"]],
        "destination_group": destination["group"],
        "destination_map": destination["map"],
        "destination_warp": destination.get("warp_id", 255),
        "arrival_x": arrival["x"], "arrival_y": arrival["y"],
        "record_address": seed["connection_or_warp_record_address"],
        "map_script_tag": 3, "event_case_id": case_id,
        "source_provenance": provenance,
    }


def _validate_trainer_tower_lifecycle_rom_binding(
    lifecycle: Any, *, owner_key: str, expected_template_raw_hex: Any,
    rom_raw: bytes, label: str,
) -> dict[str, Any]:
    match = re.fullmatch(r"OBJECT:002/([0-9]{3}):([0-9]{3})", owner_key)
    if match is None:
        _fail(f"{label} Trainer Tower owner identity不一致")
    map_number = int(match.group(1), 10)
    if not isinstance(expected_template_raw_hex, str) \
            or re.fullmatch(r"[0-9A-F]{48}", expected_template_raw_hex) is None:
        _fail(f"{label} Trainer Tower template preimage欠落")
    raw = bytes.fromhex(expected_template_raw_hex)
    static_object = [
        int.from_bytes(raw[4:6], "little", signed=True),
        int.from_bytes(raw[6:8], "little", signed=True),
    ]
    expected_object, expected_movement = (
        _TRAINER_TOWER_VISIBLE_RUNTIME.get(
            owner_key, (static_object, raw[9]),
        )
    )
    checked = _validate_trainer_tower_runtime_map_lifecycle(
        lifecycle, group=2, map_number=map_number,
        expected_object=expected_object, label=label,
    )
    if checked["expected_movement_type"] != expected_movement:
        _fail(f"{label} Trainer Tower movement/source preimage不一致")
    spans = (
        (
            _TRAINER_TOWER_LIFECYCLE_ROOT,
            _TRAINER_TOWER_TRANSITION_SIZE,
            _TRAINER_TOWER_TRANSITION_SHA256,
            "OnTransition",
        ),
        (
            _TRAINER_TOWER_LOCAL_BLOB_ADDRESS,
            _TRAINER_TOWER_LOCAL_BLOB_SIZE,
            _TRAINER_TOWER_LOCAL_BLOB_SHA256,
            "local fallback blob",
        ),
    )
    for address, size, digest, span_label in spans:
        offset = _runtime_position_rom_offset(
            rom_raw, address, size, f"{label} Trainer Tower {span_label}",
        )
        if _sha256(rom_raw[offset:offset + size]) != digest:
            _fail(f"{label} Trainer Tower {span_label} ROM SHA不一致")
    return checked


def attach_catalog_runtime_position_producers(
    rows: Mapping[str, Mapping[str, Any]],
    event_rows: Mapping[str, Mapping[str, Any]], *,
    rom_raw: bytes, rom_sha256: str,
) -> dict[str, dict[str, Any]]:
    """Bind dynamically positioned NPCs to a real incoming map-load path."""
    if not isinstance(rom_raw, bytes) \
            or not isinstance(rom_sha256, str) \
            or _RAW_SHA256.fullmatch(rom_sha256) is None \
            or _sha256(rom_raw) != rom_sha256:
        _fail("catalog runtime-position final ROM SHA不一致")
    candidates_by_map: dict[tuple[int, int], list[dict[str, Any]]] = {}
    for case_id, event_row in sorted(event_rows.items()):
        candidate = _runtime_position_candidate(event_row, case_id=case_id)
        if candidate is None:
            continue
        key = (
            candidate["destination_group"],
            candidate["destination_map"],
        )
        candidates_by_map.setdefault(key, []).append(candidate)
    result: dict[str, dict[str, Any]] = {}
    for case_id, source_row in rows.items():
        row = deepcopy(dict(source_row))
        interaction = row.get("interaction")
        if isinstance(interaction, Mapping):
            contract_source = interaction
            group = _int(interaction.get("group"), f"{case_id}.group", 255)
            map_number = _int(
                interaction.get("map"), f"{case_id}.map", 255,
            )
            object_position = _pair(
                interaction.get("object"), f"{case_id}.object",
            )
            expected_raw = interaction.get("expected_template_raw_hex")
        else:
            contract_source = row
            group = _int(row.get("group"), f"{case_id}.group", 255)
            map_number = _int(row.get("map"), f"{case_id}.map", 255)
            object_position = _pair(
                row.get("object"), f"{case_id}.object",
            )
            expected_raw = row.get("expected_template_raw_hex")
        owner_key = row.get("owner_key")
        if not isinstance(owner_key, str) or not owner_key.startswith("OBJECT:"):
            producer = _none_runtime_position_producer(group, map_number)
            producer_required = False
        else:
            template_position = _catalog_template_position(
                expected_raw, f"catalog {case_id}",
            )
            coordinate_dynamic = template_position != object_position
            producer_required = bool(
                contract_source.get(
                    "runtime_position_map_load_required", False,
                )
            )
            if coordinate_dynamic and not producer_required:
                _fail(
                    f"catalog {case_id} runtime座標にmap-load契約欠落"
                )
            if not producer_required:
                producer = _none_runtime_position_producer(group, map_number)
            else:
                lifecycle = row.get("runtime_map_lifecycle")
                if isinstance(lifecycle, Mapping) \
                        and lifecycle.get("kind") \
                            == "TRAINER_TOWER_ON_TRANSITION":
                    lifecycle = _validate_trainer_tower_lifecycle_rom_binding(
                        lifecycle, owner_key=owner_key,
                        expected_template_raw_hex=expected_raw,
                        rom_raw=rom_raw, label=f"catalog {case_id}",
                    )
                    start = _pair(
                        contract_source.get("start"),
                        f"catalog {case_id}.lifecycle.start",
                    )
                    producer = {
                        "kind": "TRAINER_TOWER_ON_TRANSITION",
                        "root": _TRAINER_TOWER_LIFECYCLE_ROOT,
                        "source_group": 0, "source_map": 0,
                        "source_warp": 255,
                        "predecessor_x": start[0], "predecessor_y": start[1],
                        "trigger_x": start[0], "trigger_y": start[1],
                        "trigger_key": 0,
                        "destination_group": group,
                        "destination_map": map_number,
                        "destination_warp": 255,
                        "arrival_x": start[0], "arrival_y": start[1],
                        "record_address": 0,
                        "map_script_tag": _TRAINER_TOWER_LIFECYCLE_TAG,
                        "event_case_id": case_id,
                        "source_provenance": {
                            "rom_sha256": rom_sha256,
                            "owner_id": row["owner_key"],
                            "kind": "TRAINER_TOWER_ON_TRANSITION",
                            "root": "0x081A96EA",
                            "map_script_tag": _TRAINER_TOWER_LIFECYCLE_TAG,
                            "local_fallback_precondition": deepcopy(
                                lifecycle["local_fallback_precondition"]
                            ),
                        },
                    }
                else:
                    candidates = candidates_by_map.get((group, map_number), [])
                    if not candidates:
                        _fail(
                            f"catalog {case_id} dynamic objectの実map-load producer欠落"
                        )
                    roots = {candidate["root"] for candidate in candidates}
                    if len(roots) != 1:
                        _fail(
                            f"catalog {case_id} dynamic objectのtag3 root非一意:"
                            f"{[f'0x{root:08X}' for root in sorted(roots)]}"
                        )
                    order = {"STOCK_WARP": 0, "STOCK_CONNECTION": 1,
                             "ENGINE_TELEPORT": 2}
                    producer = deepcopy(min(candidates, key=lambda candidate: (
                        order[candidate["kind"]], candidate["source_group"],
                        candidate["source_map"], candidate["source_warp"],
                        candidate["predecessor_y"], candidate["predecessor_x"],
                        candidate["trigger_y"], candidate["trigger_x"],
                        candidate["destination_warp"],
                        candidate["record_address"], candidate["event_case_id"],
                    )))
        engine_start: list[int] | None = None
        engine_layout_id: int | None = None
        if producer["kind"] == "ENGINE_TELEPORT":
            raw_start = contract_source.get("start")
            if raw_start is None:
                legacy_execution = contract_source.get(
                    "interaction_execution",
                )
                if isinstance(legacy_execution, Mapping):
                    raw_start = legacy_execution.get("start")
            engine_start = _pair(
                raw_start,
                f"catalog {case_id}.interaction.start",
            )
            engine_layout_id = _runtime_position_engine_layout_id(
                row, contract_source, group=group, map_number=map_number,
                label=f"catalog {case_id}",
            )
            for x_key, y_key in (
                ("predecessor_x", "predecessor_y"),
                ("trigger_x", "trigger_y"),
                ("arrival_x", "arrival_y"),
            ):
                producer[x_key], producer[y_key] = engine_start
            provenance = deepcopy(dict(producer["source_provenance"]))
            provenance.update(_runtime_position_engine_geometry(
                rom_raw, group=group, map_number=map_number,
                start=engine_start, layout_id=engine_layout_id,
            ))
            provenance["rom_sha256"] = rom_sha256
            producer["source_provenance"] = provenance
        elif producer["kind"] == "TRAINER_TOWER_ON_TRANSITION":
            engine_start = [producer["arrival_x"], producer["arrival_y"]]
        row["runtime_position_producer"] = (
            _validate_runtime_position_producer(
                producer, group=group, map_number=map_number,
                required=producer_required, label=f"catalog {case_id}",
                rom_raw=rom_raw, rom_sha256=rom_sha256,
                expected_engine_start=engine_start,
                engine_layout_id=engine_layout_id,
            )
        )
        result[case_id] = row
    return result


def _runtime_position_producer_tsv_fields(
    row: Mapping[str, Any], interaction: Mapping[str, Any], case_id: str,
) -> list[str]:
    group = int(interaction["group"])
    map_number = int(interaction["map"])
    owner_key = row.get("owner_key")
    expected_raw = interaction.get("expected_template_raw_hex")
    producer_required = bool(
        interaction.get("runtime_position_map_load_required", False)
    )
    if isinstance(owner_key, str) and owner_key.startswith("OBJECT:"):
        coordinate_dynamic = _catalog_template_position(
            expected_raw, f"catalog TSV {case_id}",
        ) != list(interaction["object"])
        if coordinate_dynamic and not producer_required:
            _fail(f"catalog TSV {case_id} runtime座標にmap-load契約欠落")
    elif producer_required:
        _fail(f"catalog TSV {case_id} non-OBJECTへmap-load producer過剰")
    producer = row.get("runtime_position_producer")
    if producer is None:
        producer = _none_runtime_position_producer(group, map_number)
    normalized = _validate_runtime_position_producer(
        producer, group=group, map_number=map_number,
        required=producer_required, label=f"catalog TSV {case_id}",
    )
    fields = [str(normalized[key]) for key in (
        "kind", "root", "source_group", "source_map", "source_warp",
        "predecessor_x", "predecessor_y", "trigger_x", "trigger_y",
        "trigger_key", "destination_group", "destination_map",
        "destination_warp", "arrival_x", "arrival_y", "record_address",
    )]
    lifecycle = row.get("runtime_map_lifecycle")
    if normalized["kind"] == "TRAINER_TOWER_ON_TRANSITION":
        if not isinstance(lifecycle, Mapping):
            _fail(f"catalog TSV {case_id} Trainer Tower lifecycle欠落")
        fields.extend([
            str(normalized["map_script_tag"]),
            str(lifecycle["layout_id"]),
            str(lifecycle["expected_movement_type"]),
        ])
    else:
        fields.extend([str(normalized["map_script_tag"]), "0", "0"])
    return fields


def _runtime_position_control_tsv_fields(
    row: Mapping[str, Any], interaction: Mapping[str, Any], case_id: str,
) -> list[str]:
    required = bool(
        interaction.get("runtime_position_map_load_required", False)
    )
    control = interaction.get(
        "runtime_position_control", row.get("runtime_position_control"),
    )
    state = row.get("state")
    producer = row.get("runtime_position_producer")
    control_required = required and not (
        isinstance(producer, Mapping)
        and producer.get("kind") == "TRAINER_TOWER_ON_TRANSITION"
    )
    normalized = _validate_runtime_position_control(
        control, required=control_required, label=f"catalog TSV {case_id}",
        state=state if isinstance(state, Mapping) else None,
    )
    return [
        str(normalized["kind"]), str(normalized["id"]),
        str(int(normalized["value"])),
    ]


def write_catalog_tsv(path: Path, expected: Mapping[str, Mapping[str, Any]]) -> None:
    """拡張state ABIをASCII TSVへ変換する（provenance/source IDは渡さない）。"""
    header = (
        "case_id\tbase_case_id\towner_key\tcatalog_branch\tgroup\tmap\t"
        "local_id\tstart_x\tstart_y\taction_key\tapproach_steps\t"
        "terminal\texpect_visible\texpect_interaction\tinput_sequences\t"
        "flags\tvars\titems\ttrainers\tcontrol_abi_complete\t"
        "external_controls\tinternal_controls\tinteraction_trigger\t"
        "runtime_root\tobject_x\tobject_y\tstance_x\tstance_y\twalk_keys\t"
        "interaction_distance\tcounter_x\tcounter_y\t"
        "actual_walk_required\tmap_level_real_walk_probe_required\t"
        "direct_script_call_forbidden\twalk_path_basis\t"
        "expected_template_raw_hex\t"
        + "\t".join(_RUNTIME_POSITION_CONTROL_TSV_COLUMNS) + "\t"
        + "\t".join(_RUNTIME_POSITION_PRODUCER_TSV_COLUMNS) + "\n"
    )
    lines = [header]
    for case_id in sorted(expected):
        row = expected[case_id]
        interaction = row["interaction"]
        expected_template_raw_hex = interaction.get(
            "expected_template_raw_hex",
        )
        if not isinstance(expected_template_raw_hex, str) \
                or re.fullmatch(
                    r"[0-9A-F]{48}", expected_template_raw_hex,
                ) is None:
            _fail(f"catalog TSV {case_id} 独立template raw欠落")
        state = row["state"]
        fields = [
            case_id, row["base_case_id"], row["owner_key"],
            row["catalog_branch"], str(interaction["group"]),
            str(interaction["map"]), str(interaction["local_id"]),
            str(interaction["start"][0]), str(interaction["start"][1]),
            str(KEYS[interaction["action"]]),
            str(interaction["approach_steps"]), row["expected_terminal"],
            str(int(row["expect_visible"])),
            str(int(row["expect_interaction"])),
            ";".join(
                _encode_input_sequence_tsv(sequence)
                for sequence in row.get("input_sequences", [])
            ) or "-",
            _encode_state(state["flags"], "value"),
            _encode_state(state["vars"], "value"),
            _encode_state(state["items"], "count"),
            _encode_state(state["trainers"], "defeated"),
            str(int(row.get("control_abi_complete", False))),
            ";".join(
                _encode_external_control(control)
                for control in row.get(
                    "control_requirements", {"external": []},
                )["external"]
            ) or "-",
            ";".join(
                _encode_internal_control(control)
                for control in row.get(
                    "control_requirements", {"internal": []},
                )["internal"]
            ) or "-",
            interaction["trigger"],
            str(interaction["runtime_root"]),
            str(interaction["object"][0]), str(interaction["object"][1]),
            str(interaction["stance"][0]), str(interaction["stance"][1]),
            ",".join(str(KEYS[token]) for token in interaction[
                "walk_sequence"
            ]) or "-",
            str(interaction["interaction_distance"]),
            str(0xFFFF if interaction["counter_tile"] is None
                else interaction["counter_tile"][0]),
            str(0xFFFF if interaction["counter_tile"] is None
                else interaction["counter_tile"][1]),
            str(int(interaction["actual_walk_required"])),
            str(int(interaction["map_level_real_walk_probe_required"])),
            str(int(interaction["direct_script_call_forbidden"])),
            interaction["walk_path_basis"],
            expected_template_raw_hex,
            *_runtime_position_control_tsv_fields(
                row, interaction, case_id,
            ),
            *_runtime_position_producer_tsv_fields(
                row, interaction, case_id,
            ),
        ]
        if any("\t" in field or "\n" in field for field in fields):
            _fail(f"catalog TSV {case_id} に制御文字があります")
        lines.append("\t".join(fields) + "\n")
    path.write_text("".join(lines), encoding="ascii", newline="\n")


_EVENT_TRIGGER_TSV_HEADER = (
    "case_id\towner_id\troot_assignment_id\tdeclared_kind\t"
    "effective_kind\troot_pc\tconsumer_pc\tstandard_index\tgroup\tmap\t"
    "x\ty\televation\tface_key\twalk_start_x\twalk_start_y\twalk_keys\t"
    "walk_key_count\tstance_x\tstance_y\tpath_trigger_key\t"
    "local_id\tobject_index\ttrigger_var\t"
    "trigger_value\tmap_precedence_guards\thidden_variant\tunderfoot\titem_id\tquantity\t"
    "collection_flag\tconsumer_root_expected_hit\tmap_subkind\t"
    "map_script_tag\tseed_kind\t"
    "source_group\tsource_map\tsource_warp\tpredecessor_x\t"
    "predecessor_y\ttrigger_x\ttrigger_y\ttrigger_key\t"
    "destination_group\tdestination_map\tdestination_warp\tarrival_x\t"
    "arrival_y\trecord_address\tresume_callback\ttransition_contract\t"
    "callback_install_instruction_pc\tcallback_dispatch_instruction_pc\t"
    "field_return_group\tfield_return_map\tfield_return_token_count\t"
    "caller_owner_id\t"
    "caller_owner_kind\tcaller_instruction_pc\tphysical_root_pc\t"
    "trigger_prefix_count\t"
    "runtime_topology_probe_required\tevent_terminal\t"
    "map_pre_transition_vars\tmap_pre_transition_flags\t"
    "map_pre_field_input_vars\tmap_pre_field_input_flags\n"
)


def _event_effective_trigger(
    trigger: Mapping[str, Any],
) -> tuple[Mapping[str, Any], dict[str, Any]]:
    common = {
        "declared_kind": trigger["kind"], "standard_index": 0,
        "caller_owner_id": "-", "caller_owner_kind": "-",
        "caller_instruction_pc": 0,
    }
    if trigger["kind"] == "MAP_LIFECYCLE_COMPOSITE_TRIGGER":
        producers = trigger.get("producer_contracts")
        if not isinstance(producers, list) or not producers:
            _fail("event runtime MAP composite producer欠落")
        return producers[0]["source_trigger_path"], common
    if trigger["kind"] != "COMMON_CALLER_TRIGGER":
        return trigger, common
    common.update({
        "standard_index": trigger["standard_index"],
        "caller_owner_id": trigger["caller_owner_id"],
        "caller_owner_kind": trigger["caller_owner_kind"],
        "caller_instruction_pc": trigger["caller_instruction_pc"],
    })
    return trigger["caller_trigger_path"], common


def _event_trigger_fields(row: Mapping[str, Any]) -> list[str]:
    declared = row["trigger_path"]
    effective, common = _event_effective_trigger(declared)
    kind = effective["kind"]
    values: dict[str, Any] = {
        "case_id": row["case_id"], "owner_id": row["owner_id"],
        "root_assignment_id": row["root_assignment_id"] or "-",
        "declared_kind": common["declared_kind"],
        "effective_kind": kind, "root_pc": declared.get("root_pc", 0),
        "physical_root_pc": effective.get("root_pc", 0),
        "consumer_pc": common["caller_instruction_pc"],
        "standard_index": common["standard_index"],
        "group": effective.get("group", 0), "map": effective.get("map", 0),
        "x": effective.get("x", 0), "y": effective.get("y", 0),
        "elevation": effective.get("elevation", 0), "face_key": 0,
        "walk_start_x": 0, "walk_start_y": 0, "walk_keys": "-",
        "walk_key_count": 0, "stance_x": 0xFFFF, "stance_y": 0xFFFF,
        "path_trigger_key": 0,
        "runtime_topology_probe_required": int(bool(effective.get(
            "runtime_topology_probe_required", False,
        ))),
        "local_id": effective.get("local_id", 0),
        "object_index": effective.get("object_index", 0),
        "trigger_var": effective.get("trigger_var", 0),
        "trigger_value": effective.get("trigger_value", 0),
        "map_precedence_guards": "-",
        "hidden_variant": effective.get("variant", "-"),
        "underfoot": int(bool(effective.get("underfoot", False))),
        "item_id": effective.get("item_id", 0),
        "quantity": effective.get("quantity", 0),
        "collection_flag": effective.get("collection_flag", 0),
        "consumer_root_expected_hit": int(bool(effective.get(
            "consumer_root_expected_hit", False,
        ))),
        "map_subkind": effective.get("root_subkind", "-"),
        "map_script_tag": effective.get("map_script_tag", 0),
        "seed_kind": "-", "source_group": 0, "source_map": 0,
        "source_warp": 0, "predecessor_x": 0, "predecessor_y": 0,
        "trigger_x": 0, "trigger_y": 0, "trigger_key": 0,
        "destination_group": 0, "destination_map": 0,
        "destination_warp": 0, "arrival_x": 0, "arrival_y": 0,
        "record_address": 0, "resume_callback": 0,
        "transition_contract": "-",
        "callback_install_instruction_pc": 0,
        "callback_dispatch_instruction_pc": 0,
        "field_return_group": 0, "field_return_map": 0,
        "field_return_token_count": 0,
        "caller_owner_id": common["caller_owner_id"],
        "caller_owner_kind": common["caller_owner_kind"],
        "caller_instruction_pc": common["caller_instruction_pc"],
        "trigger_prefix_count": len(_event_trigger_tokens(declared)),
        "event_terminal": row["terminal_kind"],
        "map_pre_transition_vars": "-",
        "map_pre_transition_flags": "-",
        "map_pre_field_input_vars": "-",
        "map_pre_field_input_flags": "-",
    }
    if kind in {"OBJECT_FACE_A", "BG_FACE_A"}:
        values["face_key"] = KEYS[effective["required_facing"]]
        if kind == "BG_FACE_A":
            values["consumer_pc"] = 0x0806C902
    elif kind == "COORD_STEP":
        values["consumer_pc"] = 0x0806D57C
    elif kind == "HIDDEN_ITEM":
        values["root_pc"] = effective["consumer_script_root"]
        values["physical_root_pc"] = effective["consumer_script_root"]
        values["consumer_pc"] = 0x0806C902
        if not effective["underfoot"]:
            values["face_key"] = KEYS[effective["required_facing"]]
    if kind in {"OBJECT_FACE_A", "BG_FACE_A", "COORD_STEP", "HIDDEN_ITEM"}:
        values.update({
            "walk_start_x": effective["start_tile"]["x"],
            "walk_start_y": effective["start_tile"]["y"],
            "walk_keys": ",".join(
                str(KEYS[token]) for token in effective["walk_sequence"]
            ),
            "walk_key_count": len(effective["walk_sequence"]),
        })
        if kind in {"OBJECT_FACE_A", "BG_FACE_A"} or (
            kind == "HIDDEN_ITEM" and not effective["underfoot"]
        ):
            values["stance_x"] = effective["stance_tile"]["x"]
            values["stance_y"] = effective["stance_tile"]["y"]
        else:
            values["path_trigger_key"] = KEYS[effective["trigger_key"]]
    elif kind == "MAP_TRANSITION_LOAD":
        seed_kind = next(
            key for key in (
                "stock_warp", "stock_connection", "engine_teleport",
                "resume_callback",
            ) if key in effective
        )
        values["seed_kind"] = seed_kind
        if effective["root_subkind"] == "CONDITION":
            # The map-script condition record is a var/value equality.  Keep
            # its exact operands in the generic trigger_var/value TSV slots so
            # the C runner can prepare and read back the condition before the
            # real transition; DIRECT rows remain zero/zero.
            values["trigger_var"] = effective["left_operand"]
            values["trigger_value"] = effective["right_operand"]
            values["map_precedence_guards"] = ";".join(
                f"{guard['variable']}:{guard['required_value']}"
                for guard in effective["precedence_guards"]
            ) or "-"
        seed = effective[seed_kind]
        resume = seed_kind == "resume_callback"
        if resume:
            predecessor = seed["actual_predecessor_consumer"]
            actual_seed_kind = next(
                key for key in (
                    "stock_warp", "stock_connection", "engine_teleport",
                ) if key in predecessor
            )
            actual_seed = predecessor[actual_seed_kind]
        else:
            actual_seed_kind = seed_kind
            actual_seed = seed
        contract_names = {
            "stock_warp": "STOCK_WARP",
            "stock_connection": "STOCK_CONNECTION_BOUNDARY_STEP",
            "engine_teleport": "ENGINE_PLAYER_TELEPORT_MAP_LOAD",
        }
        resume_contract_names = {
            "stock_warp": "STOCK_WARP_THEN_FIELD_RETURN",
            "stock_connection": "STOCK_CONNECTION_THEN_FIELD_RETURN",
            "engine_teleport": "ENGINE_TELEPORT_THEN_FIELD_RETURN",
        }
        values["transition_contract"] = (
            resume_contract_names[actual_seed_kind]
            if resume else contract_names[actual_seed_kind]
        )
        if actual_seed_kind in {"stock_warp", "stock_connection"}:
            values.update({
                "source_group": actual_seed["source"]["group"],
                "source_map": actual_seed["source"]["map"],
                "source_warp": actual_seed["source"].get("warp_id", 255),
                "predecessor_x": actual_seed["predecessor_tile"]["x"],
                "predecessor_y": actual_seed["predecessor_tile"]["y"],
                "trigger_x": actual_seed["trigger_tile"]["x"],
                "trigger_y": actual_seed["trigger_tile"]["y"],
                "trigger_key": KEYS[actual_seed["trigger_key"]],
                "destination_group": actual_seed["destination"]["group"],
                "destination_map": actual_seed["destination"]["map"],
                "destination_warp": actual_seed["destination"].get(
                    "warp_id", 255,
                ),
                "arrival_x": actual_seed["arrival_tile"]["x"],
                "arrival_y": actual_seed["arrival_tile"]["y"],
                "record_address": actual_seed[
                    "connection_or_warp_record_address"
                ],
            })
        else:
            start_tile = actual_seed["start_tile"]
            values.update({
                "source_warp": 255,
                "predecessor_x": start_tile["x"],
                "predecessor_y": start_tile["y"],
                "trigger_x": start_tile["x"],
                "trigger_y": start_tile["y"],
                "destination_group": actual_seed["destination"]["group"],
                "destination_map": actual_seed["destination"]["map"],
                "destination_warp": 255,
                "arrival_x": start_tile["x"],
                "arrival_y": start_tile["y"],
            })
        if resume:
            field_return = predecessor["field_return"]
            values.update({
                "resume_callback": seed["callback_address"],
                "callback_install_instruction_pc": field_return[
                    "callback_install_instruction_pc"
                ],
                "callback_dispatch_instruction_pc": field_return[
                    "callback_dispatch_instruction_pc"
                ],
                "field_return_group": field_return["expected_map"]["group"],
                "field_return_map": field_return["expected_map"]["map"],
                "field_return_token_count": len(
                    field_return["normal_trigger_tokens"]
                ),
            })
        lifecycle = row.get("map_lifecycle")
        if lifecycle is not None:
            sequence_lifecycle = lifecycle.get("sequence") \
                if isinstance(lifecycle, Mapping) else None
            phase_rows = sequence_lifecycle.get("phase_controls") \
                if isinstance(sequence_lifecycle, Mapping) else None
            if not isinstance(phase_rows, list) or len(phase_rows) != 2:
                _fail(f"event runtime TSV {row['case_id']} phase controls欠落")
            by_phase = {phase["phase_marker"]: phase for phase in phase_rows}

            def encode_phase(phase_marker: str, owner: str) -> str:
                rows = by_phase[phase_marker][owner]
                return ",".join(
                    f"{item['id']}:{int(item['value'])}" for item in rows
                ) or "-"

            values.update({
                "map_pre_transition_vars": encode_phase(
                    "PRE_TRANSITION", "variables",
                ),
                "map_pre_transition_flags": encode_phase(
                    "PRE_TRANSITION", "flags",
                ),
                "map_pre_field_input_vars": encode_phase(
                    "PRE_FIELD_INPUT", "variables",
                ),
                "map_pre_field_input_flags": encode_phase(
                    "PRE_FIELD_INPUT", "flags",
                ),
            })
    order = _EVENT_TRIGGER_TSV_HEADER.rstrip("\n").split("\t")
    fields = [str(values[key]) for key in order]
    if len(fields) != 67 or any(
        not field or "\t" in field or "\n" in field or "\r" in field
        for field in fields
    ):
        _fail(f"event runtime TSV {row['case_id']} field契約不一致")
    return fields


def _event_catalog_projection(row: Mapping[str, Any]) -> dict[str, Any]:
    effective, _common = _event_effective_trigger(row["trigger_path"])
    kind = effective["kind"]
    runtime_root = effective.get("consumer_script_root") \
        if kind == "HIDDEN_ITEM" else row["trigger_path"].get("root_pc")
    if isinstance(runtime_root, bool) or not isinstance(runtime_root, int) \
            or not 0x08000000 <= runtime_root < 0x0A000000:
        _fail(f"event runtime {row['case_id']} catalog root不正")
    group = int(effective.get("group", 0))
    map_number = int(effective.get("map", 0))
    action = "DOWN"
    start = [int(effective.get("x", 0)), int(effective.get("y", 0))]
    walk_sequence = ["UP", "DOWN"]
    stance = list(start)
    actual_walk_required = True
    if kind in {"OBJECT_FACE_A", "BG_FACE_A", "COORD_STEP", "HIDDEN_ITEM"}:
        start = [
            effective["start_tile"]["x"], effective["start_tile"]["y"],
        ]
        walk_sequence = list(effective["walk_sequence"])
        action = effective.get(
            "required_facing", effective.get("trigger_key", "DOWN"),
        )
        endpoint = effective.get("stance_tile")
        if not isinstance(endpoint, Mapping):
            endpoint = {"x": effective["x"], "y": effective["y"]}
        stance = [endpoint["x"], endpoint["y"]]
    elif kind == "MAP_TRANSITION_LOAD":
        _resume, _outer_kind, seed_kind, seed = _event_map_actual_seed(
            effective, str(row["case_id"]),
        )
        if seed_kind == "engine_teleport":
            group, map_number = (
                seed["destination"]["group"], seed["destination"]["map"],
            )
            start = [seed["start_tile"]["x"], seed["start_tile"]["y"]]
            walk_sequence = []
            actual_walk_required = False
        else:
            group, map_number = seed["source"]["group"], seed["source"]["map"]
            start = [seed["predecessor_tile"]["x"],
                     seed["predecessor_tile"]["y"]]
            action = seed["trigger_key"]
            walk_sequence = [action]
        stance = list(start)
    terminal = "BATTLE_START" \
        if row["terminal_kind"] == "BATTLE_START" else "FIELD_RELEASE"
    dx, dy = {
        "UP": (0, -1), "DOWN": (0, 1),
        "LEFT": (-1, 0), "RIGHT": (1, 0),
    }[action]
    dummy_object = [stance[0] + dx, stance[1] + dy]
    return {
        "case_id": row["case_id"],
        "base_case_id": row["root_assignment_id"] or row["owner_id"],
        "owner_key": row["owner_id"],
        "catalog_branch": row["input_sequence"][
            "expected_static_branch_token"
        ],
        "interaction": {
            "group": group, "map": map_number,
            "local_id": int(effective.get("local_id", 0)),
            "runtime_root": runtime_root,
            "object": dummy_object, "start": start,
            "action": action, "approach_steps": len(walk_sequence),
            "trigger": "EVENT_RUNTIME_TRIGGER_DISPATCH",
            "walk_sequence": walk_sequence,
            "stance": stance, "interaction_distance": 1,
            "counter_tile": None,
            "actual_walk_required": actual_walk_required,
            "actual_walk_exception": None,
            "walk_path_basis": (
                "EVENT_RUNTIME_OWNER_SPECIFIC_REAL_WALK"
                if actual_walk_required else
                "ENGINE_TELEPORT_NON_OBJECT_EVENT_ZERO_WALK"
            ),
            "expected_template_raw_hex": "0" * 48,
            "direct_script_call_forbidden": True,
            "map_level_real_walk_probe_required": False,
        },
        "state": deepcopy(row["state"]),
        "expect_visible": True, "expect_interaction": True,
        "expected_terminal": terminal,
        "control_abi_complete": True,
        "control_requirements": deepcopy(row["control_requirements"]),
        "input_sequences": [deepcopy(row["input_sequence"])],
    }


def write_event_runtime_tsv_files(
    catalog_path: Path, trigger_path: Path,
    expected: Mapping[str, Mapping[str, Any]],
) -> None:
    """Write lockstep state/control and physical-trigger TSV shards."""
    if not expected:
        _fail("event runtime TSV sourceが空です")
    catalog_rows = {
        case_id: _event_catalog_projection(row)
        for case_id, row in expected.items()
    }
    write_catalog_tsv(catalog_path, catalog_rows)
    lines = [_EVENT_TRIGGER_TSV_HEADER]
    for case_id in sorted(expected):
        fields = _event_trigger_fields(expected[case_id])
        if fields[0] != case_id:
            _fail("event runtime trigger/catalog case順不一致")
        lines.append("\t".join(fields) + "\n")
    trigger_path.write_text("".join(lines), encoding="ascii", newline="\n")


_STATEFUL_MENU_TSV_FIELDS = (
    "schema", "witness_id", "family", "root_pc", "menu_pc",
    "backedge_pc", "terminal_pc", "group", "map", "start_x",
    "start_y", "walk_keys", "stance_x", "stance_y", "face_key",
    "word", "pre_money", "post_money", "pre_qty_26", "pre_qty_27",
    "pre_qty_28", "post_qty_26", "post_qty_27", "post_qty_28",
    "pocket_slots", "occupied_slots", "pre_seen_sb2",
    "pre_seen_sb1_primary", "pre_seen_sb1_secondary", "post_seen_sb2",
    "post_seen_sb1_primary", "post_seen_sb1_secondary", "temp_flag_2",
    "temp_flag_3", "expected_root_hits", "expected_menu_hits",
    "expected_checkmoney_hits", "expected_checkspace_hits",
    "expected_removemoney_hits", "expected_additem_hits",
    "expected_backedge_hits", "expected_special_hits", "terminal_reason",
    "terminal_branch_pc", "expected_branch_hits",
)
_STATEFUL_MENU_RUNTIME_CONTRACT_IDS = (
    "VENDING_0818429E", "VENDING_09431D20",
    "BILL_SET_SEEN_09434AEC",
)


def load_stateful_menu_loop_contracts(
    path: Path, *, rom_raw: bytes,
) -> tuple[dict[str, Any], str]:
    """Load the canonical stateful-loop proof for this exact ROM."""
    if not path.is_file():
        _fail(f"stateful menu loop contractがありません: {path}")
    try:
        source = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as error:
        _fail(f"stateful menu loop contractを読めません: {error}")
    try:
        if str(ROOT) not in sys.path:
            sys.path.insert(0, str(ROOT))
        from tools.stage61_stateful_menu_loop_contracts import (
            validate_stateful_menu_loop_contracts,
        )

        document = validate_stateful_menu_loop_contracts(
            source, rom_raw, workspace_root=ROOT,
        )
    except (ImportError, KeyError, TypeError, ValueError, RuntimeError) as error:
        _fail(f"stateful menu loop contract検証失敗: {error}")
    if document.get("status") != "PASS" \
            or document.get("kind") != "STATEFUL_MENU_LOOP_CONTRACT_V1" \
            or document.get("rom_binding", {}).get("sha256") != _sha256(rom_raw) \
            or not all(document.get("assertions", {}).values()):
        _fail("stateful menu loop contract exact-ROM binding不一致")
    return document, _sha256(_stable(document).encode("utf-8"))


def _stateful_contract_address(value: Any, label: str) -> int:
    if not isinstance(value, str) \
            or re.fullmatch(r"0x0[89][0-9A-F]{6}", value) is None:
        _fail(f"stateful menu {label} address不正: {value!r}")
    return int(value, 16)


def _stateful_physical_trigger(
    event_rows: Mapping[str, Mapping[str, Any]], owner_id: str,
    *, expected_root: int,
) -> dict[str, Any]:
    candidates = [
        row.get("trigger_path") for row in event_rows.values()
        if row.get("owner_id") == owner_id
    ]
    if not candidates or any(not isinstance(row, Mapping) for row in candidates):
        _fail(f"stateful menu physical owner trigger欠落: {owner_id}")
    normalized = [deepcopy(dict(row)) for row in candidates]
    first = normalized[0]
    if any(row != first for row in normalized[1:]) \
            or first.get("kind") != "BG_FACE_A" \
            or first.get("root_pc") != expected_root:
        _fail(f"stateful menu physical owner trigger不一致: {owner_id}")
    return first


def build_stateful_menu_loop_tsv_rows(
    document: Mapping[str, Any],
    event_rows: Mapping[str, Mapping[str, Any]],
) -> tuple[list[list[str]], dict[str, dict[str, Any]]]:
    """Join 56 algebraic witnesses to current-ROM teleport/walk/face paths."""
    contracts = document.get("contracts")
    if not isinstance(contracts, list):
        _fail("stateful menu contracts list欠落")
    by_id = {
        row.get("contract_id"): row for row in contracts
        if isinstance(row, Mapping) and isinstance(row.get("contract_id"), str)
    }
    if len(by_id) != len(contracts) \
            or any(identifier not in by_id
                   for identifier in _STATEFUL_MENU_RUNTIME_CONTRACT_IDS):
        _fail("stateful menu contract ID重複/欠落")
    rows: list[list[str]] = []
    expected: dict[str, dict[str, Any]] = {}
    for contract_id in _STATEFUL_MENU_RUNTIME_CONTRACT_IDS:
        contract = by_id[contract_id]
        owner_binding = contract.get("owner_binding")
        rom_binding = contract.get("rom_binding")
        cfg = contract.get("cfg")
        witnesses = contract.get("witnesses")
        if not isinstance(owner_binding, Mapping) \
                or not isinstance(rom_binding, Mapping) \
                or not isinstance(cfg, Mapping) \
                or not isinstance(witnesses, list) or not witnesses:
            _fail(f"stateful menu {contract_id} runtime contract不正")
        root_pc = _stateful_contract_address(
            owner_binding.get("root"), f"{contract_id}.root",
        )
        menu_pc = _stateful_contract_address(
            rom_binding.get("menu_pc"), f"{contract_id}.menu",
        )
        terminal_pc = _stateful_contract_address(
            cfg.get("terminal_pc"), f"{contract_id}.terminal",
        )
        trace_sites_raw = rom_binding.get("runtime_trace_sites")
        trace_site_keys = {
            "root", "menu", "terminal", "choice", "checkmoney",
            "checkspace", "removemoney", "additem", "backedge", "special",
        }
        if not isinstance(trace_sites_raw, Mapping) \
                or set(trace_sites_raw) != trace_site_keys:
            _fail(f"stateful menu {contract_id} runtime trace site schema不正")
        trace_sites: dict[str, list[str]] = {}
        for kind in sorted(trace_site_keys):
            values = trace_sites_raw[kind]
            if not isinstance(values, list) \
                    or len(values) != len(set(values)) \
                    or any(not isinstance(value, str) for value in values):
                _fail(
                    f"stateful menu {contract_id}.{kind} trace site不正"
                )
            trace_sites[kind] = [
                f"0x{_stateful_contract_address(value, f'{contract_id}.{kind}'):08X}"
                for value in values
            ]
        if trace_sites["root"] != [f"0x{root_pc:08X}"] \
                or trace_sites["menu"] != [f"0x{menu_pc:08X}"] \
                or trace_sites["terminal"] != [f"0x{terminal_pc:08X}"]:
            _fail(f"stateful menu {contract_id} root/menu/terminal trace不一致")
        backedges = cfg.get("backedges")
        if not isinstance(backedges, list) or not backedges \
                or any(not isinstance(row, Mapping) for row in backedges):
            _fail(f"stateful menu {contract_id} backedge欠落")
        backedge_pc = _stateful_contract_address(
            backedges[0].get(
                "to" if contract_id == "BILL_SET_SEEN_09434AEC" else "from"
            ),
            f"{contract_id}.backedge",
        )
        backedge_event_pcs = trace_sites["backedge"]
        special_event_pc = None
        if contract_id == "BILL_SET_SEEN_09434AEC":
            if len(trace_sites["special"]) != 1:
                _fail(f"stateful menu {contract_id} special trace site不正")
            special_event_pc = trace_sites["special"][0]
        owner_ids = owner_binding.get("owner_ids")
        runtime_owner_ids = owner_binding.get("runtime_owner_ids")
        if not isinstance(owner_ids, list) or not owner_ids \
                or owner_ids != sorted(set(owner_ids)) \
                or any(not isinstance(owner, str) for owner in owner_ids) \
                or not isinstance(runtime_owner_ids, list) \
                or not runtime_owner_ids \
                or runtime_owner_ids != sorted(set(runtime_owner_ids)) \
                or any(not isinstance(owner, str)
                       for owner in runtime_owner_ids) \
                or not set(runtime_owner_ids) <= set(owner_ids):
            _fail(f"stateful menu {contract_id} owner/runtime IDs不正")
        state_projection = contract.get("state_projection", {})
        for index, witness in enumerate(witnesses):
            if not isinstance(witness, Mapping):
                _fail(f"stateful menu {contract_id} witness不正")
            witness_id = witness.get("witness_id")
            if not isinstance(witness_id, str) \
                    or _CASE_ID.fullmatch(witness_id) is None \
                    or witness_id in expected:
                _fail(f"stateful menu witness ID不正/重複: {witness_id!r}")
            # Static ownership is broader than the fresh-ROM physical witness
            # pool.  One Vega owner has an occupied stance tile, so only the
            # source-pinned runtime subset may drive real player input.
            owner_id = runtime_owner_ids[index % len(runtime_owner_ids)]
            trigger = _stateful_physical_trigger(
                event_rows, owner_id, expected_root=root_pc,
            )
            start = trigger["start_tile"]
            stance = trigger["stance_tile"]
            walk = trigger["walk_sequence"]
            face = trigger["required_facing"]
            word = witness.get("word")
            steps = witness.get("steps")
            dynamic = witness.get("dynamic_hits")
            pre = witness.get("pre")
            post = witness.get("expected_post")
            terminal = witness.get("terminal")
            if not isinstance(word, list) or not word \
                    or any(not isinstance(action, str) for action in word) \
                    or not isinstance(steps, list) \
                    or len(steps) != len(word) \
                    or any(
                        not isinstance(step, Mapping)
                        or step.get("ordinal") != step_index
                        or step.get("action") != word[step_index - 1]
                        for step_index, step in enumerate(steps, 1)
                    ) \
                    or not isinstance(dynamic, Mapping) \
                    or not isinstance(pre, Mapping) \
                    or not isinstance(post, Mapping) \
                    or not isinstance(terminal, Mapping):
                _fail(f"stateful menu {witness_id} witness schema不正")
            bill = contract_id == "BILL_SET_SEEN_09434AEC"
            if bill:
                pre_counts = post_counts = {
                    "0x001A": 0, "0x001B": 0, "0x001C": 0,
                }
                pre_money = post_money = 0
                mirror_owners = (
                    "SAVE_BLOCK2_POKEDEX_SEEN",
                    "SAVE_BLOCK1_SEEN_PRIMARY",
                    "SAVE_BLOCK1_SEEN_SECONDARY",
                )
                pre_mirrors = pre.get("seen_mirror_bytes")
                post_mirrors = post.get("seen_mirror_bytes")
                if not isinstance(pre_mirrors, Mapping) \
                        or not isinstance(post_mirrors, Mapping):
                    _fail(f"stateful menu {witness_id} seen mirrors不正")
                pre_seen = tuple(pre_mirrors[owner] for owner in mirror_owners)
                post_seen = tuple(post_mirrors[owner] for owner in mirror_owners)
                pocket_slots = occupied_slots = 0
                temp_flag_2, temp_flag_3 = index % 2, 1
                branch_hits = sum(
                    action.startswith("DISPLAY_") for action in word
                ) + 2
                terminal_branch_pc = terminal_pc
            else:
                pre_counts = pre.get("bag_counts")
                post_counts = post.get("bag_counts")
                fixture = state_projection.get("bag_physical_fixture") \
                    if isinstance(state_projection, Mapping) else None
                if not isinstance(pre_counts, Mapping) \
                        or not isinstance(post_counts, Mapping) \
                        or not isinstance(fixture, Mapping):
                    _fail(f"stateful menu {witness_id} bag projection不正")
                pre_money, post_money = pre.get("money"), post.get("money")
                pre_seen = post_seen = (0, 0, 0)
                pocket_slots = fixture.get("items_pocket_slots")
                empty_slots = fixture.get("items_pocket_empty_slots")
                if not isinstance(pocket_slots, int) \
                        or not isinstance(empty_slots, int):
                    _fail(f"stateful menu {witness_id} pocket fixture不正")
                occupied_slots = pocket_slots - empty_slots
                temp_flag_2 = temp_flag_3 = 0
                branch_hits = sum(
                    action.startswith("CHOICE_") for action in word
                ) + 1
                terminal_branch_pc = _stateful_contract_address(
                    terminal.get("branch_pc"),
                    f"{witness_id}.terminal_branch",
                )
                if word[-1] in {"EXIT_B", "EXIT_EXPLICIT"}:
                    # Exit paths emit the synthetic terminal BRANCH marker at
                    # the terminal PC itself.  Failure paths retain the
                    # source failure-branch PC before their terminal event.
                    terminal_branch_pc = terminal_pc
            quantities = (
                pre_counts["0x001A"], pre_counts["0x001B"],
                pre_counts["0x001C"], post_counts["0x001A"],
                post_counts["0x001B"], post_counts["0x001C"],
            )
            trace_expected = {
                "root": 1,
                "menu": dynamic["menu"],
                "branch": branch_hits,
                "checkmoney": dynamic.get("checkmoney", 0),
                "checkspace": dynamic.get("checkitemspace", 0),
                "removemoney": dynamic.get("removemoney", 0),
                "additem": dynamic.get("additem", 0),
                "backedge": dynamic["backedge"],
                "special": dynamic.get("set_seen_special", 0),
                "terminal": 1,
            }
            trace_kind_by_key = {
                "root": "ROOT", "menu": "MENU", "branch": "BRANCH",
                "checkmoney": "CHECKMONEY",
                "checkspace": "CHECKSPACE",
                "removemoney": "REMOVEMONEY", "additem": "ADDITEM",
                "backedge": "BACKEDGE", "special": "SPECIAL",
                "terminal": "TERMINAL",
            }
            trace_expected_events: list[dict[str, Any]] = []

            def expect_trace(kind: str, pc: str, iteration: int) -> None:
                trace_expected_events.append({
                    "kind": kind, "pc": pc, "menu_iteration": iteration,
                })

            expect_trace("ROOT", trace_sites["root"][0], 0)
            if bill:
                if len(trace_sites["choice"]) != 7 \
                        or len(trace_sites["backedge"]) != 4:
                    _fail(f"stateful menu {witness_id} Bill trace site数不正")
                # checkflag 0x0003=true selects this physical root branch
                # before the first multichoice instruction is dispatched.
                expect_trace("BRANCH", trace_sites["choice"][2], 0)
                expect_trace("MENU", trace_sites["menu"][0], 1)
                for iteration, (action, step) in enumerate(
                    zip(word, steps), 1,
                ):
                    if action.startswith("DISPLAY_"):
                        if step.get("next") != "SAME_MENU":
                            _fail(
                                f"stateful menu {witness_id} Bill step next不正"
                            )
                        choice = int(action.removeprefix("DISPLAY_"))
                        if not 0 <= choice < 4:
                            _fail(f"stateful menu {witness_id} Bill action不正")
                        expect_trace(
                            "BRANCH", trace_sites["choice"][3 + choice],
                            iteration,
                        )
                        expect_trace(
                            "SPECIAL", trace_sites["special"][0], iteration,
                        )
                        expect_trace(
                            "BACKEDGE", trace_sites["backedge"][choice],
                            iteration,
                        )
                        expect_trace(
                            "MENU", trace_sites["menu"][0], iteration + 1,
                        )
                    elif action in {"EXIT_B", "EXIT_EXPLICIT"}:
                        if step.get("next") != "TERMINAL":
                            _fail(
                                f"stateful menu {witness_id} Bill exit next不正"
                            )
                        expect_trace(
                            "TERMINAL", trace_sites["terminal"][0],
                            iteration,
                        )
                        expect_trace(
                            "BRANCH", trace_sites["terminal"][0], iteration,
                        )
                    else:
                        _fail(f"stateful menu {witness_id} Bill action不正")
            else:
                if len(trace_sites["choice"]) != 5 \
                        or len(trace_sites["checkmoney"]) != 3 \
                        or len(trace_sites["checkspace"]) != 1 \
                        or len(trace_sites["removemoney"]) != 3 \
                        or len(trace_sites["additem"]) != 1 \
                        or len(trace_sites["backedge"]) != 1 \
                        or trace_sites["special"]:
                    _fail(f"stateful menu {witness_id} vending trace site数不正")
                expect_trace("MENU", trace_sites["menu"][0], 1)
                for iteration, (action, step) in enumerate(
                    zip(word, steps), 1,
                ):
                    if action.startswith("CHOICE_"):
                        choice = int(action.removeprefix("CHOICE_"))
                        if not 0 <= choice < 3:
                            _fail(f"stateful menu {witness_id} choice不正")
                        expect_trace(
                            "BRANCH", trace_sites["choice"][choice], iteration,
                        )
                        expect_trace(
                            "CHECKMONEY", trace_sites["checkmoney"][choice],
                            iteration,
                        )
                        next_state = step.get("next")
                        if next_state == "SAME_MENU":
                            expect_trace(
                                "CHECKSPACE", trace_sites["checkspace"][0],
                                iteration,
                            )
                            expect_trace(
                                "REMOVEMONEY",
                                trace_sites["removemoney"][choice], iteration,
                            )
                            expect_trace(
                                "ADDITEM", trace_sites["additem"][0],
                                iteration,
                            )
                            expect_trace(
                                "BACKEDGE", trace_sites["backedge"][0],
                                iteration,
                            )
                            expect_trace(
                                "MENU", trace_sites["menu"][0], iteration + 1,
                            )
                        elif next_state == "TERMINAL_INSUFFICIENT" \
                                and terminal["reason"] == "INSUFFICIENT":
                            expect_trace(
                                "BRANCH", trace_sites["choice"][3], iteration,
                            )
                            expect_trace(
                                "TERMINAL", trace_sites["terminal"][0],
                                iteration,
                            )
                        elif next_state == "TERMINAL_BAG_FULL" \
                                and terminal["reason"] == "BAG_FULL":
                            expect_trace(
                                "CHECKSPACE", trace_sites["checkspace"][0],
                                iteration,
                            )
                            expect_trace(
                                "BRANCH", trace_sites["choice"][4], iteration,
                            )
                            expect_trace(
                                "TERMINAL", trace_sites["terminal"][0],
                                iteration,
                            )
                        else:
                            _fail(
                                f"stateful menu {witness_id} success/terminal"
                                " trace導出不一致"
                            )
                    elif action in {"EXIT_B", "EXIT_EXPLICIT"}:
                        if step.get("next") != "TERMINAL":
                            _fail(
                                f"stateful menu {witness_id} vending exit next不正"
                            )
                        expect_trace(
                            "TERMINAL", trace_sites["terminal"][0],
                            iteration,
                        )
                        expect_trace(
                            "BRANCH", trace_sites["terminal"][0], iteration,
                        )
                    else:
                        _fail(f"stateful menu {witness_id} action不正")
            trace_expected_pcs = {
                key: [
                    event["pc"] for event in trace_expected_events
                    if event["kind"] == kind
                ]
                for key, kind in trace_kind_by_key.items()
            }
            if any(
                len(trace_expected_pcs[key]) != trace_expected[key]
                for key in trace_expected
            ):
                _fail(f"stateful menu {witness_id} trace PC/count導出不一致")
            values: list[Any] = [
                "STATEFUL_MENU_LOOP_CONTRACT_V1", witness_id, contract_id,
                f"0x{root_pc:08X}", f"0x{menu_pc:08X}",
                f"0x{backedge_pc:08X}", f"0x{terminal_pc:08X}",
                trigger["group"], trigger["map"], start["x"], start["y"],
                ",".join(walk), stance["x"], stance["y"], face,
                ",".join(word), pre_money, post_money, *quantities,
                pocket_slots, occupied_slots, *pre_seen, *post_seen,
                temp_flag_2, temp_flag_3, trace_expected["root"],
                trace_expected["menu"], trace_expected["checkmoney"],
                trace_expected["checkspace"], trace_expected["removemoney"],
                trace_expected["additem"], trace_expected["backedge"],
                trace_expected["special"], terminal["reason"],
                f"0x{terminal_branch_pc:08X}", trace_expected["branch"],
            ]
            fields = [str(value) for value in values]
            if len(fields) != len(_STATEFUL_MENU_TSV_FIELDS) \
                    or any(not value or any(mark in value for mark in "\t\r\n")
                           for value in fields):
                _fail(f"stateful menu {witness_id} TSV field不正")
            rows.append(fields)
            expected[witness_id] = {
                "witness_id": witness_id,
                "family": contract_id,
                "root_pc": f"0x{root_pc:08X}",
                "menu_pc": f"0x{menu_pc:08X}",
                "stock_warp": [
                    trigger["group"], trigger["map"], start["x"], start["y"],
                ],
                "real_walk_steps": len(walk),
                "face_key": KEYS[face],
                "action_count": len(word),
                "terminal_reason": terminal["reason"],
                "pre_money": pre_money,
                "post_money": post_money,
                "pre_quantities": list(quantities[:3]),
                "post_quantities": list(quantities[3:]),
                "all_five_pockets_byte_exact": not bill,
                "bag_snapshot_range": (
                    None if bill else ["0x0310", "0x05F8"]
                ),
                "bag_snapshot_bytes": 0 if bill else 0x02E8,
                "target_item_ids_and_slots_exact": not bill,
                "pre_seen": list(pre_seen),
                "post_seen": list(post_seen),
                "temp_flag_2": bool(temp_flag_2),
                "temp_flag_3": bool(temp_flag_3),
                "failure_path_state_unchanged": terminal["reason"] in {
                    "INSUFFICIENT", "BAG_FULL",
                },
                "trace_expected": trace_expected,
                "trace_expected_pcs": trace_expected_pcs,
                "trace_expected_events": trace_expected_events,
                "backedge_pc": f"0x{backedge_pc:08X}",
                "terminal_pc": f"0x{terminal_pc:08X}",
                "terminal_branch_pc": f"0x{terminal_branch_pc:08X}",
                "backedge_event_pcs": backedge_event_pcs,
                "special_event_pc": special_event_pc,
                "peak_artifact": f"{witness_id}-peak.ppm",
            }
    if len(rows) != 56 or len(expected) != 56:
        _fail(f"stateful menu witness exact 56不一致: {len(rows)}")
    return rows, expected


def write_stateful_menu_loop_tsv(
    path: Path, document: Mapping[str, Any],
    event_rows: Mapping[str, Mapping[str, Any]],
) -> dict[str, dict[str, Any]]:
    rows, expected = build_stateful_menu_loop_tsv_rows(document, event_rows)
    lines = ["\t".join(_STATEFUL_MENU_TSV_FIELDS) + "\n"]
    lines.extend("\t".join(row) + "\n" for row in rows)
    path.write_text("".join(lines), encoding="ascii", newline="\n")
    return expected


def _validate_stateful_menu_loop_batch(
    document: Any, expected: Mapping[str, Mapping[str, Any]],
) -> dict[str, Any]:
    root_keys = {
        "schema_version", "status", "case", "contract_kind",
        "fresh_baseline_restore_per_witness", "preparation_only_host_writes",
        "host_write_policy", "party_and_battle_tower_baseline_snapshot_only",
        "actual_stock_warp_walk_face_a", "direct_root_call_before",
        "results", "fixture_count", "vending_witness_count",
        "bill_witness_count", "failed", "bill_root_flag_probes",
        "research_result_disjoint_probe", "direct_root_call_after",
        "required_peak_artifact_count", "untested", "warnings",
    }
    if not isinstance(document, Mapping) or set(document) != root_keys \
            or (
                document.get("schema_version"), document.get("status"),
                document.get("case"), document.get("contract_kind"),
                document.get("fresh_baseline_restore_per_witness"),
                document.get("preparation_only_host_writes"),
                document.get("host_write_policy"),
                document.get("party_and_battle_tower_baseline_snapshot_only"),
                document.get("actual_stock_warp_walk_face_a"),
                document.get("direct_root_call_before"),
                document.get("direct_root_call_after"),
                document.get("fixture_count"),
                document.get("vending_witness_count"),
                document.get("bill_witness_count"), document.get("failed"),
                document.get("required_peak_artifact_count"),
                document.get("untested"), document.get("warnings"),
            ) != (
                1, "PASS", "stateful_menu_loop_batch",
                "STATEFUL_MENU_LOOP_CONTRACT_V1", True, True,
                "DECLARED_PRECONDITION_FIELDS_ONLY_NO_SENTINEL_WRITES", True,
                True,
                0, 0, 56, 44, 12, 0, 61, 0, 0,
            ):
        _fail(f"stateful menu runtime root契約不一致: {document}")
    raw_rows = document["results"]
    if not isinstance(raw_rows, list) or len(raw_rows) != len(expected) \
            or [row.get("witness_id") if isinstance(row, Mapping) else None
                for row in raw_rows] != list(expected):
        _fail("stateful menu runtime witness order/cardinality不一致")
    row_keys = {
        "witness_id", "family", "root_pc", "menu_pc", "stock_warp",
        "real_walk_steps", "face_key", "action_count", "terminal_reason",
        "pre_money", "post_money", "pre_quantities", "post_quantities",
        "all_five_pockets_byte_exact", "bag_snapshot_range",
        "bag_snapshot_bytes", "target_item_ids_and_slots_exact",
        "pre_seen", "post_seen", "temp_flag_2", "temp_flag_3",
        "fresh_baseline_restore", "physical_root_activation",
        "direct_root_call_before", "direct_root_call_after",
        "failure_path_state_unchanged", "peak_artifact",
        "state_projection_exact",
        "dynamic_trace", "second_hits_distinct_by_menu_iteration",
        "field_release", "field_input_recovered",
    }
    trace_count_keys = {
        "root", "menu", "branch", "checkmoney", "checkspace",
        "removemoney", "additem", "backedge", "special", "terminal",
    }
    kind_by_key = {
        "root": "ROOT", "menu": "MENU", "branch": "BRANCH",
        "checkmoney": "CHECKMONEY", "checkspace": "CHECKSPACE",
        "removemoney": "REMOVEMONEY", "additem": "ADDITEM",
        "backedge": "BACKEDGE", "special": "SPECIAL",
        "terminal": "TERMINAL",
    }
    normalized_rows = []
    for index, raw in enumerate(raw_rows):
        witness_id = raw.get("witness_id") if isinstance(raw, Mapping) else "?"
        if not isinstance(raw, Mapping) or set(raw) != row_keys:
            _fail(f"stateful menu result[{index}] schema不一致")
        oracle = expected[witness_id]
        comparable = {
            key: raw[key] for key in oracle
            if key not in {
                "trace_expected", "trace_expected_pcs",
                "trace_expected_events",
                "backedge_pc", "terminal_pc",
                "terminal_branch_pc", "backedge_event_pcs",
                "special_event_pc",
            }
        }
        expected_comparable = {
            key: value for key, value in oracle.items()
            if key not in {
                "trace_expected", "trace_expected_pcs",
                "trace_expected_events",
                "backedge_pc", "terminal_pc",
                "terminal_branch_pc", "backedge_event_pcs",
                "special_event_pc",
            }
        }
        if comparable != expected_comparable or any(
            raw.get(key) is not True for key in (
                "fresh_baseline_restore", "physical_root_activation",
                "state_projection_exact",
                "second_hits_distinct_by_menu_iteration", "field_release",
                "field_input_recovered",
            )
        ) or raw.get("direct_root_call_before") != 0 \
                or raw.get("direct_root_call_after") != 0:
            _fail(f"stateful menu {witness_id} physical/state projection不一致")
        trace = raw["dynamic_trace"]
        if not isinstance(trace, Mapping) \
                or set(trace) != trace_count_keys | {"events"} \
                or {key: trace[key] for key in trace_count_keys} \
                    != oracle["trace_expected"]:
            _fail(f"stateful menu {witness_id} dynamic count不一致")
        events = trace["events"]
        if not isinstance(events, list) \
                or len(events) != sum(oracle["trace_expected"].values()):
            _fail(f"stateful menu {witness_id} dynamic event数不一致")
        counts = {kind: 0 for kind in kind_by_key.values()}
        previous_ordinal = -1
        previous_event: Mapping[str, Any] | None = None
        events_by_kind: dict[str, list[Mapping[str, Any]]] = {
            kind: [] for kind in counts
        }
        for event_index, event in enumerate(events):
            if not isinstance(event, Mapping) or set(event) != {
                "kind", "pc", "instruction_ordinal", "menu_iteration",
            } or event.get("kind") not in counts \
                    or not isinstance(event.get("pc"), str) \
                    or re.fullmatch(r"0x0[89][0-9A-F]{6}", event["pc"]) is None \
                    or isinstance(event.get("instruction_ordinal"), bool) \
                    or not isinstance(event["instruction_ordinal"], int) \
                    or event["instruction_ordinal"] <= 0 \
                    or event["instruction_ordinal"] < previous_ordinal \
                    or isinstance(event.get("menu_iteration"), bool) \
                    or not isinstance(event["menu_iteration"], int) \
                    or not 0 <= event["menu_iteration"] <= 8:
                _fail(
                    f"stateful menu {witness_id} trace event[{event_index}]不正"
                )
            equal_terminal_pair = previous_event is not None \
                and event["instruction_ordinal"] == previous_ordinal \
                and previous_event["kind"] == "TERMINAL" \
                and event["kind"] == "BRANCH" \
                and previous_event["pc"] == event["pc"] \
                and previous_event["menu_iteration"] \
                    == event["menu_iteration"]
            if event["instruction_ordinal"] == previous_ordinal \
                    and not equal_terminal_pair:
                _fail(
                    f"stateful menu {witness_id} trace ordinal"
                    f"[{event_index}]非単調増加"
                )
            previous_ordinal = event["instruction_ordinal"]
            previous_event = event
            counts[event["kind"]] += 1
            events_by_kind[event["kind"]].append(event)
        projected_events = [
            {
                "kind": event["kind"], "pc": event["pc"],
                "menu_iteration": event["menu_iteration"],
            }
            for event in events
        ]
        if projected_events != oracle["trace_expected_events"] or any(
            counts[kind] != oracle["trace_expected"][key]
            for key, kind in kind_by_key.items()
        ) or any(
            [event["pc"] for event in events_by_kind[kind]]
            != oracle["trace_expected_pcs"][key]
            for key, kind in kind_by_key.items()
        ) or {event["pc"] for event in events_by_kind["ROOT"]} \
                != {oracle["root_pc"]} \
                or {event["pc"] for event in events_by_kind["MENU"]} \
                != {oracle["menu_pc"]} \
                or {event["pc"] for event in events_by_kind["BACKEDGE"]} \
                - set(oracle["backedge_event_pcs"]) \
                or {event["pc"] for event in events_by_kind["TERMINAL"]} \
                != {oracle["terminal_pc"]} \
                or oracle["terminal_branch_pc"] not in {
                    event["pc"] for event in events_by_kind["BRANCH"]
                } or (
                    oracle["special_event_pc"] is not None
                    and {event["pc"] for event in events_by_kind["SPECIAL"]}
                    not in (set(), {oracle["special_event_pc"]})
                ):
            _fail(f"stateful menu {witness_id} trace PC/count binding不一致")
        mutator_kind = "SPECIAL" if raw["family"] \
            == "BILL_SET_SEEN_09434AEC" else "REMOVEMONEY"
        mutator_iterations = [
            event["menu_iteration"] for event in events_by_kind[mutator_kind]
        ]
        if any(value <= 0 for value in mutator_iterations) \
                or len(mutator_iterations) != len(set(mutator_iterations)):
            _fail(f"stateful menu {witness_id} second-hit iteration不一致")
        normalized_rows.append(deepcopy(dict(raw)))

    probes = document["bill_root_flag_probes"]
    if not isinstance(probes, list) or len(probes) != 4:
        _fail("stateful Bill four flag probes欠落")
    expected_probes = (
        (False, False, "0x09434A0B", False),
        (True, False, "0x09434A15", False),
        (False, True, "0x09434AD9", True),
        (True, True, "0x09434AD9", True),
    )
    probe_keys = {
        "temp_flag_2", "temp_flag_3", "root_pc",
        "expected_branch_pc", "root_hits", "branch_hits", "menu_hits",
        "terminal_hits", "menu_entered",
        "direct_root_call", "peak_artifact", "field_input_recovered",
        "dynamic_trace",
    }
    for index, (probe, expected_probe) in enumerate(zip(probes, expected_probes)):
        flag2, flag3, branch, menu = expected_probe
        if not isinstance(probe, Mapping) or set(probe) != probe_keys \
                or (
                    probe["temp_flag_2"], probe["temp_flag_3"],
                    probe["root_pc"], probe["expected_branch_pc"],
                    probe["root_hits"], probe["branch_hits"],
                    probe["menu_hits"], probe["terminal_hits"],
                    probe["menu_entered"],
                    probe["direct_root_call"], probe["peak_artifact"],
                    probe["field_input_recovered"],
                ) != (
                    flag2, flag3, "0x094349F8", branch, 1,
                    2 if flag3 else 1, 1 if flag3 else 0,
                    1 if flag3 else 0, menu, False,
                    f"bill-root-flags-{int(flag2)}-{int(flag3)}-peak.ppm",
                    True,
                ):
            _fail(f"stateful Bill root flag probe[{index}]不一致")
        expected_events = [
            {"kind": "ROOT", "pc": "0x094349F8", "menu_iteration": 0},
            {"kind": "BRANCH", "pc": branch, "menu_iteration": 0},
        ]
        if flag3:
            expected_events.extend([
                {
                    "kind": "MENU", "pc": "0x09434AEC",
                    "menu_iteration": 1,
                },
                {
                    "kind": "TERMINAL", "pc": "0x09434B89",
                    "menu_iteration": 1,
                },
                {
                    "kind": "BRANCH", "pc": "0x09434B89",
                    "menu_iteration": 1,
                },
            ])
        trace = probe["dynamic_trace"]
        expected_counts = {
            "root": 1, "menu": int(flag3),
            "branch": 2 if flag3 else 1,
            "checkmoney": 0, "checkspace": 0, "removemoney": 0,
            "additem": 0, "backedge": 0, "special": 0,
            "terminal": int(flag3),
        }
        if not isinstance(trace, Mapping) \
                or set(trace) != set(expected_counts) | {"events"} \
                or {key: trace[key] for key in expected_counts} \
                    != expected_counts \
                or not isinstance(trace["events"], list) \
                or len(trace["events"]) != len(expected_events):
            _fail(f"stateful Bill root flag probe[{index}] trace不正")
        projected = []
        previous_ordinal = -1
        previous_event: Mapping[str, Any] | None = None
        for event_index, event in enumerate(trace["events"]):
            if not isinstance(event, Mapping) or set(event) != {
                "kind", "pc", "instruction_ordinal", "menu_iteration",
            } or isinstance(event.get("instruction_ordinal"), bool) \
                    or not isinstance(event["instruction_ordinal"], int) \
                    or event["instruction_ordinal"] <= 0 \
                    or event["instruction_ordinal"] < previous_ordinal:
                _fail(
                    f"stateful Bill root flag probe[{index}]"
                    f" trace event[{event_index}]不正"
                )
            equal_terminal_pair = previous_event is not None \
                and event["instruction_ordinal"] == previous_ordinal \
                and previous_event["kind"] == "TERMINAL" \
                and event["kind"] == "BRANCH" \
                and previous_event["pc"] == event["pc"] \
                and previous_event["menu_iteration"] \
                    == event["menu_iteration"]
            if event["instruction_ordinal"] == previous_ordinal \
                    and not equal_terminal_pair:
                _fail(
                    f"stateful Bill root flag probe[{index}]"
                    " trace ordinal不正"
                )
            projected.append({
                "kind": event["kind"], "pc": event["pc"],
                "menu_iteration": event["menu_iteration"],
            })
            previous_ordinal = event["instruction_ordinal"]
            previous_event = event
        if projected != expected_events:
            _fail(
                f"stateful Bill root flag probe[{index}] exact trace不一致"
            )
    research = document["research_result_disjoint_probe"]
    research_keys = {
        "locked_precondition_control", "root_pc", "root_hits",
        "kanto_access_precondition_flags", "open_shop_busy_result",
        "open_shop_busy_result_observed", "native_cancel_via_b", "final_result",
        "reentry_required_result", "yes_no_pc", "yes_no_hits",
        "syntactic_backedge_pc", "syntactic_backedge_hits",
        "result_10_observed", "cancel_result", "cancel_result_observed",
        "direct_root_call", "peak_artifact", "field_input_recovered",
        "dynamic_trace",
    }
    locked = research.get("locked_precondition_control") \
        if isinstance(research, Mapping) else None
    locked_keys = {
        "kanto_access_precondition_flags_set", "final_result", "root_hits",
        "peak_artifact", "field_input_recovered", "dynamic_trace",
    }
    if not isinstance(research, Mapping) or set(research) != research_keys \
            or not isinstance(locked, Mapping) or set(locked) != locked_keys \
            or (
                research["root_pc"], research["root_hits"],
                research["kanto_access_precondition_flags"],
                research["open_shop_busy_result"],
                research["open_shop_busy_result_observed"],
                research["native_cancel_via_b"], research["final_result"],
                research["reentry_required_result"], research["yes_no_pc"],
                research["yes_no_hits"], research["syntactic_backedge_pc"],
                research["syntactic_backedge_hits"],
                research["result_10_observed"], research["cancel_result"],
                research["cancel_result_observed"],
                research["direct_root_call"], research["peak_artifact"],
                research["field_input_recovered"],
            ) != (
                "0x093C0328", 1, ["0x0824", "0x114B"], 9, True,
                True, 2, 10, "0x093C03A4", 0,
                "0x093C03B8", 0, False, 2, True, False,
                "research-physical-native-cancel-peak.ppm", True,
            ) or (
                locked["kanto_access_precondition_flags_set"],
                locked["final_result"], locked["root_hits"],
                locked["peak_artifact"], locked["field_input_recovered"],
            ) != (False, 3, 1, None, True):
        _fail("stateful Research result-disjoint physical probe不一致")

    def validate_research_trace(
        trace: Any, *, label: str,
    ) -> None:
        expected_counts = {
            "root": 1, "menu": 0, "branch": 1, "checkmoney": 0,
            "checkspace": 0, "removemoney": 0, "additem": 0,
            "backedge": 0, "special": 0, "terminal": 1,
        }
        expected_events = [
            {"kind": "ROOT", "pc": "0x093C0328", "menu_iteration": 0},
            {"kind": "TERMINAL", "pc": "0x093C0404", "menu_iteration": 0},
            {"kind": "BRANCH", "pc": "0x093C0404", "menu_iteration": 0},
        ]
        if not isinstance(trace, Mapping) \
                or set(trace) != set(expected_counts) | {"events"} \
                or {key: trace[key] for key in expected_counts} \
                    != expected_counts \
                or not isinstance(trace["events"], list) \
                or len(trace["events"]) != len(expected_events):
            _fail(f"stateful Research {label} trace count不一致")
        projected = []
        previous = -1
        for index, event in enumerate(trace["events"]):
            if not isinstance(event, Mapping) or set(event) != {
                "kind", "pc", "instruction_ordinal", "menu_iteration",
            } or isinstance(event.get("instruction_ordinal"), bool) \
                    or not isinstance(event["instruction_ordinal"], int) \
                    or event["instruction_ordinal"] <= 0 \
                    or event["instruction_ordinal"] < previous \
                    or (event["instruction_ordinal"] == previous
                        and index != 2):
                _fail(f"stateful Research {label} trace ordinal不一致")
            previous = event["instruction_ordinal"]
            projected.append({
                "kind": event["kind"], "pc": event["pc"],
                "menu_iteration": event["menu_iteration"],
            })
        if projected != expected_events:
            _fail(f"stateful Research {label} exact trace不一致")

    validate_research_trace(
        locked["dynamic_trace"], label="locked-precondition",
    )
    validate_research_trace(
        research["dynamic_trace"], label="native-B-cancel",
    )
    result = deepcopy(dict(document))
    result["results"] = normalized_rows
    return result


def _stateful_required_peak_artifact_paths(
    expected: Mapping[str, Mapping[str, Any]],
) -> list[str]:
    """Return the exact 56 witness + 4 Bill + 1 Research peak set."""
    paths = [f"{witness_id}-peak.ppm" for witness_id in expected]
    paths.extend(
        f"bill-root-flags-{flag2}-{flag3}-peak.ppm"
        for flag2 in (0, 1) for flag3 in (0, 1)
    )
    paths.append("research-physical-native-cancel-peak.ppm")
    if len(paths) != 61 or len(paths) != len(set(paths)):
        _fail("stateful menu required peak artifact集合不正")
    return paths


def _normalize_legacy_runtime_position_contract(
    value: Any, *, npc_id: str, group: int, map_number: int,
    runtime_object: Sequence[int], expected_template_raw_hex: str,
    local_id: int, shadow: Mapping[str, Any] | None,
) -> dict[str, Any] | None:
    label = f"legacy.{npc_id}.runtime_position_state_contract"
    expected = _RUNTIME_POSITION_EXPECTED_CONTROLS.get((group, map_number))
    if value is None:
        if list(runtime_object) != _catalog_template_position(
            expected_template_raw_hex, label,
        ):
            _fail(f"{label} runtime座標差分に条件契約欠落")
        return None
    required_keys = {
        "kind", "root", "map_script_tag", "control", "variants",
        "setobjectxyperm_instruction_addresses", "root_prefix_hex",
        "assertions",
    }
    if not isinstance(value, Mapping) or set(value) != required_keys \
            or value.get("kind") \
                != "CONDITIONAL_MAP_SCRIPT_RUNTIME_POSITION" \
            or value.get("map_script_tag") != 3 \
            or expected is None \
            or value.get("root") != f"0x{int(expected['root']):08X}":
        _fail(f"{label} root/map/tag schema不一致")
    expected_control = {
        key: item for key, item in expected.items()
        if key not in {"root", "owner_count"}
    }
    if value.get("control") != expected_control:
        _fail(f"{label} exact control不一致")
    prefix = value.get("root_prefix_hex")
    addresses = value.get("setobjectxyperm_instruction_addresses")
    assertions = value.get("assertions")
    if not isinstance(prefix, str) or not prefix \
            or re.fullmatch(r"[0-9a-f]+", prefix) is None \
            or len(prefix) % 2 \
            or not isinstance(addresses, list) or not addresses \
            or any(
                not isinstance(address, str)
                or re.fullmatch(r"0x0[89][0-9A-F]{6}", address) is None
                for address in addresses
            ) \
            or not isinstance(assertions, Mapping) or not assertions \
            or any(item is not True for item in assertions.values()):
        _fail(f"{label} provenance/assertions不一致")
    variants = value.get("variants")
    if not isinstance(variants, list) or len(variants) != 2:
        _fail(f"{label} variantsはexact 2件です")
    by_id: dict[str, dict[str, Any]] = {}
    static_object = _catalog_template_position(
        expected_template_raw_hex, label,
    )
    for index, variant in enumerate(variants):
        variant_label = f"{label}.variants[{index}]"
        if not isinstance(variant, Mapping) or set(variant) != {
            "variant_id", "object", "state", "baseline",
            "interaction_execution",
        }:
            _fail(f"{variant_label} schema不一致")
        variant_id = variant.get("variant_id")
        if variant_id not in {"STATIC", "RUNTIME"} or variant_id in by_id:
            _fail(f"{variant_label}.variant_id不正")
        expected_object = (
            static_object if variant_id == "STATIC" else list(runtime_object)
        )
        if _pair(variant.get("object"), f"{variant_label}.object") \
                != expected_object:
            _fail(f"{variant_label}.object不一致")
        expected_value = bool(
            expected["static_value"] if variant_id == "STATIC"
            else expected["runtime_value"]
        )
        state = variant.get("state")
        if not isinstance(state, Mapping) or set(state) != {"flags", "vars"}:
            _fail(f"{variant_label}.state schema不一致")
        reason = (
            "MAP_TAG3_RUNTIME_POSITION_CONDITION_STATIC"
            if variant_id == "STATIC" else
            "MAP_TAG3_RUNTIME_POSITION_CONDITION_RUNTIME"
        )
        expected_flags = [{
            "id": int(
                expected["id"] if expected["kind"] == "FLAG"
                else expected["flag_id"]
            ),
            "value": expected_value,
            "reason": reason,
        }]
        expected_vars = [] if expected["kind"] == "FLAG" else [{
            "id": int(expected["var_id"]),
            "value": int(expected["enabled_var_value"])
                if expected_value else 0,
            "reason": reason,
        }]
        if state.get("flags") != expected_flags \
                or state.get("vars") != expected_vars \
                or variant.get("baseline") is not (
                    variant_id == (
                        "RUNTIME" if expected["kind"] == "NATIONAL_DEX"
                        else "STATIC"
                    )
                ):
            _fail(f"{variant_label}.state/baseline不一致")
        interaction = _catalog_interaction_execution({
            "owner_key": npc_id,
            "group": group, "map": map_number, "local_id": local_id,
            "object": expected_object,
            "interaction_execution": variant["interaction_execution"],
            "non_product_shadow_alias": shadow,
            "expected_template_raw_hex": expected_template_raw_hex,
        }, variant_label)
        normalized_variant = deepcopy(dict(variant))
        normalized_variant["object"] = expected_object
        normalized_variant["interaction_execution"] = {
            key: deepcopy(interaction[key]) for key in (
                "trigger", "start", "walk_sequence", "stance", "action",
                "interaction_distance", "counter_tile",
                "actual_walk_required", "actual_walk_exception",
                "walk_path_basis", "direct_script_call_forbidden",
            )
        }
        by_id[variant_id] = normalized_variant
    if set(by_id) != {"STATIC", "RUNTIME"} \
            or by_id["STATIC"]["object"] == by_id["RUNTIME"]["object"]:
        _fail(f"{label} static/runtime variant集合不一致")
    normalized = deepcopy(dict(value))
    normalized["variants"] = [by_id["STATIC"], by_id["RUNTIME"]]
    return normalized


_LEGACY_NPC_KEYS = {
    "npc_id", "group", "map", "map_key", "object_index", "local_id",
    "x", "y", "graphics_id", "movement_type", "flag", "script_pointer",
    "owner_role", "source_script_pointer", "branches",
    "static_owner_status", "mgba_status",
    "non_product_shadow_alias", "expected_template_raw_hex",
    "interaction_execution", "runtime_position_state_contract",
}


def validate_legacy_catalog_document(
    value: Any,
) -> tuple[dict[str, Any], dict[str, dict[str, Any]]]:
    """Stage61 builderの旧base catalogを校正専用に厳格化する。"""
    root_keys = {
        "schema_version", "task", "stage", "status", "script_object_count",
        "branch_count", "owner_ledger_missing_object_count",
        "static_failure_count", "static_failures", "mgba_contract", "npcs",
    }
    if not isinstance(value, Mapping) or set(value) != root_keys:
        _fail("旧NPC catalog root keys不一致")
    if (value.get("schema_version"), value.get("task"), value.get("stage"),
            value.get("status")) != (1, TASK, STAGE, "PASS"):
        _fail("旧NPC catalog schema/task/stage/status不一致")
    if value["static_failure_count"] != 0 or value["static_failures"] != []:
        _fail("旧NPC catalogにstatic failureがあります")
    contract = value["mgba_contract"]
    if not isinstance(contract, Mapping) or set(contract) != {"trigger", "required"} \
            or any(not isinstance(contract[key], str) or not contract[key]
                   for key in contract):
        _fail("旧NPC catalog mgba_contract不正")
    npcs = value["npcs"]
    if not isinstance(npcs, list) or not npcs:
        _fail("旧NPC catalog npcsは非空listが必要です")
    if value["script_object_count"] != len(npcs):
        _fail("旧NPC catalog script_object_count不一致")
    missing = value["owner_ledger_missing_object_count"]
    if isinstance(missing, bool) or not isinstance(missing, int) or missing < 0:
        _fail("旧NPC catalog owner missing count不正")

    normalized_npcs: list[dict[str, Any]] = []
    calibration: dict[str, dict[str, Any]] = {}
    npc_ids: set[str] = set()
    coordinates: set[tuple[int, int, int]] = set()
    runtime_position_counts: dict[tuple[int, int], int] = {}
    branch_count = 0
    for index, npc in enumerate(npcs):
        label = f"npcs[{index}]"
        if not isinstance(npc, Mapping) or set(npc) != _LEGACY_NPC_KEYS:
            _fail(f"旧NPC catalog {label} keys不一致")
        npc_id = npc["npc_id"]
        if not isinstance(npc_id, str) \
                or re.fullmatch(r"OBJECT:[0-9]{3}/[0-9]{3}:[0-9]{3}", npc_id) is None:
            _fail(f"旧NPC catalog {label}.npc_id不正")
        if npc_id in npc_ids:
            _fail(f"旧NPC catalog npc_id重複: {npc_id}")
        npc_ids.add(npc_id)
        group = _int(npc["group"], f"legacy.{label}.group", 255)
        map_number = _int(npc["map"], f"legacy.{label}.map", 255)
        object_index = _int(
            npc["object_index"], f"legacy.{label}.object_index", 255,
        )
        key = (group, map_number, object_index)
        if key in coordinates:
            _fail(f"旧NPC catalog object coordinate重複: {key}")
        coordinates.add(key)
        local_id = _int(npc["local_id"], f"legacy.{label}.local_id", 255)
        x = _int(npc["x"], f"legacy.{label}.x", 65535)
        y = _int(npc["y"], f"legacy.{label}.y", 65535)
        flag = _int(npc["flag"], f"legacy.{label}.flag", 65535)
        graphics_id = _int(
            npc["graphics_id"], f"legacy.{label}.graphics_id", 65535,
        )
        movement_type = _int(
            npc["movement_type"], f"legacy.{label}.movement_type", 255,
        )
        expected_template_raw_hex = npc["expected_template_raw_hex"]
        if not isinstance(expected_template_raw_hex, str) \
                or re.fullmatch(
                    r"[0-9A-F]{48}", expected_template_raw_hex,
                ) is None:
            _fail(f"旧NPC catalog {label}.expected_template_raw_hex不正")
        shadow = npc["non_product_shadow_alias"]
        if shadow is not None and (
            not isinstance(shadow, Mapping)
            or set(shadow) != {
                "classification", "role", "source_owner_id",
                "canonical_owner_id",
            }
            or shadow.get("classification")
                != "CANONICAL_SHADOW_NON_PRODUCT_SOURCE"
            or shadow.get("role") not in {
                "NON_PRODUCT_SOURCE", "CANONICAL_PHYSICAL_OWNER",
            }
        ):
            _fail(f"旧NPC catalog {label}.non_product_shadow_alias不正")
        position_contract = _normalize_legacy_runtime_position_contract(
            npc.get("runtime_position_state_contract"),
            npc_id=npc_id, group=group, map_number=map_number,
            runtime_object=[x, y],
            expected_template_raw_hex=expected_template_raw_hex,
            local_id=local_id,
            shadow=None if shadow is None else dict(shadow),
        )
        if position_contract is None:
            runtime_position_control = _none_runtime_position_control()
            runtime_position_map_load_required = False
        else:
            runtime_position_counts[(group, map_number)] = (
                runtime_position_counts.get((group, map_number), 0) + 1
            )
            source_control = position_contract["control"]
            runtime_position_control = {
                "kind": source_control["kind"],
                "id": int(source_control["id"]),
                "value": bool(source_control["runtime_value"]),
            }
            runtime_position_map_load_required = True
        script_pointer = npc["script_pointer"]
        source_pointer = npc["source_script_pointer"]
        if isinstance(script_pointer, bool) or not isinstance(script_pointer, int) \
                or script_pointer < 0x08000000 or script_pointer >= 0x0A000000:
            _fail(f"旧NPC catalog {label}.script_pointer不正")
        if source_pointer is not None and (
            isinstance(source_pointer, bool) or not isinstance(source_pointer, int)
            or source_pointer < 0x08000000 or source_pointer >= 0x0A000000
        ):
            _fail(f"旧NPC catalog {label}.source_script_pointer不正")
        for text_key in ("map_key", "owner_role"):
            if not isinstance(npc[text_key], str) or not npc[text_key]:
                _fail(f"旧NPC catalog {label}.{text_key}不正")
        branches = npc["branches"]
        if not isinstance(branches, list) or not branches or any(
            not isinstance(branch, str) or _CASE_ID.fullmatch(branch) is None
            for branch in branches
        ) or len(set(branches)) != len(branches):
            _fail(f"旧NPC catalog {label}.branches不正")
        if npc["static_owner_status"] != "PASS" \
                or npc["mgba_status"] != "SCHEDULED_STAGE61_ALL_NPC_INPUT_AUDIT":
            _fail(f"旧NPC catalog {label} static/mGBA status不一致")
        branch_count += len(branches)
        case_id = f"cal-{group:03d}-{map_number:03d}-{object_index:03d}"
        row = {
            "case_id": case_id,
            "owner_key": npc_id,
            "group": group,
            "map": map_number,
            "map_key": npc["map_key"],
            "object_index": object_index,
            "local_id": local_id,
            "object": [x, y],
            "graphics_id": graphics_id,
            "movement_type": movement_type,
            "visibility_flag": flag,
            "script_pointer": script_pointer,
            "source_script_pointer": source_pointer,
            "owner_role": npc["owner_role"],
            "non_product_shadow_alias": (
                None if shadow is None else deepcopy(dict(shadow))
            ),
            "expected_template_raw_hex": expected_template_raw_hex,
            "runtime_position_state_contract": position_contract,
            "runtime_position_map_load_required": (
                runtime_position_map_load_required
            ),
            "runtime_position_control": runtime_position_control,
            "branches": list(branches),
        }
        interaction = _catalog_interaction_execution({
            "owner_key": npc_id,
            "group": group,
            "map": map_number,
            "local_id": local_id,
            "object": [x, y],
            "interaction_execution": npc["interaction_execution"],
            "non_product_shadow_alias": shadow,
            "expected_template_raw_hex": expected_template_raw_hex,
        }, f"legacy.{label}")
        row["interaction_execution"] = {
            "trigger": interaction["trigger"],
            "start": list(interaction["start"]),
            "walk_sequence": list(interaction["walk_sequence"]),
            "stance": list(interaction["stance"]),
            "action": interaction["action"],
            "interaction_distance": interaction["interaction_distance"],
            "counter_tile": (
                None if interaction["counter_tile"] is None
                else list(interaction["counter_tile"])
            ),
            "actual_walk_required": interaction["actual_walk_required"],
            "actual_walk_exception": deepcopy(
                interaction["actual_walk_exception"],
            ),
            "walk_path_basis": interaction["walk_path_basis"],
            "direct_script_call_forbidden": True,
        }
        if position_contract is not None:
            runtime_variant = next(
                variant for variant in position_contract["variants"]
                if variant["variant_id"] == "RUNTIME"
            )
            if row["interaction_execution"] \
                    != runtime_variant["interaction_execution"]:
                _fail(f"旧NPC catalog {label} runtime execution二重正本不一致")
        normalized_npcs.append(row)
        calibration[case_id] = row
    expected_runtime_position_counts = {
        key: int(value["owner_count"])
        for key, value in _RUNTIME_POSITION_EXPECTED_CONTROLS.items()
    }
    production_catalog = len(npcs) == 3108
    invalid_runtime_position_counts = any(
        count > expected_runtime_position_counts.get(key, -1)
        for key, count in runtime_position_counts.items()
    )
    if production_catalog:
        invalid_runtime_position_counts = invalid_runtime_position_counts \
            or runtime_position_counts != expected_runtime_position_counts \
            or sum(runtime_position_counts.values()) != 16
    if invalid_runtime_position_counts:
        _fail(
            "旧NPC catalog conditional runtime position owner集合不一致:"
            f"{runtime_position_counts}"
        )
    if value["branch_count"] != branch_count:
        _fail("旧NPC catalog branch_count不一致")
    normalized = {
        "schema_version": 1,
        "task": TASK,
        "stage": STAGE,
        "status": "PASS",
        "script_object_count": len(normalized_npcs),
        "branch_count": branch_count,
        "owner_ledger_missing_object_count": missing,
        "static_failure_count": 0,
        "static_failures": [],
        "mgba_contract": dict(contract),
        "npcs": normalized_npcs,
    }
    return normalized, calibration


def load_legacy_catalog(
    path: Path,
) -> tuple[dict[str, Any], dict[str, dict[str, Any]]]:
    if not path.is_file():
        _fail(f"校正用の旧NPC catalogがありません: {path}")
    try:
        source = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as error:
        _fail(f"旧NPC catalogを読めません: {error}")
    return validate_legacy_catalog_document(source)


def load_legacy_catalog_source(path: Path) -> dict[str, Any]:
    """校正結果のstrict昇格用に旧catalog原形を厳格検証して返す。"""
    if not path.is_file():
        _fail(f"校正用の旧NPC catalogがありません: {path}")
    try:
        source = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as error:
        _fail(f"旧NPC catalogを読めません: {error}")
    validate_legacy_catalog_document(source)
    return deepcopy(dict(source))


def write_calibration_tsv(
    path: Path, calibration: Mapping[str, Mapping[str, Any]],
) -> None:
    lines = [
        "case_id\towner_key\tgroup\tmap\tlocal_id\t"
        "object_x\tobject_y\tvisibility_flag\t"
        + "\t".join(_RUNTIME_POSITION_CONTROL_TSV_COLUMNS) + "\t"
        + "\t".join(_RUNTIME_POSITION_PRODUCER_TSV_COLUMNS) + "\n"
    ]
    for case_id in sorted(calibration):
        row = calibration[case_id]
        interaction = {
            "group": row["group"], "map": row["map"],
            "object": row["object"],
            "expected_template_raw_hex": row["expected_template_raw_hex"],
            "runtime_position_map_load_required": row.get(
                "runtime_position_map_load_required", False,
            ),
            "runtime_position_control": row.get(
                "runtime_position_control",
                _none_runtime_position_control(),
            ),
        }
        fields = [
            case_id, row["owner_key"], str(row["group"]), str(row["map"]),
            str(row["local_id"]), str(row["object"][0]),
            str(row["object"][1]), str(row["visibility_flag"]),
            *_runtime_position_control_tsv_fields(
                row, interaction, case_id,
            ),
            *_runtime_position_producer_tsv_fields(
                row, interaction, case_id,
            ),
        ]
        lines.append("\t".join(fields) + "\n")
    path.write_text("".join(lines), encoding="ascii", newline="\n")


