def write_local_static_incoming_absent_diagnostic_tsv(
    path: Path, diagnostics: Mapping[str, Any],
) -> None:
    """Dormant map fixtureをdirect script pointerなしのbounded ABIへ落とす。"""
    lines = [_DIAGNOSTIC_TSV_HEADER]
    rows: list[list[str]] = []
    for map_row in diagnostics["maps"]:
        minimum = map_row["minimum_real_walk_cycle_probe_id"]
        for row in map_row["object_probes"]:
            sequence = row["input_sequence"]
            rows.append([
                row["probe_id"], "OBJECT", str(map_row["group"]),
                str(map_row["map"]), str(row["teleport"]["x"]),
                str(row["teleport"]["y"]), str(row["target_object"][0]),
                str(row["target_object"][1]), str(row["local_id"]),
                str(row["visibility"]["flag"]), "0",
                str(row["script_pointer"]), str(KEYS[sequence[-2]["key"]]),
                ",".join(str(KEYS[key]) for key in row["real_walk_cycle"])
                or "-", str(int(row["probe_id"] == minimum)),
            ])
        for row in map_row["bg_script_probes"]:
            sequence = row["input_sequence"]
            rows.append([
                row["probe_id"], "BG_SCRIPT", str(map_row["group"]),
                str(map_row["map"]), str(row["teleport"]["x"]),
                str(row["teleport"]["y"]),
                str(row["target_bg_position"][0]),
                str(row["target_bg_position"][1]), "0", "0",
                str(row["record_address"]), str(row["script_pointer"]),
                str(KEYS[sequence[-2]["key"]]),
                ",".join(str(KEYS[key]) for key in row["real_walk_cycle"])
                or "-", str(int(row["probe_id"] == minimum)),
            ])
        for row in map_row["bg_non_script_visibility_proofs"]:
            rows.append([
                row["probe_id"], "BG_HIDDEN", str(map_row["group"]),
                str(map_row["map"]), str(row["position"][0]),
                str(row["position"][1]), str(row["position"][0]),
                str(row["position"][1]), "0", str(row["visibility_flag"]),
                str(row["record_address"]), "0", "0", "-",
                str(int(row["probe_id"] == minimum)),
            ])
    rows.sort(key=lambda fields: fields[0])
    expected = (
        diagnostics["object_probe_count"]
        + diagnostics["bg_script_probe_count"]
        + diagnostics["bg_non_script_visibility_proof_count"]
    )
    if len(rows) != expected or len({row[0] for row in rows}) != expected:
        _fail("fixture diagnostic TSV coverage不一致")
    for fields in rows:
        if len(fields) != 15 or any(
            not isinstance(field, str) or not field
            or "\t" in field or "\n" in field or "\r" in field
            for field in fields
        ):
            _fail(f"fixture diagnostic TSV row不正: {fields[:1]}")
        lines.append("\t".join(fields) + "\n")
    path.write_text("".join(lines), encoding="ascii", newline="\n")


