            False, True, True, _GIVEEGG_RNG_SEED,
            "0x09600320", _GIVEEGG_BASE_STATS_SPECIES25_HEX,
            "0x0803F355", "0x0803F4B1", "0x0808B4B5",
            True, "CFRU_JP_PLAINTEXT_80", True, True,
            True, True, True, 4, 6,
